def _get_desktop_dir():
    """Trả về đường dẫn Desktop của người dùng (Windows/Mac/Linux).
    Hỗ trợ cả Desktop tiếng Việt (OneDrive). Nếu không thấy -> thư mục home."""
    home = os.path.expanduser("~")
    candidates = [
        os.path.join(home, "Desktop"),
        os.path.join(home, "OneDrive", "Desktop"),
        os.path.join(home, "OneDrive", "Máy tính"),
        os.path.join(home, "Máy tính"),
    ]
    # đọc từ registry trên Windows (chính xác nhất)
    try:
        import sys
        if sys.platform.startswith("win"):
            import winreg
            key = winreg.OpenKey(
                winreg.HKEY_CURRENT_USER,
                r"Software\Microsoft\Windows\CurrentVersion\Explorer\Shell Folders")
            val, _ = winreg.QueryValueEx(key, "Desktop")
            winreg.CloseKey(key)
            if val and os.path.isdir(os.path.expandvars(val)):
                return os.path.expandvars(val)
    except Exception:
        pass
    for c in candidates:
        if os.path.isdir(c):
            return c
    return home


def _quy_cua_ky(tu_ngay, den_ngay):
    """Từ khoảng ngày (dd/mm/yyyy) suy ra (năm, quý). Nếu khoảng ngày NẰM GỌN
    trong 1 quý -> trả (năm, số_quý 1..4). Nếu trải nhiều quý (6 tháng/cả năm)
    hoặc không đọc được -> trả (năm, None) để lưu thẳng vào thư mục năm."""
    try:
        d1 = datetime.datetime.strptime(tu_ngay, "%d/%m/%Y").date()
        d2 = datetime.datetime.strptime(den_ngay, "%d/%m/%Y").date()
    except Exception:
        return None, None
    if d1 > d2:
        d1, d2 = d2, d1
    q1 = (d1.month - 1) // 3 + 1
    q2 = (d2.month - 1) // 3 + 1
    if d1.year == d2.year and q1 == q2:
        return d1.year, q1
    return d1.year, None   # trải nhiều quý -> chỉ dùng thư mục năm


def _thang_cua_ky(tu_ngay, den_ngay):
    """Như _quy_cua_ky nhưng theo THÁNG: nếu khoảng ngày (dd/mm/yyyy) NẰM GỌN
    trong đúng 1 tháng -> trả (năm, tháng 1..12); nếu trải nhiều tháng hoặc
    không đọc được -> trả (năm, None) để lưu thẳng vào thư mục năm."""
    try:
        d1 = datetime.datetime.strptime(tu_ngay, "%d/%m/%Y").date()
        d2 = datetime.datetime.strptime(den_ngay, "%d/%m/%Y").date()
    except Exception:
        return None, None
    if d1 > d2:
        d1, d2 = d2, d1
    if d1.year == d2.year and d1.month == d2.month:
        return d1.year, d1.month
    return d1.year, None   # trải nhiều tháng -> chỉ dùng thư mục năm


def _co_thu_muc_theo_thang(thu_muc_nam):
    """Công ty đã tự tổ chức thư mục kỳ THEO THÁNG (có sẵn ít nhất 1 thư mục
    con dạng "THANG N"/"THÁNG N") thay vì theo Quý (vd OneDrive của khách:
    .../2026/THANG 1.. THANG 6) — nếu có thì ưu tiên lưu tiếp đúng cấu trúc
    tháng đó thay vì luôn mặc định tạo/dùng "QUY N"."""
    try:
        if not os.path.isdir(thu_muc_nam):
            return False
        for name in os.listdir(thu_muc_nam):
            if _khong_dau(name).startswith("thang "):
                return True
    except Exception:
        pass
    return False


def _tu_den_cua_quy(nam, quy):
    """CHIỀU NGƯỢC của _quy_cua_ky: từ (năm, quý 1..4) suy ra khoảng ngày
    (tu_ngay, den_ngay) dd/mm/yyyy của đúng quý đó. quy rỗng/0/None -> cả năm."""
    nam = int(nam)
    if not quy:
        return f"01/01/{nam}", f"31/12/{nam}"
    quy = int(quy)
    thang_dau = (quy - 1) * 3 + 1
    thang_cuoi = thang_dau + 2
    ngay_cuoi = calendar.monthrange(nam, thang_cuoi)[1]
    return f"01/{thang_dau:02d}/{nam}", f"{ngay_cuoi:02d}/{thang_cuoi:02d}/{nam}"


def _thu_muc_ket_xuat_ky(export_dir, tu_ngay, den_ngay):
    """Tạo (nếu thiếu) cấu trúc thư mục lưu file kết xuất theo Năm/Quý (hoặc
    Năm/Tháng — xem dưới) dưới export_dir và trả về đường dẫn thư mục ĐÍCH
    để lưu file.
      export_dir/<năm>/QUY 1..4/     (mặc định — tạo đủ cả 4 quý khi tạo mới năm)
      export_dir/<năm>/THANG 1..12/  (nếu công ty ĐÃ TỰ tổ chức thư mục kỳ
                                       theo tháng — vd OneDrive khách có sẵn
                                       "THANG 1".."THANG 6" — thì lưu tiếp
                                       đúng cấu trúc tháng đó thay vì Quý)
    Nếu kỳ trải nhiều quý/tháng -> lưu thẳng vào export_dir/<năm>/.
    Trả None nếu export_dir trống/không tạo được.
    Tên thư mục dùng "QUY N"/"THANG N" (không dấu, viết hoa) thay vì có dấu —
    tránh lỗi hiển thị/gõ dấu tiếng Việt trên một số hệ thống/ổ mạng cũ."""
    export_dir = (export_dir or "").strip()
    if not export_dir:
        return None
    nam, quy = _quy_cua_ky(tu_ngay, den_ngay)
    if not nam:
        return None
    try:
        thu_muc_nam = os.path.join(export_dir, str(nam))
        os.makedirs(thu_muc_nam, exist_ok=True)
        if _co_thu_muc_theo_thang(thu_muc_nam):
            _, thang = _thang_cua_ky(tu_ngay, den_ngay)
            # tạo đủ 12 tháng mỗi khi có thư mục năm (kể cả năm đã có sẵn —
            # không sao, exist_ok) để người dùng thấy sẵn cấu trúc, khỏi tạo tay
            for t in range(1, 13):
                os.makedirs(os.path.join(thu_muc_nam, f"THANG {t}"), exist_ok=True)
            dich = os.path.join(thu_muc_nam, f"THANG {thang}") if thang else thu_muc_nam
        else:
            # tạo đủ 4 quý mỗi khi có thư mục năm (kể cả năm đã có sẵn — không
            # sao, exist_ok) để người dùng thấy sẵn cấu trúc, khỏi tạo tay
            for q in (1, 2, 3, 4):
                os.makedirs(os.path.join(thu_muc_nam, f"QUY {q}"), exist_ok=True)
            dich = os.path.join(thu_muc_nam, f"QUY {quy}") if quy else thu_muc_nam
        os.makedirs(dich, exist_ok=True)
        return dich
    except Exception:
        return None


def _resp_xuat(path, fname, extra=None):
    """Trả FileResponse cho file kết xuất. Nếu file ĐÃ CÓ trên Desktop (đã
    được copy ra đó) thì gắn header 'X-Saved-Desktop: 1' để trình duyệt KHÔNG
    tải trùng thêm 1 bản vào thư mục Downloads — người dùng chỉ muốn 1 bản
    ngoài Desktop. File nào KHÔNG có trên Desktop (vd file mẫu) thì không gắn
    header -> trình duyệt vẫn tải bình thường (không mất file)."""
    h = dict(extra or {})
    try:
        d = _get_desktop_dir()
        if d and os.path.isfile(os.path.join(d, fname)):
            h["X-Saved-Desktop"] = "1"
    except Exception:
        pass
    # KHÔNG được để trình duyệt CACHE — endpoint gọi hàm này (vd "Xuất Excel
    # tổng hợp") GHI FILE MỚI mỗi lần gọi (GET, cùng URL/tham số mỗi lần bấm
    # lại); nếu trình duyệt lặng lẽ phục vụ lại response CŨ thì file trên đĩa
    # không được cập nhật, các bước sau (vd "Kết xuất XML" đọc lại đúng file
    # này) vẫn thấy dữ liệu CŨ dù người dùng đã sửa/tra cứu lại.
    h["Cache-Control"] = "no-store"
    return FileResponse(path, filename=fname, headers=h)

def _open_file_local(path):
    """Mở file bằng ứng dụng mặc định của HĐH (Excel/trình xem XML).
    Chỉ chạy khi server chạy local trên máy người dùng."""
    try:
        import sys, subprocess
        if sys.platform.startswith("win"):
            os.startfile(path)  # type: ignore
        elif sys.platform == "darwin":
            subprocess.Popen(["open", path])
        else:
            subprocess.Popen(["xdg-open", path])
    except Exception:
        pass


def _to_num(v):
    """Chuyển '10.000000' hoặc '807544.000000' thành số; nếu không được giữ nguyên."""
    try:
        f = float(v)
        return int(f) if f == int(f) else f
    except Exception:
        return v if v not in (None,) else ""


def _tygia_ngoai_te(dvtte, tgia):
    """Trả về tỷ giá (số) nếu hóa đơn dùng NGOẠI TỆ (đơn vị tiền tệ khác VND
    và có tỷ giá hợp lệ > 0); trả về None nếu là VND (không cần quy đổi) hoặc
    không đọc được tỷ giá — dùng để quy đổi đơn giá/thành tiền hóa đơn USD...
    ra VNĐ khi xuất Excel (Chi tiết BÁN RA / BK Bán ra)."""
    dv = str(dvtte or "").strip().upper()
    if not dv or dv == "VND":
        return None
    tg = _to_num(tgia)
    if not isinstance(tg, (int, float)) or tg <= 0:
        return None
    return tg


def _gop_hoa_don_trung_he_thong(rows):
    """Gộp các dòng invoices TRÙNG LẶP giữa 2 hệ thống (hóa đơn điện tử
    'query' / máy tính tiền 'sco-query') — cùng 1 hóa đơn thật (giống hệt
    nbmst/khmshdon/khhdon/shdon/loai) đôi khi được trang Thuế trả về ở CẢ 2
    hệ thống, nên được lưu thành 2 DÒNG RIÊNG trong DB (khoá UNIQUE có cột
    he_thong nên không tự loại nhau). Nếu không gộp lại ở đây, mọi báo cáo
    tổng hợp (Excel, tờ khai GTGT, Tạm tính VAT, danh sách hóa đơn) sẽ ĐẾM/
    TÍNH TIỀN GẤP ĐÔI cho đúng các hóa đơn này — người dùng đã phát hiện qua
    file Excel kết xuất bị liệt kê trùng lặp.
    Giữ lại dòng có 'ttxly' trong raw (đầy đủ thông tin xử lý hơn); nếu cả
    2 dòng đều có/đều không có ttxly thì giữ dòng gặp trước. Nhận list các
    sqlite3.Row, trả về list đã lọc, GIỮ NGUYÊN thứ tự ban đầu.

    Khoá so khớp phải CHUẨN HÓA (không so chuỗi y hệt) — đã xác nhận thực tế
    hóa đơn hộ/cá nhân kinh doanh (máy tính tiền) đôi khi trang Thuế trả về
    khmshdon/shdon LỆCH ĐỊNH DẠNG nhẹ giữa 2 hệ thống (vd '1' so với '01',
    hoặc MST có/không dấu gạch), khiến so khớp CHUỖI Y HỆT trước đây bỏ sót,
    không gộp được, làm hóa đơn hiện LẶP ĐÔI trong file Excel kết xuất.

    KHÔNG dùng khmshdon trong khoá gộp: đã xác nhận thực tế có trường hợp
    khmshdon trả về giữa 2 hệ thống lệch nhau KHÔNG PHẢI chỉ do số 0 ở đầu
    (vd '1' vs '6' — mã phân loại khác hẳn, không phải cùng số chỉ khác định
    dạng), khiến chuẩn hóa kiểu bỏ số 0 đầu vẫn không gộp được, hóa đơn vẫn
    hiện lặp đôi. Ký hiệu (khhdon) hóa đơn của Tổng cục Thuế đã tự mang
    thông tin mẫu số (ký tự đầu ký hiệu), nên chỉ cần so khớp
    nbmst + khhdon + shdon + loai là đủ xác định 1 hóa đơn thật, không cần
    thêm khmshdon (thêm vào chỉ làm khoá DỄ BỊ LỆCH giữa 2 hệ thống hơn)."""
    def _co_ttxly(r):
        try:
            raw = json.loads(r["raw"]) if r["raw"] else {}
        except Exception:
            raw = {}
        return bool(str(raw.get("ttxly", "") or "").strip())

    def _chuan_ma(v):
        """Bỏ số 0 ở đầu (shdon đôi khi lệch định dạng '1' vs '01')."""
        s = str(v or "").strip()
        return s.lstrip("0") or "0" if s else ""

    best = {}
    for r in rows:
        key = (_chuan_mst(r["nbmst"]), str(r["khhdon"] or "").strip(),
               _chuan_ma(r["shdon"]), r["loai"])
        if key not in best:
            best[key] = r
        elif _co_ttxly(r) and not _co_ttxly(best[key]):
            best[key] = r
    giu_lai = {id(r) for r in best.values()}
    return [r for r in rows if id(r) in giu_lai]


def _save_invoice_files(folder, base, zip_bytes):
    """
    Lưu file invoice.zip do TCT trả về, đồng thời giải nén lấy
    invoice.html và file xml ra để dễ đọc.
    folder: thư mục lưu, base: tên file gốc (vd C26TYY_1360_0317483204)
    """
    import io as _io
    import zipfile as _zip
    os.makedirs(folder, exist_ok=True)
    # 1) Lưu nguyên file zip gốc
    zip_path = os.path.join(folder, base + ".zip")
    with open(zip_path, "wb") as f:
        f.write(zip_bytes)
    # 2) Thử giải nén lấy invoice.html và *.xml
    try:
        zf = _zip.ZipFile(_io.BytesIO(zip_bytes))
        for name in zf.namelist():
            low = name.lower()
            data = zf.read(name)
            if low.endswith(".html") or low.endswith(".htm"):
                with open(os.path.join(folder, base + "_invoice.html"), "wb") as f:
                    f.write(data)
            elif low.endswith(".xml"):
                with open(os.path.join(folder, base + ".xml"), "wb") as f:
                    f.write(data)
    except Exception:
        # không phải zip (có thể là xml thuần) -> lưu thẳng .xml
        if zip_bytes[:5] == b"<?xml" or zip_bytes[:5] == b"<HDon":
            with open(os.path.join(folder, base + ".xml"), "wb") as f:
                f.write(zip_bytes)


def _doc_kiem_tra_file_hoadon(fpath):
    """Đọc + thử parse nhanh 1 file hóa đơn đã tải (XML thuần, hoặc ZIP chứa
    XML) để biết file có ĐỌC ĐƯỢC hay không. File hỏng/sai định dạng -> trả
    về [] (rỗng), coi như KHÔNG dùng được (phải tải lại)."""
    try:
        with open(fpath, "rb") as f:
            data = f.read()
        if fpath.lower().endswith(".zip"):
            import zipfile as _zf, io as _io2
            try:
                z = _zf.ZipFile(_io2.BytesIO(data))
                xn = next((n for n in z.namelist()
                           if n.lower().endswith(".xml")), None)
                if xn:
                    data = z.read(xn)
            except Exception:
                pass
        return bool(_parse_xml_invoice(data))
    except Exception:
        return False


def _ngu_ktra_huy(giay, cancel_check=None):
    """time.sleep(giay) nhưng chia nhỏ thành từng đoạn ngắn, kiểm tra
    cancel_check() giữa mỗi đoạn — để khi người dùng hủy tra cứu (vd chuyển
    sang công ty khác) giữa lúc đang CHỜ để thử lại (có thể chờ tới 90s nếu
    bị 429 giới hạn tốc độ), tiến trình dừng lại trong khoảng nửa giây thay
    vì phải chờ hết trọn thời gian chờ rồi mới kiểm tra lại."""
    if not cancel_check:
        time.sleep(giay)
        return
    con_lai = giay
    buoc = 0.5
    while con_lai > 0:
        if cancel_check():
            return
        thoi = min(buoc, con_lai)
        time.sleep(thoi)
        con_lai -= thoi


# ============================================================
#  GDT API CLIENT  (module gọi API Tổng cục Thuế)
#  --> Nếu TCT đổi endpoint, chỉ cần sửa các URL trong class này
# ============================================================
class GDTClient:
    # Endpoint thật xác nhận từ DevTools: có tiền tố /api
    BASE = "https://hoadondientu.gdt.gov.vn/api"
    BASE_QUERY = "https://hoadondientu.gdt.gov.vn/api/query"

    HEADERS = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                      "AppleWebKit/537.36 (KHTML, like Gecko) "
                      "Chrome/120.0 Safari/537.36",
        "Accept": "application/json, text/plain, */*",
    }

    def __init__(self):
        # hoadondientu.gdt.gov.vn cũng đứng sau WAF F5 (thấy cookie kiểu
        # "TS0114b13e=..." — dấu hiệu điển hình của F5 BIG-IP ASM) chặn/làm
        # chậm request theo dấu vân tay TLS/JA3 — request.Session (dùng
        # OpenSSL của Python) có vân tay TLS KHÁC hẳn Chrome thật, dù đã copy
        # đúng từng header (action, User-Agent...) vẫn có thể bị WAF coi là
        # bot và xử lý chậm/lỗi ngẫu nhiên (500/treo) dù trình duyệt thật gọi
        # CÙNG request lại rất nhanh. DVCClient (dịch vụ công) đã gặp và sửa
        # y hệt vấn đề này bằng curl_cffi (giả lập đúng vân tay TLS Chrome) —
        # áp dụng lại đây cho GDTClient.
        self.impersonate = False
        try:
            from curl_cffi import requests as _cffi
            self.session = _cffi.Session(impersonate="chrome")
            self.impersonate = True
            self.session.headers.update({"Accept": self.HEADERS["Accept"]})
        except Exception:
            self.session = requests.Session()
            self.session.headers.update(self.HEADERS)
        self.token: Optional[str] = None
        self._last_total = 0
        self._token_dead = False  # bật khi gặp 401 (hết phiên) -> bỏ qua nốt các gọi mạng

    # --- Lấy ảnh captcha ---
    def get_captcha(self):
        url = f"{self.BASE}/captcha"
        r = self.session.get(url, timeout=30)
        r.raise_for_status()
        # Trang trả JSON: {"key": "...", "content": "data:image/svg+xml;base64,..."}
        # (content có thể là chuỗi SVG thô hoặc data-URI base64)
        try:
            data = r.json()
        except Exception:
            # phòng trường hợp trả thẳng SVG/ảnh
            data = {"key": "", "content": r.text}
        return data  # trả nguyên về frontend để hiển thị

    # --- Đăng nhập lấy token ---
    def login(self, username, password, cvalue, ckey):
        url = f"{self.BASE}/security-taxpayer/authenticate"
        payload = {
            "username": username,
            "password": password,
            "cvalue": cvalue,   # mã captcha người dùng nhập
            "ckey": ckey,       # key captcha tương ứng
        }
        r = self.session.post(url, json=payload, timeout=30)
        if r.status_code != 200:
            raise Exception(f"Đăng nhập thất bại ({r.status_code}): {r.text[:200]}")
        data = r.json()
        token = data.get("token")
        if not token:
            raise Exception(f"Không nhận được token: {json.dumps(data)[:200]}")
        self.token = token
        self.session.headers.update({"Authorization": f"Bearer {token}"})
        return token

    def set_token(self, token):
        self.token = token
        self.session.headers.update({"Authorization": f"Bearer {token}"})

    # --- Tra cứu hóa đơn (tự chia nhỏ theo tháng) ---
    # loai: "purchase" (mua vào) hoặc "sold" (bán ra)
    # he_thong: "query" (HĐ điện tử thường) hoặc "sco-query" (HĐ máy tính tiền)
    def query_invoices(self, tu_ngay, den_ngay, loai="purchase", page_size=50,
                       he_thong="query", progress=None, chi_cac_doan=None,
                       mtt_limiter=None, cancel_check=None):
        """
        Tra cứu hóa đơn trong khoảng ngày bất kỳ (kể cả nhiều tháng/cả năm).
        Trang Thuế giới hạn mỗi lần gọi tối đa ~31 ngày, nên hàm này tự
        CHIA NHỎ khoảng ngày thành từng tháng rồi gộp kết quả lại.
        tu_ngay, den_ngay định dạng dd/mm/yyyy
        he_thong: "query" (hóa đơn điện tử) / "sco-query" (hóa đơn máy tính tiền)
        progress: hàm callback(msg) để báo tiến độ (tùy chọn)
        chi_cac_doan: nếu có, CHỈ dò lại đúng các đoạn này (list dict
          {"tu":dd/mm/yyyy,"den":dd/mm/yyyy,"ttxly":int_hoặc_None}) thay vì
          toàn bộ khoảng ngày — dùng khi RETRY sau khi 1 phần nhỏ (vd 1
          tháng × 1 trạng thái) bị lỗi mạng, để KHÔNG phải dò lại từ đầu
          các tháng/trạng thái ĐÃ THÀNH CÔNG (trước đây bất kỳ lỗi cục bộ
          nào cũng khiến cả khoảng ngày (có khi cả năm) bị dò lại từ đầu,
          rất lâu — nhất là hệ thống máy tính tiền hay bị lỗi mạng vặt).
        mtt_limiter: DynamicLimiter DÙNG CHUNG với thanh trượt "Số lượng tải
          song song" (vd giữa mua vào và bán ra máy tính tiền chạy song
          song ở _run_fetch_job) để tổng số lượt gọi ĐANG THỰC SỰ chạy tới
          hệ thống máy tính tiền — CỘNG DỒN CẢ 2 LOẠI — không vượt quá mức
          người dùng đang chỉnh, dùng CHUNG 1 giới hạn với hóa đơn điện tử
          thường (không tách riêng nữa). Nếu không truyền (vd gọi lẻ, không
          chạy song song với loại khác) thì chỉ dựa vào giới hạn nội bộ
          như trước.
        cancel_check: callable() -> bool — kiểm tra người dùng đã hủy tra
          cứu chưa (vd chuyển sang công ty khác giữa chừng). Được kiểm tra
          liên tục ở NHIỀU điểm bên trong (mỗi trang/mỗi lần thử lại/mỗi
          tháng/mỗi trạng thái) để tiến trình DỪNG THẬT SỰ trong vài giây,
          thay vì cứ âm thầm chạy tiếp tới khi tự xong dù giao diện đã ẩn.

        Trả về tuple (results, total_expected, loi_rieng, cac_doan_loi) —
        KHÔNG dùng self.last_query_* nữa (không an toàn khi mua vào/bán ra
        chạy song song trên cùng 1 client — xem _run_fetch_job).
        """
        all_results = []
        seen = set()  # khử trùng lặp hóa đơn ở ranh giới tháng
        total_expected = 0
        loi_tich_luy = []   # gom LỖI THẬT SỰ (đã thử lại vẫn lỗi) qua các tháng/trạng thái
        cac_doan_loi = []   # {"tu","den","ttxly"} — để RETRY ĐÚNG đoạn này ở lượt sau
        khoa = threading.Lock()  # bảo vệ các biến gộp kết quả ở trên khi nhiều luồng ghi cùng lúc

        # Số luồng THỰC SỰ thực thi cùng lúc trong ThreadPoolExecutor bên dưới
        # — đây chỉ là TRẦN CỨNG (an toàn, không giới hạn thực tế), số luồng
        # ĐANG THỰC SỰ chạy được quyết định bởi mtt_limiter (DÙNG CHUNG với
        # thanh trượt "Số lượng tải song song" — không tách riêng máy tính
        # tiền/hóa đơn điện tử thường nữa, theo yêu cầu). Hóa đơn điện tử
        # thường không có limiter riêng cho bước tra cứu danh sách nên vẫn
        # giữ mức cố định thấp hơn 1 chút.
        so_luong_song_song = MTT_TRAN_CUNG_EXECUTOR if he_thong == "sco-query" else 4

        def _gop(s_from, s_to, ket_qua):
            chunk, total, loi_rieng, ttxly_that_bai = ket_qua
            with khoa:
                nonlocal total_expected
                total_expected += total or 0
                for loi in loi_rieng:
                    loi_tich_luy.append(f"{s_from}-{s_to} {loi}")
                for t in ttxly_that_bai:
                    cac_doan_loi.append({"tu": s_from, "den": s_to, "ttxly": t})
                # THIẾU so với total của ĐÚNG THÁNG NÀY (trang Thuế báo nhiều
                # hơn số lấy được) dù KHÔNG có lỗi/exception nào (vd 1 hóa đơn
                # lặng lẽ rơi mất giữa ranh giới phân trang) — TRƯỚC ĐÂY chỉ
                # phát hiện được ở TỔNG CỘNG toàn khoảng ngày (nhiều tháng), nên
                # phải dò lại TOÀN BỘ khoảng ngày đó (có khi cả năm) dù chỉ 1
                # tháng bị thiếu vài hóa đơn — rất lâu, đúng phản ánh của người
                # dùng. Ghi nhận NGAY ở đây (mức 1 THÁNG) để lượt sau chỉ cần
                # dò lại ĐÚNG tháng này (chi_cac_doan), không phải dò lại từ
                # đầu. Chỉ thêm khi KHÔNG đã có ttxly_that_bai cho tháng này
                # (tránh trùng — trường hợp đó lượt sau đã dò riêng theo đúng
                # trạng thái lỗi rồi, cần chi tiết hơn "cả tháng").
                if not ttxly_that_bai and total and len(chunk) < total:
                    cac_doan_loi.append({"tu": s_from, "den": s_to, "ttxly": None})
                for inv in chunk:
                    key = (inv.get("khmshdon"), inv.get("khhdon"),
                           inv.get("shdon"), inv.get("nbmst"))
                    if key not in seen:
                        seen.add(key)
                        all_results.append(inv)

        if chi_cac_doan:
            # ----- CHỈ dò lại các đoạn cụ thể đã lỗi ở lượt trước -----
            def _xu_ly_doan(doan):
                s_from, s_to, ttxly = doan["tu"], doan["den"], doan.get("ttxly")
                if cancel_check and cancel_check():
                    return s_from, s_to, ([], 0, [], [])
                # Gắn nhãn [ĐOẠN dd/mm→dd/mm] vào MỌI dòng tiến độ của đoạn
                # này (kể cả các dòng lỗi/thử lại phát sinh bên trong
                # _query_one_range/_fetch_paginated) — để giao diện phân biệt
                # được ĐANG chạy đoạn nào, thay vì chỉ 1 dòng chung chung đè
                # lẫn nhau khi nhiều đoạn chạy song song.
                def _progress_doan(t):
                    if progress:
                        progress(f"[ĐOẠN {s_from}→{s_to}] {t}")
                _progress_doan("đang dò lại đoạn lỗi trước đó...")
                # chỉ dò ĐÚNG trạng thái đã lỗi (mua vào); None -> dò cả tháng (bán ra)
                ttxly_can_do = (ttxly,) if ttxly is not None else None
                dung_chung = mtt_limiter if he_thong == "sco-query" else None
                if dung_chung:
                    dung_chung.acquire()
                try:
                    ket_qua = self._query_one_range(
                        s_from, s_to, loai, page_size, he_thong,
                        progress=_progress_doan, ttxly_can_do=ttxly_can_do,
                        cancel_check=cancel_check)
                finally:
                    if dung_chung:
                        dung_chung.release()
                _progress_doan("✓ xong")
                return s_from, s_to, ket_qua

            with _cf.ThreadPoolExecutor(max_workers=so_luong_song_song) as ex:
                futs = [ex.submit(_xu_ly_doan, doan) for doan in chi_cac_doan]
                for fut in _cf.as_completed(futs):
                    try:
                        s_from, s_to, ket_qua = fut.result()
                    except Exception as e:
                        if "CANCELLED" in str(e):
                            break   # dừng gộp thêm — với-block vẫn đợi các đoạn còn lại tự thoát nhanh
                        raise
                    _gop(s_from, s_to, ket_qua)
            return all_results, total_expected, loi_tich_luy, cac_doan_loi

        d_from = datetime.datetime.strptime(tu_ngay, "%d/%m/%Y").date()
        d_to = datetime.datetime.strptime(den_ngay, "%d/%m/%Y").date()
        if d_from > d_to:
            d_from, d_to = d_to, d_from

        # ===== ĐẾM NHANH TOÀN KỲ trước khi dò từng tháng (CHỈ hóa đơn điện tử
        # thường — KHÔNG áp dụng máy tính tiền nữa, theo yêu cầu) =====
        # Nhiều công ty KHÔNG dùng hóa đơn máy tính tiền, nhưng với công ty CÓ
        # dùng (phát sinh hầu hết các tháng) thì bước đếm nhanh này KHÔNG BAO
        # GIỜ bỏ qua được gì — mà hệ thống máy tính tiền vốn hay chậm/lỗi vặt
        # (502/504) khiến NGAY CẢ bước "đếm nhanh" (đáng lẽ nhẹ) cũng hiện lỗi
        # thử lại liên tục, gây cảm giác "kiểm tra" cũng lâu không kém tải
        # thật. Với hóa đơn điện tử thường (hệ thống ổn định hơn) vẫn giữ bước
        # này vì rẻ và vẫn có ích khi công ty thật sự không có hóa đơn nào.
        if he_thong != "sco-query":
            try:
                if self._toan_ky_rong(tu_ngay, den_ngay, loai, he_thong, page_size, progress,
                                      cancel_check=cancel_check):
                    if progress:
                        progress("kỳ này không có hóa đơn — bỏ qua nhanh")
                    return [], 0, [], []
            except Exception as e:
                if "TOKEN_EXPIRED" in str(e) or "CANCELLED" in str(e):
                    raise
                # lỗi khác khi đếm nhanh -> KHÔNG bỏ qua, dò đầy đủ như cũ cho an toàn

        # Tính SẴN toàn bộ các đoạn tháng cần dò (thay vì dò tuần tự từng
        # tháng một) — để có thể XỬ LÝ SONG SONG NHIỀU THÁNG CÙNG LÚC ngay
        # bên dưới: nếu 1 tháng đang bị lỗi máy chủ (502/504, đang chờ thử
        # lại) thì các tháng KHÁC vẫn tiếp tục chạy, không phải xếp hàng chờ
        # đúng tháng đó xong xuôi mới bắt đầu tháng tiếp theo (khác hẳn trước
        # đây: hoàn toàn tuần tự, 1 tháng bị kẹt là mọi tháng sau đều phải đợi).
        cac_thang = []
        cur = d_from
        while cur <= d_to:
            if cur.month == 12:
                month_end = datetime.date(cur.year, 12, 31)
            else:
                month_end = datetime.date(cur.year, cur.month + 1, 1) - datetime.timedelta(days=1)
            chunk_end = min(month_end, d_to)
            cac_thang.append((cur.strftime("%d/%m/%Y"), chunk_end.strftime("%d/%m/%Y")))
            cur = chunk_end + datetime.timedelta(days=1)

        def _xu_ly_thang(s_from, s_to):
            if cancel_check and cancel_check():
                return s_from, s_to, ([], 0, [], [])
            # Gắn nhãn [THÁNG dd/mm→dd/mm] vào MỌI dòng tiến độ của tháng này
            # (kể cả lỗi/thử lại phát sinh bên trong) — để giao diện hiện
            # ĐƯỢC NHIỀU DÒNG, mỗi dòng 1 tháng đang chạy song song, thay vì
            # chỉ 1 dòng chung chung bị đè liên tục bởi tháng nào báo sau cùng.
            def _progress_thang(t):
                if progress:
                    progress(f"[THÁNG {s_from}→{s_to}] {t}")
            _progress_thang("đang tải...")
            dung_chung = mtt_limiter if he_thong == "sco-query" else None
            if dung_chung:
                dung_chung.acquire()
            try:
                ket_qua = self._query_one_range(
                    s_from, s_to, loai, page_size, he_thong, progress=_progress_thang,
                    cancel_check=cancel_check)
            finally:
                if dung_chung:
                    dung_chung.release()
            _progress_thang("✓ xong")
            return s_from, s_to, ket_qua

        with _cf.ThreadPoolExecutor(max_workers=so_luong_song_song) as ex:
            futs = [ex.submit(_xu_ly_thang, s_from, s_to) for s_from, s_to in cac_thang]
            for fut in _cf.as_completed(futs):
                try:
                    s_from, s_to, ket_qua = fut.result()
                except Exception as e:
                    if "CANCELLED" in str(e):
                        break   # dừng gộp thêm — với-block vẫn đợi các tháng còn lại tự thoát nhanh
                    raise
                _gop(s_from, s_to, ket_qua)
                if progress:
                    progress(f"đã lấy {len(all_results)} tờ (lũy kế, vừa xong {s_to})")
        # LỖI THẬT SỰ ở 1 phần (vd 1 trạng thái mua vào lỗi hẳn dù đã thử lại) —
        # khác với "0 kết quả" hợp lệ; người gọi (_run_fetch_job) dùng để KHÔNG
        # báo "Hoàn tất" như bình thường mà cảnh báo rõ có thể thiếu dữ liệu.
        # Trả về TRỰC TIẾP qua tuple (KHÔNG qua self.last_query_* nữa) — từ khi
        # mua vào/bán ra (× thường/máy tính tiền) có thể chạy SONG SONG với
        # nhau trên CÙNG 1 client (xem _run_fetch_job), lưu qua thuộc tính
        # instance sẽ bị 1 tổ hợp khác GHI ĐÈ trước khi tổ hợp này kịp đọc lại.
        return all_results, total_expected, loi_tich_luy, cac_doan_loi

    def _toan_ky_rong(self, tu_ngay, den_ngay, loai, he_thong, page_size, progress=None,
                      cancel_check=None):
        """True nếu TOÀN khoảng ngày CHẮC CHẮN không có hóa đơn nào (tổng = 0).
        Chỉ đếm nhanh (size=1) trên CẢ khoảng ngày, không dò từng tháng. Trả
        False nếu có hóa đơn HOẶC không đếm chắc chắn được (khi đó dò đầy đủ)."""
        base = f"https://hoadondientu.gdt.gov.vn/api/{he_thong}"
        is_mtt = (he_thong == "sco-query")
        date_filter = (f"tdlap=ge={tu_ngay}T00:00:00;tdlap=le={den_ngay}T23:59:59")
        if loai == "purchase":
            url = f"{base}/invoices/purchase"
            action = "Tìm kiếm (hóa đơn %smua vào)" % ("máy tính tiền " if is_mtt else "")
            # mua vào phân theo 3 trạng thái — CHỈ coi là rỗng khi CẢ 3 đều = 0.
            # Chạy SONG SONG cả 3 (thay vì lần lượt + nghỉ giữa mỗi lần) — kiểm
            # tra nhanh này CHỈ áp dụng cho máy tính tiền (is_mtt), là hệ thống
            # phản hồi chậm hơn hẳn hóa đơn điện tử thường; làm tuần tự 3 lần
            # (mỗi lần có thể tự thử lại nhiều lần nếu mạng trục trặc) sẽ cộng
            # dồn thời gian chờ, khiến kiểm tra nhanh không còn "nhanh" nữa —
            # đây chính là phần việc THÊM RIÊNG cho máy tính tiền mà hóa đơn
            # điện tử thường không phải làm, nên cần giảm tối đa thời gian.
            with _cf.ThreadPoolExecutor(max_workers=3) as ex:
                tongs = list(ex.map(
                    lambda tt: self._dem_tong_nhanh(
                        url, f"{date_filter};ttxly=={tt}", action, progress,
                        cancel_check=cancel_check),
                    (5, 6, 8)))
            for tong in tongs:
                if tong is None or tong > 0:
                    return False   # không chắc hoặc có hóa đơn -> dò đầy đủ
            return True
        else:
            url = f"{base}/invoices/sold"
            action = "Tìm kiếm (hóa đơn %sbán ra)" % ("máy tính tiền " if is_mtt else "")
            tong = self._dem_tong_nhanh(url, date_filter, action, progress, cancel_check=cancel_check)
            return tong == 0   # None (không chắc) -> False -> dò đầy đủ

    def _query_one_range(self, tu_ngay, den_ngay, loai="purchase",
                         page_size=50, he_thong="query", progress=None,
                         ttxly_can_do=None, cancel_check=None):
        """
        Tra cứu 1 khoảng ngày (<= 31 ngày).
        Khớp đúng cURL thật từ hoadondientu.gdt.gov.vn:
          HĐ điện tử : /api/query/invoices/{purchase,sold}
          HĐ máy tính tiền: /api/sco-query/invoices/{purchase,sold}
        Mua vào được phân theo trạng thái xử lý (ttxly): 5, 6, 8 -> gọi từng cái và gộp.
        ttxly_can_do: khi RETRY 1 đoạn cụ thể, CHỈ dò đúng (các) trạng thái đã
          lỗi trước đó (tuple số) thay vì mặc định cả 3.

        Trả về TUPLE (results, total, loi_rieng_phan, ttxly_that_bai_phan) —
        KHÔNG còn ghi qua self._last_total/self._loi_rieng_phan/... (thuộc
        tính instance) nữa, vì hàm này có thể được gọi ĐỒNG THỜI từ nhiều
        luồng khác nhau (nhiều tháng/đoạn chạy song song) trên CÙNG 1 client
        — ghi qua thuộc tính chung sẽ bị luồng khác ghi đè/đọc nhầm giữa
        chừng (race condition). Trả về qua giá trị hàm thì an toàn tuyệt đối.
        """
        base = f"https://hoadondientu.gdt.gov.vn/api/{he_thong}"
        is_mtt = (he_thong == "sco-query")
        date_filter = (f"tdlap=ge={tu_ngay}T00:00:00;"
                       f"tdlap=le={den_ngay}T23:59:59")

        def _thu_lai(fn, so_lan=2):
            """Gọi fn() tối đa so_lan lần (nghỉ giữa các lần) trước khi bỏ cuộc.
            TOKEN_EXPIRED/CANCELLED thì raise ngay, không cần thử lại."""
            last_err = None
            for i in range(so_lan):
                try:
                    return fn()
                except Exception as e:
                    if "TOKEN_EXPIRED" in str(e) or "CANCELLED" in str(e):
                        raise
                    last_err = e
                    if i < so_lan - 1:
                        time.sleep(SP()["retry_base"])
            raise last_err

        if loai == "purchase":
            url = f"{base}/invoices/purchase"
            action = "Tìm kiếm (hóa đơn %smua vào)" % ("máy tính tiền " if is_mtt else "")
            # Các trạng thái xử lý hóa đơn mua vào (mỗi cái là 1 lần gọi riêng):
            #   5 = tổng hợp/đã cấp mã, 6 = đã nhận không mã, 8 = HĐ có rủi ro...
            ttxly_can_do = ttxly_can_do or (5, 6, 8)
            results = []
            seen = set()
            total_all = 0
            loi_trang_thai = []   # mô tả LỖI THẬT SỰ (không phải rỗng) -> báo cho người dùng biết
            ttxly_that_bai = []   # CÁC SỐ trạng thái bị lỗi (để RETRY ĐÚNG đoạn đó, không dò lại cả tháng)
            for ttxly in ttxly_can_do:
                if cancel_check and cancel_check():
                    raise Exception("CANCELLED")
                search = f"{date_filter};ttxly=={ttxly}"
                try:
                    part, ptotal = _thu_lai(lambda: self._fetch_paginated(
                        url, search, action, page_size, want_total=True, progress=progress,
                        cancel_check=cancel_check))
                    if ptotal:
                        total_all += ptotal
                except Exception as e:
                    # Đã thử lại rồi vẫn lỗi -> GHI NHẬN LÀ LỖI (không coi như "không có"),
                    # để người gọi biết kết quả có thể THIẾU chứ không phải chắc chắn = 0.
                    # KHÔNG raise (trừ TOKEN_EXPIRED/CANCELLED) — để các trạng thái/tháng
                    # KHÁC vẫn được dò tiếp, không mất trắng dữ liệu đã lấy được vì 1 lỗi cục bộ.
                    if "TOKEN_EXPIRED" in str(e) or "CANCELLED" in str(e):
                        raise
                    part = []
                    loi_trang_thai.append(f"ttxly={ttxly}: {str(e)[:120]}")
                    ttxly_that_bai.append(ttxly)
                for inv in part:
                    key = (inv.get("khmshdon"), inv.get("khhdon"),
                           inv.get("shdon"), inv.get("nbmst"))
                    if key not in seen:
                        seen.add(key)
                        results.append(inv)
                time.sleep(SP()["status"])  # nghỉ giữa các trạng thái
            return results, total_all, loi_trang_thai, ttxly_that_bai
        else:
            url = f"{base}/invoices/sold"
            action = "Tìm kiếm (hóa đơn %sbán ra)" % ("máy tính tiền " if is_mtt else "")
            # KHÔNG để lỗi lan ra ngoài (raise) nữa — trước đây 1 tháng lỗi hẳn
            # (dù đã thử lại nội bộ) làm MẤT TRẮNG toàn bộ kết quả các tháng
            # KHÁC đã lấy thành công trong CÙNG 1 lượt gọi query_invoices (vì
            # ngoại lệ văng ra khỏi cả vòng lặp nhiều tháng). Ghi nhận là lỗi
            # riêng phần giống mua vào, để tháng này được RETRY RIÊNG sau, các
            # tháng khác vẫn giữ nguyên kết quả.
            try:
                results, total = _thu_lai(lambda: self._fetch_paginated(
                    url, date_filter, action, page_size, want_total=True, progress=progress,
                    cancel_check=cancel_check))
                return results, total, [], []
            except Exception as e:
                if "TOKEN_EXPIRED" in str(e) or "CANCELLED" in str(e):
                    raise
                # sold không có ttxly -> đánh dấu cả tháng lỗi (ttxly=None)
                return [], 0, [str(e)[:120]], [None]

    def _dem_tong_nhanh(self, url, search, action, progress=None, cancel_check=None):
        """ĐẾM NHANH tổng số hóa đơn của 1 truy vấn — chỉ gọi 1 trang size=1 để
        đọc trường 'total', KHÔNG phân trang lấy hết dữ liệu. Dùng để PHÁT HIỆN
        SỚM khoảng ngày RỖNG (đặc biệt hóa đơn máy tính tiền — nhiều công ty
        không hề dùng — để khỏi dò từng tháng × 3 trạng thái rất lâu cho con số
        0). Trả về int total nếu chắc chắn (kể cả 0); None nếu KHÔNG chắc (lỗi
        mạng/429...) -> người gọi nên dò đầy đủ bình thường cho an toàn.
        TOKEN_EXPIRED thì raise để dừng cả tiến trình.
        cancel_check: callable() -> bool, gọi lại để kiểm tra người dùng đã
        hủy tra cứu (vd chuyển sang công ty khác) chưa — nếu có, raise CANCELLED
        NGAY thay vì cứ thử lại vô tận, để tiến trình dừng thật sự chứ không
        chỉ dừng hiển thị ở giao diện trong khi vẫn âm thầm chạy nền."""
        from urllib.parse import quote
        extra_headers = {
            "accept-language": "vi",
            "action": quote(action),
            "end-point": "/tra-cuu/tra-cuu-hoa-don",
            "referer": "https://hoadondientu.gdt.gov.vn/tra-cuu/tra-cuu-hoa-don",
        }
        qs = f"sort=tdlap:desc&size=1&search={quote(search, safe='=;,:/')}"
        full_url = f"{url}?{qs}"
        sp = SP()
        # KHÔNG bỏ cuộc sau 1 khoảng thời gian cố định nữa — trước đây nếu hệ
        # thống máy tính tiền chậm/lỗi mạng vặt quá 40s thì ĐẾM NHANH bỏ cuộc
        # (trả None) rồi rơi xuống dò ĐẦY ĐỦ (3 trạng thái x tải phân trang —
        # còn nặng hơn nhiều), khiến CẢ HAI bước (đếm nhanh + dò đầy đủ) đều
        # phải chờ, cảm giác treo liên tục dù tháng đó KHÔNG có hóa đơn nào.
        # Nay đếm nhanh cũng cứ THỬ LẠI ĐẾN KHI CÓ KẾT QUẢ (chờ cố định 3s mỗi
        # lần lỗi mạng) — vì bản thân request này rất nhẹ (size=1), rẻ hơn
        # nhiều so với dò đầy đủ, nên cứ chờ tới khi có câu trả lời rồi mới
        # quyết định bỏ qua hay dò đầy đủ, thay vì bỏ cuộc giữa chừng rồi vẫn
        # phải làm việc nặng hơn ngay sau đó.
        attempt = 0
        while True:
            if cancel_check and cancel_check():
                raise Exception("CANCELLED")
            attempt += 1
            try:
                r = self.session.get(full_url, headers=extra_headers, timeout=45)
            except Exception:
                if progress:
                    progress(f"đang kiểm tra nhanh kỳ này có hóa đơn không... (lần {attempt})")
                _ngu_ktra_huy(3, cancel_check)
                continue
            if r.status_code == 401:
                raise Exception("TOKEN_EXPIRED")
            if r.status_code == 429:
                ra = r.headers.get("Retry-After")
                try:
                    wait = int(ra) if ra else sp["retry_base"]
                except Exception:
                    wait = sp["retry_base"]
                _ngu_ktra_huy(min(wait, 30), cancel_check)
                continue
            if r.status_code != 200:
                return None   # 400/5xx... -> không chắc, để dò đầy đủ
            try:
                data = r.json()
            except Exception:
                return None
            tong = data.get("total")
            return int(tong) if isinstance(tong, (int, float)) else None

    def _fetch_paginated(self, url, search, action, page_size=50, want_total=False, progress=None,
                        cancel_check=None):
        """Gọi 1 endpoint với tham số search, tự phân trang và xử lý 429.
        want_total=True -> trả (results, total_kỳ_vọng) để kiểm tra đủ chưa.
        progress: callback(str) báo tiến độ khi đang chờ 429/lỗi mạng (tùy
        chọn) — để màn hình KHÔNG đứng yên như "đứng máy" trong lúc chờ.
        cancel_check: callable() -> bool — kiểm tra người dùng đã hủy tra cứu
        chưa (vd chuyển công ty khác giữa chừng); nếu có, raise CANCELLED
        ngay ở đầu mỗi trang/mỗi lần thử lại, KHÔNG cứ thử lại vô tận nữa —
        để việc "chuyển công ty khác" thực sự dừng hẳn tiến trình cũ đang
        chạy nền, thay vì chỉ ẩn khỏi giao diện mà vẫn âm thầm chạy tiếp."""
        from urllib.parse import quote
        extra_headers = {
            "accept-language": "vi",
            "action": quote(action),  # tiếng Việt -> URL-encode (header chỉ nhận latin-1)
            "end-point": "/tra-cuu/tra-cuu-hoa-don",
            "referer": "https://hoadondientu.gdt.gov.vn/tra-cuu/tra-cuu-hoa-don",
        }
        results = []
        state = None
        total_expected = None
        for _ in range(500):  # tối đa 500 trang an toàn
            if cancel_check and cancel_check():
                raise Exception("CANCELLED")
            qs = (f"sort=tdlap:desc&size={page_size}"
                  f"&search={quote(search, safe='=;,:/')}")
            if state:
                qs += f"&state={quote(str(state), safe='')}"
            full_url = f"{url}?{qs}"

            # Gọi có tự động thử lại khi bị 429 (Too Many Requests) HOẶC lỗi mạng
            # thoáng qua (mất kết nối/timeout) — trước đây CHỈ retry khi 429, nên
            # 1 lần rớt mạng ngẫu nhiên giữa chừng làm rớt luôn cả lượt tra cứu
            # (thường gặp nhất ở "bán ra" vì chỉ gọi 1 lần, không có nhiều lượt
            # dự phòng như "mua vào" theo từng trạng thái).
            # KHÔNG giới hạn số lần/tổng thời gian thử lại nữa — trước đây bỏ
            # cuộc sau 8 lần hoặc 75s rồi báo LỖI hẳn (dù trang Thuế/hệ thống
            # máy tính tiền chỉ đang chậm chứ không phải hỏng hẳn), khiến người
            # dùng phải tự tra cứu lại nhiều lần. Nay cứ THỬ LẠI ĐẾN KHI TẢI
            # ĐƯỢC (chờ cố định 3s giữa các lần lỗi mạng, không tăng dần) —
            # CHỈ dừng khi thật sự tải được, hoặc gặp lỗi KHÔNG THỂ retry
            # (token hết hạn / 400 — kiểm tra ở dưới, sau khi có response).
            r = None
            last_net_err = None
            sp = SP()
            attempt = 0
            so_lan_5xx_lien_tiep = 0   # đếm số lần lỗi 5xx LIÊN TIẾP (reset khi gặp loại khác)
            while True:
                if cancel_check and cancel_check():
                    raise Exception("CANCELLED")
                attempt += 1
                try:
                    # timeout 90s (không phải 60s) — hệ thống máy tính tiền có
                    # thể phân trang chậm dần theo offset khi tổng số hóa đơn
                    # lớn (vd "bán ra" hàng nghìn tờ); nếu timeout NGẮN HƠN
                    # thời gian trang Thuế thực sự cần để trả lời, request sẽ
                    # LUÔN bị hủy giữa chừng (Read timed out) và thử lại mãi
                    # mà không bao giờ kịp nhận được phản hồi — trông như lỗi
                    # mạng liên tục dù thực ra là do timeout đặt quá ngắn.
                    r = self.session.get(full_url, headers=extra_headers, timeout=90)
                except Exception as e:
                    last_net_err = e
                    r = None
                    # Lỗi mạng thoáng qua (mất kết nối/timeout, KHÁC với 429 bị
                    # giới hạn tốc độ ở dưới) -> chờ CỐ ĐỊNH 3s rồi thử lại ngay,
                    # KHÔNG tăng dần theo số lần thử — trước đây chờ tăng dần
                    # (4s, 8s, 12s...) khiến cảm giác "treo" rất lâu giữa các lần
                    # thử, nhất là hệ thống máy tính tiền hay bị lỗi mạng vặt.
                    # Ghi rõ LOẠI lỗi cụ thể (vd "Read timed out", "Connection
                    # reset", SSL...) vào log thay vì chỉ nói chung chung "lỗi
                    # mạng" — để biết chính xác đang gặp vấn đề gì mà xử lý.
                    so_lan_5xx_lien_tiep = 0
                    cho = 3
                    if progress:
                        progress(f"lỗi mạng ({type(e).__name__}: {str(e)[:100]}), "
                                 f"đợi {cho}s rồi thử lại (lần {attempt})...")
                    _ngu_ktra_huy(cho, cancel_check)
                    continue
                if r.status_code == 429:
                    so_lan_5xx_lien_tiep = 0
                    ra = r.headers.get("Retry-After")
                    try:
                        wait = int(ra) if ra else sp["retry_base"]
                    except Exception:
                        wait = sp["retry_base"]
                    wait = min(wait, 90)
                    if progress:
                        progress(f"bị Tổng cục Thuế giới hạn tốc độ (429), đợi {wait}s rồi "
                                 f"thử lại (lần {attempt})...")
                    _ngu_ktra_huy(wait, cancel_check)
                    continue
                if r.status_code >= 500:
                    # Lỗi PHÍA MÁY CHỦ Thuế (500/502/503/504...) — thường là quá
                    # tải/đang bảo trì TẠM THỜI (nhất là hệ thống máy tính tiền),
                    # không phải do request sai.
                    so_lan_5xx_lien_tiep += 1
                    if so_lan_5xx_lien_tiep == 1:
                        # LẦN ĐẦU gặp 5xx -> chỉ chờ 3s rồi TỰ THỬ LẠI BÌNH
                        # THƯỜNG (tuần tự, KHÔNG chạy song song với ai) — giống
                        # hệt cách xử lý gốc, chưa vội coi là bất thường.
                        if progress:
                            progress(f"lỗi máy chủ Thuế ({r.status_code}), đợi 3s rồi thử lại "
                                     f"(lần {attempt})...")
                        _ngu_ktra_huy(3, cancel_check)
                        continue
                    # Đã chờ 3s rồi thử lại nhưng VẪN lỗi 5xx (2 lần LIÊN TIẾP)
                    # — lúc này mới thử bằng 1 LUỒNG KHÁC xem kênh đó có bị lỗi
                    # không (có thể lỗi chỉ do đúng lượt gọi/kết nối đó, không
                    # phải toàn hệ thống đang sập). Làm TUẦN TỰ — chờ luồng
                    # khác xong rồi mới quyết định tiếp, KHÔNG chạy song song
                    # với lượt thử ban đầu.
                    if progress:
                        progress(f"vẫn lỗi máy chủ Thuế ({r.status_code}) sau khi đã thử lại — "
                                 f"đang thử bằng 1 luồng khác xem có bị lỗi không...")
                    ket_qua_phu = {}

                    def _thu_luong_khac():
                        try:
                            ket_qua_phu["r"] = self.session.get(full_url, headers=extra_headers, timeout=90)
                        except Exception as e2:
                            ket_qua_phu["err"] = e2

                    t_khac = threading.Thread(target=_thu_luong_khac, daemon=True)
                    t_khac.start()
                    while t_khac.is_alive():
                        if cancel_check and cancel_check():
                            raise Exception("CANCELLED")
                        t_khac.join(timeout=0.5)
                    r_khac = ket_qua_phu.get("r")
                    so_lan_5xx_lien_tiep = 0   # dù kết quả thế nào cũng bắt đầu chu kỳ đếm mới
                    if r_khac is not None and r_khac.status_code < 500 and r_khac.status_code != 429:
                        # Luồng khác THÀNH CÔNG (không lỗi máy chủ/giới hạn tốc
                        # độ) -> dùng luôn kết quả này, bỏ qua luồng cũ bị lỗi.
                        if progress:
                            progress(f"✓ luồng khác tải được (không bị {r.status_code}) — dùng luôn, "
                                     f"bỏ qua luồng bị lỗi")
                        r = r_khac
                        break
                    # Luồng khác CŨNG lỗi -> coi như hệ thống thật sự đang quá
                    # tải toàn diện, quay lại chờ 3s rồi thử lại bình thường.
                    if progress:
                        progress(f"luồng khác cũng bị lỗi — đợi 3s rồi thử lại (lần {attempt})...")
                    _ngu_ktra_huy(3, cancel_check)
                    continue
                break

            if r.status_code == 401:
                raise Exception("TOKEN_EXPIRED")
            if r.status_code == 400:
                raise Exception(
                    f"Trang Thuế từ chối (400). Thử thu hẹp khoảng ngày "
                    f"(mỗi lần tối đa 1 tháng). Chi tiết: {r.text[:150]}")
            r.raise_for_status()
            data = r.json()
            datas = data.get("datas", []) or []
            results.extend(datas)
            # tổng số hóa đơn kỳ vọng (trang Thuế trả 'total')
            if total_expected is None:
                total_expected = data.get("total")
            # Báo tiến độ SỐ LƯỢNG hóa đơn đang lấy được / còn lại — trước đây
            # chỉ có dòng "đang tải..." đứng yên trong lúc phân trang (có thể
            # mất nhiều giây/phút với kỳ nhiều hóa đơn), người dùng không biết
            # đã lấy được bao nhiêu, còn lại bao nhiêu.
            if progress:
                if total_expected:
                    con_lai = max(0, total_expected - len(results))
                    progress(f"đang tải danh sách... đã lấy {len(results)}/{total_expected} "
                             f"hóa đơn (còn {con_lai})")
                else:
                    progress(f"đang tải danh sách... đã lấy {len(results)} hóa đơn")
            state = data.get("state")
            if not state or len(datas) == 0:
                break
            time.sleep(sp["page"])  # nghỉ giữa các trang

        # KIỂM TRA ĐỦ CHƯA: nếu trang Thuế báo total nhiều hơn số lấy được,
        # thử phân trang lại 1 lần nữa (phòng trang bị lỗi giữa chừng).
        # CHỈ áp dụng khi đã lấy được ÍT NHẤT 1 hóa đơn nhưng còn thiếu — tức
        # là dấu hiệu thật sự của "phân trang bị đứt giữa chừng". Nếu lấy
        # được 0 hóa đơn thì KHÔNG chạy lại: trang Thuế thường trả 'total'
        # > 0 dù 'datas' rỗng (total không lọc đúng theo trạng thái/kỳ thực
        # tế đang truy vấn) — trước đây cứ thấy total>0 mà results=0 là chạy
        # lại TOÀN BỘ phân trang (tối đa 500 trang, chờ 429 không giới hạn số
        # lần thử) nên các kỳ KHÔNG có hóa đơn lại chậm hơn hẳn kỳ có hóa đơn.
        if (total_expected and 0 < len(results) < total_expected):
            try:
                retry_results = []
                state2 = None
                so_lan_429 = 0
                # GIỚI HẠN TỔNG THỜI GIAN cho cả vòng retry này — trước đây CHỈ
                # giới hạn số trang (500) và số lần 429 (retry_max), không giới
                # hạn THỜI GIAN, nên nếu mỗi trang đều mất gần 60s (timeout) mà
                # KHÔNG lỗi hẳn (vd trang Thuế phản hồi rất chậm), vòng lặp có
                # thể "treo" hàng giờ mà người dùng chỉ thấy 1 dòng tiến độ đứng
                # yên — trông như phần mềm bị đơ dù thực ra vẫn đang thử lại.
                t_bat_dau_fallback = time.time()
                NGUONG_FALLBACK = 90  # giây
                for _ in range(500):
                    if time.time() - t_bat_dau_fallback > NGUONG_FALLBACK:
                        if progress:
                            progress("đã thử lại quá lâu, dùng tạm kết quả hiện có...")
                        break
                    if cancel_check and cancel_check():
                        break
                    qs = (f"sort=tdlap:desc&size={page_size}"
                          f"&search={quote(search, safe='=;,:/')}")
                    if state2:
                        qs += f"&state={quote(str(state2), safe='')}"
                    r2 = self.session.get(f"{url}?{qs}", headers=extra_headers, timeout=60)
                    if r2.status_code == 429:
                        so_lan_429 += 1
                        if so_lan_429 > SP()["retry_max"]:
                            break
                        wait2 = min(SP()["retry_base"] * 2, 90)
                        if progress:
                            progress(f"bị giới hạn tốc độ (429), đợi {wait2}s rồi thử lại "
                                     f"(lần {so_lan_429}/{SP()['retry_max']})...")
                        _ngu_ktra_huy(wait2, cancel_check); continue
                    if r2.status_code != 200:
                        break
                    d2 = r2.json()
                    retry_results.extend(d2.get("datas", []) or [])
                    state2 = d2.get("state")
                    if not state2:
                        break
                    time.sleep(SP()["page"])
                # gộp, khử trùng
                seen = {(x.get("khmshdon"), x.get("khhdon"), x.get("shdon"), x.get("nbmst"))
                        for x in results}
                for inv in retry_results:
                    k = (inv.get("khmshdon"), inv.get("khhdon"), inv.get("shdon"), inv.get("nbmst"))
                    if k not in seen:
                        seen.add(k); results.append(inv)
            except Exception:
                pass

        if want_total:
            return results, total_expected
        return results

    # --- Tải file XML của 1 hóa đơn ---
    def download_xml(self, nbmst, khhdon, khmshdon, shdon, loai="purchase",
                     he_thong="query", max_retry=None):
        """Tải file invoice.zip (chứa XML + invoice.html) của 1 hóa đơn từ TCT.
        Endpoint thật: /api/{he_thong}/invoices/export-xml?nbmst=&khhdon=&shdon=&khmshdon=
        (không có tham số type).
        TRƯỚC ĐÂY hàm này KHÔNG hề thử lại — 1 lần bị 429/rớt mạng là mất file đó
        vĩnh viễn (không lỗi, không log, chỉ đơn giản không có file). Với hàng
        nghìn hóa đơn tải liên tiếp, chỉ cần bị chặn tốc độ giữa chừng là MẤT
        HẲN các file còn lại từ điểm đó. Nay tự thử lại như get_detail."""
        base = f"https://hoadondientu.gdt.gov.vn/api/{he_thong}"
        url = f"{base}/invoices/export-xml"
        params = {
            "nbmst": nbmst, "khhdon": khhdon,
            "shdon": shdon, "khmshdon": khmshdon,
        }
        extra_headers = {
            "accept-language": "vi",
            "action": "Xuat xml",
            "end-point": "/tra-cuu/tra-cuu-hoa-don",
            "referer": "https://hoadondientu.gdt.gov.vn/tra-cuu/tra-cuu-hoa-don",
        }
        sp = SP()
        so_lan = max_retry if max_retry else sp["retry_max"]
        last_err = None
        t_bat_dau_thu = time.time()
        NGUONG_THOI_GIAN_THU_LAI = 150  # giây — chặn cộng dồn khi hệ thống (vd
                                          # máy tính tiền) phản hồi chậm/treo liên tục
        for attempt in range(so_lan):
            if time.time() - t_bat_dau_thu > NGUONG_THOI_GIAN_THU_LAI:
                break
            try:
                r = self.session.get(url, params=params, headers=extra_headers, timeout=90)
            except Exception as e:
                last_err = e
                time.sleep(min(sp["retry_base"] * (attempt + 1), 60))
                continue
            if r.status_code == 200 and r.content[:5] not in (b'{"mes', b'{"err'):
                return r.content  # bytes của file zip
            if r.status_code == 401:
                self._token_dead = True
                return None   # hết phiên, thử lại vô ích
            if r.status_code == 429:
                ra = r.headers.get("Retry-After")
                try:
                    wait = int(ra) if ra else sp["retry_base"] * (attempt + 1)
                except Exception:
                    wait = sp["retry_base"] * (attempt + 1)
                time.sleep(min(wait, 60))
                continue
            last_err = f"status={r.status_code}"
            time.sleep(sp["retry_base"])
        return None

    def get_detail(self, nbmst, khhdon, khmshdon, shdon, he_thong="query",
                   max_retry=None, cho_khi_429=True, loai=None):
        """Lấy JSON chi tiết đầy đủ 1 hóa đơn — CÙNG API với nút "Xem hóa đơn"
        trên trang Thuế (chỉ xem dữ liệu, không phải in/tải file).
        max_retry: giới hạn số lần thử (khi xuất Excel hàng loạt -> đặt nhỏ để
        1 hóa đơn lỗi không làm nghẽn cả luồng nhiều phút).
        cho_khi_429: True (mặc định) -> gặp 429 thì CHỜ theo Retry-After rồi thử lại
        (dùng cho tra cứu tương tác, không vội). False -> BỎ QUA NGAY khi bị giới
        hạn tốc độ, không chờ (dùng cho xuất Excel hàng loạt hàng nghìn hóa đơn,
        để 1 lượt rớt không kéo cả tiến trình chờ hàng chục phút).
        loai: 'purchase'/'sold' — để gửi header action ĐÚNG HỆT trình duyệt."""
        from urllib.parse import quote
        base = f"https://hoadondientu.gdt.gov.vn/api/{he_thong}"
        url = f"{base}/invoices/detail"
        params = {
            "nbmst": nbmst, "khhdon": khhdon,
            "shdon": shdon, "khmshdon": khmshdon,
        }
        # Header action GIỐNG HỆT trình duyệt thật khi bấm "Xem hóa đơn" (đã
        # đối chiếu request thực tế): tiếng Việt có dấu + URL-encode. Trước
        # đây gửi "Xem hoa don" không dấu — khác chữ ký trình duyệt, dễ bị
        # tường lửa trang Thuế nhận diện là truy cập tự động.
        if loai == "purchase":
            act = "Xem hóa đơn (hóa đơn mua vào)"
        elif loai == "sold":
            act = "Xem hóa đơn (hóa đơn bán ra)"
        else:
            act = "Xem hóa đơn"
        extra_headers = {
            "accept-language": "vi",
            # safe="()": trình duyệt thật KHÔNG mã hóa dấu ngoặc trong header này
            "action": quote(act, safe="()"),
            "end-point": "/tra-cuu/tra-cuu-hoa-don",
            "referer": "https://hoadondientu.gdt.gov.vn/tra-cuu/tra-cuu-hoa-don",
        }
        sp = SP()
        so_lan = max_retry if max_retry else sp["retry_max"]
        for attempt in range(so_lan):
            try:
                r = self.session.get(url, params=params,
                                     headers=extra_headers, timeout=60)
                if r.status_code == 200:
                    return r.json()
                if r.status_code == 401:
                    self._token_dead = True
                    return None  # token hết hạn, không retry vô ích
                if r.status_code == 429:
                    if not cho_khi_429:
                        return None   # bỏ ngay, không chờ (chế độ nhanh)
                    ra = r.headers.get("Retry-After")
                    try:
                        wait = int(ra) if ra else sp["retry_base"] * (attempt + 1)
                    except Exception:
                        wait = sp["retry_base"] * (attempt + 1)
                    time.sleep(min(wait, 60))
                    continue
                if not cho_khi_429:
                    return None
                # các lỗi khác (5xx...) -> chờ ngắn rồi thử lại
                time.sleep(sp["retry_base"])
            except Exception:
                if not cho_khi_429:
                    return None
                time.sleep(sp["retry_base"])
        return None



# Mỗi công ty giữ 1 client riêng trong RAM (theo phiên token)
CLIENTS = {}  # {company_id: GDTClient}
FETCH_JOBS = {}  # {company_id: {messages, last, running, ...}} - tiến độ tra cứu nền

def get_client(company_id) -> GDTClient:
    if company_id not in CLIENTS:
        CLIENTS[company_id] = GDTClient()
    return CLIENTS[company_id]


