#  DỊCH VỤ CÔNG (dichvucong.gdt.gov.vn)
#  Tự đăng nhập + tải tờ khai / báo cáo ĐÃ NỘP về máy.
#  *** Tính năng thử nghiệm — làm dần, sửa dần ***
#  Cổng có WAF (F5 BIG-IP) + XSRF token + 2 lớp captcha nên có thể
#  cần điều chỉnh sau khi chạy thực tế. Mọi hàm đều trả về thông tin
#  chẩn đoán để dễ dò lỗi.
# ============================================================
DVC_BASE = "https://dichvucong.gdt.gov.vn/tthc"
DVC_CLIENTS = {}   # cid -> DVCClient (giữ phiên đăng nhập)

class DVCClient:
    UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
          "(KHTML, like Gecko) Chrome/149.0.0.0 Safari/537.36")

    SECCH = {
        "sec-ch-ua": '"Google Chrome";v="149", "Chromium";v="149", "Not)A;Brand";v="24"',
        "sec-ch-ua-mobile": "?0",
        "sec-ch-ua-platform": '"Windows"',
    }

    def __init__(self):
        # WAF F5 chặn theo dấu vân tay TLS/JA3 -> dùng curl_cffi giả lập Chrome thật
        # nếu có; không thì lùi về requests thường.
        self.impersonate = False
        try:
            from curl_cffi import requests as _cffi
            self.session = _cffi.Session(impersonate="chrome")
            self.impersonate = True
            # curl_cffi đã tự đặt UA + sec-ch-ua khớp vân tay -> chỉ thêm ngôn ngữ
            self.session.headers.update({
                "Accept-Language": "vi,en-US;q=0.9,en;q=0.8,vi-VN;q=0.7",
            })
        except Exception:
            self.session = requests.Session()
            self.session.headers.update({
                "User-Agent": self.UA,
                "Accept-Language": "vi,en-US;q=0.9,en;q=0.8,vi-VN;q=0.7",
                "Accept": "*/*",
                "Upgrade-Insecure-Requests": "1",
                **self.SECCH,
            })
        self.primed = False
        self.logged_in = False
        self.prime_diag = {}

    def _xsrf(self):
        # Spring/Angular: XSRF-TOKEN nằm trong cookie, gửi lại qua header.
        # requests.Session tự cập nhật cookie mỗi response nên luôn lấy giá trị mới nhất.
        try:
            return self.session.cookies.get("XSRF-TOKEN", "") or ""
        except Exception:
            # cookie có thể trùng tên ở nhiều domain/path
            for c in self.session.cookies:
                if c.name == "XSRF-TOKEN":
                    return c.value or ""
            return ""

    def prime(self):
        """Vào trang chủ rồi trang login như trình duyệt để WAF (F5 BIG-IP) cấp
        cookie TS01.../JSESSIONID/XSRF. Ghi lại chẩn đoán để dò lỗi."""
        nav = {
            "Accept": ("text/html,application/xhtml+xml,application/xml;q=0.9,"
                       "image/avif,image/webp,image/apng,*/*;q=0.8"),
            "Sec-Fetch-Dest": "document",
            "Sec-Fetch-Mode": "navigate",
            "Sec-Fetch-Site": "none",
            "Sec-Fetch-User": "?1",
        }
        diag = {"buoc": []}
        last = None
        for path in ("/homelogin", "/login"):
            try:
                r = self.session.get(DVC_BASE + path, headers=nav, timeout=30,
                                     allow_redirects=True)
                last = r
                diag["buoc"].append({"url": path, "status": r.status_code,
                                     "len": len(r.content or b"")})
                nav = dict(nav); nav["Sec-Fetch-Site"] = "same-origin"
                nav["Referer"] = DVC_BASE + path
            except Exception as e:
                diag["buoc"].append({"url": path, "loi": f"{type(e).__name__}: {e}"})
            time.sleep(0.3)
        try:
            names = [getattr(c, "name", c) for c in self.session.cookies]
            diag["cookies"] = sorted(str(n) for n in names)
        except Exception:
            diag["cookies"] = []
        diag["co_waf"] = any(str(n).startswith("TS") for n in diag["cookies"])
        diag["co_xsrf"] = bool(self._xsrf())
        diag["tls_chrome"] = self.impersonate
        self.prime_diag = diag
        self.primed = True
        return last

    def get_captcha_png(self, referer="/login"):
        """Tải 1 ảnh captcha (PNG bytes). Tự rasterize nếu server trả SVG."""
        ts = int(time.time() * 1000)
        h = {
            "Accept": "image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8",
            "Referer": DVC_BASE + referer,
            "Sec-Fetch-Dest": "image",
            "Sec-Fetch-Mode": "no-cors",
            "Sec-Fetch-Site": "same-origin",
        }
        r = self.session.get(f"{DVC_BASE}/getCaptcha?{ts}", headers=h, timeout=30)
        r.raise_for_status()
        ct = (r.headers.get("content-type") or "").lower()
        data = r.content or b""
        head = data[:300].lstrip().lower()
        if "svg" in ct or head.startswith(b"<svg") or b"<svg" in head:
            png = _svg_to_png(data.decode("utf-8", "replace"))
            return png or data
        # đôi khi trả JSON {content: "data:image..."} như cổng hóa đơn
        if "json" in ct:
            try:
                j = r.json()
                cont = j.get("content") or j.get("image") or ""
                if cont.startswith("data:"):
                    b64 = cont.split(",", 1)[1]
                    return base64.b64decode(b64)
            except Exception:
                pass
        return data

    def solve_captcha(self, referer="/login"):
        png = self.get_captcha_png(referer)
        return _ocr_png(png)

    def _post_headers(self, json_body=False, referer="/login"):
        h = {
            "X-Requested-With": "XMLHttpRequest",
            "Origin": "https://dichvucong.gdt.gov.vn",
            "Referer": DVC_BASE + referer,
            "Sec-Fetch-Dest": "empty",
            "Sec-Fetch-Mode": "cors",
            "Sec-Fetch-Site": "same-origin",
        }
        tok = self._xsrf()
        if tok:
            h["X-XSRF-TOKEN"] = tok
        h["Content-Type"] = ("application/json"
                             if json_body
                             else "application/x-www-form-urlencoded; charset=UTF-8")
        return h

    def login(self, mst, password, captcha):
        ten_dn = f"{_chuan_mst(mst) or mst}-QL"
        mat_khau = base64.b64encode((password or "").encode("utf-8")).decode("ascii")
        data = {"tenDN": ten_dn, "matKhau": mat_khau,
                "doiTuong": "DN", "captcha": captcha}
        r = self.session.post(DVC_BASE + "/loginLDAP", data=data,
                              headers=self._post_headers(False), timeout=40)
        return r

    def search(self, tu_ngay, den_ngay, captcha):
        """tu_ngay/den_ngay định dạng dd/mm/yyyy. Trả response (HTML bảng hồ sơ)."""
        params = {
            "maNghiepVu": "", "maTTHC": "", "maToKhai": "", "maHoSo": "",
            "tuNgay": tu_ngay, "denNgay": den_ngay,
            "scope_tdt1": "SELF", "mstUyQuyen_tdt1": "", "captcha": captcha,
        }
        r = self.session.get(DVC_BASE + "/ho-so/search", params=params,
                             headers={"X-Requested-With": "XMLHttpRequest",
                                      "Referer": DVC_BASE + "/tchs",
                                      "Sec-Fetch-Dest": "empty",
                                      "Sec-Fetch-Mode": "cors",
                                      "Sec-Fetch-Site": "same-origin"},
                             timeout=60)
        return r

    def download_hoso(self, ma_ho_so):
        h = self._post_headers(True)
        h["Referer"] = f"{DVC_BASE}/tchs/files/detail/{ma_ho_so}?loai="
        r = self.session.post(DVC_BASE + "/tchs/downloadhoso",
                              data=json.dumps({"maHoSo": ma_ho_so}),
                              headers=h, timeout=180)
        return r


def get_dvc_client(cid):
    c = DVC_CLIENTS.get(cid)
    if c is None:
        c = DVCClient()
        DVC_CLIENTS[cid] = c
    return c


def _dvc_parse_ma_ho_so(html):
    """Bóc các mã hồ sơ (maHoSo) từ HTML kết quả tra cứu. Giữ thứ tự, khử trùng."""
    import re as _re
    found, seen = [], set()
    # Mã hồ sơ có nhiều định dạng:
    #   quý : G12.18-260424-00039970            (bắt đầu bằng chữ)
    #   năm : 000.701.18.G12-260330-27012345    (bắt đầu bằng số, nhiều nhóm)
    # -> mẫu chung: các nhóm chữ-số nối bằng dấu chấm, rồi -6số-(nhiều số)
    pats = [
        r'[A-Z0-9]+(?:\.[A-Z0-9]+)+-\d{6}-\d{3,}',
        r"downloadHoSo\(\s*['\"]([^'\"]+)['\"]",
        r'(?:files/detail/)([A-Za-z0-9.\-]{8,60})',
        r'(?:idTKhai|maHoSo)["\'=: ]+([A-Za-z0-9.\-]{8,60})',
    ]
    for i, p in enumerate(pats):
        for m in _re.findall(p, html):
            val = m if isinstance(m, str) else (m[0] if m else "")
            val = val.strip().rstrip("?").split("?")[0]
            if val and val not in seen:
                seen.add(val)
                found.append(val)
        if found and i == 0:
            break   # mẫu chính đã bắt được thì dùng luôn
    return found


def _dvc_parse_id_tbao(html):
    """Bóc idTbao của các thông báo (Tiếp nhận / Xác nhận) trong trang chi tiết hồ sơ.
    Trả về list (idTbao, loaiTBao_đoán)."""
    import re as _re
    ids, seen = [], set()
    pats = [
        r'idTbao["\'\s:=]+["\']?(\d{12,22})',
        r'(?:downloadThongBao|taiThongBao|downloadTB|taiTB|xemThongBao)\(\s*["\']?(\d{12,22})',
        r'data-id-?tbao=["\'](\d{12,22})',
        r'data-id=["\'](\d{14,22})',
    ]
    for p in pats:
        for m in _re.findall(p, html, _re.IGNORECASE):
            if m and m not in seen:
                seen.add(m); ids.append(m)
    return ids


def _chuan_ngay_het_han(s):
    """Chuẩn hoá chuỗi 'Ngày hết hạn' CKS (nhiều định dạng có thể gặp trên
    trang, vd '2028-11-07 00:00:00.0' hoặc '07/11/2028') về ISO yyyy-mm-dd
    để lưu/so sánh/sắp xếp. Trả '' nếu không nhận dạng được."""
    import re as _re
    s = str(s or "").strip()
    if not s:
        return ""
    m = _re.match(r'^(\d{4})-(\d{1,2})-(\d{1,2})', s)
    if m:
        y, mo, d = m.groups()
        return f"{y}-{int(mo):02d}-{int(d):02d}"
    m = _re.match(r'^(\d{1,2})/(\d{1,2})/(\d{4})', s)
    if m:
        d, mo, y = m.groups()
        return f"{y}-{int(mo):02d}-{int(d):02d}"
    return ""


def _dvc_parse_token_info(rows_from_js):
    """rows_from_js: list {cells, section} (từ _JS_PARSE_TOKEN_TABLES) — mỗi
    dòng kèm 'section' = tên mục cha gần nhất trên trang ('Thông tin khai
    thuế'/'Thông tin nộp thuế'/'Thông tin hóa đơn'...). Trang "Quản lý thông
    tin" CÓ NHIỀU bảng "Thông tin chứng thư số" ở CÁC MỤC KHÁC NHAU — đã xác
    nhận qua ảnh chụp thật của người dùng: mục "Thông tin khai thuế" có CKS
    THẬT đang dùng để khai/nộp tờ khai; mục "Thông tin nộp thuế" là CKS
    KHÁC (không liên quan khai thuế) — THEO ĐÚNG YÊU CẦU: CHỈ lấy CKS ở mục
    "Thông tin khai thuế", TUYỆT ĐỐI KHÔNG lấy ở mục "Thông tin nộp thuế" dù
    bảng đó có dữ liệu (trước đây lấy nhầm/bỏ sót vì chỉ đọc theo thứ tự
    bảng xuất hiện, không phân biệt được đang ở mục nào -> có lúc bỏ trống
    Hạn Token dù công ty CÓ CKS hợp lệ ở đúng mục khai thuế).
    Trả (to_chuc_cap, ngay_het_han_iso) hoặc (None, None) nếu không có."""
    def _khong_dau_an_toan(s):
        return _khong_dau(str(s or ""))

    def _tim_bang(nhan_muc):
        """nhan_muc(section_khong_dau) -> True nếu mục này được PHÉP dùng.
        Trả kết quả bảng ĐẦU TIÊN (theo thứ tự trang) vừa khớp mục vừa có dữ
        liệu thật; bảng rỗng hoặc sai mục thì bỏ qua, thử bảng tiếp theo."""
        i = 0
        n = len(rows_from_js)
        while i < n:
            r = rows_from_js[i]
            cells = r.get("cells") or [] if isinstance(r, dict) else (r or [])
            section = _khong_dau_an_toan(r.get("section")) if isinstance(r, dict) else ""
            joined = _khong_dau_an_toan(" ".join(cells))
            if not ("to chuc cap" in joined and "ngay het han" in joined):
                i += 1
                continue
            header = [_khong_dau_an_toan(c) for c in cells]

            def find(*keys):
                for j, h in enumerate(header):
                    if any(k in h for k in keys):
                        return j
                return -1

            idx_to_chuc = find("to chuc cap")
            idx_het_han = find("ngay het han")
            j = i + 1
            ket_qua = None
            while j < n:
                r2 = rows_from_js[j]
                cells2 = r2.get("cells") or [] if isinstance(r2, dict) else (r2 or [])
                if not cells2:
                    j += 1
                    continue
                joined2 = _khong_dau_an_toan(" ".join(cells2))
                if "to chuc cap" in joined2 and "ngay het han" in joined2:
                    break   # gặp tiêu đề bảng KHÁC -> hết dữ liệu bảng đang xét
                if all(not c for c in cells2):
                    j += 1
                    continue
                to_chuc = cells2[idx_to_chuc].strip() if 0 <= idx_to_chuc < len(cells2) else ""
                het_han = cells2[idx_het_han].strip() if 0 <= idx_het_han < len(cells2) else ""
                if to_chuc or het_han:
                    ket_qua = (to_chuc, _chuan_ngay_het_han(het_han))
                j += 1
                if ket_qua:
                    break
            if ket_qua and nhan_muc(section):
                return ket_qua
            i = j if j > i else i + 1
        return None, None

    # Đợt 1: CHỈ nhận bảng ở đúng mục "Thông tin khai thuế".
    tc, hh = _tim_bang(lambda s: "khai thue" in s)
    if tc or hh:
        return tc, hh
    # Đợt 2 (dự phòng khi mục "khai thuế" không có/rỗng, hoặc trang không
    # xác định được mục — section rỗng): chấp nhận mục khác, NHƯNG TUYỆT ĐỐI
    # vẫn loại trừ "Thông tin nộp thuế" theo đúng yêu cầu.
    return _tim_bang(lambda s: "nop thue" not in s)


def _dvc_browser_lay_token_info(drv):
    """Vào trang "Quản lý thông tin" (dichvucong.gdt.gov.vn/tthc/dang-ky-dich-vu,
    sau khi đã đăng nhập), đọc thông tin chứng thư số (CKS): Tổ chức cấp +
    Ngày hết hạn. Trả (to_chuc_cap, ngay_het_han_iso, chi_tiet_loi) — chi_tiet_loi
    là chuỗi mô tả NGUYÊN NHÂN cụ thể khi KHÔNG đọc được (None nếu đọc được) —
    trước đây mọi lỗi ở đây đều bị NUỐT ÂM THẦM (except: pass/return None,None),
    khiến người dùng chỉ thấy "không đọc được thông tin token" mà không biết vì
    sao (trang không tải được? bảng rỗng/khác cấu trúc? lỗi JS?), đúng phản ánh
    của người dùng."""
    import time as _t
    try:
        drv.get(DVC_BASE + "/dang-ky-dich-vu")
        _t.sleep(1.5)
        if not _dvc_wait_jquery(drv, 10):
            return None, None, "Trang \"Quản lý thông tin\" không nạp được jQuery (có thể tải chậm/bị chặn)"
        html = drv.page_source or ""
    except Exception as e:
        return None, None, f"Lỗi khi mở trang \"Quản lý thông tin\": {e}"
    try:
        pr = drv.execute_async_script(_JS_PARSE_TOKEN_TABLES, html)
    except Exception as e:
        return None, None, f"Lỗi khi đọc bảng dữ liệu (JS): {e}"
    if not pr or not pr.get("ok"):
        return None, None, f"Không đọc được bảng dữ liệu trên trang (kết quả: {str(pr)[:150]})"
    to_chuc_cap, ngay_het_han = _dvc_parse_token_info(pr.get("rows") or [])
    if not to_chuc_cap and not ngay_het_han:
        so_dong = len(pr.get("rows") or [])
        return None, None, (f"Trang đã tải được ({so_dong} dòng dữ liệu) nhưng KHÔNG tìm thấy dòng "
                             f"'Tổ chức cấp'/'Ngày hết hạn' chứng thư số — có thể công ty này chưa "
                             f"đăng ký chứng thư số trên Dịch vụ công, hoặc giao diện trang đã đổi khác")
    return to_chuc_cap, ngay_het_han, None


