_JS_INIT_NOP_TKHAI = r"""
var maTthc = arguments[0], maTKhai = arguments[1], ktraDoiTuong = arguments[2];
var cb = arguments[arguments.length-1];
function xsrf(){ var m=document.cookie.match(/XSRF-TOKEN=([^;]+)/); return m?decodeURIComponent(m[1]):''; }
var tok = xsrf();
function post(url, data){
  return $.ajax({type:'POST', url:url, data:data||undefined,
    headers:{'X-XSRF-TOKEN':tok, 'X-Requested-With':'XMLHttpRequest'}});
}
function buoc4(r1, r2, r3){
  if(!ktraDoiTuong){
    cb({ok:true, b1:(''+r1).slice(0,150), b2:(''+r2).slice(0,150), b3:(''+r3).slice(0,250)});
    return;
  }
  // Riêng TNCN: cổng còn gọi thêm ktraDoiTuongKeKhai sau init-nop-tkhai
  // (kiểm tra loại người nộp thuế/đối tượng kê khai) trước khi cho vào trang tải file.
  post('/tthc/getfragmenttthc/ktraDoiTuongKeKhai', {loaiTKhai: maTKhai})
    .done(function(r4){
      cb({ok:true, b1:(''+r1).slice(0,150), b2:(''+r2).slice(0,150), b3:(''+r3).slice(0,250),
          b4:(''+r4).slice(0,150)});
    })
    .fail(function(x){ cb({ok:false, buoc:4, status:x.status, text:(x.responseText||'').slice(0,250)}); });
}
post('/tthc/sso/check-to-khai?maTthc='+encodeURIComponent(maTthc)+'&module=DN')
  .done(function(r1){
    post('/tthc/getfragmenttkhai/check-uyquyen', {maTKhai:maTKhai})
      .done(function(r2){
        post('/tthc/getfragmenttthc/init-nop-tkhai', {
          maTTHC:maTthc, maTKhai:maTKhai, maHoSo:'', mstUyQuyen:'',
          mstKhaiThay:'', doiTuongNopThay:'', maCqtAllowBS:'', isTraiNghiem:'false'
        }).done(function(r3){ buoc4(r1, r2, r3); })
          .fail(function(x){ cb({ok:false, buoc:3, status:x.status, text:(x.responseText||'').slice(0,250)}); });
      }).fail(function(x){ cb({ok:false, buoc:2, status:x.status, text:(x.responseText||'').slice(0,250)}); });
  }).fail(function(x){ cb({ok:false, buoc:1, status:x.status, text:(x.responseText||'').slice(0,250)}); });
"""


def _tim_file_nop_to_khai(folder, mst, loai, nam=None, quy=None):
    """Tìm (các) file XML trong 'thư mục mặc định' khớp công ty (theo MST đầu
    tên file, đúng quy ước fname của export_htkk: {mst13}-...) + loại tờ khai
    (theo từ khoá trong tên file, vd 'gtgt'/'tncn'). Nếu có truyền (nam, quy)
    -> CHỈ lấy file có KỲ (suy từ tên file qua _ky_tu_ten_file_nop) KHỚP ĐÚNG
    kỳ đã chọn — tránh nhặt NHẦM file của kỳ khác (vd thư mục còn sót lại file
    Quý 1 trong khi người dùng đang chọn nộp Quý 2) chỉ vì file đó có mtime
    mới hơn. Trả (file_moi_nhat, [tất cả ứng viên])."""
    if not folder or not os.path.isdir(folder):
        return None, []
    mst10 = "".join(ch for ch in str(mst or "") if ch.isdigit())[:10]
    if not mst10:
        return None, []
    tu_khoa = _DVC_LOAI_TU_KHOA_FILE.get(loai, [])
    ky_muon = _tu_den_cua_quy(nam, quy) if nam and quy else None
    ung_vien = []
    try:
        ten_file_list = os.listdir(folder)
    except Exception:
        return None, []
    for fn in ten_file_list:
        low = fn.lower()
        if not low.endswith(".xml"):
            continue
        if not low.startswith(mst10):
            continue
        if tu_khoa and not any(k in low for k in tu_khoa):
            continue
        if ky_muon and _ky_tu_ten_file_nop(fn) != ky_muon:
            continue
        full = os.path.join(folder, fn)
        try:
            mtime = os.path.getmtime(full)
        except Exception:
            mtime = 0
        ung_vien.append((mtime, full))
    if not ung_vien:
        return None, []
    ung_vien.sort(reverse=True)
    return ung_vien[0][1], [u[1] for u in ung_vien]


def _tim_file_nop_theo_cong_ty(comp, loai, nam, quy, folder_mac_dinh):
    """Tìm file XML để nộp cho 1 công ty — ƯU TIÊN tìm ĐÚNG trong "Thư mục
    lưu file kết xuất" RIÊNG của công ty này (theo cấu trúc Năm/Quý đã có
    sẵn, dựa vào (nam, quy) người dùng chọn), thay vì chỉ dựa vào 1 "thư mục
    mặc định" dùng chung cho mọi công ty (phải tự gom file thủ công). Nếu
    công ty CHƯA cấu hình thư mục riêng, hoặc không tìm thấy file ở đó ->
    LÙI VỀ thư mục mặc định như cách làm cũ (không phá vỡ công ty đang dùng
    cách cũ). Trả (file_moi_nhat, [tất cả ứng viên])."""
    export_dir = (comp["export_dir"] if comp and "export_dir" in comp.keys() else "") or ""
    if export_dir and nam:
        tu_ngay, den_ngay = _tu_den_cua_quy(nam, quy)
        dich = _thu_muc_ket_xuat_ky(export_dir, tu_ngay, den_ngay)
        if dich:
            fp, ung_vien = _tim_file_nop_to_khai(dich, comp["mst"], loai, nam, quy)
            if fp:
                return fp, ung_vien
    return _tim_file_nop_to_khai(folder_mac_dinh, comp["mst"], loai, nam, quy)


_DVC_OPEN_DRIVERS = {}   # {phien_id: drv} — giữ tham chiếu trình duyệt HIỂN THỊ đang chờ người
                          # dùng tự Ký+Nộp, tra theo phien_id để thao tác tiếp lên ĐÚNG cửa sổ đó

_HOA_KHONG_DAU = "ABCDEFGHIJKLMNOPQRSTUVWXYZÁÀẢÃẠĂẮẰẲẴẶÂẤẦẨẪẬÉÈẺẼẸÊẾỀỂỄỆÍÌỈĨỊÓÒỎÕỌÔỐỒỔỖỘƠỚỜỞỠỢÚÙỦŨỤƯỨỪỬỮỰÝỲỶỸỴĐ"
_THUONG_KHONG_DAU = "abcdefghijklmnopqrstuvwxyzáàảãạăắằẳẵặâấầẩẫậéèẻẽẹêếềểễệíìỉĩịóòỏõọôốồổỗộơớờởỡợúùủũụưứừửữựýỳỷỹỵđ"

def _dvc_tim_nut(drv, text_can_tim):
    """Tìm (các) nút/link đang HIỂN THỊ trên trang có chứa đúng đoạn chữ
    text_can_tim (không phân biệt hoa/thường, có/không dấu)."""
    xpath = (f"//*[self::button or self::a or self::span][contains("
             f"translate(normalize-space(.),'{_HOA_KHONG_DAU}','{_THUONG_KHONG_DAU}'),"
             f"'{text_can_tim.lower()}')]")
    try:
        els = drv.find_elements("xpath", xpath)
    except Exception:
        return []
    return [e for e in els if e.is_displayed()]


def _dvc_nut_gon_nhat(drv, text_can_tim):
    """Như _dvc_tim_nut nhưng ưu tiên phần tử có chữ NGẮN NHẤT — vì XPath
    khớp cả thẻ bọc ngoài (vd 1 <span> chứa cả thanh công cụ) lẫn đúng cái
    nút; bấm vào thẻ bọc ngoài có thể không ăn."""
    def _do_dai(e):
        try:
            return len((e.text or "").strip())
        except Exception:
            return 10 ** 6
    return sorted(_dvc_tim_nut(drv, text_can_tim), key=_do_dai)


def _dvc_click_chac_chan(drv, el):
    """Bấm 1 phần tử CHẮC CHẮN hơn: cuộn vào tầm nhìn rồi bấm bình thường;
    nếu bị lớp phủ/modal còn sót che (ElementClickInterceptedException) thì
    bấm bằng JS (JS không bị lớp phủ chặn). Trả (ok, loi)."""
    try:
        drv.execute_script("arguments[0].scrollIntoView({block:'center'});", el)
    except Exception:
        pass
    loi_goc = ""
    try:
        el.click()
        return True, None
    except Exception as e:
        loi_goc = str(e)[:200]
    try:
        drv.execute_script("arguments[0].click();", el)
        return True, None
    except Exception as e:
        return False, f"{loi_goc} | bấm bằng JS cũng lỗi: {str(e)[:200]}"


def _dvc_xu_ly_alert_neu_co(drv):
    """Nếu trang hiện hộp thoại JS GỐC của trình duyệt (window.confirm/alert
    — vd "Bạn có chắc chắn muốn nộp tờ khai?") thì tự bấm OK để xác nhận
    luôn — đây KHÔNG phải phần tử DOM (không tìm bằng find_elements/nút
    "Đồng ý" được) mà là hộp thoại CỦA CHÍNH TRÌNH DUYỆT, phải dùng
    Selenium switch_to.alert. Nếu không xử lý hộp thoại này thì mọi lệnh
    đọc trang sau đó (current_url/page_source) đều bị chặn/lỗi
    (UnexpectedAlertPresentException). Trả nội dung hộp thoại nếu vừa xử
    lý, None nếu không có."""
    try:
        alert = drv.switch_to.alert
        text = alert.text
        alert.accept()
        return text
    except Exception:
        return None


def _dvc_cho_ket_qua_nop(drv, cho_toi_da=30):
    """Chờ trang chuyển sang màn kết quả "THÀNH CÔNG" sau khi bấm "Nộp tờ
    khai" — LUÔN kiểm tra ít nhất 1 lần (cho_toi_da=0 nghĩa là chỉ xem ngay
    lúc này, không chờ). Tự xử lý hộp thoại xác nhận JS gốc (nếu có) ở MỖI
    vòng — nếu không thì việc đọc trang bên dưới sẽ bị chặn mãi. Trả
    (thanh_cong, ma_ho_so)."""
    import time as _t, re as _re
    cho_den = _t.time() + cho_toi_da
    while True:
        _dvc_xu_ly_alert_neu_co(drv)
        try:
            url = (drv.current_url or "").lower()
        except Exception:
            url = ""
        try:
            html = drv.page_source or ""
        except Exception:
            html = ""
        low = html.lower()
        if "ket-qua-xml" in url or ("thành công" in low and "mã hồ sơ" in low):
            m = _re.search(r"[A-Za-z]\d{1,3}\.\d{1,3}-\d{6}-\d+", html)
            return True, (m.group(0) if m else None)
        if _t.time() >= cho_den:
            return False, None
        _t.sleep(1)


def _dvc_bam_ky_ho_so(drv):
    """Sau khi đã tải file XML lên (trang .../nop-file-xml), tự bấm nút "Ký
    hồ sơ", đợi khung "Chọn chữ ký số" hiện ra rồi tự bấm "Tiếp tục" để vào
    đúng chứng thư số — bấm "Tiếp tục" xong là lúc hub CKS cục bộ (chương
    trình RIÊNG ngoài trình duyệt) bật hộp thoại "Xác nhận PIN" — xem
    _dvc_nhap_pin_ky_so() để tự nhập PIN tiếp bước này."""
    import time as _t
    buoc = []

    def _tim_nut(text_can_tim):
        return _dvc_tim_nut(drv, text_can_tim)

    try:
        nut_ky = _tim_nut("ký hồ sơ")
        if not nut_ky:
            return {"ok": False, "loi": "Không tìm thấy nút \"Ký hồ sơ\" trên trang hiện tại",
                    "buoc": buoc}
        nut_ky[0].click()
        buoc.append("Đã bấm \"Ký hồ sơ\"")
    except Exception as e:
        return {"ok": False, "loi": f"Lỗi khi bấm \"Ký hồ sơ\": {e}", "buoc": buoc}

    hien = False
    for _ in range(20):
        _t.sleep(0.5)
        if _tim_nut("tiếp tục"):
            hien = True
            break
    if not hien:
        return {"ok": False,
                "loi": "Không thấy khung \"Chọn chữ ký số\" hiện ra sau khi bấm \"Ký hồ sơ\" "
                       "(có thể trang tải chậm hoặc đã đổi giao diện) — cửa sổ Chrome vẫn mở, "
                       "bạn tự làm tiếp từ đây.",
                "buoc": buoc}
    buoc.append("Khung \"Chọn chữ ký số\" đã hiện ra")

    try:
        radios = [r for r in drv.find_elements("css selector", "input[type=radio]") if r.is_displayed()]
        if radios and not any(r.is_selected() for r in radios):
            radios[0].click()
            buoc.append("Đã chọn chứng thư số (dòng đầu tiên trong danh sách)")
    except Exception:
        pass

    try:
        nut_tt = _tim_nut("tiếp tục")
        if not nut_tt:
            return {"ok": False,
                    "loi": "Không tìm thấy nút \"Tiếp tục\" trong khung chọn chữ ký số",
                    "buoc": buoc}
        nut_tt[0].click()
        buoc.append("Đã bấm \"Tiếp tục\" để vào bước ký")
    except Exception as e:
        return {"ok": False, "loi": f"Lỗi khi bấm \"Tiếp tục\": {e}", "buoc": buoc}

    return {"ok": True, "buoc": buoc}


# ============================================================
#  TỰ ĐỘNG NHẬP MÃ PIN chữ ký số + BẤM "NỘP TỜ KHAI" — hộp thoại nhập PIN là
#  1 CỬA SỔ WINDOWS RIÊNG do hub CKS cục bộ tự bật ra (đã xác nhận qua ảnh
#  chụp thật của người dùng), KHÔNG nằm trong DOM trang web nên Selenium
#  không điều khiển được — phải dùng pywinauto (điều khiển ứng dụng Windows
#  qua UI Automation) để dò đúng cửa sổ, nhập PIN vào ô "Mã PIN:" rồi bấm
#  "Đăng nhập". TIÊU ĐỀ cửa sổ KHÁC NHAU tuỳ nhà cung cấp token (đã xác nhận
#  qua ảnh chụp thật của người dùng, dùng "nhiều token"): "Xác nhận PIN"
#  (chung), "Kiểm tra mã PIN" (Viettel-CA — logo Viettel, có nút "Thay đổi
#  mã PIN"/"Đăng nhập"/"Hủy"), "Đăng nhập" (VINCA Token — có kèm dòng "Bạn
#  còn N lần để đăng nhập"). Tiêu đề "Đăng nhập" khá chung chung nên phải
#  kiểm tra THÊM nội dung (có nhắc "mã pin"/"token") để chắc chắn đúng hộp
#  thoại token, tránh nhầm với 1 cửa sổ "Đăng nhập" khác không liên quan
#  trên máy — "Xác nhận PIN"/"Kiểm tra mã PIN" đã đủ riêng biệt, không cần
#  kiểm tra thêm.
#  AN TOÀN: hầu hết token/CKS KHOÁ VĨNH VIỄN sau 3 LẦN NHẬP SAI PIN liên
#  tiếp (phải mang tới nhà cung cấp mở khoá lại) — nên CHỈ thử tối đa 2 LẦN
#  rồi DỪNG HẲN (tự bấm "Huỷ"/"Huỷ bỏ"), không bao giờ thử lần thứ 3, đúng
#  yêu cầu của người dùng. Nếu hộp thoại tự báo rõ số lần CÒN LẠI (vd VINCA
#  Token "Bạn còn N lần để đăng nhập") thì còn CHẶT HƠN: không bao giờ dùng
#  tới lần thử CUỐI CÙNG được báo — luôn chừa lại ít nhất 1 lần cho người
#  dùng tự nhập tay nếu cần.
# ============================================================
_DVC_PIN_DIALOG_TITLES = ("Xác nhận PIN", "Kiểm tra mã PIN", "Đăng nhập")
_DVC_PIN_TU_KHOA_SAI = ("sai", "khong dung", "khong hop le", "invalid", "incorrect",
                        "khoa", "loi", "error", "khong chinh xac")

def _dvc_la_hop_thoai_pin(w):
    """Xác nhận ĐÚNG là hộp thoại nhập PIN token — tiêu đề "Xác nhận PIN"/
    "Kiểm tra mã PIN" (Viettel-CA) là đủ chắc chắn (dùng riêng cho việc này),
    nhưng tiêu đề "Đăng nhập" (VINCA Token) khá chung chung nên phải có THÊM
    ô nhập + nhắc tới "mã pin"/"token" trong nội dung mới coi là đúng."""
    try:
        tieu_de = w.window_text().strip()
    except Exception:
        return False
    if tieu_de not in _DVC_PIN_DIALOG_TITLES:
        return False
    if tieu_de in ("Xác nhận PIN", "Kiểm tra mã PIN"):
        return True
    try:
        if not w.descendants(control_type="Edit"):
            return False
        noi_dung = " ".join(_khong_dau(t.window_text()) for t in w.descendants(control_type="Text"))
        return "ma pin" in noi_dung or "token" in noi_dung
    except Exception:
        return False


def _dvc_so_lan_con_lai(w):
    """Đọc số lần CÒN LẠI để đăng nhập nếu hộp thoại tự báo (vd VINCA Token:
    "Bạn còn 10 lần để đăng nhập") — None nếu không có."""
    import re as _re
    try:
        for t in w.descendants(control_type="Text"):
            m = _re.search(r"con\s+(\d+)\s+lan", _khong_dau(t.window_text() or ""))
            if m:
                return int(m.group(1))
    except Exception:
        pass
    return None


def _dvc_tim_hop_thoai_pin(desk):
    try:
        for w in desk.windows():
            try:
                if w.is_visible() and _dvc_la_hop_thoai_pin(w):
                    return w
            except Exception:
                continue
    except Exception:
        pass
    return None


def _dvc_bam_cho_phep_neu_co(desk):
    """Khi bấm "Tiếp tục" để vào bước ký, Chrome có thể tự hiện bong bóng xin
    quyền (vd "...muốn: Truy cập vào các ứng dụng và dịch vụ khác trên thiết
    bị này" — xin phép liên lạc với hub CKS cục bộ chạy trên máy) — đây là UI
    CỦA CHÍNH TRÌNH DUYỆT (không nằm trong DOM trang web) nên phải dò bằng
    pywinauto, không dùng Selenium find_element được. Nếu KHÔNG bấm "Cho
    phép" thì hub CKS không liên lạc được, hộp thoại "Xác nhận PIN" sẽ không
    bao giờ hiện ra. Trả True nếu vừa bấm."""
    try:
        for w in desk.windows():
            try:
                if not w.is_visible():
                    continue
                for b in w.descendants(control_type="Button"):
                    try:
                        if _khong_dau(b.window_text()).strip() == "cho phep":
                            b.click_input()
                            return True
                    except Exception:
                        continue
            except Exception:
                continue
    except Exception:
        pass
    return False


def _dvc_nhap_pin_ky_so(pin, so_lan_toi_da=2, cho_hien_toi_da=30, cho_dong_toi_da=8):
    """Tự nhập mã PIN vào hộp thoại nhập PIN của token (cửa sổ Windows RIÊNG
    do hub CKS bật ra sau khi bấm "Tiếp tục" trong _dvc_bam_ky_ho_so — KHÔNG
    phải trang web nên phải dùng pywinauto, không dùng Selenium được — xem
    _DVC_PIN_DIALOG_TITLES cho các tiêu đề đã gặp tuỳ nhà cung cấp token).
    Chờ hộp thoại hiện ra tối đa cho_hien_toi_da giây (đồng thời tự bấm
    "Cho phép" nếu Chrome hiện bong bóng xin quyền); mỗi lần nhập xong bấm
    "Đăng nhập" rồi chờ tối đa cho_dong_toi_da giây xem hộp thoại có TỰ ĐÓNG
    (= đăng nhập PIN thành công) không. SAI PIN thì hộp thoại vẫn còn —
    thử lại, nhưng CHỈ tối đa so_lan_toi_da lần (mặc định 2, hoặc ÍT HƠN
    nếu token tự báo số lần còn lại thấp hơn — xem _dvc_so_lan_con_lai) rồi
    DỪNG HẲN (tự bấm "Huỷ"/"Huỷ bỏ") để tránh khoá token — token thường khoá
    sau 3 lần nhập sai liên tiếp, không bao giờ được thử vượt quá giới hạn.
    Trả dict: {ok, buoc, sai_pin?, khong_thay_hop_thoai?, so_lan_da_thu, loi?}."""
    try:
        from pywinauto import Desktop
    except ImportError:
        return {"ok": False, "khong_thay_hop_thoai": True, "buoc": [],
                "loi": "Chưa cài thư viện pywinauto (cần để tự điều khiển hộp thoại nhập PIN — "
                       "đây là cửa sổ Windows RIÊNG, ngoài trình duyệt) — đóng phần mềm, chạy lại "
                       "start.bat để tự cài, rồi thử lại. Trong lúc chờ, hãy tự nhập PIN bằng tay."}
    import time as _t
    buoc = []
    desk = Desktop(backend="uia")

    dlg = None
    da_bam_cho_phep = False
    cho_den = _t.time() + cho_hien_toi_da
    while _t.time() < cho_den:
        dlg = _dvc_tim_hop_thoai_pin(desk)
        if dlg:
            break
        # bong bóng xin quyền của Chrome (nếu có) phải bấm "Cho phép" TRƯỚC
        # thì hub CKS mới liên lạc được và hộp thoại PIN mới hiện ra
        if _dvc_bam_cho_phep_neu_co(desk):
            da_bam_cho_phep = True
        _t.sleep(0.5)
    if not dlg:
        return {"ok": False, "khong_thay_hop_thoai": True, "buoc": buoc, "so_lan_da_thu": 0,
                "loi": f"Không thấy hộp thoại nhập mã PIN của token hiện ra sau {cho_hien_toi_da}s "
                       f"(đã tìm các tiêu đề: {', '.join(_DVC_PIN_DIALOG_TITLES)}) — có thể token "
                       "chưa cắm, hub CKS chưa chạy, hoặc giao diện đã đổi khác. Hãy tự kiểm tra và "
                       "nhập PIN bằng tay."}
    if da_bam_cho_phep:
        buoc.append("Đã tự bấm \"Cho phép\" ở bong bóng xin quyền của Chrome")
    tieu_de_hop_thoai = dlg.window_text().strip()
    buoc.append(f"Hộp thoại \"{tieu_de_hop_thoai}\" đã hiện ra")
    so_lan_con_lai = _dvc_so_lan_con_lai(dlg)
    # LUÔN chừa lại ÍT NHẤT 1 lần thử cho người dùng tự nhập tay (không bao
    # giờ tự dùng tới lần thử CUỐI CÙNG mà token báo) — cùng nguyên tắc với
    # gợi ý "sai quá 2 lần thì dừng" của người dùng, áp cho token báo trước
    # số lần cụ thể.
    so_lan_thuc_te = min(so_lan_toi_da, so_lan_con_lai - 1) if so_lan_con_lai is not None else so_lan_toi_da
    if so_lan_con_lai is not None:
        buoc.append(f"Token báo còn {so_lan_con_lai} lần để đăng nhập — tự giới hạn thử tối đa "
                    f"{max(so_lan_thuc_te, 0)} lần (luôn chừa lại ít nhất 1 lần)")
    if so_lan_thuc_te < 1:
        return {"ok": False, "sai_pin": False, "so_lan_da_thu": 0, "buoc": buoc,
                "loi": f"Token báo chỉ còn {so_lan_con_lai} lần để đăng nhập — KHÔNG tự thử để "
                       "tránh khoá hẳn token, hãy tự kiểm tra/nhập PIN đúng bằng tay cho công ty này."}

    for lan in range(1, so_lan_thuc_te + 1):
        dlg = _dvc_tim_hop_thoai_pin(desk)
        if not dlg:
            buoc.append("Hộp thoại đã tự đóng trước khi kịp thao tác — coi như đã xong")
            return {"ok": True, "buoc": buoc, "so_lan_da_thu": lan - 1}
        try:
            edits = dlg.descendants(control_type="Edit")
            if not edits:
                return {"ok": False, "buoc": buoc, "so_lan_da_thu": lan - 1,
                        "loi": "Không tìm thấy ô nhập PIN trong hộp thoại"}
            o_pin = edits[0]
            o_pin.set_focus()
            try:
                o_pin.set_edit_text("")
            except Exception:
                pass
            o_pin.type_keys(pin, with_spaces=True)
            buoc.append(f"Đã nhập mã PIN (lần {lan}/{so_lan_thuc_te})")
            nut_dn = None
            for b in dlg.descendants(control_type="Button"):
                try:
                    if "dang nhap" in _khong_dau(b.window_text()):
                        nut_dn = b
                        break
                except Exception:
                    continue
            if not nut_dn:
                return {"ok": False, "buoc": buoc, "so_lan_da_thu": lan - 1,
                        "loi": "Không tìm thấy nút \"Đăng nhập\" trong hộp thoại"}
            nut_dn.click_input()
            buoc.append("Đã bấm \"Đăng nhập\"")
        except Exception as e:
            return {"ok": False, "buoc": buoc, "so_lan_da_thu": lan - 1,
                    "loi": f"Lỗi khi thao tác hộp thoại PIN: {e}"}

        dong = False
        cho_den2 = _t.time() + cho_dong_toi_da
        while _t.time() < cho_den2:
            if not _dvc_tim_hop_thoai_pin(desk):
                dong = True
                break
            _t.sleep(0.5)
        if dong:
            buoc.append("Hộp thoại đã tự đóng — đăng nhập PIN thành công")
            return {"ok": True, "buoc": buoc, "so_lan_da_thu": lan}

        dlg2 = _dvc_tim_hop_thoai_pin(desk)
        thong_bao_loi = ""
        if dlg2:
            try:
                for t in dlg2.descendants(control_type="Text"):
                    tx_goc = t.window_text()
                    if tx_goc and any(k in _khong_dau(tx_goc) for k in _DVC_PIN_TU_KHOA_SAI):
                        thong_bao_loi = tx_goc
                        buoc.append(f"Phát hiện thông báo trong hộp thoại: {tx_goc}")
                        break
            except Exception:
                pass
        if lan >= so_lan_thuc_te:
            if dlg2:
                try:
                    for b in dlg2.descendants(control_type="Button"):
                        if "huy" in _khong_dau(b.window_text()):
                            b.click_input()
                            buoc.append("Đã bấm \"Huỷ\"")
                            break
                except Exception:
                    pass
            return {"ok": False, "sai_pin": True, "so_lan_da_thu": lan, "buoc": buoc,
                    "loi": f"Sai mã PIN {lan} lần liên tiếp{(' (' + thong_bao_loi + ')') if thong_bao_loi else ''}"
                           " — ĐÃ DỪNG LẠI (bấm \"Huỷ\") để tránh khoá token (token thường khoá sau "
                           "3 lần nhập sai, hoặc theo đúng số lần token báo) — hãy tự kiểm tra/nhập "
                           "đúng mã PIN bằng tay cho công ty này."}
        buoc.append(f"Lần {lan} chưa thành công — thử lại")
    return {"ok": False, "sai_pin": True, "so_lan_da_thu": so_lan_thuc_te, "buoc": buoc,
            "loi": "Không xác nhận được đăng nhập PIN"}


# Nút xác nhận trong hộp thoại "Bạn có chắc muốn nộp?" (nếu cổng có hiện)
_DVC_NUT_XAC_NHAN_NOP = ("đồng ý", "xác nhận", "chấp nhận")

def _dvc_bam_nut_nop_to_khai(drv, cho_ky_toi_da=25, cho_ket_qua_toi_da=30, so_lan_thu=3,
                             cho_gan_chu_ky=3):
    """Sau khi hộp thoại PIN đã đóng (ký PIN xong), tự bấm nút "Nộp tờ khai"
    THẬT trên trang — hoàn tất NỘP CHÍNH THỨC lên cơ quan Thuế (hành động
    KHÔNG THỂ ĐẢO NGƯỢC).

    QUAN TRỌNG (nguyên nhân đã gặp thật: "đã ký thành công rồi mà không bấm
    Nộp tờ khai"): nút "Nộp tờ khai" nằm SẴN trên trang ngay cạnh "Ký hồ sơ"
    NGAY TỪ ĐẦU — nên KHÔNG được coi "tìm thấy nút" là "ký xong rồi" mà bấm
    ngay. Bấm quá sớm (chữ ký chưa gắn xong vào hồ sơ) thì cổng bỏ qua/báo
    lỗi và vẫn nằm ở trang nộp file; hoặc khung modal "Chọn chữ ký số" còn
    sót lớp phủ khiến cú bấm bị CHẶN (ElementClickInterceptedException) mà
    trước đây bị coi là lỗi cứng, bỏ luôn không thử lại. Vì vậy:
      1. CHỜ khung "Chọn chữ ký số" đóng hẳn + chờ thêm 1 nhịp cho trang gắn
         chữ ký (cho_gan_chu_ky giây — mặc định 3s cho lần ký PIN thật vừa
         xong; gọi với giá trị NHỎ HƠN khi biết chữ ký đã gắn xong từ TRƯỚC
         đó rồi, vd dùng chung phiên không hiện lại hộp thoại PIN), RỒI mới bấm.
      2. Bấm qua _dvc_click_chac_chan (cuộn vào tầm nhìn, bị lớp phủ chặn
         thì bấm bằng JS).
      3. Nếu cổng hiện hộp xác nhận "Bạn có chắc..." thì tự bấm Đồng ý.
      4. Chưa thấy trang "THÀNH CÔNG" thì THỬ LẠI (tối đa so_lan_thu lần) —
         lần sau chắc chắn đã qua thời gian ký xong.
    CHỜ tới khi trang chuyển sang màn "THÀNH CÔNG" (URL .../ket-qua-xml, có
    "Mã hồ sơ") mới coi là XÁC NHẬN THẬT SỰ đã nộp xong — điều kiện để phần
    mềm CHUYỂN LUÔN sang tờ khai tiếp theo (vd GTGT xong -> TNCN)."""
    import time as _t
    buoc = []

    # (1) chờ ký xong THẬT: khung "Chọn chữ ký số" (chứa nút "Tiếp tục") phải
    #     đóng hẳn — đó là dấu hiệu hub CKS đã trả chữ ký về cho trang
    cho_den = _t.time() + cho_ky_toi_da
    modal_dong = False
    while _t.time() < cho_den:
        if not _dvc_tim_nut(drv, "tiếp tục"):
            modal_dong = True
            break
        _t.sleep(0.5)
    buoc.append("Khung \"Chọn chữ ký số\" đã đóng — trang đã nhận chữ ký" if modal_dong
                else f"Khung \"Chọn chữ ký số\" vẫn còn sau {cho_ky_toi_da}s — vẫn thử bấm "
                     "\"Nộp tờ khai\"")
    _t.sleep(cho_gan_chu_ky)   # nhịp chờ trang gắn chữ ký vào hồ sơ trước khi nộp

    loi_cuoi = ""
    for lan in range(1, so_lan_thu + 1):
        # có thể lần bấm trước ĐÃ thành công nhưng trang chậm — kiểm tra trước
        thanh_cong, ma_ho_so = _dvc_cho_ket_qua_nop(drv, 0)
        if thanh_cong:
            buoc.append("Trang đã ở màn THÀNH CÔNG")
            return {"ok": True, "ma_ho_so": ma_ho_so, "buoc": buoc}

        nut = _dvc_nut_gon_nhat(drv, "nộp tờ khai")
        if not nut:
            loi_cuoi = "Không tìm thấy nút \"Nộp tờ khai\" trên trang"
            buoc.append(f"Lần {lan}: {loi_cuoi}")
            _t.sleep(3)
            continue
        ok_click, loi_click = _dvc_click_chac_chan(drv, nut[0])
        if not ok_click:
            loi_cuoi = f"bấm nút không được ({loi_click})"
            buoc.append(f"Lần {lan}: {loi_cuoi}")
            _t.sleep(3)
            continue
        buoc.append(f"Đã bấm \"Nộp tờ khai\" (lần {lan}/{so_lan_thu})")

        # (3) hộp xác nhận "Bạn có chắc muốn nộp?" — nếu có thì tự đồng ý.
        # Có 2 dạng CÓ THỂ gặp: (a) hộp thoại JS GỐC của trình duyệt
        # (window.confirm) — _dvc_cho_ket_qua_nop() bên dưới TỰ xử lý dạng
        # này ở đầu mỗi vòng (xem _dvc_xu_ly_alert_neu_co); (b) 1 nút DOM
        # thường như "Đồng ý"/"Xác nhận" do trang tự vẽ — tìm và bấm luôn.
        _t.sleep(1.5)
        alert_da_xu_ly = _dvc_xu_ly_alert_neu_co(drv)
        if alert_da_xu_ly:
            buoc.append(f"Đã tự xác nhận hộp thoại của trình duyệt: \"{alert_da_xu_ly}\"")
        elif not _dvc_cho_ket_qua_nop(drv, 0)[0]:
            for tu in _DVC_NUT_XAC_NHAN_NOP:
                nut_xn = _dvc_nut_gon_nhat(drv, tu)
                if nut_xn:
                    if _dvc_click_chac_chan(drv, nut_xn[0])[0]:
                        buoc.append(f"Đã bấm nút xác nhận \"{tu}\" trong hộp thoại xác nhận nộp")
                    break

        # (4) chờ trang kết quả
        thanh_cong, ma_ho_so = _dvc_cho_ket_qua_nop(drv, cho_ket_qua_toi_da)
        if thanh_cong:
            buoc.append("Trang báo THÀNH CÔNG" +
                        (f" (Mã hồ sơ: {ma_ho_so})" if ma_ho_so else ""))
            return {"ok": True, "ma_ho_so": ma_ho_so, "buoc": buoc}
        loi_cuoi = f"bấm rồi nhưng không thấy trang \"THÀNH CÔNG\" sau {cho_ket_qua_toi_da}s"
        buoc.append(f"Lần {lan}: {loi_cuoi} — thử lại" if lan < so_lan_thu else f"Lần {lan}: {loi_cuoi}")

    try:
        url_hien_tai = drv.current_url
    except Exception:
        url_hien_tai = ""
    return {"ok": False, "buoc": buoc,
            "loi": f"Đã thử bấm \"Nộp tờ khai\" {so_lan_thu} lần nhưng {loi_cuoi} "
                   f"(đang ở: {url_hien_tai}) — hãy tự kiểm tra lại trên cửa sổ Chrome (có thể "
                   "trang báo lỗi cần xử lý, hoặc đã nộp được nhưng trang tải quá chậm)."}


def _dvc_browser_nop_to_khai(drv, cfg, file_path):
    """Sau khi đã đăng nhập: khởi tạo đúng phiên nộp tờ khai (giống hệt 3
    request thật đã bắt được: check-to-khai → check-uyquyen → init-nop-tkhai),
    điều hướng tới trang nộp file XML, rồi tự đưa file vào ô chọn tệp.
    DỪNG LẠI Ở ĐÂY — không tự bấm "Ký hồ sơ" / "Nộp tờ khai"."""
    import time as _t
    buoc = []
    drv.get(DVC_BASE + "/thu-tuc-hanh-chinh")
    _t.sleep(1.2)
    _dvc_wait_jquery(drv, 12)
    try:
        res = drv.execute_async_script(
            _JS_INIT_NOP_TKHAI, cfg["ma_tthc"], cfg["ma_tkhai"], bool(cfg.get("ktra_doi_tuong")))
    except Exception as e:
        return {"ok": False, "loi": f"Lỗi gọi init-nop-tkhai: {e}", "buoc": buoc}
    buoc.append({"buoc": "init-nop-tkhai", "ket_qua": res})
    if not res or not res.get("ok"):
        return {"ok": False, "loi": "Không khởi tạo được phiên nộp tờ khai (có thể công ty "
                                     "chưa có quyền với thủ tục này, hoặc phiên đăng nhập chưa "
                                     "sẵn sàng)", "buoc": buoc}
    drv.get(DVC_BASE + cfg["url"])
    _t.sleep(1.5)
    _dvc_wait_jquery(drv, 12)
    try:
        finp = drv.find_element("css selector", "input[type=file]")
    except Exception as e:
        return {"ok": False, "loi": f"Không tìm thấy ô chọn tệp trên trang {cfg['url']}: {e}",
                "buoc": buoc}
    try:
        finp.send_keys(os.path.abspath(file_path))
    except Exception as e:
        return {"ok": False, "loi": f"Không đưa được file vào ô chọn tệp: {e}", "buoc": buoc}
    _t.sleep(2)
    buoc.append({"buoc": "da-chon-file", "file": file_path})
    return {"ok": True, "buoc": buoc, "url_hien_tai": drv.current_url}


def _dvc_save_folder(cid):
    """Thư mục lưu tờ khai đã nộp: <save_dir|data_dir>/ToKhai_DaNop/."""
    conn = db()
    comp = conn.execute(
        "SELECT mst, save_dir, data_dir FROM companies WHERE id=?", (cid,)).fetchone()
    conn.close()
    if not comp:
        return None
    sd = (comp["save_dir"] or "").strip()
    dd = (comp["data_dir"] or "").strip() if "data_dir" in comp.keys() else ""
    base = sd or dd or os.path.join(DATA_DIR, "cong_ty")
    folder = os.path.join(base, "ToKhai_DaNop")
    try:
        os.makedirs(folder, exist_ok=True)
    except Exception:
        return None
    return folder


_DVC_LOI_DN = ["sai", "không đúng", "khong dung", "thất bại", "that bai",
               "lỗi", "error", "tài khoản", "mật khẩu", "khóa", "captcha",
               "mã xác nhận", "ma xac nhan", "chưa đăng nhập"]

def _dvc_login_voi_retry(client, mst, password, so_lan=6):
    """Tự lấy captcha + giải + đăng nhập, thử nhiều lần. Trả (ok, thong_tin)."""
    tried = []
    last = ""
    for lan in range(1, so_lan + 1):
        try:
            cap = client.solve_captcha()
        except Exception as e:
            last = f"Lỗi lấy/giải captcha: {type(e).__name__}: {e}"
            tried.append("(lỗi captcha)")
            continue
        if not cap:
            tried.append("(không đọc được captcha)")
            last = "ddddocr không đọc được mã (rỗng) — có thể chưa cài ddddocr"
            continue
        try:
            r = client.login(mst, password, cap)
        except Exception as e:
            last = f"Lỗi gọi loginLDAP: {e}"
            tried.append(f"{cap}→lỗi")
            continue
        body = (r.text or "")[:400]
        low = body.lower()
        # Heuristic: 200 + không chứa từ khóa lỗi/captcha => coi như thành công.
        captcha_loi = ("captcha" in low or "mã xác nhận" in low or "ma xac nhan" in low)
        co_loi = any(k in low for k in _DVC_LOI_DN)
        if r.status_code == 200 and not co_loi:
            client.logged_in = True
            return True, {"so_lan_thu": lan, "ma_da_thu": tried + [cap],
                          "status": r.status_code, "tra_loi": body}
        last = f"status={r.status_code}, trả lời: {body}"
        tried.append(f"{cap}→{'captcha sai' if captcha_loi else 'từ chối'}")
        if not captcha_loi and not r.ok:
            # lỗi không phải do captcha (vd sai mật khẩu) -> dừng sớm
            break
    return False, {"ma_da_thu": tried, "loi_cuoi": last}


# ============================================================
#  DVC qua TRÌNH DUYỆT THẬT (Selenium + Chrome) — vượt WAF F5
#  Cổng Thuế chặn HTTP thuần (kể cả curl_cffi) vì WAF cần chạy
#  JavaScript. Phần mềm Vsign cũng dùng chromedriver. Ta làm tương tự:
#  mở Chrome (ẩn), để trang tự qua WAF, rồi chạy getCaptcha/loginLDAP/
#  search/downloadhoso NGAY TRONG ngữ cảnh trang (XHR/$.ajax) nên token
#  XSRF/_csrf và cookie được xử lý y như trình duyệt thật.
# ============================================================
_DVC_UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
           "(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36")

_ESIGNER_EXT_ID = "ekaaenaocpheoabajfdnkhiibfmfmloo"   # tiện ích ký số GDT (eSigner)

def _find_chrome_extension(ext_id):
    """Tìm thư mục tiện ích Chrome đã cài (để nạp vào trình duyệt tự động).
    Tra trong cac profile Chrome/Chromium tren Windows."""
    import glob
    bases = [
        os.path.expandvars(r"%LOCALAPPDATA%\Google\Chrome\User Data"),
        os.path.expandvars(r"%LOCALAPPDATA%\Chromium\User Data"),
        os.path.expandvars(r"%LOCALAPPDATA%\Microsoft\Edge\User Data"),
    ]
    for base in bases:
        if not os.path.isdir(base):
            continue
        profs = ["Default"] + [os.path.basename(p) for p in glob.glob(os.path.join(base, "Profile *"))]
        for prof in profs:
            extdir = os.path.join(base, prof, "Extensions", ext_id)
            if os.path.isdir(extdir):
                vers = [d for d in glob.glob(os.path.join(extdir, "*")) if os.path.isdir(d)]
                if vers:
                    vers.sort()
                    return vers[-1]
    return None

def _dvc_make_driver(headless=True, esigner=False):
    from selenium import webdriver
    from selenium.webdriver.chrome.options import Options
    opts = Options()
    if headless:
        opts.add_argument("--headless=new")
    opts.add_argument("--disable-gpu")
    opts.add_argument("--no-sandbox")
    opts.add_argument("--disable-dev-shm-usage")
    opts.add_argument("--window-size=1366,920")
    opts.add_argument("--lang=vi-VN")
    opts.add_argument("--disable-blink-features=AutomationControlled")
    # UA chuẩn (tránh chuỗi 'HeadlessChrome' bị WAF nghi ngờ)
    opts.add_argument(f"--user-agent={_DVC_UA}")
    # Nạp tiện ích ký số eSigner đã cài sẵn (để vào được cổng eTax)
    ext_path = _find_chrome_extension(_ESIGNER_EXT_ID) if esigner else None
    if ext_path:
        opts.add_argument(f"--load-extension={ext_path}")
        opts.add_argument(f"--disable-extensions-except={ext_path}")
    try:
        opts.add_experimental_option("excludeSwitches", ["enable-automation"])
        opts.add_experimental_option("useAutomationExtension", False)
    except Exception:
        pass
    drv = webdriver.Chrome(options=opts)   # Selenium Manager tự tải chromedriver
    drv._esigner_ext = ext_path
    drv.set_page_load_timeout(70)
    drv.set_script_timeout(150)
    try:
        drv.execute_cdp_cmd("Page.addScriptToEvaluateOnNewDocument",
            {"source": "Object.defineProperty(navigator,'webdriver',{get:()=>undefined})"})
    except Exception:
        pass
    return drv

# --- Các đoạn JS chạy trong ngữ cảnh trang dichvucong ---
_JS_GETCAPTCHA = r"""
var cb = arguments[arguments.length-1];
// Dùng chính thẻ <img> captcha của trang + hàm reload của trang (đúng URL trang
// dùng, request kiểu ảnh nên qua WAF). Cùng nguồn -> canvas không bị 'taint'.
try {
  function findImg(){
    var ids=['image-capt','image-capt-cbt','imgCaptcha','captcha','imgcaptcha'];
    for(var i=0;i<ids.length;i++){ var e=document.getElementById(ids[i]);
      if(e && e.tagName==='IMG') return e; }
    var imgs=document.getElementsByTagName('img');
    for(var j=0;j<imgs.length;j++){ if(((imgs[j].src||'').indexOf('getCaptcha'))>=0) return imgs[j]; }
    return null;
  }
  var img = findImg();
  if(!img){ cb({ok:false, err:'no-captcha-img'}); return; }
  var oldsrc = img.src||'';
  // nạp captcha mới: ưu tiên hàm của trang, nếu không thì đổi timestamp trên src cũ
  var reloaded=false;
  try{ if(typeof reloadCaptcha==='function'){ reloadCaptcha(); reloaded=true; } }catch(e){}
  if(!reloaded){ try{ if(typeof reloadCaptchaCbt==='function'){ reloadCaptchaCbt(); reloaded=true; } }catch(e){} }
  if(!reloaded){
    var base=(oldsrc.split('?')[0]) || '/tthc/getCaptcha';
    img.src = base + '?' + Date.now();
  }
  var done=false, tries=0;
  function check(){
    if(done) return;
    tries++;
    if(img.complete && img.naturalWidth>2){
      done=true;
      try{
        var w=img.naturalWidth, h=img.naturalHeight||60, sc=3;
        var c=document.createElement('canvas'); c.width=w*sc; c.height=h*sc;
        var g=c.getContext('2d'); g.fillStyle='#fff'; g.fillRect(0,0,c.width,c.height);
        g.drawImage(img,0,0,c.width,c.height);
        cb({ok:true, w:w, h:h, src:(img.src||'').slice(0,90), png:c.toDataURL('image/png')});
      }catch(e){ cb({ok:false, err:'canvas:'+e, src:(img.src||'').slice(0,90)}); }
      return;
    }
    if(tries>50){ done=true; cb({ok:false, err:'wait', src:(img.src||'').slice(0,90),
                                  complete:img.complete, nw:img.naturalWidth}); return; }
    setTimeout(check,150);
  }
  setTimeout(check, 400);
} catch(e){ cb({ok:false, err:''+e}); }
"""

