_DVC_HOA_KO_DAU = "ABCDEFGHIJKLMNOPQRSTUVWXYZÁÀẢÃẠĂẮẰẲẴẶÂẤẦẨẪẬÉÈẺẼẸÊẾỀỂỄỆÍÌỈĨỊÓÒỎÕỌÔỐỒỔỖỘƠỚỜỞỠỢÚÙỦŨỤƯỨỪỬỮỰÝỲỶỸỴĐ"
_DVC_THUONG_KO_DAU = "abcdefghijklmnopqrstuvwxyzáàảãạăắằẳẵặâấầẩẫậéèẻẽẹêếềểễệíìỉĩịóòỏõọôốồổỗộơớờởỡợúùủũụưứừửữựýỳỷỹỵđ"


def _dvc_qua_man_chon_loai_tk(drv, giay_cho=15):
    """Trang đăng nhập DVC hiện thêm 1 màn 'Chọn loại tài khoản đăng nhập'
    (Thuế điện tử / Định danh điện tử / Công chức thuế) TRƯỚC khi vào được
    form nhập mật khẩu + captcha thật sự (khác trước đây vào thẳng form).
    Nếu gặp màn này thì tự bấm 'Đăng nhập bằng tài khoản Thuế điện tử' rồi
    chờ form thật load xong; nếu không gặp (portal đổi lại như cũ, hoặc đã
    ở sẵn form thật) thì bỏ qua ngay, không tốn thời gian chờ vô ích."""
    import time as _t
    xpath = (f"//*[contains(translate(normalize-space(.),"
             f"'{_DVC_HOA_KO_DAU}','{_DVC_THUONG_KO_DAU}'),'đăng nhập bằng tài khoản thuế điện tử')]")
    for _ in range(int(giay_cho * 2)):
        try:
            if drv.find_elements("id", "image-capt") or drv.find_elements("id", "imgCaptcha"):
                return False   # da o san form that (co anh captcha) -> khong can bam gi them
        except Exception:
            pass
        try:
            els = [e for e in drv.find_elements("xpath", xpath) if e.is_displayed()]
        except Exception:
            els = []
        if els:
            try:
                els[0].click()
            except Exception:
                try:
                    drv.execute_script("arguments[0].click();", els[0])
                except Exception:
                    return False
            _t.sleep(1.2)
            return True
        _t.sleep(0.5)
    return False


def _dvc_wait_jquery(drv, giay=12):
    import time as _t
    for _ in range(int(giay*2)):
        try:
            if drv.execute_script(
                "return (typeof window.jQuery!=='undefined') && (typeof window.$==='function');"):
                return True
        except Exception:
            pass
        _t.sleep(0.5)
    return False

def _dvc_cap_from_js(res):
    """Từ kết quả _JS_GETCAPTCHA (PNG do trình duyệt vẽ từ canvas) → mã captcha."""
    if not res or not res.get("ok"):
        return ""
    png_uri = res.get("png") or ""
    if png_uri.startswith("data:"):
        try:
            raw = base64.b64decode(png_uri.split(",", 1)[1])
        except Exception:
            return ""
        return _ocr_png(raw)
    # phòng hờ phiên bản cũ trả b64 thô
    b64 = res.get("b64") or ""
    if b64:
        try:
            raw = base64.b64decode(b64)
        except Exception:
            return ""
        ct = (res.get("ct") or "").lower()
        if "svg" in ct or b"<svg" in raw[:200].lower():
            raw = _svg_to_png(raw.decode("utf-8", "replace")) or b""
        return _ocr_png(raw)
    return ""

def _dvc_cap_meta(res):
    """Chuỗi chẩn đoán khi captcha rỗng."""
    if not res:
        return "res=None"
    if not res.get("ok"):
        return (f"ok=False err={res.get('err')} src={res.get('src')} "
                f"complete={res.get('complete')} nw={res.get('nw')}")
    return f"ok=True w={res.get('w')} h={res.get('h')} src={res.get('src')} ocr=rỗng"

def _dvc_norm_data(d):
    if isinstance(d, str):
        try:
            return json.loads(d)
        except Exception:
            return {"_raw": d[:200]}
    return d

def _dvc_browser_login(drv, mst, password, so_lan=8):
    """Mở trang, qua WAF, tự giải captcha + đăng nhập. Trả (ok, info)."""
    import time as _t
    # "Trang login không nạp được jQuery" hầu hết là WAF chặn TẠM THỜI khi
    # nhiều luồng (nhiều trình duyệt ẩn) cùng dội request lên cổng DVC từ
    # CÙNG 1 địa chỉ IP trong lúc chạy "Tra cứu tờ khai hàng loạt" song song
    # nhiều công ty — KHÔNG PHẢI lỗi vĩnh viễn của riêng công ty đó (đã xác
    # nhận qua phản ánh thật của người dùng: đăng nhập TỪNG công ty một luôn
    # thành công, chỉ chạy hàng loạt song song mới báo lỗi này hàng loạt).
    # Trước đây báo lỗi NGAY ở lần tải đầu tiên -> công ty bị coi là "sai mật
    # khẩu/lỗi đăng nhập" oan trong khi mật khẩu hoàn toàn đúng. Giờ thử tải
    # lại vài lần, nghỉ tăng dần giữa các lần, để né đúng lúc WAF đang chặn.
    ok_jquery = False
    for lan_tai in range(3):
        drv.get(DVC_BASE + "/homelogin"); _t.sleep(1.5)
        drv.get(DVC_BASE + "/login"); _t.sleep(1.0)
        _dvc_qua_man_chon_loai_tk(drv)
        if _dvc_wait_jquery(drv, 15):
            ok_jquery = True
            break
        _t.sleep(3 + lan_tai * 3)
    if not ok_jquery:
        return False, {"loi": "Trang login không nạp được jQuery (có thể WAF chặn cả trình duyệt, đã thử tải lại 3 lần)"}
    # GIỮ NGUYÊN dấu gạch ngang trong MST (không chỉ lấy chữ số rồi nối lại)
    # — công ty CHI NHÁNH có MST dạng "xxxxxxxxxx-xxx" (MST công ty mẹ + số
    # nhánh); trước đây bỏ hết ký tự không phải số rồi nối chuỗi khiến MST
    # chi nhánh bị NỐI LIỀN số nhánh vào MST chính (vd "0313030299-001"
    # thành "0313030299001-QL") — SAI tên đăng nhập thật của DVC (đã xác
    # nhận đúng tên đăng nhập thật phải giữ dấu gạch: "0313030299-001-QL"),
    # khiến đăng nhập LUÔN báo sai tài khoản/mật khẩu dù mật khẩu đúng.
    ten = f"{str(mst or '').strip()}-QL"
    tried = []
    for lan in range(1, so_lan + 1):
        try:
            capres = drv.execute_async_script(_JS_GETCAPTCHA)
            cap = _dvc_cap_from_js(capres)
        except Exception as e:
            tried.append(f"(lỗi lấy captcha: {e})"); continue
        if not cap:
            tried.append(f"(captcha rỗng: {_dvc_cap_meta(capres)})"); continue
        try:
            res = drv.execute_async_script(_JS_LOGIN, ten, password, cap)
        except Exception as e:
            tried.append(f"{cap}→lỗi gọi login: {e}"); continue
        if res and res.get("ok"):
            d = _dvc_norm_data(res.get("data"))
            st = str(d.get("status")) if isinstance(d, dict) else ""
            if st == "200" or (isinstance(d, dict) and d.get("value")):
                return True, {"so_lan": lan, "ten_dn": ten}
            desc = (d.get("desc") if isinstance(d, dict) else str(d)) or ""
            tried.append(f"{cap}→{str(desc)[:70]}")
        else:
            tried.append(f"{cap}→{str(res)[:80]}")
        _t.sleep(0.4)
    return False, {"ten_dn": ten, "da_thu": tried}

def _dvc_browser_search(drv, tu, den, so_lan=8):
    """Sau khi đăng nhập: vào trang tra cứu, giải captcha lớp 2, tìm hồ sơ."""
    import time as _t
    diag = []
    drv.get(DVC_BASE + "/tchs"); _t.sleep(1.5)
    if not _dvc_wait_jquery(drv, 15):
        return [], ["Trang tra cứu (/tchs) không nạp được — có thể chưa đăng nhập thành công"]
    for lan in range(1, so_lan + 1):
        try:
            cap = _dvc_cap_from_js(drv.execute_async_script(_JS_GETCAPTCHA))
        except Exception as e:
            diag.append(f"(lỗi captcha: {e})"); continue
        if not cap:
            diag.append("(captcha rỗng)"); continue
        try:
            res = drv.execute_async_script(_JS_SEARCH, tu, den, cap)
        except Exception as e:
            diag.append(f"{cap}→lỗi search: {e}"); continue
        if res and res.get("ok"):
            html = res.get("html") or ""
            low = html.lower()
            if ("table-container" in low or "tổng số bản ghi" in low
                    or "totalpage" in low):
                ma = _dvc_parse_ma_ho_so(html)
                diag.append(f"{cap}→OK, {len(ma)} hồ sơ")
                return ma, diag
            diag.append(f"{cap}→chưa ra bảng (len={len(html)})")
        else:
            diag.append(f"{cap}→{str(res)[:80]}")
        _t.sleep(0.4)
    return [], diag

def _dvc_browser_download(drv, ma):
    res = drv.execute_async_script(_JS_DOWNLOAD, ma)
    if not res or not res.get("ok"):
        raise Exception(f"{res}")
    d = _dvc_norm_data(res.get("data"))
    if not isinstance(d, dict):
        raise Exception("phản hồi không hợp lệ")
    content = d.get("content") or ""
    fname = d.get("fileName") or f"{ma}.zip"
    raw = base64.b64decode(content) if content else b""
    return fname, raw

def _dvc_browser_thongbao(drv, ma):
    """Vào trang chi tiết hồ sơ, đọc idTbao rồi tải các thông báo (Tiếp nhận/Xác nhận).
    Trả về (list[(fname, raw)], diag)."""
    import time as _t
    out, diag = [], []
    try:
        drv.get(f"{DVC_BASE}/tchs/files/detail/{ma}?loai=")
        _t.sleep(1.2)
        _dvc_wait_jquery(drv, 10)
        html = drv.page_source or ""
    except Exception as e:
        return out, [f"lỗi mở chi tiết {ma}: {e}"]
    ids = _dvc_parse_id_tbao(html)
    if not ids:
        # dò manh mối để tinh chỉnh sau
        import re as _re
        m = _re.search(r'.{0,40}(?:hongBao|hong báo|Tbao).{0,40}', html)
        diag.append(f"{ma}: không thấy idTbao" + (f" | gợi ý: {m.group(0)[:80]}" if m else ""))
        return out, diag
    for idt in ids:
        body = json.dumps({"idTbao": idt, "loaiTBao": ""})
        try:
            res = drv.execute_async_script(_JS_DOWNLOAD_TB, body)
        except Exception as e:
            diag.append(f"{idt}: lỗi gọi: {e}"); continue
        if not res or not res.get("ok"):
            diag.append(f"{idt}: {str(res)[:80]}"); continue
        d = _dvc_norm_data(res.get("data"))
        if not isinstance(d, dict):
            diag.append(f"{idt}: phản hồi lạ"); continue
        content = d.get("content") or ""
        raw = base64.b64decode(content) if content else b""
        if not raw:
            diag.append(f"{idt}: rỗng"); continue
        fname = d.get("fileName") or f"TB_{ma}_{idt}.zip"
        out.append((fname, raw))
        _t.sleep(0.3)
    diag.append(f"{ma}: {len(out)}/{len(ids)} thông báo")
    return out, diag


def _khong_dau(s):
    import unicodedata
    # "đ"/"Đ" là 1 CHỮ CÁI RIÊNG trong Unicode (Latin D with stroke), KHÔNG
    # phải chữ cái gốc + dấu kết hợp nên NFD không tách được — nếu bỏ qua sẽ
    # khiến MỌI so khớp từ khoá có chữ "đ" (vd "đã chấp nhận") luôn thất bại
    # dù chuỗi gốc đúng y hệt. Phải tự thay trước khi chuẩn hoá NFD.
    s = str(s or "").replace("đ", "d").replace("Đ", "D")
    s = unicodedata.normalize("NFD", s)
    return "".join(c for c in s if unicodedata.category(c) != "Mn").lower().strip()

# Các cột báo cáo Tra cứu tờ khai (theo file mẫu)
TRACUU_COLS = ["to_khai", "ky", "loai", "ngay_nop", "lan_nop", "lan_bs", "trang_thai"]
TRACUU_HEADERS = ["Mst", "Tên công ty", "Tờ khai", "Kỳ", "Loại",
                  "Ngày nộp", "Lần nộp", "Lần bổ sung", "Trạng thái", "Nộp đúng hạn?"]


def _han_nop_to_khai(ky):
    """Suy HẠN NỘP tờ khai từ chuỗi 'Kỳ' trên trang Thuế, theo Luật Quản lý
    thuế/TT80: kỳ QUÝ ('Qx/YYYY') chậm nhất ngày CUỐI THÁNG ĐẦU của quý sau
    (vd Q1 -> 30/04); kỳ THÁNG ('MM/YYYY') chậm nhất ngày 20 THÁNG SAU; kỳ
    NĂM (chỉ 'YYYY' — quyết toán/BCTC) chậm nhất ngày 31/03 năm sau. Trả về
    None nếu 'Kỳ' không khớp mẫu nào (vd dòng 'chưa tìm thấy tờ khai' ghi
    khoảng ngày '01/01/2016 - 31/12/2025') — KHÔNG đoán mò hạn trong trường
    hợp đó."""
    import re as _re_han
    s = str(ky or "").strip()
    m = _re_han.match(r'^Q(\d)/(\d{4})$', s, _re_han.IGNORECASE)
    if m:
        q, nam = int(m.group(1)), int(m.group(2))
        # hạn = ngày cuối THÁNG ĐẦU của quý SAU — quý q kết thúc ở tháng q*3,
        # quý sau bắt đầu ở tháng q*3+1 (q=1->tháng 4, q=2->tháng 7, q=3->
        # tháng 10, q=4->tháng 1 năm sau). TRƯỚC ĐÂY nhầm dùng q+1 (ra tháng
        # 2/3/4/5) thay vì q*3+1 (đúng phải là 4/7/10/1) — đã sửa.
        thang_han, nam_han = (q * 3 + 1, nam) if q < 4 else (1, nam + 1)
        return datetime.date(nam_han, thang_han, calendar.monthrange(nam_han, thang_han)[1])
    if _re_han.match(r'^\d{4}$', s):
        return datetime.date(int(s) + 1, 3, 31)
    m = _re_han.match(r'^(\d{1,2})/(\d{4})$', s)
    if m:
        thang, nam = int(m.group(1)), int(m.group(2))
        if 1 <= thang <= 12:
            thang_han, nam_han = (thang + 1, nam) if thang < 12 else (1, nam + 1)
            return datetime.date(nam_han, thang_han, 20)
    return None

# Nhãn gọn cho tên file, theo mã tờ khai (vd '01/GTGT' -> '01GTGT')
_TEN_TO_KHAI_MAP = {
    "01/GTGT": "01GTGT",
    "01/KK-TNCN": "01KK-TNCN",
    "02/KK-TNCN": "02KK-TNCN",
    "03/KK-TNCN": "03KK-TNCN",
    "05/KK-TNCN": "05KK-TNCN",
    "03/TNDN": "QTTNDN_BCTC",
    "05/QTT-TNCN": "QTTNCN",
    "02/TNDN": "TNDN",
}

def _ma_to_khai_tu_ten(ten_to_khai):
    """Lấy MÃ tờ khai (vd '05/KK-TNCN') từ chuỗi đầy đủ 'MÃ - Tên đầy đủ' trong cột Tờ khai."""
    s = str(ten_to_khai or "").strip()
    if not s:
        return ""
    if " - " in s:
        return s.split(" - ", 1)[0].strip()
    return s.split(" ")[0].strip()

def _chuan_ky_ten_file(ky):
    """Chuẩn hoá chuỗi kỳ ('Quý 2/2026','Năm 2025','Tháng 3/2026'...) thành tên gọn để đặt tên file."""
    import re as _re
    kd = _khong_dau(ky)   # đã bỏ dấu + viết thường
    m = _re.search(r'quy\s*(\d)\D+(\d{4})', kd)
    if m:
        return f"QUY{m.group(1)}.{m.group(2)}"
    m = _re.search(r'nam\s*(\d{4})', kd)
    if m:
        return f"NAM{m.group(1)}"
    m = _re.search(r'thang\s*(\d{1,2})\D+(\d{4})', kd)
    if m:
        return f"T{int(m.group(1))}.{m.group(2)}"
    m = _re.match(r'^q\s*(\d)\s*/\s*(\d{4})$', kd)
    if m:
        return f"QUY{m.group(1)}.{m.group(2)}"
    if _re.match(r'^\d{4}$', kd):
        return f"NAM{kd}"
    m = _re.match(r'^(\d{1,2})\s*/\s*(\d{4})$', kd)
    if m:
        return f"T{int(m.group(1))}.{m.group(2)}"
    out = _re.sub(r'[^a-z0-9]', '', kd).upper()
    return out or "KyKhongRo"

def _so_lan_bs(v):
    """Bóc số lần bổ sung từ ô 'Lần bổ sung' (có thể là '0','1','Lần 2',...). 0 = tờ khai gốc."""
    import re as _re
    m = _re.search(r'\d+', str(v or ""))
    return int(m.group(0)) if m else 0

def _ten_file_than_thien(ten_to_khai_full, ky, mst, lan_bs):
    """Ghép tên file thân thiện: {MÃ}_{KỲ}-{MST}[_L{lần bổ sung}].
    Ví dụ: 05KK-TNCN_QUY2.2026-0316429370  hoặc  QTTNDN_BCTC_NAM2025-0316429370_L1"""
    import re as _re
    ma = _ma_to_khai_tu_ten(ten_to_khai_full)
    nhan = _TEN_TO_KHAI_MAP.get(ma.upper()) if ma else None
    if not nhan:
        nhan = _re.sub(r'[^A-Za-z0-9]', '', ma) or "ToKhai"
    ky_s = _chuan_ky_ten_file(ky)
    mst_s = _re.sub(r'[^A-Za-z0-9]', '', str(mst or ""))
    ten = f"{nhan}_{ky_s}-{mst_s}"
    lb = _so_lan_bs(lan_bs)
    if lb > 0:
        ten += f"_L{lb}"
    return ten

# Nhận diện MÃ NGẮN loại tờ khai từ TÊN ĐẦY ĐỦ — dùng cho tab "Thuế điện tử"
# (cột "Tờ khai/Phụ lục" ghi TÊN ĐẦY ĐỦ, vd "TỜ KHAI THUẾ GIÁ TRỊ GIA TĂNG
# (TT80/2021)(00-...)", KHÔNG có dạng "MÃ - Tên" như tab DVC, nên
# _ma_to_khai_tu_ten/_TEN_TO_KHAI_MAP không dùng được — trước đây rơi vào
# nhánh dự phòng, cắt bỏ dấu kiểu Việt còn trơ lại đúng 1 chữ cái đầu (vd
# "Tờ khai..." -> "T"), khiến tên file vô nghĩa như "T_QUY1.2025-...").
# Khớp theo TỪ KHÓA (không phân biệt hoa/thường, không dấu) — ưu tiên các
# mẫu CỤ THỂ hơn (quyết toán, báo cáo tài chính...) trước các mẫu chung.
_TDT_LOAI_TU_KHOA = [
    ("QTTNCN", ["quyet toan thue thu nhap ca nhan", "quyet toan tncn"]),
    ("QTTNDN", ["quyet toan thue thu nhap doanh nghiep", "quyet toan tndn"]),
    ("BCTC",   ["bao cao tai chinh"]),
    ("GTGT",   ["gia tri gia tang", "gtgt"]),
    ("TNCN",   ["thu nhap ca nhan", "tncn"]),
    ("TNDN",   ["thu nhap doanh nghiep", "tndn"]),
    ("TTDB",   ["tieu thu dac biet"]),
    ("TAINGUYEN", ["thue tai nguyen", "tai nguyen"]),
    ("MONBAI", ["mon bai"]),
    ("BVMT",   ["bao ve moi truong"]),
    ("XNK",    ["xuat nhap khau"]),
]
_TDT_TU_BO_QUA = {"to", "khai", "bao", "cao", "thue", "ve", "cua", "va", "so", "phu", "luc"}

def _loai_tk_tu_ten_day_du(ten_to_khai_full):
    """Nhận diện mã ngắn loại tờ khai từ TÊN ĐẦY ĐỦ (không có mã đi kèm)."""
    kd = _khong_dau(ten_to_khai_full or "")
    for ma_ngan, tu_khoa_list in _TDT_LOAI_TU_KHOA:
        if any(tk in kd for tk in tu_khoa_list):
            return ma_ngan
    # không nhận diện được -> lấy từ có nghĩa ĐẦU TIÊN (bỏ các từ đệm
    # "tờ khai", "báo cáo"...) thay vì lấy đại 1 chữ cái như trước đây
    words = [w for w in kd.split() if w and w not in _TDT_TU_BO_QUA]
    return (words[0].upper() if words else "ToKhai")

def _ten_file_than_thien_tdt(ten_to_khai_full, ky, mst, lan_bs):
    """Như _ten_file_than_thien nhưng dùng nhận diện loại tờ khai theo TÊN
    ĐẦY ĐỦ (tab Thuế điện tử). Ví dụ: GTGT_QUY1.2025-0313889644."""
    import re as _re
    nhan = _loai_tk_tu_ten_day_du(ten_to_khai_full)
    ky_s = _chuan_ky_ten_file(ky)
    mst_s = _re.sub(r'[^A-Za-z0-9]', '', str(mst or ""))
    ten = f"{nhan}_{ky_s}-{mst_s}"
    lb = _so_lan_bs(lan_bs)
    if lb > 0:
        ten += f"_L{lb}"
    return ten

def _dvc_map_bang(rows):
    """Từ mảng dòng {cells, ma} (DOM, xem _JS_PARSE_TABLE) → list dict theo TRACUU_COLS + 'ma'.
    Tự dò cột theo tiêu đề. Cũng chấp nhận mảng dòng×ô "thô" (list) để tương thích ngược."""
    if not rows:
        return []
    def _cells_of(r):
        return r.get("cells") or [] if isinstance(r, dict) else (r or [])
    def _ma_of(r):
        return (r.get("ma") or "") if isinstance(r, dict) else ""

    # tìm dòng tiêu đề: dòng chứa 'trang thai' hoặc 'to khai'
    h_idx = -1
    for i, r in enumerate(rows[:5]):
        joined = _khong_dau(" ".join(_cells_of(r)))
        if "trang thai" in joined or "to khai" in joined or "ky tinh" in joined:
            h_idx = i; break
    if h_idx < 0:
        h_idx = 0
    header = [_khong_dau(c) for c in _cells_of(rows[h_idx])]

    def find(*keys, avoid=()):
        for j, h in enumerate(header):
            if any(k in h for k in keys) and not any(a in h for a in avoid):
                return j
        return -1

    col = {
        "trang_thai": find("trang thai"),
        "ngay_nop":   find("ngay nop", "ngay"),
        "ky":         find("ky tinh", avoid=()) if find("ky tinh") >= 0 else find("ky", avoid=("ky thuat",)),
        "lan_bs":     find("bo sung"),
        "lan_nop":    find("lan nop", avoid=("bo sung",)),
        "loai":       find("loai"),
        "to_khai":    find("to khai", "thu tuc", avoid=("loai",)),
    }
    out = []
    for r in rows[h_idx + 1:]:
        cells = _cells_of(r)
        if not cells or all(not c for c in cells):
            continue
        # bỏ dòng phân trang / tổng
        j = _khong_dau(" ".join(cells))
        if "tong so ban ghi" in j or "trang" == j[:5]:
            continue
        rec = {}
        ok_any = False
        for c in TRACUU_COLS:
            idx = col.get(c, -1)
            v = cells[idx] if 0 <= idx < len(cells) else ""
            rec[c] = v
            if v:
                ok_any = True
        if ok_any:
            rec["ma"] = _ma_of(r)
            out.append(rec)
    return out


def _dvc_map_bang_tdt(rows):
    """Như _dvc_map_bang nhưng cho bảng kết quả tab "Tra cứu hồ sơ đã nộp
    trên thuế điện tử" (dùng cho tờ khai nộp TRƯỚC 01/07/2025 — tab DVC chỉ
    có dữ liệu TỪ 01/07/2025). Cột thật: STT, Mã giao dịch, Tờ khai/Phụ lục,
    Kỳ tính thuế, Loại tờ khai, Lần nộp, Lần bổ sung, Ngày nộp, Nơi nộp,
    Tiến trình giải quyết hồ sơ (Trạng thái), Thao tác.
    Trả list dict theo TRACUU_COLS (dùng chung khuôn Excel với tab DVC) +
    'ma' = Mã giao dịch (khoá để tải file — định dạng số, khác mã hồ sơ
    dạng chữ-số-chấm-gạch của tab DVC nhưng cùng cơ chế tải)."""
    if not rows:
        return []
    def _cells_of(r):
        return r.get("cells") or [] if isinstance(r, dict) else (r or [])

    h_idx = -1
    for i, r in enumerate(rows[:5]):
        joined = _khong_dau(" ".join(_cells_of(r)))
        if "trang thai" in joined or "to khai" in joined or "ma giao dich" in joined:
            h_idx = i; break
    if h_idx < 0:
        h_idx = 0
    header = [_khong_dau(c) for c in _cells_of(rows[h_idx])]

    def find(*keys, avoid=()):
        for j, h in enumerate(header):
            if any(k in h for k in keys) and not any(a in h for a in avoid):
                return j
        return -1

    col = {
        "ma_giao_dich": find("ma giao dich"),
        "to_khai":      find("to khai", "phu luc"),
        "ky":           find("ky tinh thue", "ky"),
        "loai":         find("loai to khai", "loai"),
        "lan_nop":      find("lan nop", avoid=("bo sung",)),
        "lan_bs":       find("bo sung"),
        "ngay_nop":     find("ngay nop", "ngay"),
        "trang_thai":   find("trang thai", "tien trinh"),
    }
    out = []
    for r in rows[h_idx + 1:]:
        cells = _cells_of(r)
        if not cells or all(not c for c in cells):
            continue
        j = _khong_dau(" ".join(cells))
        if "tong so ban ghi" in j or "trang" == j[:5]:
            continue
        rec = {}
        ok_any = False
        for c in TRACUU_COLS:
            idx = col.get(c, -1)
            v = cells[idx] if 0 <= idx < len(cells) else ""
            rec[c] = v
            if v:
                ok_any = True
        if ok_any:
            ma_idx = col.get("ma_giao_dich", -1)
            rec["ma"] = cells[ma_idx].strip() if 0 <= ma_idx < len(cells) else ""
            out.append(rec)
    return out


def _dvc_browser_login_2pass(drv, mst, pw1, pw2):
    """Thử pass1 rồi pass2. Trả (ok, dùng_pass(1/2/0), info)."""
    if pw1:
        ok, info = _dvc_browser_login(drv, mst, pw1)
        if ok:
            return True, 1, info
        info1 = info
    else:
        info1 = {"bo_qua": "pass1 trống"}
    if pw2:
        ok, info = _dvc_browser_login(drv, mst, pw2)
        if ok:
            return True, 2, info
        return False, 0, {"pass1": info1, "pass2": info}
    return False, 0, {"pass1": info1, "pass2": "(không có pass2)"}


def _dvc_mo_ta_loi_dang_nhap(info):
    """Rút gọn dict 'info' trả về từ _dvc_browser_login_2pass (khi đăng nhập
    THẤT BẠI) thành 1 dòng dễ hiểu — TRƯỚC ĐÂY thông tin chi tiết này bị bỏ
    qua hoàn toàn ở nơi gọi (chỉ hiện chung chung "sai mật khẩu / lỗi đăng
    nhập"), khiến người dùng không biết CHÍNH XÁC là sai mật khẩu 1, mật khẩu
    2, hay lỗi khác (trang không tải được, captcha lỗi liên tục...)."""
    if not isinstance(info, dict):
        return str(info)[:200]

    def _1_dong(nhan, sub):
        if isinstance(sub, str):
            return f"{nhan}: {sub}"
        if isinstance(sub, dict):
            if "bo_qua" in sub:
                return f"{nhan}: {sub['bo_qua']}"
            if "loi" in sub:
                return f"{nhan}: {sub['loi']}"
            da_thu = sub.get("da_thu")
            if da_thu:
                return f"{nhan}: sai sau {len(da_thu)} lần thử ({da_thu[-1]})"
        return f"{nhan}: thất bại (không rõ lý do — {str(sub)[:100]})"

    phan = []
    if "pass1" in info:
        phan.append(_1_dong("Mật khẩu 1", info["pass1"]))
    if "pass2" in info:
        phan.append(_1_dong("Mật khẩu 2", info["pass2"]))
    return " | ".join(phan) if phan else str(info)[:200]


def _dvc_browser_tracuu(drv, tu, den, so_lan=8):
    """Tra cứu → trả (rows_struct, ma_list, raw_html, diag)."""
    import time as _t
    diag = []
    drv.get(DVC_BASE + "/tchs"); _t.sleep(1.5)
    if not _dvc_wait_jquery(drv, 15):
        return [], [], "", ["Trang /tchs không nạp được"]
    for lan in range(1, so_lan + 1):
        try:
            cap = _dvc_cap_from_js(drv.execute_async_script(_JS_GETCAPTCHA))
        except Exception as e:
            diag.append(f"(captcha lỗi: {e})"); continue
        if not cap:
            diag.append("(captcha rỗng)"); continue
        try:
            res = drv.execute_async_script(_JS_SEARCH, tu, den, cap)
        except Exception as e:
            diag.append(f"{cap}→lỗi search: {e}"); continue
        if res and res.get("ok"):
            html = res.get("html") or ""
            low = html.lower()
            if ("table-container" in low or "tổng số bản ghi" in low or "totalpage" in low):
                ma = _dvc_parse_ma_ho_so(html)
                rows = []
                try:
                    pr = drv.execute_async_script(_JS_PARSE_TABLE, html)
                    if pr and pr.get("ok"):
                        rows = _dvc_map_bang(pr.get("rows") or [])
                except Exception as e:
                    diag.append(f"parse bảng lỗi: {e}")
                diag.append(f"{cap}→OK: {len(ma)} hồ sơ, {len(rows)} dòng bảng")
                return rows, ma, html, diag
            diag.append(f"{cap}→chưa ra bảng ({len(html)})")
        else:
            diag.append(f"{cap}→{str(res)[:80]}")
        _t.sleep(0.4)
    return [], [], "", diag


def _dvc_browser_tracuu_tdt(drv, tu, den, so_lan=8):
    """Như _dvc_browser_tracuu nhưng tra cứu ở tab "Tra cứu hồ sơ đã nộp
    trên thuế điện tử" — chỉ hỗ trợ tờ khai nộp TRƯỚC 01/07/2025 (tab DVC
    hiện có chỉ có dữ liệu TỪ 01/07/2025 trở đi, nên 2 tab bổ sung cho nhau).
    Trả (rows_struct, ma_list, raw_html, diag)."""
    import time as _t
    diag = []
    drv.get(DVC_BASE + "/tchs"); _t.sleep(1.5)
    if not _dvc_wait_jquery(drv, 15):
        return [], [], "", ["Trang /tchs không nạp được"]
    for lan in range(1, so_lan + 1):
        try:
            cap = _dvc_cap_from_js(drv.execute_async_script(_JS_GETCAPTCHA))
        except Exception as e:
            diag.append(f"(captcha lỗi: {e})"); continue
        if not cap:
            diag.append("(captcha rỗng)"); continue
        try:
            res = drv.execute_async_script(_JS_SEARCH_TDT, tu, den, cap)
        except Exception as e:
            diag.append(f"{cap}→lỗi search: {e}"); continue
        if res and res.get("ok"):
            html = res.get("html") or ""
            low = html.lower()
            if ("tổng số bản ghi" in low or "mã giao dịch" in low
                    or "<table" in low or "totalpage" in low):
                rows, ma = [], []
                try:
                    pr = drv.execute_async_script(_JS_PARSE_TABLE, html)
                    if pr and pr.get("ok"):
                        rows = _dvc_map_bang_tdt(pr.get("rows") or [])
                        ma = [r["ma"] for r in rows if r.get("ma")]
                except Exception as e:
                    diag.append(f"parse bảng lỗi: {e}")
                diag.append(f"{cap}→OK: {len(ma)} hồ sơ, {len(rows)} dòng bảng")
                return rows, ma, html, diag
            diag.append(f"{cap}→chưa ra bảng ({len(html)})")
        else:
            diag.append(f"{cap}→{str(res)[:80]}")
        _t.sleep(0.4)
    return [], [], "", diag


def _dvc_browser_download_tdt(drv, ma):
    """Tải tờ khai từ tab "Thuế điện tử" — vào trang chi tiết (?loai=ETAX,
    đúng đường dẫn xác nhận được từ request thật) trước để có đúng ngữ
    cảnh/referer, rồi gọi POST /tthc/tchs/downloadhoso-tdt?loaiTraCuu=ETAX
    (endpoint đã xác nhận qua request bắt được từ trình duyệt)."""
    import time as _t
    try:
        drv.get(f"{DVC_BASE}/tchs/files/detail/{ma}?loai=ETAX")
        _t.sleep(1.0)
        _dvc_wait_jquery(drv, 10)
    except Exception:
        pass
    # "Mã giao dịch" là số nguyên (17 chữ số) — dựng JSON body sẵn ở Python
    # để giữ nguyên chính xác, tránh mất độ chính xác nếu để JS tự chuyển
    # qua kiểu Number (xem giải thích ở _JS_DOWNLOAD_TDT).
    ma_so = "".join(ch for ch in str(ma) if ch.isdigit()) or "0"
    body = '{"maHoSo":%s}' % ma_so
    res = drv.execute_async_script(_JS_DOWNLOAD_TDT, body)
    if not res or not res.get("ok"):
        raise Exception(f"{res}")
    d = _dvc_norm_data(res.get("data"))
    if not isinstance(d, dict):
        raise Exception("phản hồi không hợp lệ")
    content = d.get("content") or ""
    fname = d.get("fileName") or f"{ma}.zip"
    raw = base64.b64decode(content) if content else b""
    return fname, raw


def _xuat_tracuu_excel(rows, path):
    """rows: list dict có mst, ten, + TRACUU_COLS. Ghi Excel theo mẫu Tracuu.xls."""
    from openpyxl import Workbook
    from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
    wb = Workbook(); ws = wb.active; ws.title = "Tracuutokhai"
    ws["A3"] = "TRA CỨU TỜ KHAI"
    ws["A3"].font = Font(bold=True, size=14)
    hr = 5
    for c, h in enumerate(TRACUU_HEADERS, 1):
        cell = ws.cell(hr, c, h)
        cell.font = Font(bold=True, color="FFFFFF")
        cell.fill = PatternFill("solid", fgColor="2F5496")
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
    thin = Side(style="thin", color="BBBBBB")
    bd = Border(left=thin, right=thin, top=thin, bottom=thin)
    do_nhat = PatternFill("solid", fgColor="FFC7CE")   # nền đỏ nhạt — trễ hạn nộp
    r = hr + 1
    for rec in rows:
        tt = _khong_dau(rec.get("trang_thai", ""))
        chua_nop = "chua nop" in tt
        do = chua_nop or "khong chap nhan" in tt or "tu choi" in tt
        # Tờ khai BỔ SUNG (sửa đổi/bổ sung 1 kỳ đã nộp trước đó) đương nhiên
        # nộp SAU hạn của kỳ gốc — không so hạn/không tô đỏ trễ hạn cho loại
        # này, chỉ áp dụng cho tờ khai CHÍNH THỨC.
        la_bo_sung = "bo sung" in _khong_dau(rec.get("loai", ""))
        # Đối chiếu Ngày nộp với HẠN NỘP suy từ Kỳ (xem _han_nop_to_khai) —
        # CHỈ kết luận được khi có cả 2: Ngày nộp thật (đã nộp) VÀ suy được
        # hạn từ Kỳ (bỏ qua các dòng "chưa tìm thấy tờ khai" ghi khoảng ngày
        # thay vì đúng 1 kỳ) — không đoán mò khi thiếu dữ liệu.
        han = _han_nop_to_khai(rec.get("ky", ""))
        ngay_nop_s = str(rec.get("ngay_nop", "") or "").strip()
        tre_han = False
        dung_han_txt = ""
        if la_bo_sung:
            dung_han_txt = "Tờ khai bổ sung (không tính trễ hạn)"
        elif han and ngay_nop_s:
            try:
                ngay_nop_d = datetime.datetime.strptime(
                    ngay_nop_s.split(" ")[0], "%d/%m/%Y").date()
                tre_han = ngay_nop_d > han
                dung_han_txt = (f"Trễ hạn (hạn {han.strftime('%d/%m/%Y')})" if tre_han
                                else f"Đúng hạn (hạn {han.strftime('%d/%m/%Y')})")
            except Exception:
                pass
        vals = ([rec.get("mst", ""), rec.get("ten", "")] + [rec.get(c, "") for c in TRACUU_COLS]
               + [dung_han_txt])
        for c, v in enumerate(vals, 1):
            cell = ws.cell(r, c, v); cell.border = bd
            cell.alignment = Alignment(vertical="center", wrap_text=(c == 2 or c == 3))
            if tre_han:
                cell.fill = do_nhat   # tô đỏ NGUYÊN DÒNG khi nộp trễ hạn
            if chua_nop:
                # cả dòng đỏ để dễ thấy công ty chưa nộp
                cell.font = Font(color="C00000", bold=True)
            elif c == 9:
                if do:
                    cell.font = Font(color="C00000", bold=True)   # đỏ đậm
                elif "da chap nhan" in tt:
                    cell.font = Font(color="008000")              # xanh
                elif tt:
                    cell.font = Font(color="BF8F00")              # vàng (chờ)
            elif c == 10 and tre_han:
                cell.font = Font(color="C00000", bold=True)
        r += 1
    widths = [16, 42, 40, 10, 12, 13, 9, 11, 16, 22]
    for c, w in enumerate(widths, 1):
        ws.column_dimensions[ws.cell(1, c).column_letter].width = w
    ws.freeze_panes = "A6"
    # bật filter cho các cột (hàng tiêu đề ở dòng 5)
    last_row = max(hr, r - 1)
    ws.auto_filter.ref = f"A{hr}:J{last_row}"
    wb.save(path)

def _xuat_saipass_excel(items, path):
    """items: list dict {mst, ten, ly_do}."""
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment
    wb = Workbook(); ws = wb.active; ws.title = "SaiMatKhau"
    ws["A1"] = "DANH SÁCH CÔNG TY ĐĂNG NHẬP KHÔNG ĐƯỢC"
    ws["A1"].font = Font(bold=True, size=13)
    heads = ["Mã số thuế", "Tên công ty", "Lý do / Lỗi"]
    for c, h in enumerate(heads, 1):
        cell = ws.cell(3, c, h)
        cell.font = Font(bold=True, color="FFFFFF")
        cell.fill = PatternFill("solid", fgColor="C00000")
        cell.alignment = Alignment(horizontal="center")
    r = 4
    for it in items:
        ws.cell(r, 1, it.get("mst", ""))
        ws.cell(r, 2, it.get("ten", ""))
        ws.cell(r, 3, str(it.get("ly_do", ""))[:500])
        r += 1
    ws.column_dimensions["A"].width = 16
    ws.column_dimensions["B"].width = 42
    ws.column_dimensions["C"].width = 70
    wb.save(path)


@app.post("/api/dvc/test-login/{cid}")
def dvc_test_login(cid: int, body: dict = Body(...)):
    """Thử đăng nhập Dịch vụ công (chỉ kiểm tra, không tải gì).
    body: { matkhau, matkhau2, luu }"""
    conn = db()
    comp = conn.execute("SELECT * FROM companies WHERE id=?", (cid,)).fetchone()
    conn.close()
    if not comp:
        raise HTTPException(404, "Không tìm thấy công ty")
    pw1 = (body.get("matkhau") or (comp["dvc_password"] if "dvc_password" in comp.keys() else "") or "").strip()
    pw2 = (body.get("matkhau2") or (comp["dvc_password2"] if "dvc_password2" in comp.keys() else "") or "").strip()
    if not pw1 and not pw2:
        raise HTTPException(400, "Chưa nhập mật khẩu Dịch vụ công")
    try:
        drv = _dvc_make_driver(headless=True)
    except Exception as e:
        raise HTTPException(500,
            "Không khởi động được trình duyệt Chrome. Hãy chắc máy đã cài Google "
            f"Chrome và có mạng để tải chromedriver lần đầu. Chi tiết: {type(e).__name__}: {e}")
    try:
        ok, dung_pass, info = _dvc_browser_login_2pass(drv, comp["mst"], pw1, pw2)
    except Exception as e:
        import traceback
        raise HTTPException(500, f"Lỗi khi đăng nhập: {type(e).__name__}: {e} | "
                                 f"{traceback.format_exc()[-400:]}")
    finally:
        try: drv.quit()
        except Exception: pass
    if ok and body.get("luu"):
        conn = db()
        conn.execute("UPDATE companies SET dvc_password=?, dvc_password2=? WHERE id=?",
                     (pw1, pw2, cid))
        conn.commit(); conn.close()
    if not ok:
        raise HTTPException(401, f"Đăng nhập thất bại. {json.dumps(info, ensure_ascii=False)}")
    return {"ok": True, "dung_pass": dung_pass, **(info if isinstance(info, dict) else {}),
            "da_luu_mat_khau": bool(body.get("luu"))}


@app.get("/api/etax/explore/{cid}")
def etax_explore(cid: int):
    """CÔNG CỤ DÒ (tạm): đăng nhập dichvucong → mở 'Dịch vụ khác' → vào
    'Thông báo của CQT' (iframe eTax) → ghi lại cấu trúc để xây tự động hóa.
    Mở thẳng trên trình duyệt: http://127.0.0.1:8686/api/etax/explore/<id>"""
    conn = db()
    comp = conn.execute("SELECT * FROM companies WHERE id=?", (cid,)).fetchone()
    conn.close()
    if not comp:
        raise HTTPException(404, "Không tìm thấy công ty")
    pw1 = ((comp["dvc_password"] if "dvc_password" in comp.keys() else "") or "").strip()
    pw2 = (comp["dvc_password2"] if "dvc_password2" in comp.keys() else "") or ""
    pw2 = pw2.strip()
    info = {"buoc": []}
    try:
        drv = _dvc_make_driver(headless=True, esigner=True)
    except Exception as e:
        raise HTTPException(500, f"Không mở được Chrome: {e}")
    info["esigner_ext"] = getattr(drv, "_esigner_ext", None) or "(KHÔNG tìm thấy tiện ích eSigner đã cài)"
    try:
        ok, dp, li = _dvc_browser_login_2pass(drv, comp["mst"], pw1, pw2)
        info["dang_nhap"] = "OK" if ok else f"THẤT BẠI: {json.dumps(li, ensure_ascii=False)[:200]}"
        if not ok:
            return info
        import time as _t
        # 0) TEST trang CQT NATIVE cua dichvucong (khong can eSigner) - POST khong loc ngay
        try:
            drv.get(DVC_BASE + "/tra-cuu-thongbao-cqt"); _t.sleep(3)
            _dvc_wait_jquery(drv, 8)
            _JS_CQT = r"""
              var cb=arguments[arguments.length-1];
              try{
                var bs=document.querySelector('[name="btnSearch"]');
                var f=bs; while(f&&f.tagName!=='FORM') f=f.parentElement;
                if(!f){cb({ok:false,err:'no form'});return;}
                var p=new URLSearchParams();
                f.querySelectorAll('input[name],select[name],textarea[name]').forEach(function(e){
                  var n=e.name,v=e.value;
                  if(n==='tuNgay'||n==='denNgay')v=''; else if(n==='size')v='100'; else if(n==='page')v='0';
                  p.append(n,v==null?'':v);
                });
                fetch(f.getAttribute('action'),{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:p.toString(),credentials:'same-origin'})
                  .then(r=>r.text()).then(t=>cb({ok:true,html:t})).catch(e=>cb({ok:false,err:''+e}));
              }catch(e){cb({ok:false,err:''+e});}
            """
            res = drv.execute_async_script(_JS_CQT)
            html = (res or {}).get("html") or ""
            info["dvc_cqt_len"] = len(html)
            import re as _re0
            try:
                pr = drv.execute_async_script(_JS_PARSE_TABLE, html)
                info["dvc_cqt_bang"] = ((pr or {}).get("rows") or [])[:8]
            except Exception as e:
                info["dvc_cqt_bang_err"] = str(e)
            flat0 = _re0.sub(r"\s+", " ", html)
            info["dvc_cqt_msg"] = [m.group(0)[:110] for m in _re0.finditer(
                r".{0,30}(?:b[ảa]n ghi|kh[ôo]ng c[óo] d[ữu] li[ệe]u|Tr[ạa]ng th[áa]i|S[ốô] th[ôo]ng b[áa]o).{0,30}", flat0, _re0.I)][:8]
            info["dvc_cqt_taive"] = list({o[:150] for o in _re0.findall(
                r'(?:onclick|href)=["\']([^"\']*(?:tai|download|idfile|tepdinhkem|thongbao|tbao|file)[^"\']*)["\']', html, _re0.I)})[:20]
            m0 = _re0.search(r'<table[^>]*>(?:(?!</table>)[\s\S]){0,2200}', html)
            info["dvc_cqt_table_html"] = (m0.group(0)[:2200] if m0 else "(khong thay table)")
        except Exception as e:
            info["dvc_cqt_err"] = str(e)
        # 1) Mở trang Dịch vụ khác
        drv.get(DVC_BASE + "/dich-vu-khac"); _t.sleep(3)
        info["dvk_title"] = drv.title
        info["dvk_url"] = drv.current_url
        # các phần tử có chữ liên quan "Thông báo của CQT"
        try:
            els = drv.find_elements("xpath",
                "//*[contains(translate(text(),'CQTHÔNGBÁO','cqthôngbáo'),'thông báo')]")
            info["el_thongbao"] = [ (e.tag_name + ":" + (e.text or "")[:40]) for e in els[:15] ]
        except Exception as e:
            info["el_thongbao_err"] = str(e)
        # iframe hiện có
        def dump_iframes(tag):
            try:
                fr = drv.find_elements("tag name", "iframe")
                return [{"src": (f.get_attribute("src") or "")[:160]} for f in fr]
            except Exception as e:
                return [f"err: {e}"]
        info["iframes_truoc"] = dump_iframes("truoc")
        import re as _re
        # 1b) DÒ cách 'Thông báo của CQT' được gắn: href, onclick, ngữ cảnh HTML
        full = drv.page_source or ""
        flat = _re.sub(r"\s+", " ", full)
        ctx = []
        for m in _re.finditer(r".{0,120}Th[ôo]ng b[áa]o c[ủu]a CQT.{0,120}", flat):
            ctx.append(m.group(0))
        info["ngu_canh_CQT"] = ctx[:4]
        # các link/onclick liên quan eTax/thuedientu/thong-bao
        info["href_lq"] = list({h for h in _re.findall(r'href=["\']([^"\']+)["\']', full)
                                if any(k in h.lower() for k in ("thuedientu","etaxnnt","thong-bao","tbao","cqt","request"))})[:20]
        info["onclick_lq"] = list({o[:120] for o in _re.findall(r'onclick=["\']([^"\']+)["\']', full)
                                   if any(k in o.lower() for k in ("thuedientu","etaxnnt","thong","tbao","cqt","sso","window.open"))})[:20]
        info["js_open"] = list({o[:140] for o in _re.findall(r'window\.open\([^)]{0,140}', full)})[:15]
        import re as _re
        # 2) Bấm card "Thông báo của CQT" = redirectHandler('360109',...) -> SSO sang eTax
        try:
            drv.execute_script("try{redirectHandler('360109','','','','Y','');}catch(e){}")
        except Exception as e:
            info["rh_err"] = str(e)
        _t.sleep(8)
        info["so_tab"] = len(drv.window_handles)
        # nếu mở tab mới -> sang tab mới nhất
        try:
            if len(drv.window_handles) > 1:
                drv.switch_to.window(drv.window_handles[-1])
                _t.sleep(3)
        except Exception:
            pass
        info["etax_url"] = drv.current_url
        info["etax_title"] = drv.title
        # nếu eTax nằm trong iframe -> vào iframe
        try:
            for f in drv.find_elements("tag name", "iframe"):
                s = (f.get_attribute("src") or "")
                if "thuedientu" in s or "etaxnnt" in s or "Request" in s:
                    info["etax_iframe_src"] = s[:160]
                    drv.switch_to.frame(f); _t.sleep(2)
                    break
        except Exception as e:
            info["etax_fr_err"] = str(e)
        # đọc trang eTax: bảng + nút Tra Cứu + form + link tải
        try:
            _dvc_wait_jquery(drv, 8)
        except Exception:
            pass
        src = drv.page_source or ""
        info["etax_len"] = len(src)
        # bảng kết quả (parse DOM hiện tại)
        try:
            pr = drv.execute_async_script(_JS_PARSE_TABLE, src)
            info["etax_bang"] = ((pr or {}).get("rows") or [])[:6]
        except Exception as e:
            info["etax_bang_err"] = str(e)
        flat = _re.sub(r"\s+", " ", src)
        info["etax_thongdiep"] = [m.group(0)[:120] for m in _re.finditer(
            r".{0,40}(?:b[ảa]n ghi|kh[ôo]ng c[óo] d[ữu] li[ệe]u|Tr[ạa]ng th[áa]i|S[ốô] th[ôo]ng b[áa]o).{0,40}", flat, _re.I)][:8]
        # nút Tra Cứu + form (dse_)
        info["etax_buttons"] = list({(m or "")[:40] for m in _re.findall(r'<(?:button|input)[^>]*value=["\']([^"\']+)["\']', src)})[:20]
        info["etax_forms"] = _re.findall(r'<form[^>]*action=["\']([^"\']*)["\']', src)[:4]
        info["etax_inputs"] = list({n for n in _re.findall(r'<input[^>]+name=["\']([^"\']+)["\']', src)})[:30]
        # link/onclick "Tải thông báo"
        info["etax_taive"] = list({o[:160] for o in _re.findall(
            r'(?:onclick|href)=["\']([^"\']*(?:tai|download|getFile|TBao|dse_)[^"\']*)["\']', src, _re.I)})[:25]
        m = _re.search(r'<table[^>]*>(?:(?!</table>)[\s\S]){0,2600}', src)
        info["etax_table_html"] = (m.group(0)[:2600] if m else "(khong thay table)")
        return info
    except Exception as e:
        import traceback
        info["loi"] = f"{e} | {traceback.format_exc()[-300:]}"
        return info
    finally:
        try: drv.quit()
        except Exception: pass


@app.get("/api/dvc/captcha-debug/{cid}", response_class=HTMLResponse)
def dvc_captcha_debug(cid: int):
    """Trang xem captcha Dịch vụ công thật + thử OCR, để dò vì sao không giải được.
    Mở: http://127.0.0.1:8686/api/dvc/captcha-debug/<id-công-ty>"""
    client = DVCClient()
    DVC_CLIENTS[cid] = client
    try:
        client.prime()
    except Exception as e:
        return f"<h3>Lỗi prime: {e}</h3>"
    ts = int(time.time() * 1000)
    h = {
        "Accept": "image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8",
        "Referer": DVC_BASE + "/login",
        "Sec-Fetch-Dest": "image", "Sec-Fetch-Mode": "no-cors",
        "Sec-Fetch-Site": "same-origin",
    }
    # KHÔNG theo redirect để xem server thực sự trả gì
    r = client.session.get(f"{DVC_BASE}/getCaptcha?{ts}", headers=h, timeout=30,
                           allow_redirects=False)
    redir = {"status": r.status_code, "location": r.headers.get("location"),
             "url_cuoi": r.url}
    ct = (r.headers.get("content-type") or "").lower()
    data = r.content or b""

    # ---- Thử nhiều biến thể request để tìm cái trả về ẢNH ----
    thi_nghiem = []
    variants = [
        ("XHR + referer /login",
         {**h, "X-Requested-With": "XMLHttpRequest"}),
        ("referer /homelogin",
         {**h, "Referer": DVC_BASE + "/homelogin"}),
        ("referer /tchs (captcha lần 2)",
         {**h, "Referer": DVC_BASE + "/tchs", "X-Requested-With": "XMLHttpRequest"}),
        ("không có Sec-Fetch, có XHR",
         {"Accept": "image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8",
          "Referer": DVC_BASE + "/login", "X-Requested-With": "XMLHttpRequest"}),
    ]
    for ten, hv in variants:
        try:
            ts2 = int(time.time() * 1000)
            rv = client.session.get(f"{DVC_BASE}/getCaptcha?{ts2}", headers=hv,
                                    timeout=30, allow_redirects=False)
            cv = (rv.headers.get("content-type") or "").lower()
            dv = rv.content or b""
            la_anh = ("image" in cv or "svg" in cv
                      or dv[:5].lstrip().lower().startswith(b"<svg")
                      or dv[:4] in (b"\x89PNG", b"GIF8") or dv[:2] == b"\xff\xd8")
            thi_nghiem.append({"ten": ten, "status": rv.status_code,
                               "ct": cv or "(trống)", "len": len(dv),
                               "la_anh": "✅ ẢNH" if la_anh else "❌ không phải ảnh",
                               "loc": rv.headers.get("location") or ""})
        except Exception as e:
            thi_nghiem.append({"ten": ten, "status": "lỗi", "ct": str(e),
                               "len": 0, "la_anh": "", "loc": ""})
    head = data[:400]
    head_txt = head.decode("utf-8", "replace")
    is_svg = ("svg" in ct or head.lstrip()[:5].lower().startswith(b"<svg")
              or b"<svg" in head.lower())
    # rasterize nếu svg
    png = _svg_to_png(data.decode("utf-8", "replace")) if is_svg else data
    import re as _re
    has_text = ("<text" in head_txt.lower())
    n_path = data.lower().count(b"<path")
    # OCR thử
    ocr = _get_ddddocr()
    ocr_raw = ""
    if ocr:
        try:
            ocr_raw = (ocr.classification(data) or "").strip()
        except Exception as e:
            ocr_raw = f"(lỗi: {e})"
    ocr_png = _ocr_png(png) if png else ""
    # ---- Soi trang /login để tìm URL captcha & form thật ----
    import re as _re2
    soi = {"login": [], "img": [], "form": [], "captcha_refs": []}
    try:
        nav = {"Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
               "Sec-Fetch-Dest": "document", "Sec-Fetch-Mode": "navigate",
               "Sec-Fetch-Site": "same-origin", "Referer": DVC_BASE + "/homelogin"}
        rl = client.session.get(DVC_BASE + "/login", headers=nav, timeout=30,
                                allow_redirects=True)
        ltxt = rl.text or ""
        soi["login"] = [f"status={rl.status_code}", f"len={len(ltxt)}",
                        f"url_cuoi={rl.url}"]
        # làm phẳng khoảng trắng để regex bắt qua nhiều dòng
        flat = _re2.sub(r'\s+', ' ', ltxt)
        for m in _re2.finditer(r'.{0,70}[Cc]aptcha.{0,70}', flat):
            soi["captcha_refs"].append(m.group(0))
        # gộp trùng, giữ tối đa 20
        seen = set(); uniq = []
        for s in soi["captcha_refs"]:
            if s not in seen:
                seen.add(s); uniq.append(s)
        soi["captcha_refs"] = uniq[:20]
        # các lời gọi ajax/fetch/getCaptcha/loginLDAP trong JS
        for kw in ("getCaptcha", "loginLDAP", "checkCaptcha", "$.ajax", "fetch(",
                   "XMLHttpRequest", "/tthc/"):
            for m in _re2.finditer(_re2.escape(kw) + r'.{0,80}', flat):
                soi["img"].append(m.group(0))  # tái dùng list 'img' để hiện
        seen = set(); uniq = []
        for s in soi["img"]:
            if s not in seen:
                seen.add(s); uniq.append(s)
        soi["img"] = uniq[:30]
        # form action + input + giá trị _csrf
        for m in _re2.findall(r'<form[^>]*action=["\']([^"\']*)["\']', ltxt)[:5]:
            soi["form"].append("action=" + m)
        for m in _re2.findall(r'<input[^>]+name=["\']([^"\']+)["\'][^>]*?(?:value=["\']([^"\']*)["\'])?',
                              ltxt)[:25]:
            nm, vl = m
            soi["form"].append(f"input={nm}" + (f" = {vl[:40]}" if vl else ""))
    except Exception as e:
        soi["login"] = [f"lỗi soi login: {e}"]

    raw_b64 = base64.b64encode(data).decode()
    png_b64 = base64.b64encode(png).decode() if png else ""
    mime = ct.split(";")[0] or ("image/svg+xml" if is_svg else "image/png")
    html = f"""<html><head><meta charset='utf-8'><title>DVC Captcha Debug</title>
<style>body{{font-family:system-ui;padding:24px;line-height:1.6}}
img{{border:2px solid #0d6efd;background:#fff;image-rendering:pixelated;margin:6px 0;display:block}}
code{{background:#f0f0f0;padding:2px 5px;border-radius:4px}}
pre{{background:#f6f8fa;padding:10px;border-radius:8px;overflow:auto;max-height:200px}}</style></head><body>
<h2>🔍 Chẩn đoán captcha Dịch vụ công</h2>
<p><b>ddddocr cài đặt:</b> {'✅ có' if ocr else '❌ CHƯA CÀI — đây là nguyên nhân!'} {('('+_DDDDOCR_ERR+')') if _DDDDOCR_ERR else ''}</p>
<p><b>Giả lập TLS Chrome (curl_cffi):</b> {'✅ CÓ — đang vượt vân tay WAF' if client.impersonate else '❌ KHÔNG (chưa cài curl_cffi) — sẽ bị WAF chặn'}</p>
<p><b>HTTP status:</b> {r.status_code} · <b>Content-Type:</b> <code>{ct or '(trống)'}</code> · <b>Kích thước:</b> {len(data)} bytes</p>
<p><b>Redirect (Location):</b> <code>{redir.get('location') or '(không)'}</code></p>
<h3>Thử các biến thể request (tìm cái ra ẢNH):</h3>
<table border="1" cellpadding="6" style="border-collapse:collapse">
<tr><th>Cách gọi</th><th>Status</th><th>Content-Type</th><th>Bytes</th><th>Kết quả</th><th>Location</th></tr>
{''.join(f"<tr><td>{t['ten']}</td><td>{t['status']}</td><td><code>{t['ct']}</code></td><td>{t['len']}</td><td>{t['la_anh']}</td><td>{t['loc']}</td></tr>" for t in thi_nghiem)}
</table>
<p><b>Là SVG:</b> {is_svg} · <b>Có &lt;text&gt;:</b> {has_text} · <b>Số &lt;path&gt;:</b> {n_path}</p>
<p><b>OCR ảnh gốc:</b> <code>{ocr_raw or '(rỗng)'}</code> · <b>OCR sau rasterize:</b> <code>{ocr_png or '(rỗng)'}</code></p>
<h3>🔎 Soi trang /login (tìm URL captcha & form thật):</h3>
<p><b>Trang login:</b> {' · '.join(soi['login'])}</p>
<p><b>Các chỗ chứa "captcha":</b></p>
<pre>{chr(10).join(x.replace('<','&lt;') for x in soi['captcha_refs']) or '(không có — login là SPA/JS render)'}</pre>
<p><b>Lời gọi JS / URL liên quan (getCaptcha, loginLDAP, ajax...):</b></p>
<pre>{chr(10).join(x.replace('<','&lt;') for x in soi['img']) or '(không có)'}</pre>
<p><b>form action / input name:</b></p>
<pre>{chr(10).join(soi['form']) or '(không có)'}</pre>
<h3>Ảnh captcha (gốc):</h3>
<img src="data:{mime};base64,{raw_b64}" width="260">
<h3>Ảnh sau khi chuyển PNG (đưa vào OCR):</h3>
{('<img src="data:image/png;base64,'+png_b64+'" width="260">') if png_b64 else '<i>không rasterize được</i>'}
<h3>400 byte đầu của nội dung:</h3>
<pre>{head_txt.replace('<','&lt;')}</pre>
<p style="color:#666">Bấm F5 để lấy captcha khác. Chụp màn hình trang này gửi lại để tinh chỉnh.</p>
</body></html>"""
    return html


@app.post("/api/dvc/tai-bao-cao/{cid}")
def dvc_tai_bao_cao(cid: int, body: dict = Body(...)):
    """Đăng nhập Dịch vụ công → tra cứu tờ khai/báo cáo ĐÃ NỘP trong khoảng ngày
    → tải file zip về thư mục công ty.
    body: { matkhau, tu_ngay (dd/mm/yyyy), den_ngay (dd/mm/yyyy), luu: bool }"""
    conn = db()
    comp = conn.execute("SELECT * FROM companies WHERE id=?", (cid,)).fetchone()
    conn.close()
    if not comp:
        raise HTTPException(404, "Không tìm thấy công ty")
    pw1 = (body.get("matkhau") or (comp["dvc_password"] if "dvc_password" in comp.keys() else "") or "").strip()
    pw2 = (body.get("matkhau2") or (comp["dvc_password2"] if "dvc_password2" in comp.keys() else "") or "").strip()
    if not pw1 and not pw2:
        raise HTTPException(400, "Chưa nhập mật khẩu Dịch vụ công")
    tu = (body.get("tu_ngay") or "").strip()
    den = (body.get("den_ngay") or "").strip()
    if not tu or not den:
        raise HTTPException(400, "Chưa chọn khoảng ngày (Từ ngày / Đến ngày)")

    folder = _dvc_save_folder(cid)
    if not folder:
        raise HTTPException(400, "Chưa cấu hình thư mục lưu cho công ty này")

    try:
        drv = _dvc_make_driver(headless=True)
    except Exception as e:
        raise HTTPException(500,
            "Không khởi động được trình duyệt Chrome. Hãy chắc máy đã cài Google "
            f"Chrome và có mạng để tải chromedriver lần đầu. Chi tiết: {type(e).__name__}: {e}")

    da_tai, loi_tai, ma_list, search_diag, info = [], [], [], [], {}
    try:
        # 1) Đăng nhập (trình duyệt thật → qua WAF), thử pass1 rồi pass2
        ok, dung_pass, info = _dvc_browser_login_2pass(drv, comp["mst"], pw1, pw2)
        if not ok:
            raise HTTPException(401, f"Đăng nhập thất bại. {json.dumps(info, ensure_ascii=False)}")
        if body.get("luu"):
            conn = db()
            conn.execute("UPDATE companies SET dvc_password=?, dvc_password2=? WHERE id=?",
                         (pw1, pw2, cid))
            conn.commit(); conn.close()

        # 2) Tra cứu hồ sơ đã nộp (captcha lớp 2)
        ma_list, search_diag = _dvc_browser_search(drv, tu, den)
        if not ma_list:
            raise HTTPException(422, "Đăng nhập OK nhưng không tra cứu được danh sách hồ sơ. "
                                     f"Chi tiết: {json.dumps(search_diag, ensure_ascii=False)}")

        # 3) Tải từng hồ sơ: vào trang chi tiết → tải tờ khai + các thông báo
        tai_tb = body.get("tai_thong_bao", True)
        tb_diag = []
        def _luu(fname, raw, pre=""):
            safe = "".join(ch for ch in (pre + fname) if ch not in '\\/:*?"<>|')
            if not safe:
                safe = "file.zip"
            path = os.path.join(folder, safe)
            # tránh ghi đè trùng tên
            if os.path.exists(path):
                base, ext = os.path.splitext(safe)
                k = 2
                while os.path.exists(os.path.join(folder, f"{base}_{k}{ext}")):
                    k += 1
                safe = f"{base}_{k}{ext}"; path = os.path.join(folder, safe)
            with open(path, "wb") as f:
                f.write(raw)
            return safe

        for ma in ma_list:
            # 3a) Mở trang chi tiết hồ sơ (để có ngữ cảnh + đọc idTbao thông báo)
            tb_files = []
            if tai_tb:
                try:
                    tb_files, d = _dvc_browser_thongbao(drv, ma)
                    tb_diag += d
                except Exception as e:
                    tb_diag.append(f"{ma}: lỗi thông báo: {e}")
            # 3b) Tải tờ khai (zip hồ sơ)
            try:
                fname, raw = _dvc_browser_download(drv, ma)
                if not raw:
                    loi_tai.append(f"{ma}: nội dung rỗng")
                else:
                    safe = _luu(fname, raw)
                    da_tai.append({"maHoSo": ma, "file": safe, "kich_thuoc": len(raw)})
            except Exception as e:
                loi_tai.append(f"{ma}: {e}")
            # 3c) Lưu các thông báo của hồ sơ này
            for tb_fname, tb_raw in tb_files:
                try:
                    safe = _luu(tb_fname, tb_raw)
                    da_tai.append({"maHoSo": ma, "file": safe,
                                   "kich_thuoc": len(tb_raw), "loai": "thông báo"})
                except Exception as e:
                    loi_tai.append(f"{ma} (TB): {e}")
            time.sleep(0.4)
    except HTTPException:
        raise
    except Exception as e:
        import traceback
        raise HTTPException(500, f"Lỗi: {type(e).__name__}: {e} | {traceback.format_exc()[-400:]}")
    finally:
        try: drv.quit()
        except Exception: pass

    return {
        "ok": True,
        "thu_muc": folder,
        "so_ho_so": len(ma_list),
        "da_tai": da_tai,
        "loi_tai": loi_tai,
        "chan_doan_dang_nhap": info,
        "chan_doan_tra_cuu": search_diag,
        "chan_doan_thong_bao": tb_diag,
    }


# ============================================================
#  DVC HÀNG LOẠT: đăng nhập + tra cứu + (tùy chọn) tải, cho NHIỀU công ty.
#  Chạy nền (1 trình duyệt dùng lại cho từng công ty), poll trạng thái.
#  Xuất 2 Excel: Tra cứu tờ khai (tổng hợp) + Sai mật khẩu.
# ============================================================
DVC_BATCH = {}        # batch_id -> {...}
_DVC_BATCH_SEQ = {"n": 0}

# Mốc chuyển hệ thống: dichvucong.gdt.gov.vn (tab "DVC") chỉ có tờ khai TỪ
# ngày này; tờ khai TRƯỚC ngày này chỉ tra cứu được qua tab "Thuế điện tử"
# (etax cũ) — 2 nguồn KHÔNG dùng chung dữ liệu.
_DVC_MOC_CHUYEN_HE_THONG = datetime.date(2025, 7, 1)

def _nguon_tra_cuu_theo_ky(tu_str, den_str):
    """Tự động chọn (các) nguồn tra cứu theo khoảng ngày, không cần người
    dùng tự chọn. Trả về list nguồn cần tra cứu — thường 1 phần tử, nhưng
    nếu khoảng ngày VẮT QUA mốc 01/07/2025 thì trả cả 2 (['thuedientu',
    'dvc']) để không bỏ sót tờ khai của giai đoạn nào."""
    def _dmy(s):
        try:
            d, m, y = (s or "").split("/")
            return datetime.date(int(y), int(m), int(d))
        except Exception:
            return None
    tu_d, den_d = _dmy(tu_str), _dmy(den_str)
    if not tu_d or not den_d:
        return ["dvc"]
    moc = _DVC_MOC_CHUYEN_HE_THONG
    nguon = []
    if tu_d < moc:
        nguon.append("thuedientu")
    if den_d >= moc:
        nguon.append("dvc")
    return nguon or ["dvc"]


# Số công ty xử lý ĐỒNG THỜI (mỗi luồng 1 trình duyệt ẩn riêng) — TÁCH RIÊNG
# 2 hằng số cho 2 tính năng để tăng luồng cho tính năng này KHÔNG ảnh hưởng
# tới tính năng kia (vd tăng cho "Tra cứu tờ khai thuế hàng loạt" nhưng vẫn
# muốn giữ "Kiểm tra hạn Token" nhẹ nhàng như cũ).
# TỪNG tăng lên 10 theo yêu cầu tăng tốc, nhưng gây ra hàng loạt lỗi "Trang
# login không nạp được jQuery (WAF chặn)" do 10 trình duyệt ẩn cùng dội
# request đăng nhập lên cổng DVC từ CÙNG 1 địa chỉ IP cùng lúc (đăng nhập
# TỪNG công ty một tuần tự luôn thành công, chỉ chạy song song mới lỗi —
# đúng phản ánh thật của người dùng). Đã thêm cơ chế tự thử tải lại trang
# login 3 lần ở _dvc_browser_login, nhưng vẫn giảm bớt xuống 5 để giảm khả
# năng bị chặn ngay từ đầu — vẫn nhanh hơn hẳn mức cũ (3) mà an toàn hơn 10.
DVC_TOKHAI_BATCH_SONG_SONG = 5    # "Tra cứu tờ khai thuế / tải tờ khai hàng loạt"
DVC_TOKEN_BATCH_SONG_SONG = 3     # "Kiểm tra hạn Token"


def _dvc_run_batch(batch_id, cids, body):
    """Chạy CÙNG LÚC tối đa DVC_TOKHAI_BATCH_SONG_SONG công ty (mỗi luồng
    (worker) mở 1 trình duyệt ẩn RIÊNG, dùng lại cho MỌI công ty luồng đó xử
    lý — tránh mở/đóng trình duyệt liên tục) — công ty nào xong trước thì
    luồng đó lập tức lấy công ty tiếp theo còn lại trong hàng đợi, không
    phải đợi xong HẾT 1 lượt mới bắt đầu lượt kế (khác hẳn trước đây: 1
    trình duyệt DUY NHẤT xử lý TUẦN TỰ từng công ty một, rất lâu với hàng
    trăm công ty).
    job['current_list']: tên các công ty ĐANG xử lý tại một thời điểm (tối
    đa DVC_TOKHAI_BATCH_SONG_SONG phần tử)."""
    import queue as _queue
    job = DVC_BATCH[batch_id]
    tu = (body.get("tu_ngay") or "").strip()
    den = (body.get("den_ngay") or "").strip()
    ky_label = (body.get("ky_label") or f"{tu} - {den}").strip()
    tai_file = bool(body.get("tai_file"))       # có tải file tờ khai về không
    tai_tb = bool(body.get("tai_thong_bao", True))
    luu_pass = bool(body.get("luu", True))
    # Nguồn tra cứu: TỰ ĐỘNG chọn theo khoảng ngày (người dùng không cần tự
    # chọn) — "dvc" cho tờ khai TỪ 01/07/2025, "thuedientu" (tab cũ) cho tờ
    # khai TRƯỚC ngày đó; nếu khoảng ngày vắt qua mốc này, tra cứu CẢ 2.
    ds_nguon = _nguon_tra_cuu_theo_ky(tu, den)
    tracuu_rows = []      # gom mọi dòng cho Excel tra cứu — DÙNG CHUNG giữa các luồng, khoá bằng job_lock
    sai_pass = []         # công ty đăng nhập không được — DÙNG CHUNG, khoá bằng job_lock
    # ĐỒNG BỘ trạng thái tick "Tự động nộp tờ khai" (GTGT/TNCN) theo đúng kết
    # quả tra cứu THẬT trên cổng — chỉ áp dụng khi khoảng ngày đang tra cứu
    # RƠI GỌN vào ĐÚNG 1 quý (kỳ tính thuế của GTGT/TNCN luôn theo quý); nếu
    # trải nhiều quý/cả năm thì bỏ qua (không rõ đồng bộ cho quý nào).
    dong_bo_nam, dong_bo_quy = _quy_cua_ky(tu, den)
    job_lock = threading.Lock()   # bảo vệ job['items']/['done']/['current_list'] + tracuu_rows/sai_pass

    def _xu_ly_1_cty(cid, drv):
        conn = db()
        comp = conn.execute("SELECT * FROM companies WHERE id=?", (cid,)).fetchone()
        conn.close()
        if not comp:
            with job_lock:
                job["done"] += 1
            return
        ten = comp["ten"]; mst = comp["mst"]
        item = {"cid": cid, "mst": mst, "ten": ten, "trang_thai": "đang xử lý",
                "so_dong": 0, "so_file": 0}
        with job_lock:
            job["items"].append(item)
            job.setdefault("current_list", []).append(ten)
            job["current"] = ten
        try:
            pw1 = (comp["dvc_password"] if "dvc_password" in comp.keys() else "") or ""
            pw2 = (comp["dvc_password2"] if "dvc_password2" in comp.keys() else "") or ""
            pw1 = (pw1 or "").strip(); pw2 = (pw2 or "").strip()
            # mật khẩu chung dự phòng (nếu người dùng nhập ở batch)
            if body.get("pass_chung"):
                pw2 = pw2 or (body.get("pass_chung") or "").strip()
            if not pw1 and not pw2:
                item["trang_thai"] = "thiếu mật khẩu"
                with job_lock:
                    sai_pass.append({"mst": mst, "ten": ten, "ly_do": "Chưa lưu mật khẩu Dịch vụ công"})
                return
            # xoá phiên công ty trước để tránh lẫn đăng nhập
            try:
                drv.get(DVC_BASE + "/homelogin")
                drv.delete_all_cookies()
            except Exception:
                pass
            try:
                ok, dung_pass, info = _dvc_browser_login_2pass(drv, mst, pw1, pw2)
            except Exception as e:
                ok, dung_pass, info = False, 0, {"loi": str(e)}
            if not ok:
                item["trang_thai"] = "sai mật khẩu / lỗi đăng nhập"
                item["loi_chi_tiet"] = _dvc_mo_ta_loi_dang_nhap(info)
                with job_lock:
                    sai_pass.append({"mst": mst, "ten": ten,
                                     "ly_do": json.dumps(info, ensure_ascii=False)[:480]})
                return
            item["dung_pass"] = dung_pass
            # Tra cứu LẦN LƯỢT từng nguồn phù hợp với khoảng ngày (thường chỉ
            # 1 nguồn; vắt qua mốc 01/07/2025 thì tra cứu cả 2 rồi gộp lại).
            co_du_lieu_nguon_nao = False
            for ngu in ds_nguon:
                if ngu == "thuedientu":
                    _tra_cuu_fn = _dvc_browser_tracuu_tdt
                    _tai_file_fn = _dvc_browser_download_tdt
                    _ten_file_fn = _ten_file_than_thien_tdt
                    nhan_nguon = "Thuế điện tử (trước 01/07/2025)"
                else:
                    _tra_cuu_fn = _dvc_browser_tracuu
                    _tai_file_fn = _dvc_browser_download
                    _ten_file_fn = _ten_file_than_thien
                    nhan_nguon = "DVC (từ 01/07/2025)"
                # QUAN TRỌNG: ô tìm kiếm trên cổng lọc theo NGÀY NỘP HỒ SƠ, KHÔNG
                # phải theo kỳ tính thuế của tờ khai (giống hệt vấn đề đã gặp và
                # sửa ở _dvc_kiem_tra_da_nop_mot_loai) — tờ khai kỳ QUÝ luôn được
                # nộp SAU KHI quý đã kết thúc (hạn nộp là cuối tháng đầu quý sau,
                # vd Quý 2 hạn 30/07), nên:
                #  1) Nếu chỉ tìm ĐÚNG trong khoảng tu-den của kỳ đang chọn (vd
                #     Quý 2 = 01/04-30/06) thì gần như KHÔNG BAO GIỜ thấy tờ khai
                #     CỦA ĐÚNG kỳ đó (vì nộp sau 30/06) — phải MỞ RỘNG vùng tìm
                #     (ngày nộp) tới HÔM NAY mới thấy được.
                #  2) Nhưng mở rộng vùng tìm như vậy lại LẪN vào tờ khai của KỲ
                #     TRƯỚC (vd kỳ Quý 1 hạn nộp 30/04 — ngày nộp đó lại RƠI VÀO
                #     đúng khoảng Quý 2 đang tìm), nên PHẢI đối chiếu lại cột 'Kỳ'
                #     THẬT của từng dòng kết quả với đúng kỳ tu-den đang tra cứu,
                #     bỏ hẳn dòng của kỳ khác — nếu không, kết quả xuất Excel sẽ
                #     lẫn lộn tờ khai của nhiều kỳ khác nhau (đã xác nhận qua dữ
                #     liệu thật người dùng gửi: chọn Quý 2/2026 nhưng bảng kết quả
                #     lại toàn tờ khai kỳ Quý 1/2026 và tờ khai quyết toán cả năm).
                tu_tim, den_tim = tu, den
                try:
                    d2, m2, y2 = den.split("/")
                    den_ngay_kt = datetime.date(int(y2), int(m2), int(d2))
                    hom_nay_kt = datetime.date.today()
                    if hom_nay_kt > den_ngay_kt:
                        den_tim = hom_nay_kt.strftime("%d/%m/%Y")
                except Exception:
                    pass
                try:
                    rows_tho, ma_list, raw_html, sdiag = _tra_cuu_fn(drv, tu_tim, den_tim)
                except Exception as e:
                    rows_tho, ma_list, raw_html, sdiag = [], [], "", [f"lỗi tra cứu: {e}"]
                rows = [r for r in rows_tho
                        if _ky_dong_bo_trong_khoang(r.get("ky", ""), tu, den)]
                if rows_tho and not rows:
                    sdiag = list(sdiag) + [
                        f"tìm thấy {len(rows_tho)} dòng trong khoảng ngày nộp {tu_tim}-{den_tim} "
                        f"nhưng KHÔNG dòng nào đúng kỳ {ky_label} đang tra cứu (kỳ khác) — coi như "
                        f"CHƯA nộp đúng kỳ này"]
                with job_lock:
                    for rec in rows:
                        rec2 = {"mst": mst, "ten": ten}; rec2.update(rec)
                        tracuu_rows.append(rec2)
                item["so_dong"] = item.get("so_dong", 0) + len(rows)
                # Nếu tra cứu THÀNH CÔNG nhưng KHÔNG có tờ khai nào trong kỳ
                # (của ĐÚNG NGUỒN này) -> ghi chú "CHƯA NỘP TỜ KHAI" (đỏ).
                # Nếu tra cứu lỗi thì không kết luận.
                if not rows:
                    if raw_html:
                        with job_lock:
                            tracuu_rows.append({
                                "mst": mst, "ten": ten,
                                "to_khai": f"(Chưa tìm thấy tờ khai trong kỳ — nguồn {nhan_nguon})",
                                "ky": ky_label, "loai": "", "ngay_nop": "",
                                "lan_nop": "", "lan_bs": "",
                                "trang_thai": "CHƯA NỘP TỜ KHAI",
                            })
                    else:
                        item.setdefault("loi_tra_cuu", "")
                        item["loi_tra_cuu"] += (f"[{nhan_nguon}] " + "; ".join(sdiag))[:200]
                else:
                    co_du_lieu_nguon_nao = True
                # tải file (tùy chọn)
                if tai_file and ma_list:
                    folder = _dvc_save_folder(cid)
                    if folder:
                        seen_ma = set()
                        # 1) các hồ sơ dò được đủ dữ liệu dòng (to_khai/ky/lan_bs) -> đặt tên thân thiện
                        for rec in rows:
                            ma = (rec.get("ma") or "").strip()
                            if not ma or ma in seen_ma:
                                continue
                            seen_ma.add(ma)
                            if job.get("cancel"):
                                break
                            ten_goi = _ten_file_fn(rec.get("to_khai"), rec.get("ky"), mst, rec.get("lan_bs"))
                            try:
                                if tai_tb:
                                    tb_files, _ = _dvc_browser_thongbao(drv, ma)
                                    so_tb = len(tb_files)
                                    for k, (fn, raw) in enumerate(tb_files, 1):
                                        if raw:
                                            ext = os.path.splitext(fn)[1] or ".xml"
                                            hau_to = f"_ThongBao{k}" if so_tb > 1 else "_ThongBao"
                                            _dvc_luu_file(folder, f"{ten_goi}{hau_to}{ext}", raw); item["so_file"] += 1
                                fn, raw = _tai_file_fn(drv, ma)
                                if raw:
                                    ext = os.path.splitext(fn)[1] or ".zip"
                                    _dvc_luu_file(folder, f"{ten_goi}{ext}", raw); item["so_file"] += 1
                            except Exception:
                                pass
                            time.sleep(0.3)
                        # Các hồ sơ có ĐỦ dữ liệu dòng (nằm trong rows_tho, biết rõ
                        # cột "Kỳ") nhưng KHÔNG khớp đúng kỳ đang tra cứu (tu, den)
                        # -> đây là tờ khai của KỲ KHÁC (vd nộp bổ sung/điều chỉnh
                        # cho Quý 1 nhưng nộp muộn trong khoảng ngày nộp của Quý 2)
                        # — KHÔNG được tải xuống ở bước "dự phòng" bên dưới, dù mã hồ
                        # sơ của nó vẫn nằm trong ma_list (danh sách mọi mã tìm thấy,
                        # không lọc theo kỳ). Trước đây thiếu bước loại trừ này nên
                        # tờ khai của kỳ khác bị tải lẫn vào (đặt tên gốc dạng
                        # "files_xxx.zip"), lẫn cả vào kết quả của kỳ đang chọn.
                        ma_ky_khac = {(r.get("ma") or "").strip() for r in rows_tho} - seen_ma
                        ma_ky_khac.discard("")
                        seen_ma |= ma_ky_khac
                        # 2) mã hồ sơ tìm thấy trong ma_list nhưng KHÔNG có trong
                        # rows_tho (raw_html có link mã nhưng không ghép được dữ
                        # liệu dòng để biết cột "Kỳ" của nó) -> CHƯA XÁC ĐỊNH được
                        # kỳ, tải với tên gốc (dự phòng) như trước — CHỈ áp dụng cho
                        # trường hợp này, không áp dụng cho hồ sơ đã biết rõ là kỳ khác.
                        for ma in ma_list:
                            if ma in seen_ma:
                                continue
                            seen_ma.add(ma)
                            if job.get("cancel"):
                                break
                            try:
                                if tai_tb:
                                    tb_files, _ = _dvc_browser_thongbao(drv, ma)
                                    for fn, raw in tb_files:
                                        if raw:
                                            _dvc_luu_file(folder, fn, raw); item["so_file"] += 1
                                fn, raw = _tai_file_fn(drv, ma)
                                if raw:
                                    _dvc_luu_file(folder, fn, raw); item["so_file"] += 1
                            except Exception:
                                pass
                            time.sleep(0.3)
            item["chua_nop"] = not co_du_lieu_nguon_nao and not item.get("loi_tra_cuu")

            # ===== ĐỒNG BỘ tick "Tự động nộp tờ khai" (GTGT/TNCN) theo đúng
            # kết quả tra cứu THẬT vừa có =====
            # - Tờ khai loại nào ĐÃ được cơ quan Thuế "Đã chấp nhận" đúng kỳ
            #   này -> tự TICK (nếu đang chưa tick).
            # - Loại nào CHƯA được chấp nhận đúng kỳ này -> tự BỎ TICK (nếu
            #   đang tick sai — vd người dùng lỡ tick nhầm, hoặc tick từ 1
            #   lần kiểm tra trước đó không còn đúng nữa).
            # Dùng lại _dvc_kiem_tra_da_nop_mot_loai (đã tự mở rộng vùng tìm
            # theo NGÀY NỘP tới hôm nay) để không bỏ sót tờ khai nộp SAU khi
            # quý đã kết thúc (trường hợp GẦN NHƯ LUÔN xảy ra với tờ khai
            # quý) — không dùng lại dữ liệu tra cứu thô ở trên vì đó tìm theo
            # ĐÚNG khoảng ngày người dùng chọn cho công cụ này, có thể quá hẹp.
            # ĐÈ CẢ xác nhận đã đánh dấu THỦ CÔNG trước đó — công cụ "Tra cứu
            # tờ khai thuế / tải tờ khai hàng loạt" này CHÍNH LÀ nơi kiểm tra
            # lại TOÀN BỘ công ty đã nộp đầy đủ hay chưa (nguồn xác thực
            # chính, tra cứu thật trên cổng Thuế), nên phải được tin cậy hơn
            # 1 lần đánh dấu tay trước đó — không loại trừ trường hợp nào.
            if dong_bo_quy:
                tu_ky_db, den_ky_db = _tu_den_cua_quy(dong_bo_nam, dong_bo_quy)
                dong_bo_ghi_chu = []
                for loai_dongbo in ("GTGT", "TNCN"):
                    try:
                        xn_dongbo, tt_dongbo, ct_dongbo = _dvc_kiem_tra_da_nop_mot_loai(
                            drv, loai_dongbo, tu_ky_db, den_ky_db)
                    except Exception:
                        continue
                    conn_db2 = db()
                    log_cu = conn_db2.execute(
                        "SELECT xac_nhan, xac_nhan_nguon FROM nop_to_khai_log "
                        "WHERE company_id=? AND loai=?", (cid, loai_dongbo)).fetchone()
                    if xn_dongbo:
                        if not (log_cu and log_cu["xac_nhan"]):
                            dong_bo_ghi_chu.append(f"tự TICK {loai_dongbo} (đã chấp nhận)")
                        conn_db2.execute(
                            "INSERT INTO nop_to_khai_log (company_id, loai, xac_nhan, xac_nhan_at, "
                            "xac_nhan_nguon, xac_nhan_chi_tiet) VALUES (?, ?, 1, ?, 'auto', ?) "
                            "ON CONFLICT(company_id, loai) DO UPDATE SET xac_nhan=1, "
                            "xac_nhan_at=excluded.xac_nhan_at, xac_nhan_nguon='auto', "
                            "xac_nhan_chi_tiet=excluded.xac_nhan_chi_tiet",
                            (cid, loai_dongbo, datetime.datetime.now().isoformat(), ct_dongbo))
                    elif log_cu and log_cu["xac_nhan"]:
                        dong_bo_ghi_chu.append(f"tự BỎ TICK {loai_dongbo} (chưa nộp/chưa chấp nhận)")
                        conn_db2.execute(
                            "UPDATE nop_to_khai_log SET xac_nhan=0, xac_nhan_at=?, "
                            "xac_nhan_nguon='auto', xac_nhan_chi_tiet=? WHERE company_id=? AND loai=?",
                            (datetime.datetime.now().isoformat(), ct_dongbo, cid, loai_dongbo))
                    # LƯU LẠI trạng thái cơ quan Thuế (3 màu: đã chấp nhận/chờ/
                    # từ chối) THEO ĐÚNG KỲ vừa kiểm tra — dùng riêng để hiện
                    # màu ngay trong danh sách công ty của công cụ tra cứu
                    # hàng loạt này (độc lập với nop_to_khai_log, không ảnh
                    # hưởng luồng tự động nộp tờ khai).
                    nhom_mau = _phan_loai_trang_thai_cqt(tt_dongbo)
                    conn_db2.execute(
                        "INSERT INTO to_khai_trang_thai_cqt (company_id, loai, nam, quy, trang_thai, "
                        "trang_thai_goc, chi_tiet, checked_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?) "
                        "ON CONFLICT(company_id, loai, nam, quy) DO UPDATE SET trang_thai=excluded.trang_thai, "
                        "trang_thai_goc=excluded.trang_thai_goc, chi_tiet=excluded.chi_tiet, "
                        "checked_at=excluded.checked_at",
                        (cid, loai_dongbo, dong_bo_nam, dong_bo_quy, nhom_mau, tt_dongbo, ct_dongbo,
                         datetime.datetime.now().isoformat()))
                    conn_db2.commit()
                    conn_db2.close()
                if dong_bo_ghi_chu:
                    item["dong_bo_nop_to_khai"] = "; ".join(dong_bo_ghi_chu)

            item["trang_thai"] = "xong"
            time.sleep(0.5)
        finally:
            with job_lock:
                job["done"] += 1
                cl = job.get("current_list", [])
                if ten in cl:
                    cl.remove(ten)

    def _worker():
        drv = None
        try:
            try:
                drv = _dvc_make_driver(headless=True)
            except Exception as e:
                with job_lock:
                    job["loi"] = ((job.get("loi") or "") + f" Không mở được Chrome (1 luồng): {e}").strip()
                return
            while True:
                if job.get("cancel"):
                    break
                try:
                    cid_lam = hang_doi.get_nowait()
                except _queue.Empty:
                    break
                try:
                    _xu_ly_1_cty(cid_lam, drv)
                except Exception:
                    # Lưới an toàn — 1 công ty lỗi bất ngờ (ngoài mọi try/except đã
                    # có bên trong) TUYỆT ĐỐI không được làm cả luồng "chết" giữa
                    # chừng, kẹt mãi các công ty còn lại trong hàng đợi của nó.
                    with job_lock:
                        job["done"] += 1
        finally:
            try:
                if drv: drv.quit()
            except Exception:
                pass

    hang_doi = _queue.Queue()
    for cid in cids:
        hang_doi.put(cid)
    so_luong = max(1, min(DVC_TOKHAI_BATCH_SONG_SONG, len(cids)))
    threads = [threading.Thread(target=_worker) for _ in range(so_luong)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    job["current_list"] = []
    # xuất Excel
    try:
        out_dir = _dvc_batch_out_dir()
        ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        if tracuu_rows:
            p = os.path.join(out_dir, f"TraCuuToKhai_{ts}.xlsx")
            _xuat_tracuu_excel(tracuu_rows, p)
            job["file_tracuu"] = p
            _open_file_local(p)   # tự mở file Excel trên máy
        if sai_pass:
            p2 = os.path.join(out_dir, f"SaiMatKhau_{ts}.xlsx")
            _xuat_saipass_excel(sai_pass, p2)
            job["file_saipass"] = p2
    except Exception as e:
        job["loi_xuat"] = str(e)
    job["so_dong_tong"] = len(tracuu_rows)
    job["so_sai_pass"] = len(sai_pass)
    job["running"] = False
    job["current"] = None

def _dvc_luu_file(folder, fname, raw):
    safe = "".join(ch for ch in fname if ch not in '\\/:*?"<>|') or "file.zip"
    path = os.path.join(folder, safe)
    if os.path.exists(path):
        base, ext = os.path.splitext(safe); k = 2
        while os.path.exists(os.path.join(folder, f"{base}_{k}{ext}")):
            k += 1
        path = os.path.join(folder, f"{base}_{k}{ext}")
    with open(path, "wb") as f:
        f.write(raw)
    return path

def _dvc_batch_out_dir():
    """Thư mục lưu 2 file Excel tổng hợp: ưu tiên save_dir/data_dir đầu tiên có."""
    conn = db()
    row = conn.execute("SELECT save_dir, data_dir FROM companies "
                       "WHERE (save_dir IS NOT NULL AND save_dir<>'') "
                       "OR (data_dir IS NOT NULL AND data_dir<>'') LIMIT 1").fetchone()
    conn.close()
    base = ""
    if row:
        base = (row["save_dir"] or row["data_dir"] or "").strip()
    if not base or not os.path.isdir(base):
        base = os.path.join(DATA_DIR, "tracuu_thue")
    os.makedirs(base, exist_ok=True)
    return base


@app.post("/api/dvc/batch")
def dvc_batch_start(body: dict = Body(...)):
    """Bắt đầu chạy hàng loạt. body: { cids:[...], tu_ngay, den_ngay,
       tai_file:bool, tai_thong_bao:bool, pass_chung?:str }. Trả { batch_id }."""
    cids = body.get("cids") or []
    if not cids:
        conn = db()
        cids = [r["id"] for r in conn.execute("SELECT id FROM companies ORDER BY ten").fetchall()]
        conn.close()
    if not (body.get("tu_ngay") and body.get("den_ngay")):
        raise HTTPException(400, "Chưa chọn khoảng ngày")
    _DVC_BATCH_SEQ["n"] += 1
    bid = _DVC_BATCH_SEQ["n"]
    DVC_BATCH[bid] = {"running": True, "total": len(cids), "done": 0,
                      "current": None, "current_list": [], "items": [], "cancel": False}
    import threading
    threading.Thread(target=lambda: _dvc_run_batch(bid, cids, body), daemon=True).start()
    return {"ok": True, "batch_id": bid}

@app.get("/api/dvc/batch-status/{bid}")
def dvc_batch_status(bid: int):
    job = DVC_BATCH.get(bid)
    if not job:
        raise HTTPException(404, "Không tìm thấy phiên")
    return job

@app.post("/api/dvc/batch-cancel/{bid}")
def dvc_batch_cancel(bid: int):
    job = DVC_BATCH.get(bid)
    if job:
        job["cancel"] = True
    return {"ok": True}


# ============================================================
#  KIỂM TRA HẠN TOKEN (chứng thư số CKS): đăng nhập từng công ty, vào
#  trang "Quản lý thông tin", đọc Tổ chức cấp + Ngày hết hạn, lưu vào DB
#  để nhớ lâu dài và cảnh báo công ty nào sắp hết hạn (không cần tra cứu
#  tờ khai — chỉ đăng nhập rồi đọc thông tin, nhanh hơn nhiều).
# ============================================================
DVC_TOKEN_BATCH = {}
_DVC_TOKEN_BATCH_SEQ = {"n": 0}

def _dvc_run_token_batch(batch_id, cids, body):
    """Kiểm tra hạn Token CÙNG LÚC tối đa DVC_TOKEN_BATCH_SONG_SONG công ty —
    cùng kiểu xử lý song song (mỗi luồng 1 trình duyệt ẩn riêng) như
    _dvc_run_batch, xem giải thích chi tiết ở đó."""
    import queue as _queue
    job = DVC_TOKEN_BATCH[batch_id]
    job_lock = threading.Lock()
    sai_pass = []   # công ty thiếu/sai mật khẩu — xuất Excel riêng cho dễ xử lý

    def _xu_ly_1_cty(cid, drv):
        conn = db()
        comp = conn.execute("SELECT * FROM companies WHERE id=?", (cid,)).fetchone()
        conn.close()
        if not comp:
            with job_lock:
                job["done"] += 1
            return
        ten = comp["ten"]; mst = comp["mst"]
        item = {"cid": cid, "mst": mst, "ten": ten, "trang_thai": "đang xử lý"}
        with job_lock:
            job["items"].append(item)
            job.setdefault("current_list", []).append(ten)
            job["current"] = ten
        try:
            pw1 = (comp["dvc_password"] if "dvc_password" in comp.keys() else "") or ""
            pw2 = (comp["dvc_password2"] if "dvc_password2" in comp.keys() else "") or ""
            pw1 = (pw1 or "").strip(); pw2 = (pw2 or "").strip()
            if body.get("pass_chung"):
                pw2 = pw2 or (body.get("pass_chung") or "").strip()
            if not pw1 and not pw2:
                item["trang_thai"] = "thiếu mật khẩu"
                with job_lock:
                    sai_pass.append({"mst": mst, "ten": ten, "ly_do": "Chưa lưu mật khẩu Dịch vụ công"})
                return
            try:
                drv.get(DVC_BASE + "/homelogin")
                drv.delete_all_cookies()
            except Exception:
                pass
            try:
                ok, dung_pass, info = _dvc_browser_login_2pass(drv, mst, pw1, pw2)
            except Exception as e:
                ok, dung_pass, info = False, 0, {"loi": str(e)}
            if not ok:
                item["trang_thai"] = "sai mật khẩu / lỗi đăng nhập"
                item["loi_chi_tiet"] = _dvc_mo_ta_loi_dang_nhap(info)
                with job_lock:
                    sai_pass.append({"mst": mst, "ten": ten, "ly_do": item["loi_chi_tiet"]})
                return
            to_chuc_cap, ngay_het_han, chi_tiet_loi_token = _dvc_browser_lay_token_info(drv)
            if not to_chuc_cap and not ngay_het_han:
                item["trang_thai"] = "không đọc được thông tin token"
                item["loi_chi_tiet"] = chi_tiet_loi_token or "Không rõ nguyên nhân"
                return
            cn = db()
            cn.execute(
                "UPDATE companies SET token_to_chuc_cap=?, token_ngay_het_han=?, "
                "token_check_at=? WHERE id=?",
                (to_chuc_cap or "", ngay_het_han or "",
                 datetime.datetime.now().isoformat(), cid))
            cn.commit(); cn.close()
            item["to_chuc_cap"] = to_chuc_cap
            item["ngay_het_han"] = ngay_het_han
            item["trang_thai"] = "xong"
            time.sleep(0.4)
        finally:
            with job_lock:
                job["done"] += 1
                cl = job.get("current_list", [])
                if ten in cl:
                    cl.remove(ten)

    def _worker():
        drv = None
        try:
            try:
                drv = _dvc_make_driver(headless=True)
            except Exception as e:
                with job_lock:
                    job["loi"] = ((job.get("loi") or "") + f" Không mở được Chrome (1 luồng): {e}").strip()
                return
            while True:
                if job.get("cancel"):
                    break
                try:
                    cid_lam = hang_doi.get_nowait()
                except _queue.Empty:
                    break
                try:
                    _xu_ly_1_cty(cid_lam, drv)
                except Exception:
                    with job_lock:
                        job["done"] += 1
        finally:
            try:
                if drv: drv.quit()
            except Exception:
                pass

    hang_doi = _queue.Queue()
    for cid in cids:
        hang_doi.put(cid)
    so_luong = max(1, min(DVC_TOKEN_BATCH_SONG_SONG, len(cids)))
    threads = [threading.Thread(target=_worker) for _ in range(so_luong)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    job["current_list"] = []
    job["so_sai_pass"] = len(sai_pass)
    if sai_pass:
        try:
            out_dir = _dvc_batch_out_dir()
            ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            p = os.path.join(out_dir, f"SaiMatKhau_KiemTraToken_{ts}.xlsx")
            _xuat_saipass_excel(sai_pass, p)
            job["file_saipass"] = p
        except Exception as e:
            job["loi_xuat"] = str(e)
    job["running"] = False
    job["current"] = None


@app.post("/api/dvc/token-batch")
def dvc_token_batch_start(body: dict = Body(...)):
    """Kiểm tra hạn Token (chứng thư số) hàng loạt. body: {cids:[...], pass_chung?}."""
    cids = body.get("cids") or []
    if not cids:
        conn = db()
        cids = [r["id"] for r in conn.execute("SELECT id FROM companies ORDER BY ten").fetchall()]
        conn.close()
    _DVC_TOKEN_BATCH_SEQ["n"] += 1
    bid = _DVC_TOKEN_BATCH_SEQ["n"]
    DVC_TOKEN_BATCH[bid] = {"running": True, "total": len(cids), "done": 0,
                            "current": None, "current_list": [], "items": [], "cancel": False}
    import threading
    threading.Thread(target=lambda: _dvc_run_token_batch(bid, cids, body), daemon=True).start()
    return {"ok": True, "batch_id": bid}

@app.get("/api/dvc/token-batch-status/{bid}")
def dvc_token_batch_status(bid: int):
    job = DVC_TOKEN_BATCH.get(bid)
    if not job:
        raise HTTPException(404, "Không tìm thấy phiên")
    return job

@app.post("/api/dvc/token-batch-cancel/{bid}")
def dvc_token_batch_cancel(bid: int):
    job = DVC_TOKEN_BATCH.get(bid)
    if job:
        job["cancel"] = True
    return {"ok": True}


