@app.post("/api/dvc/nop-to-khai/{cid}")
def dvc_nop_to_khai(cid: int, body: dict = Body(...)):
    """TỰ ĐỘNG hết mức: đăng nhập (hoặc DÙNG LẠI phiên trình duyệt đã đăng
    nhập sẵn — xem phien_id_cu bên dưới), khởi tạo đúng tờ khai, tự tìm +
    chọn file XML khớp công ty, tự Ký hồ sơ + nhập PIN + bấm "Nộp tờ khai".
    body: {loai: "GTGT"|"TNCN", nam?: int, quy?: int, phien_id?: str}
    phien_id (tuỳ chọn): phien_id của 1 phiên trình duyệt ĐANG MỞ (trả về từ
    lần gọi TRƯỚC, vd vừa nộp xong GTGT của CÙNG công ty này) — nếu còn
    sống thì DÙNG LẠI ĐÚNG cửa sổ + phiên đăng nhập đó để nộp tiếp tờ khai
    khác (vd TNCN), KHÔNG mở Chrome mới/đăng nhập lại. Ngoài lợi ích không
    tốn thời gian đăng nhập lại, còn tránh được rủi ro 2 phiên trình duyệt
    cùng tranh giành hub CKS cục bộ/token vật lý cùng lúc (đã gặp thật:
    tờ khai thứ 2 "đứng im" không ký/nộp được vì phiên trước đó CHƯA ĐÓNG
    vẫn đang giữ hub/token). Trình duyệt được mở HIỂN THỊ (không ẩn) và
    KHÔNG bị đóng sau khi hàm này trả về — người gọi (frontend) chịu trách
    nhiệm đóng qua /api/dvc/dong-phien khi không còn tờ khai nào khác cần
    nộp cho công ty này nữa.
    File được tìm ƯU TIÊN trong "Thư mục lưu file kết xuất" RIÊNG của công
    ty (theo Năm/Quý đã chọn) nếu công ty đã cấu hình; nếu không, lùi về
    "thư mục mặc định" dùng chung như cách làm cũ."""
    loai = (body.get("loai") or "").strip().upper()
    nam = body.get("nam")
    quy = body.get("quy")
    cfg = _DVC_TO_KHAI_CONFIG.get(loai)
    if not cfg:
        raise HTTPException(
            400, f"Chưa hỗ trợ tự động nộp tờ khai loại '{loai}'. "
                 f"Hiện chỉ hỗ trợ: {', '.join(_DVC_TO_KHAI_CONFIG) or '(chưa có)'}.")
    conn = db()
    comp = conn.execute("SELECT * FROM companies WHERE id=?", (cid,)).fetchone()
    conn.close()
    if not comp:
        raise HTTPException(404, "Không tìm thấy công ty")
    pw1 = ((comp["dvc_password"] if "dvc_password" in comp.keys() else "") or "").strip()
    pw2 = ((comp["dvc_password2"] if "dvc_password2" in comp.keys() else "") or "").strip()
    if not pw1 and not pw2:
        raise HTTPException(400, "Chưa lưu mật khẩu Dịch vụ công cho công ty này")
    folder = _get_setting("thu_muc_nop_to_khai", "")
    export_dir = (comp["export_dir"] if "export_dir" in comp.keys() else "") or ""
    if not folder and not export_dir:
        raise HTTPException(
            400, "Chưa cấu hình 'Thư mục lưu file kết xuất' cho công ty này, và cũng chưa "
                 "cài đặt 'Thư mục mặc định' dùng chung — cần ít nhất 1 trong 2.")
    file_path, ung_vien = _tim_file_nop_theo_cong_ty(comp, loai, nam, quy, folder)
    if not file_path:
        raise HTTPException(
            404, f"Không tìm thấy file XML {loai} khớp MST {comp['mst']} (đã tìm trong thư mục "
                 f"kết xuất riêng của công ty theo kỳ đã chọn, và thư mục mặc định)")
    phien_id_cu = (body.get("phien_id") or "").strip()
    drv = _DVC_OPEN_DRIVERS.get(phien_id_cu) if phien_id_cu else None
    tai_su_dung_phien = drv is not None
    if not tai_su_dung_phien:
        try:
            drv = _dvc_make_driver(headless=False, esigner=True)
        except Exception as e:
            raise HTTPException(500, f"Không mở được Chrome: {e}")
    try:
        if tai_su_dung_phien:
            ok, info = True, {}
        else:
            ok, dung_pass, info = _dvc_browser_login_2pass(drv, comp["mst"], pw1, pw2)
        if not ok:
            drv.quit()
            raise HTTPException(401, f"Đăng nhập thất bại: {json.dumps(info, ensure_ascii=False)}")
        # KIỂM TRA TRƯỚC khi tải file lên: tờ khai kỳ này (loai) đã được cơ
        # quan Thuế CHẤP NHẬN từ trước chưa (vd đã nộp ở máy khác, hoặc lần
        # chạy trước đã xong nhưng phần mềm chưa kịp ghi nhận) — nếu CÓ thì
        # DỪNG LẠI NGAY, không tải file lên nộp trùng lần nữa. Dùng lại
        # ĐÚNG session trình duyệt vừa đăng nhập (không tốn thêm 1 lượt đăng
        # nhập/mở Chrome riêng).
        # Ưu tiên kỳ NGƯỜI DÙNG ĐÃ CHỌN trên form (nam/quy) làm chuẩn — không
        # được để tên file "lấn át" lựa chọn của người dùng (trước đây làm
        # ngược lại: nếu thư mục còn sót/nhặt nhầm file của kỳ KHÁC, phần
        # mềm sẽ kiểm tra + báo "đã nộp" theo kỳ CỦA FILE ĐÓ chứ không phải
        # kỳ người dùng vừa chọn — vd chọn Quý 2 nhưng lại báo đã nộp Quý 1).
        # Suy từ tên file chỉ dùng làm phương án DỰ PHÒNG khi form không có
        # nam/quy (vd gọi từ chỗ khác không truyền kỳ).
        tu_ck, den_ck = (_tu_den_cua_quy(nam, quy) if nam and quy else (None, None))
        if not tu_ck or not den_ck:
            tu_ck, den_ck = _ky_tu_ten_file_nop(os.path.basename(file_path))
        loi_kiem_tra_truoc = ""
        if tu_ck and den_ck:
            try:
                xac_nhan_truoc, trang_thai_truoc, chi_tiet_truoc = _dvc_kiem_tra_da_nop_mot_loai(
                    drv, loai, tu_ck, den_ck)
            except Exception as e:
                # KHÔNG được coi lỗi khi tra cứu lại là "chắc chắn CHƯA nộp"
                # rồi âm thầm tiếp tục nộp — bước tra cứu lại này CHÍNH LÀ
                # lưới an toàn chống nộp trùng (vd lỡ tay bỏ tick "đã nộp" để
                # thử). Nếu bước này tự nó lỗi (mất mạng, cổng đổi giao diện,
                # timeout...) thì lưới an toàn coi như KHÔNG chạy được lần
                # này — phải giữ lại lý do để báo RÕ, không được im lặng coi
                # như đã kiểm tra xong và kết luận "chưa nộp".
                xac_nhan_truoc, trang_thai_truoc, chi_tiet_truoc = False, "", ""
                loi_kiem_tra_truoc = str(e)[:200]
            if xac_nhan_truoc:
                # GIỮ NGUYÊN phiên trình duyệt đang mở (KHÔNG quit()) và trả
                # về phien_id — để nếu công ty này còn tờ khai KHÁC cần kiểm
                # tra/nộp tiếp (vd GTGT đã chấp nhận -> kiểm tra tiếp TNCN),
                # hàng đợi DÙNG LẠI ĐÚNG phiên đã đăng nhập sẵn thay vì phải
                # đóng rồi mở trình duyệt mới + đăng nhập lại từ đầu chỉ để
                # kiểm tra tiếp 1 loại khác của CÙNG công ty.
                phien_id = phien_id_cu if tai_su_dung_phien else f"{cid}-{loai}-{int(time.time() * 1000)}"
                _DVC_OPEN_DRIVERS[phien_id] = drv
                conn = db()
                conn.execute(
                    "INSERT INTO nop_to_khai_log (company_id, loai, xac_nhan, xac_nhan_at, xac_nhan_nguon, xac_nhan_chi_tiet) "
                    "VALUES (?, ?, 1, ?, 'auto', ?) "
                    "ON CONFLICT(company_id, loai) DO UPDATE SET xac_nhan=1, "
                    "xac_nhan_at=excluded.xac_nhan_at, xac_nhan_nguon='auto', "
                    "xac_nhan_chi_tiet=excluded.xac_nhan_chi_tiet",
                    (cid, loai, datetime.datetime.now().isoformat(), chi_tiet_truoc))
                conn.commit()
                conn.close()
                return {"ok": False, "da_chap_nhan": True, "phien_id": phien_id,
                        "trang_thai": trang_thai_truoc, "chi_tiet": chi_tiet_truoc,
                        "thong_bao": f"Tờ khai {loai} kỳ này ĐÃ ĐƯỢC CƠ QUAN THUẾ CHẤP NHẬN từ trước "
                                     f"— KHÔNG tự động nộp lại để tránh nộp trùng. {chi_tiet_truoc}"}
        ket = _dvc_browser_nop_to_khai(drv, cfg, file_path)
    except HTTPException:
        raise
    except Exception as e:
        try:
            drv.quit()
        except Exception:
            pass
        if tai_su_dung_phien:
            _DVC_OPEN_DRIVERS.pop(phien_id_cu, None)
        raise HTTPException(500, f"Lỗi khi tự động hoá: {e}")
    phien_id = phien_id_cu if tai_su_dung_phien else f"{cid}-{loai}-{int(time.time() * 1000)}"
    _DVC_OPEN_DRIVERS[phien_id] = drv   # giữ trình duyệt MỞ, không quit()
    if not ket.get("ok"):
        _tb_dung_giua = ("Tự động hoá dừng giữa chừng — cửa sổ Chrome vẫn đang mở, "
                         "bạn có thể tự làm tiếp bằng tay từ đó.")
        if loi_kiem_tra_truoc:
            _tb_dung_giua = (f"⚠ KHÔNG tra cứu lại được xem tờ khai {loai} kỳ này đã nộp/được "
                             f"chấp nhận từ trước hay chưa ({loi_kiem_tra_truoc}) — hãy tự vào cổng "
                             f"Thuế kiểm tra lại nếu nghi ngờ có thể bị nộp trùng. ") + _tb_dung_giua
        return {"ok": False, "loi": ket.get("loi"), "buoc": ket.get("buoc"),
                "file_da_chon": file_path, "phien_id": phien_id,
                "thong_bao": _tb_dung_giua}
    # Tải file XONG là TỰ LUÔN bấm "Ký hồ sơ" → chọn chứng thư số → "Tiếp
    # tục" (không bắt người dùng phải bấm thêm 1 nút riêng trong phần mềm).
    try:
        ket_ky = _dvc_bam_ky_ho_so(drv)
    except Exception as e:
        ket_ky = {"ok": False, "loi": f"Lỗi khi tự bấm Ký hồ sơ: {e}", "buoc": []}
    # Bấm "Tiếp tục" xong (ở bước trên) là lúc hub CKS cục bộ bật hộp thoại
    # Windows "Xác nhận PIN" — tự nhập PIN mặc định rồi tự bấm "Nộp tờ khai"
    # luôn, KHÔNG dừng lại chờ người dùng nữa (theo yêu cầu). An toàn: chỉ
    # thử PIN tối đa 2 lần rồi dừng hẳn (xem _dvc_nhap_pin_ky_so) để tránh
    # khoá token.
    ket_pin = None
    ket_nop = None
    if ket_ky.get("ok"):
        pin = _get_setting("pin_nop_to_khai", "12345678")
        # Đang DÙNG LẠI phiên (vd GTGT xong -> TNCN ngay trong CÙNG cửa sổ) —
        # hub CKS thường KHÔNG hiện lại hộp thoại PIN nữa (đã nhớ token mở
        # khoá từ tờ khai trước, xem giải thích chi tiết bên dưới) nên KHÔNG
        # CẦN chờ đủ 30s như phiên đăng nhập lần đầu mới biết — chờ ngắn hơn
        # (8s) là đủ, giảm thời gian chờ vô ích cho các tờ khai sau trong
        # cùng phiên (vd TNCN sau GTGT).
        cho_hien_pin = 4 if tai_su_dung_phien else 30
        try:
            ket_pin = _dvc_nhap_pin_ky_so(pin, cho_hien_toi_da=cho_hien_pin)
        except Exception as e:
            ket_pin = {"ok": False, "loi": f"Lỗi khi tự nhập mã PIN: {e}", "buoc": []}
        # KHÔNG thấy hộp thoại PIN hiện ra (khác hẳn "thấy nhưng sai PIN") —
        # gặp thật khi DÙNG CHUNG 1 phiên trình duyệt cho nhiều tờ khai liên
        # tiếp (vd GTGT xong -> TNCN): hub CKS cục bộ thường NHỚ token đã mở
        # khoá từ lần ký TRƯỚC trong CÙNG phiên (không hỏi lại PIN mỗi lần ký
        # để đỡ phiền), nên hộp thoại PIN có thể KHÔNG BAO GIỜ hiện ra dù ký
        # vẫn tự hoàn tất ngầm — không phải lỗi thật. Vì vậy vẫn CỨ THỬ bấm
        # "Nộp tờ khai" xem có được không, thay vì dừng lại ngay chỉ vì không
        # thấy hộp thoại; nếu vẫn không nộp được thì _dvc_bam_nut_nop_to_khai
        # tự báo lỗi rõ như bình thường.
        if ket_pin.get("ok") or ket_pin.get("khong_thay_hop_thoai"):
            # Nhịp chờ "gắn chữ ký vào hồ sơ" sau khi khung "Chọn chữ ký số"
            # đóng: mặc định 3s cho lần VỪA nhập PIN thật xong (ký mới hoàn
            # tất ngay lúc này, trang cần 1 nhịp để gắn). Nhưng khi KHÔNG hề
            # thấy hộp thoại PIN (token đã mở khoá sẵn từ tờ khai trước trong
            # CÙNG phiên) thì việc ký đã tự hoàn tất NGẦM từ trước đó (ngay
            # sau khi bấm "Tiếp tục"), không phải vừa mới xong — không cần
            # chờ thêm nhịp dài, bấm "Nộp tờ khai" ngay để đỡ phải chờ vô ích
            # (đúng yêu cầu người dùng: ký xong là bấm nộp luôn, không chờ
            # thêm 10-15s như trước).
            cho_gan_chu_ky = 1 if ket_pin.get("khong_thay_hop_thoai") else 3
            try:
                ket_nop = _dvc_bam_nut_nop_to_khai(drv, cho_gan_chu_ky=cho_gan_chu_ky)
            except Exception as e:
                ket_nop = {"ok": False, "loi": f"Lỗi khi tự bấm \"Nộp tờ khai\": {e}"}
    da_tu_dong_nop = bool(ket_ky.get("ok") and ket_pin
                          and ket_nop and ket_nop.get("ok"))
    ma_ho_so = (ket_nop or {}).get("ma_ho_so") if da_tu_dong_nop else None
    conn = db()
    if da_tu_dong_nop:
        # Đã tự Ký + nhập PIN + bấm "Nộp tờ khai" và cổng báo THÀNH CÔNG
        # (kèm Mã hồ sơ) — TỰ TICK NGAY là đã nộp xong theo đúng yêu cầu,
        # không bắt tra cứu lại xác nhận "Đã chấp nhận" mới tick (bước đó xử
        # lý sau, ở lần nộp kỳ tiếp theo sẽ tự kiểm tra lại).
        conn.execute(
            "INSERT INTO nop_to_khai_log (company_id, loai, file_ten, done_at, xac_nhan, xac_nhan_at, xac_nhan_nguon, xac_nhan_chi_tiet) "
            "VALUES (?, ?, ?, ?, 1, ?, 'auto', ?) "
            "ON CONFLICT(company_id, loai) DO UPDATE SET file_ten=excluded.file_ten, "
            "done_at=excluded.done_at, xac_nhan=1, xac_nhan_at=excluded.xac_nhan_at, "
            "xac_nhan_nguon='auto', xac_nhan_chi_tiet=excluded.xac_nhan_chi_tiet",
            (cid, loai, os.path.basename(file_path), datetime.datetime.now().isoformat(),
             datetime.datetime.now().isoformat(),
             "Đã tự động Ký hồ sơ + nhập PIN + Nộp tờ khai — cổng báo THÀNH CÔNG" +
             (f" (Mã hồ sơ: {ma_ho_so})" if ma_ho_so else "") + "."))
    else:
        # Mỗi lần TỰ ĐỘNG tải file lên là 1 lượt CHỜ KÝ MỚI — reset xác nhận
        # "đã nộp" cũ về chưa, vì xác nhận trước đó (nếu có) là của LẦN CHẠY
        # TRƯỚC, không phải lần này.
        conn.execute(
            "INSERT INTO nop_to_khai_log (company_id, loai, file_ten, done_at, xac_nhan, xac_nhan_at, xac_nhan_nguon) "
            "VALUES (?, ?, ?, ?, 0, NULL, NULL) "
            "ON CONFLICT(company_id, loai) DO UPDATE SET file_ten=excluded.file_ten, "
            "done_at=excluded.done_at, xac_nhan=0, xac_nhan_at=NULL, xac_nhan_nguon=NULL",
            (cid, loai, os.path.basename(file_path), datetime.datetime.now().isoformat()))
    conn.commit()
    conn.close()
    if da_tu_dong_nop:
        ma_ho_so = (ket_nop or {}).get("ma_ho_so")
        thong_bao = ("Đã tự động đăng nhập, tải file XML lên, ký hồ sơ, nhập mã PIN và bấm "
                     "\"Nộp tờ khai\" — trang báo THÀNH CÔNG" +
                     (f" (Mã hồ sơ: {ma_ho_so})" if ma_ho_so else "") + ".")
    elif not ket_ky.get("ok"):
        thong_bao = ("Đã tự động đăng nhập và tải file XML lên, nhưng KHÔNG tự bấm được "
                     f"\"Ký hồ sơ\" ({ket_ky.get('loi') or 'không rõ lý do'}). Cửa sổ Chrome vẫn "
                     "đang mở — hãy tự bấm \"Ký hồ sơ\" và \"Nộp tờ khai\" bằng tay từ đó.")
    elif ket_nop is not None:
        # Đã THỬ bấm "Nộp tờ khai" (kể cả khi không thấy hộp thoại PIN — có
        # thể phiên đã ký sẵn từ tờ khai trước trong CÙNG cửa sổ) nhưng vẫn
        # không thành công.
        ghi_chu_pin = (" (không thấy hộp thoại nhập PIN — có thể phiên đã tự ký sẵn từ tờ khai "
                       "trước, hoặc token/hub CKS có vấn đề)"
                       if ket_pin and ket_pin.get("khong_thay_hop_thoai") else "")
        thong_bao = (f"Đã tự động Ký hồ sơ + chọn chứng thư số xong{ghi_chu_pin}, nhưng KHÔNG tự "
                     f"bấm được \"Nộp tờ khai\" ({(ket_nop or {}).get('loi') or 'không rõ lý do'}). "
                     "Cửa sổ Chrome vẫn đang mở — hãy tự nhập mã PIN (nếu cần) và bấm \"Nộp tờ "
                     "khai\" bằng tay từ đó.")
    else:
        thong_bao = ("Đã tự động Ký hồ sơ + chọn chứng thư số, nhưng KHÔNG tự nhập được mã PIN "
                     f"({(ket_pin or {}).get('loi') or 'không rõ lý do'}). Cửa sổ Chrome vẫn đang "
                     "mở — hãy tự nhập mã PIN và bấm \"Nộp tờ khai\" bằng tay từ đó.")
    if loi_kiem_tra_truoc:
        thong_bao = (f"⚠ KHÔNG tra cứu lại được xem tờ khai {loai} kỳ này đã nộp/được chấp nhận "
                     f"từ trước hay chưa ({loi_kiem_tra_truoc}) — lưới an toàn chống nộp trùng đã "
                     f"KHÔNG chạy được lần này nên vẫn cứ tiếp tục nộp như bình thường. Hãy tự vào "
                     f"cổng Thuế kiểm tra lại nếu nghi ngờ có thể bị nộp trùng. ") + thong_bao
    return {"ok": True, "file_da_chon": file_path, "phien_id": phien_id,
            "ky_ho_so": ket_ky, "pin": ket_pin, "nop": ket_nop,
            "da_tu_dong_nop": da_tu_dong_nop,
            "ung_vien_khac": [u for u in ung_vien if u != file_path],
            "thong_bao": thong_bao}


@app.post("/api/dvc/bam-ky-ho-so/{phien_id}")
def dvc_bam_ky_ho_so(phien_id: str):
    """Trên ĐÚNG cửa sổ Chrome đã tải file XML lên (theo phien_id trả về từ
    /api/dvc/nop-to-khai) — dùng khi lần đầu KHÔNG tự bấm "Ký hồ sơ" được:
    tự bấm "Ký hồ sơ" → chọn chứng thư số → "Tiếp tục", rồi tự nhập mã PIN
    (hộp thoại Windows riêng) + tự bấm "Nộp tờ khai" luôn (giống hệt luồng
    tự động trong /api/dvc/nop-to-khai)."""
    drv = _DVC_OPEN_DRIVERS.get(phien_id)
    if not drv:
        raise HTTPException(
            404, "Không tìm thấy phiên trình duyệt này (có thể cửa sổ đã bị đóng, hoặc "
                 "phiên đã quá cũ) — hãy chạy lại từ bước tải file lên.")
    try:
        ket = _dvc_bam_ky_ho_so(drv)
    except Exception as e:
        raise HTTPException(500, f"Lỗi khi tự bấm Ký hồ sơ: {e}")
    if not ket.get("ok"):
        return {"ok": False, "loi": ket.get("loi"), "buoc": ket.get("buoc"),
                "thong_bao": "Dừng giữa chừng — cửa sổ Chrome vẫn đang mở, bạn tự làm tiếp từ đó."}
    pin = _get_setting("pin_nop_to_khai", "12345678")
    try:
        ket_pin = _dvc_nhap_pin_ky_so(pin)
    except Exception as e:
        ket_pin = {"ok": False, "loi": f"Lỗi khi tự nhập mã PIN: {e}", "buoc": []}
    ket_nop = None
    # KHÔNG thấy hộp thoại PIN (khác "thấy nhưng sai PIN") vẫn cứ THỬ bấm
    # "Nộp tờ khai" — xem giải thích chi tiết ở /api/dvc/nop-to-khai (hub CKS
    # thường nhớ token đã mở khoá từ lần ký trước trong CÙNG phiên, nên ký đã
    # tự hoàn tất ngầm từ trước chứ không phải vừa mới xong -> khỏi cần chờ
    # thêm nhịp dài mới bấm "Nộp tờ khai", bấm ngay cho nhanh).
    if ket_pin.get("ok") or ket_pin.get("khong_thay_hop_thoai"):
        cho_gan_chu_ky = 1 if ket_pin.get("khong_thay_hop_thoai") else 3
        try:
            ket_nop = _dvc_bam_nut_nop_to_khai(drv, cho_gan_chu_ky=cho_gan_chu_ky)
        except Exception as e:
            ket_nop = {"ok": False, "loi": f"Lỗi khi tự bấm \"Nộp tờ khai\": {e}"}
    da_tu_dong_nop = bool(ket_nop and ket_nop.get("ok"))
    if da_tu_dong_nop:
        ma_ho_so = (ket_nop or {}).get("ma_ho_so")
        thong_bao = ("Đã tự bấm \"Ký hồ sơ\", nhập mã PIN và bấm \"Nộp tờ khai\" — trang báo "
                     "THÀNH CÔNG" + (f" (Mã hồ sơ: {ma_ho_so})" if ma_ho_so else "") + ".")
    elif ket_nop is not None:
        ghi_chu_pin = (" (không thấy hộp thoại nhập PIN — có thể phiên đã tự ký sẵn từ tờ khai "
                       "trước, hoặc token/hub CKS có vấn đề)"
                       if ket_pin.get("khong_thay_hop_thoai") else "")
        thong_bao = (f"Đã bấm \"Ký hồ sơ\" và chọn chứng thư số xong{ghi_chu_pin}, nhưng KHÔNG tự "
                     f"bấm được \"Nộp tờ khai\" ({(ket_nop or {}).get('loi') or 'không rõ lý do'}). "
                     "Cửa sổ Chrome vẫn đang mở — hãy tự nhập mã PIN (nếu cần) và bấm \"Nộp tờ "
                     "khai\" bằng tay từ đó.")
    else:
        thong_bao = ("Đã bấm \"Ký hồ sơ\" và chọn chứng thư số, nhưng KHÔNG tự nhập được mã PIN "
                     f"({ket_pin.get('loi') or 'không rõ lý do'}). Cửa sổ Chrome vẫn đang mở — hãy "
                     "tự nhập mã PIN và bấm \"Nộp tờ khai\" bằng tay từ đó.")
    return {"ok": True, "buoc": ket.get("buoc"), "pin": ket_pin, "nop": ket_nop,
            "da_tu_dong_nop": da_tu_dong_nop, "thong_bao": thong_bao}


@app.post("/api/dvc/dong-phien/{phien_id}")
def dvc_dong_phien(phien_id: str):
    """Chủ động đóng 1 phiên trình duyệt đang mở (vd đã nộp xong HẾT các tờ
    khai của 1 công ty, chuyển sang công ty khác — hoặc xong hết hàng đợi).
    Không lỗi nếu phiên đã đóng/không tồn tại (idempotent)."""
    drv = _DVC_OPEN_DRIVERS.pop(phien_id, None)
    if drv is None:
        return {"ok": True, "da_dong": False}
    try:
        drv.quit()
    except Exception:
        pass
    return {"ok": True, "da_dong": True}


def _ky_tu_ten_file_nop(ten_file):
    """Tách khoảng ngày (tu, den dạng dd/mm/yyyy) từ tên file XML nộp tờ
    khai, dựa theo mẫu 'Q{quý}{yyyy}' hoặc 'M{mm}{yyyy}' đã dùng trong tên
    file — khớp cả quy ước phần mềm tự xuất (export_htkk*) lẫn tên file
    HTKK xuất thật (vd '...TT80Q22026L00.xml'). (None, None) nếu không
    nhận diện được."""
    import re as _re, calendar as _cal
    m = _re.search(r"Q([1-4])(\d{4})", ten_file or "", _re.I)
    if m:
        q, yyyy = int(m.group(1)), int(m.group(2))
        mm1 = (q - 1) * 3 + 1
        mm2 = mm1 + 2
        return f"01/{mm1:02d}/{yyyy}", f"{_cal.monthrange(yyyy, mm2)[1]}/{mm2:02d}/{yyyy}"
    m = _re.search(r"M(\d{2})(\d{4})", ten_file or "", _re.I)
    if m:
        mm, yyyy = int(m.group(1)), int(m.group(2))
        return f"01/{mm:02d}/{yyyy}", f"{_cal.monthrange(yyyy, mm)[1]}/{mm:02d}/{yyyy}"
    return None, None


def _ky_text_ra_tu_den(ky_text):
    """Suy (tu, den) dạng dd/mm/yyyy từ chuỗi cột 'Kỳ' hiển thị TRÊN CỔNG DVC/
    Thuế điện tử (vd 'Q1/2026', 'Quý 1/2026', 'Tháng 3/2026', '2026'/'Năm
    2026') — dùng để đối chiếu ĐÚNG KỲ TỜ KHAI của từng dòng kết quả, KHÔNG
    được tin theo khoảng ngày đã dùng để tìm kiếm. (None, None) nếu không
    nhận diện được."""
    import re as _re, calendar as _cal
    kd = _khong_dau(ky_text)
    m = _re.search(r'q(?:uy)?\s*([1-4])\D+(\d{4})', kd)
    if m:
        q, yyyy = int(m.group(1)), int(m.group(2))
        mm1 = (q - 1) * 3 + 1
        mm2 = mm1 + 2
        return f"01/{mm1:02d}/{yyyy}", f"{_cal.monthrange(yyyy, mm2)[1]}/{mm2:02d}/{yyyy}"
    m = _re.search(r'thang\s*(\d{1,2})\D+(\d{4})', kd)
    if m:
        mm, yyyy = int(m.group(1)), int(m.group(2))
        return f"01/{mm:02d}/{yyyy}", f"{_cal.monthrange(yyyy, mm)[1]}/{mm:02d}/{yyyy}"
    m = _re.search(r'nam\s*(\d{4})', kd)
    if m:
        yyyy = int(m.group(1))
        return f"01/01/{yyyy}", f"31/12/{yyyy}"
    if _re.match(r'^\d{4}$', kd):
        yyyy = int(kd)
        return f"01/01/{yyyy}", f"31/12/{yyyy}"
    return None, None


def _ky_dong_bo_trong_khoang(ky_text, tu_str, den_str):
    """True nếu kỳ của 1 dòng kết quả (cột 'Kỳ' thô, vd 'Quý 1/2026') NẰM TRỌN
    trong khoảng (tu_str, den_str) đang tra cứu (dd/mm/yyyy) — dùng thay cho so
    sánh BẰNG TUYỆT ĐỐI như trước (_ky_text_ra_tu_den(...) == (tu, den)).
    So bằng tuyệt đối chỉ đúng khi người dùng chọn ĐÚNG 1 kỳ (Quý/Tháng) khớp
    hệt kỳ tính thuế thật của dòng đó; nhưng khi chọn "Tùy chọn ngày" với
    khoảng RỘNG HƠN 1 kỳ (vd cả năm 2023, trong khi công ty nộp theo QUÝ), so
    bằng tuyệt đối luôn SAI (không kỳ quý nào bằng hệt cả năm) -> mọi tờ khai
    thật đều bị loại, báo nhầm 'CHƯA NỘP' dù công ty đã nộp đủ (đã xác nhận
    qua dữ liệu thật: chọn Tùy chọn ngày 01/01/2023-31/12/2023, công ty báo
    'Chưa nộp báo cáo kỳ này' dù có nộp tờ khai quý bình thường trong năm đó).
    Vẫn PHẢI kiểm tra kỳ của dòng nằm TRỌN trong khoảng đang tra cứu (không
    phải chỉ giao nhau) để không lẫn tờ khai của kỳ VẮT RA NGOÀI khoảng chọn."""
    import datetime as _dt2
    ky_tu, ky_den = _ky_text_ra_tu_den(ky_text)
    if not ky_tu or not ky_den:
        return False
    try:
        d1 = _dt2.datetime.strptime(ky_tu, "%d/%m/%Y").date()
        d2 = _dt2.datetime.strptime(ky_den, "%d/%m/%Y").date()
        dt_req = _dt2.datetime.strptime(tu_str, "%d/%m/%Y").date()
        dd_req = _dt2.datetime.strptime(den_str, "%d/%m/%Y").date()
    except Exception:
        return False
    return dt_req <= d1 and d2 <= dd_req


def _phan_loai_trang_thai_cqt(trang_thai_text):
    """Phân loại chữ trạng thái THÔ trên cổng Thuế (vd 'Đã chấp nhận', 'Đang
    xử lý', 'Không chấp nhận'...) thành 1 trong 3 nhóm để tô màu:
      'da_chap_nhan' (xanh) / 'cho' (vàng) / 'tu_choi' (đỏ)
    Trả None nếu rỗng (chưa nộp/chưa có dữ liệu — không tô màu)."""
    if not trang_thai_text:
        return None
    t = _khong_dau(trang_thai_text)
    if "da chap nhan" in t:
        return "da_chap_nhan"
    if any(k in t for k in ("khong chap nhan", "tu choi", "khong du dieu kien", "huy bo", "da huy")):
        return "tu_choi"
    return "cho"


def _dvc_kiem_tra_da_nop_mot_loai(drv, loai, tu, den):
    """Tra cứu LẠI trên cổng Dịch vụ công (tự chọn DVC/Thuế điện tử theo
    đúng mốc 01/07/2025, dùng chung hạ tầng đã có) xem tờ khai loại `loai`
    trong khoảng tu-den ĐÃ ĐƯỢC CƠ QUAN THUẾ CHẤP NHẬN thật hay chưa —
    không suy đoán, không tự nhận là xong chỉ vì đã tải file lên.
    LƯU Ý QUAN TRỌNG: ô tìm kiếm tu/den trên cổng lọc theo NGÀY NỘP HỒ SƠ,
    KHÔNG phải theo kỳ tính thuế của tờ khai — 1 tờ khai kỳ Quý 1 hoàn toàn
    có thể được NỘP vào ngày rơi trong khoảng Quý 2 (nộp đúng hạn cuối tháng
    4, hoặc nộp muộn/nộp bổ sung), nên PHẢI tự đối chiếu lại cột 'Kỳ' THẬT
    của từng dòng kết quả với đúng kỳ tu-den đang kiểm tra, không được coi
    mọi dòng khớp loại tờ khai nằm trong kết quả tìm kiếm là "đúng kỳ".
    Trả (xac_nhan: bool, trang_thai_text: str, chi_tiet: str)."""
    # QUAN TRỌNG: ô tìm kiếm tren cổng lọc theo NGÀY NỘP HỒ SƠ — nhưng tờ
    # khai theo quý GẦN NHƯ LUÔN được nộp SAU KHI quý đã kết thúc (hạn luật
    # định là cuối tháng đầu quý tiếp theo, vd Quý 2 hạn 30/07), tức ngày nộp
    # thật sự luôn RƠI RA NGOÀI khoảng tu-den (kỳ tính thuế) — vd kỳ Quý
    # 2/2026 là 01/04-30/06/2026 nhưng hồ sơ thường được nộp đầu/giữa tháng
    # 07/2026. Nếu chỉ tìm ĐÚNG trong khoảng tu-den của kỳ tính thuế thì
    # HẦU HẾT mọi trường hợp thực tế đều bị bỏ sót (tìm không ra), khiến lưới
    # an toàn chống nộp trùng gần như không bao giờ phát huy tác dụng — đã
    # xác nhận đúng lỗi này qua dữ liệu thật (tờ khai 'Đã chấp nhận' ngày nộp
    # 17/07/2026 cho kỳ Quý 2/2026 kết thúc 30/06/2026). Mở RỘNG vùng tìm
    # kiếm (ngày nộp) tới HÔM NAY (không thể nộp trong tương lai) — nhưng
    # VẪN giữ nguyên tu/den làm mốc so sánh cột 'Kỳ' thật của từng dòng kết
    # quả, để không nhận nhầm tờ khai của KỲ KHÁC là đúng kỳ đang kiểm tra.
    tu_tim, den_tim = tu, den
    try:
        d2, m2, y2 = den.split("/")
        den_ngay = datetime.date(int(y2), int(m2), int(d2))
        hom_nay = datetime.date.today()
        if hom_nay > den_ngay:
            den_tim = hom_nay.strftime("%d/%m/%Y")
    except Exception:
        pass
    nguon_list = _nguon_tra_cuu_theo_ky(tu_tim, den_tim)
    tat_ca = []
    for nguon in nguon_list:
        if nguon == "dvc":
            rows, _, _, _ = _dvc_browser_tracuu(drv, tu_tim, den_tim)
        else:
            rows, _, _, _ = _dvc_browser_tracuu_tdt(drv, tu_tim, den_tim)
        tat_ca.extend(rows or [])
    cung_loai = [r for r in tat_ca if _loai_tk_tu_ten_day_du(r.get("to_khai", "")) == loai]
    khop = []
    khop_khac_ky = []
    for r in cung_loai:
        ky_tu, ky_den = _ky_text_ra_tu_den(r.get("ky", ""))
        if ky_tu == tu and ky_den == den:
            khop.append(r)
        else:
            khop_khac_ky.append(r)
    if not khop:
        if khop_khac_ky:
            rk = khop_khac_ky[0]
            return False, "", (
                f"Trong khoảng ngày nộp {tu_tim} - {den_tim} chỉ tìm thấy tờ khai '{rk.get('to_khai', '')}' "
                f"của KỲ KHÁC (kỳ {rk.get('ky', '')}), CHƯA tìm thấy tờ khai đúng kỳ đang kiểm tra "
                "— có thể bạn CHƯA nộp kỳ này.")
        return False, "", ("Chưa tìm thấy tờ khai đã nộp trên cổng Dịch vụ công trong khoảng "
                            f"{tu_tim} - {den_tim}. Có thể bạn chưa bấm \"Ký hồ sơ\"/\"Nộp tờ khai\", "
                            "hoặc cổng Thuế chưa cập nhật kịp.")
    for r in khop:
        if "da chap nhan" in _khong_dau(r.get("trang_thai", "")):
            return True, r.get("trang_thai", ""), (
                f"Tờ khai '{r.get('to_khai', '')}' kỳ {r.get('ky', '')} — {r.get('trang_thai', '')}")
    r0 = khop[0]
    return False, r0.get("trang_thai", ""), (
        f"Tìm thấy tờ khai '{r0.get('to_khai', '')}' kỳ {r0.get('ky', '')} nhưng trạng thái hiện "
        f"là '{r0.get('trang_thai', '')}' (chưa phải \"Đã chấp nhận\").")


@app.post("/api/dvc/kiem-tra-da-nop/{cid}")
def dvc_kiem_tra_da_nop(cid: int, body: dict = Body(...)):
    """Tra cứu LẠI trên cổng Dịch vụ công để XÁC NHẬN tờ khai đã thực sự
    được cơ quan Thuế chấp nhận, TRƯỚC KHI đánh dấu "đã nộp xong" — vì bước
    tự động tải file lên chỉ mới là "sẵn sàng ký", CHƯA chắc người dùng đã
    thực sự bấm Ký hồ sơ + Nộp tờ khai. body: {loai, tu?, den?, nam?, quy?}
    (tu/den dd/mm/yyyy; nếu không truyền, ưu tiên suy từ (nam, quy), rồi mới
    tới suy từ tên file đã khớp — như cách làm cũ)."""
    loai = (body.get("loai") or "").strip().upper()
    if loai not in _DVC_TO_KHAI_CONFIG:
        raise HTTPException(400, f"Loại '{loai}' không hợp lệ")
    conn = db()
    comp = conn.execute("SELECT * FROM companies WHERE id=?", (cid,)).fetchone()
    conn.close()
    if not comp:
        raise HTTPException(404, "Không tìm thấy công ty")
    tu, den = body.get("tu"), body.get("den")
    nam = body.get("nam")
    if (not tu or not den) and nam:
        tu, den = _tu_den_cua_quy(nam, body.get("quy"))
    if not tu or not den:
        folder = _get_setting("thu_muc_nop_to_khai", "")
        fp, _ = _tim_file_nop_theo_cong_ty(comp, loai, nam, body.get("quy"), folder)
        if fp:
            tu, den = _ky_tu_ten_file_nop(os.path.basename(fp))
    if not tu or not den:
        raise HTTPException(
            400, "Không xác định được kỳ để tra cứu lại (không tìm thấy file/kỳ tương ứng)")
    pw1 = ((comp["dvc_password"] if "dvc_password" in comp.keys() else "") or "").strip()
    pw2 = ((comp["dvc_password2"] if "dvc_password2" in comp.keys() else "") or "").strip()
    if not pw1 and not pw2:
        raise HTTPException(400, "Chưa lưu mật khẩu Dịch vụ công cho công ty này")
    try:
        drv = _dvc_make_driver(headless=True)
    except Exception as e:
        raise HTTPException(500, f"Không mở được Chrome: {e}")
    try:
        ok, dung_pass, info = _dvc_browser_login_2pass(drv, comp["mst"], pw1, pw2)
        if not ok:
            raise HTTPException(401, f"Đăng nhập thất bại: {json.dumps(info, ensure_ascii=False)}")
        xac_nhan, trang_thai_text, chi_tiet = _dvc_kiem_tra_da_nop_mot_loai(drv, loai, tu, den)
    finally:
        try:
            drv.quit()
        except Exception:
            pass
    conn = db()
    conn.execute(
        "INSERT INTO nop_to_khai_log (company_id, loai, xac_nhan, xac_nhan_at, xac_nhan_nguon, xac_nhan_chi_tiet) "
        "VALUES (?, ?, ?, ?, 'auto', ?) "
        "ON CONFLICT(company_id, loai) DO UPDATE SET xac_nhan=excluded.xac_nhan, "
        "xac_nhan_at=excluded.xac_nhan_at, xac_nhan_nguon='auto', "
        "xac_nhan_chi_tiet=excluded.xac_nhan_chi_tiet",
        (cid, loai, 1 if xac_nhan else 0, datetime.datetime.now().isoformat(), chi_tiet))
    conn.commit()
    conn.close()
    # Đã XÁC NHẬN THẬT SỰ là nộp xong -> cửa sổ Chrome dùng để ký/nộp không
    # còn cần nữa, tự đóng lại (nếu còn mở) thay vì để người dùng phải tự tắt.
    phien_id = (body.get("phien_id") or "").strip()
    da_dong_trinh_duyet = False
    if xac_nhan and phien_id:
        drv_phien = _DVC_OPEN_DRIVERS.pop(phien_id, None)
        if drv_phien is not None:
            try:
                drv_phien.quit()
                da_dong_trinh_duyet = True
            except Exception:
                pass
    return {"ok": True, "xac_nhan": xac_nhan, "trang_thai": trang_thai_text, "chi_tiet": chi_tiet,
            "da_dong_trinh_duyet": da_dong_trinh_duyet}


@app.post("/api/dvc/nop-to-khai-thu-cong/{cid}")
def dvc_nop_to_khai_thu_cong(cid: int, body: dict = Body(...)):
    """Đánh dấu THỦ CÔNG trạng thái "đã nộp" cho 1 công ty + loại tờ khai —
    dùng khi người dùng tự biết chắc đã nộp (hoặc muốn bỏ đánh dấu) mà
    không chờ/không cần phần mềm tự tra cứu lại. body: {loai, xac_nhan}."""
    loai = (body.get("loai") or "").strip().upper()
    if loai not in _DVC_TO_KHAI_CONFIG:
        raise HTTPException(400, f"Loại '{loai}' không hợp lệ")
    xac_nhan = bool(body.get("xac_nhan"))
    conn = db()
    conn.execute(
        "INSERT INTO nop_to_khai_log (company_id, loai, xac_nhan, xac_nhan_at, xac_nhan_nguon) "
        "VALUES (?, ?, ?, ?, 'thu_cong') "
        "ON CONFLICT(company_id, loai) DO UPDATE SET xac_nhan=excluded.xac_nhan, "
        "xac_nhan_at=excluded.xac_nhan_at, xac_nhan_nguon='thu_cong'",
        (cid, loai, 1 if xac_nhan else 0, datetime.datetime.now().isoformat()))
    conn.commit()
    conn.close()
    return {"ok": True}


@app.post("/api/dvc/reset-trang-thai-nop")
def dvc_reset_trang_thai_nop():
    """Xoá TOÀN BỘ trạng thái "đã nộp" đã ghi nhận cho mọi công ty — dùng
    khi bắt đầu 1 kỳ kê khai mới, để tất cả công ty trở về "chưa nộp"."""
    conn = db()
    conn.execute("DELETE FROM nop_to_khai_log")
    conn.commit()
    conn.close()
    return {"ok": True}


@app.get("/api/dvc/nop-to-khai-trang-thai")
def dvc_nop_to_khai_trang_thai(nam: int = 0, quy: int = 0):
    """Với mỗi công ty: file XML (GTGT/TNCN) đang khớp — ưu tiên tìm trong
    "Thư mục lưu file kết xuất" riêng của công ty theo (nam, quy) đã chọn,
    lùi về "thư mục mặc định" nếu không có — và đã được XÁC NHẬN THẬT SỰ là
    nộp xong chưa (qua tra cứu lại trên cổng Thuế, hoặc người dùng tự đánh
    dấu thủ công) — KHÔNG còn coi "đã tải file lên" là "đã nộp xong" nữa, vì
    đó mới chỉ là bước sẵn sàng ký. Xác nhận kiểu 'auto' tự động hết hiệu
    lực nếu file khớp đổi tên (sang kỳ mới); xác nhận 'thu_cong' được giữ
    tới khi người dùng tự bỏ đánh dấu hoặc bấm 'Bỏ hết trạng thái đã nộp'."""
    folder = _get_setting("thu_muc_nop_to_khai", "")
    conn = db()
    rows = conn.execute("SELECT * FROM companies ORDER BY ten").fetchall()
    logs = {(r["company_id"], r["loai"]): r
            for r in conn.execute(
                "SELECT company_id, loai, file_ten, xac_nhan, xac_nhan_nguon, xac_nhan_chi_tiet "
                "FROM nop_to_khai_log").fetchall()}
    conn.close()
    out = {}
    for c in rows:
        cid = c["id"]
        item = {}
        for loai in _DVC_TO_KHAI_CONFIG:
            fp, _ = _tim_file_nop_theo_cong_ty(c, loai, nam or None, quy or None, folder)
            ten = os.path.basename(fp) if fp else None
            log = logs.get((cid, loai))
            da_nop = False
            if log and log["xac_nhan"]:
                if log["xac_nhan_nguon"] == "thu_cong":
                    da_nop = True
                elif ten and log["file_ten"] and ten != log["file_ten"]:
                    # có file KHÁC xuất hiện trong thư mục (kỳ mới) -> xác
                    # nhận cũ không còn đáng tin, phải tra cứu lại
                    da_nop = False
                else:
                    # vẫn đúng file cũ (hoặc thư mục hiện không còn file nào,
                    # vd đã dọn sau khi nộp) -> GIỮ xác nhận đã có, không đòi
                    # hỏi file phải luôn còn nằm trong thư mục mới tính là xong
                    da_nop = True
            item[loai] = {
                "file": ten, "da_nop": da_nop,
                "xac_nhan_nguon": (log["xac_nhan_nguon"] if log else None),
                "chi_tiet": (log["xac_nhan_chi_tiet"] if log else None),
            }
        out[str(cid)] = item
    return out


@app.get("/api/dvc/trang-thai-cqt")
def dvc_trang_thai_cqt(nam: int, quy: int):
    """Trạng thái tờ khai GTGT/TNCN theo cơ quan Thuế (Đã chấp nhận/Chờ/Từ
    chối) của ĐÚNG 1 quý — dùng để tô màu trong danh sách công ty của công cụ
    "Tra cứu tờ khai thuế / tải tờ khai hàng loạt". Dữ liệu do chính công cụ
    đó ghi lại mỗi lần chạy xong (bảng to_khai_trang_thai_cqt) — endpoint này
    CHỈ đọc lại, không tự tra cứu mới (tránh mở trình duyệt/đăng nhập chỉ để
    hiện danh sách)."""
    conn = db()
    rows = conn.execute(
        "SELECT company_id, loai, trang_thai, trang_thai_goc, chi_tiet, checked_at "
        "FROM to_khai_trang_thai_cqt WHERE nam=? AND quy=?", (nam, quy)).fetchall()
    conn.close()
    out = {}
    for r in rows:
        cid = str(r["company_id"])
        out.setdefault(cid, {})[r["loai"]] = {
            "trang_thai": r["trang_thai"], "nhan": r["trang_thai_goc"],
            "chi_tiet": r["chi_tiet"], "checked_at": r["checked_at"],
        }
    return out


@app.get("/api/dvc/tai-excel")
def dvc_tai_excel(path: str):
    """Tải 1 file Excel tổng hợp đã tạo (đường dẫn do batch-status trả về)."""
    from fastapi.responses import FileResponse
    out_dir = os.path.realpath(_dvc_batch_out_dir())
    rp = os.path.realpath(path)
    # an toàn: chỉ cho tải file .xlsx trong thư mục xuất
    if not rp.startswith(out_dir) or not rp.endswith(".xlsx") or not os.path.isfile(rp):
        # cũng cho phép nằm trong DATA_DIR
        if not (rp.startswith(os.path.realpath(DATA_DIR)) and os.path.isfile(rp)):
            raise HTTPException(404, "File không hợp lệ")
    return FileResponse(rp, filename=os.path.basename(rp),
                        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")


def _mo_ta_ds_hd_loi(ds_inv, loai, gioi_han=10):
    """Mô tả ngắn gọn danh sách hóa đơn LỖI (chưa tải được file) — kèm tên
    công ty đối tác (mua vào: tên người bán; bán ra: tên người mua) + số hóa
    đơn, để người dùng biết CHÍNH XÁC đang thiếu file của hóa đơn nào, thay
    vì chỉ biết SỐ LƯỢNG chung chung."""
    dong = []
    for inv in ds_inv[:gioi_han]:
        if loai == "purchase":
            ten = (inv.get("nbten") or "").strip() or (inv.get("nbmst") or "?")
        else:
            ten = (inv.get("nmten") or "").strip() or (inv.get("nmmst") or "?")
        khhdon = inv.get("khhdon", "") or ""
        shdon = inv.get("shdon", "") or ""
        dong.append(f"{ten} (SH {khhdon}-{shdon})")
    txt = "; ".join(dong)
    con_lai = len(ds_inv) - gioi_han
    if con_lai > 0:
        txt += f"; ... và {con_lai} hóa đơn khác"
    return txt


def _dam_bao_du_chi_tiet_hoa_don(cid, client, save_dir, msg, chi_ids=None):
    """Sau khi ĐÃ TẢI XONG file XML (bước RIÊNG BIỆT, không chạy xen lẫn
    với việc tải file — tránh lặp lại sự cố tường lửa Thuế từng CHẶN CẢ IP
    khi 2 loại request (tải file + lấy chi tiết) chạy xen kẽ nhau qua nhiều
    luồng cùng lúc), lấy nốt 'chi tiết dòng hàng' (detail_json) qua mạng cho
    các hóa đơn KHÔNG có file trên máy (hóa đơn 'không mã' ttxly=6 — Thuế
    không cấp file XML cho loại này, hoặc hóa đơn tải file bị lỗi/thất bại)
    — để lúc Xuất Excel CHỈ cần ĐỌC dữ liệu đã có sẵn (file hoặc detail_json
    đã lưu), không phải tự đi tải bù qua mạng gây treo lâu như trước.

    chi_ids: list id bảng invoices (CÓ THỂ rỗng []) -> CHỈ lấy nốt chi tiết
    cho ĐÚNG các hóa đơn đó (vd tra cứu/Kết xuất XML chỉ cần đủ dữ liệu cho
    hóa đơn CỦA KỲ đang chạy, không cần quét/chờ TOÀN BỘ lịch sử hóa đơn
    công ty — tránh treo lâu/gây hiểu nhầm "sao lấy nhiều hóa đơn hơn cả số
    trong kỳ" với công ty có nhiều hóa đơn tồn đọng từ các kỳ trước). None
    (không truyền) -> quét TẤT CẢ hóa đơn công ty (mọi kỳ)."""
    # LƯU Ý: KHÔNG loại trừ client._token_dead ở đây — nếu phiên vừa chết
    # NGAY TRONG lúc tải file (bước ngay trước khi gọi hàm này) thì vòng lặp
    # bên dưới vẫn phải được chạy để CÓ CƠ HỘI tự đăng nhập lại, thay vì bỏ
    # cuộc ngay từ đầu chỉ vì phiên đang chết đúng lúc này.
    if not (client and client.token):
        return
    conn = db()
    if chi_ids is not None:
        # chi_ids CÓ THỂ rỗng (vd không có hóa đơn nào trong kỳ) — PHẢI phân
        # biệt rõ với "không truyền" (None), không được coi rỗng là "không
        # giới hạn" rồi lỡ quét lại TOÀN BỘ lịch sử hóa đơn công ty.
        if not chi_ids:
            conn.close()
            return
        ph = ",".join("?" * len(chi_ids))
        rows = conn.execute(
            f"SELECT * FROM invoices WHERE company_id=? AND id IN ({ph}) "
            f"AND (detail_json IS NULL OR detail_json='')",
            (cid, *chi_ids)).fetchall()
    else:
        rows = conn.execute(
            "SELECT * FROM invoices WHERE company_id=? AND (detail_json IS NULL OR detail_json='')",
            (cid,)).fetchall()
    conn.close()
    if not rows:
        return

    # Xây index file trên máy (giống hệt cách Xuất Excel làm) để biết hóa
    # đơn nào ĐÃ CÓ file — chỉ những hóa đơn KHÔNG có file mới cần lấy chi
    # tiết qua mạng ở đây.
    file_index = {}
    file_index_2 = {}
    if save_dir and os.path.isdir(save_dir):
        for rootdir, _d, files in os.walk(save_dir):
            for fn in files:
                low = fn.lower()
                if not (low.endswith(".zip") or low.endswith(".xml")):
                    continue
                name = fn.rsplit(".", 1)[0]
                parts = name.split("_")
                if len(parts) < 2:
                    continue
                f_khh, f_sho = parts[0], parts[1].lstrip("0") or "0"
                if len(parts) >= 3:
                    file_index[(f_khh, f_sho, _chuan_mst(parts[2])[:10])] = True
                else:
                    file_index_2[(f_khh, f_sho)] = True

    can_nap = []
    for r in rows:
        khh = str(r["khhdon"] or ""); sho = str(r["shdon"] or "").lstrip("0") or "0"
        mst = _chuan_mst(r["nbmst"])[:10]
        if (khh, sho, mst) in file_index or (khh, sho) in file_index_2:
            continue
        can_nap.append(r)
    if not can_nap:
        return

    msg(stage="info",
        text=f"Đang lấy nốt chi tiết dòng hàng cho {len(can_nap)} hóa đơn không có file trên máy "
             f"(hóa đơn không mã/tải file lỗi) — để Xuất Excel sau này không phải tải bù...")

    def _goi(r):
        ht0 = r["he_thong"] or "query"
        for ht in [ht0, ("sco-query" if ht0 == "query" else "query")]:
            for km in _bien_the_khmshdon(r["khmshdon"]):
                try:
                    d = client.get_detail(r["nbmst"], r["khhdon"], km, r["shdon"], ht,
                                          max_retry=2, cho_khi_429=True, loai=r["loai"])
                    if d and (d.get("hdhhdvu") or d.get("nbmst")):
                        return r["id"], json.dumps(d, ensure_ascii=False)
                except Exception:
                    pass
        time.sleep(SP()["file"])
        return r["id"], None

    workers = {"fast": 4, "balanced": 3, "safe": 2}.get(CURRENT_SPEED, 3)
    SO_VONG_KHONG_TIEN_TOI_DA = 5
    so_vong_khong_tien = 0
    vong = 0
    ds = can_nap
    while ds:
        if getattr(client, "_token_dead", False):
            # Phiên hết hạn GIỮA CHỪNG lúc đang lấy nốt chi tiết -> TỰ ĐĂNG
            # NHẬP LẠI (dùng trình duyệt ẩn vẽ captcha chính xác, giống
            # /api/auto-login) rồi TIẾP TỤC lấy nốt, thay vì bỏ cuộc ngay và
            # đẩy việc dở dang sang cho Xuất Excel xử lý — đúng yêu cầu "tra
            # cứu phải tải hết, lỗi thì quay lại tải cho đủ, Xuất Excel chỉ
            # đọc file".
            conn_relog = db()
            comp_relog = conn_relog.execute(
                "SELECT password FROM companies WHERE id=?", (cid,)).fetchone()
            conn_relog.close()
            if not (comp_relog and comp_relog["password"]):
                msg(stage="warn",
                    text=f"⚠ phiên đăng nhập hết hạn giữa chừng — còn {len(ds)} hóa đơn CHƯA lấy được "
                         f"chi tiết dòng hàng, đăng nhập lại rồi tra cứu lại để lấy nốt")
                return
            msg(stage="warn",
                text=f"⚠ phiên đăng nhập hết hạn giữa chừng — đang tự động đăng nhập lại để lấy nốt "
                     f"{len(ds)} hóa đơn còn thiếu chi tiết...")
            drv_relog = _mo_trinh_duyet_captcha()
            try:
                ok_relog, tb_relog, _, _ = _tu_dong_dang_nhap(cid, so_lan=8, drv=drv_relog)
            finally:
                _dong_trinh_duyet_captcha(drv_relog)
            if not ok_relog:
                msg(stage="warn",
                    text=f"⚠ tự đăng nhập lại thất bại ({tb_relog}) — còn {len(ds)} hóa đơn CHƯA lấy "
                         f"được chi tiết dòng hàng, đăng nhập lại rồi tra cứu lại để lấy nốt")
                return
            msg(stage="info", text="✓ đã tự đăng nhập lại thành công, tiếp tục lấy nốt chi tiết...")
            client = get_client(cid)   # client mới (token mới) sau khi đăng nhập lại
            continue
        vong += 1
        ket_qua = {}
        # Dùng submit()+as_completed() thay vì ex.map() — map() trả kết quả
        # THEO ĐÚNG THỨ TỰ đưa vào (phải đợi hóa đơn ĐẦU DANH SÁCH xong mới
        # trả, dù hóa đơn SAU đó đã xong từ lâu), nên KHÔNG thể báo tiến độ
        # NGAY khi từng hóa đơn xong — người dùng chỉ thấy 1 dòng tĩnh suốt cả
        # vòng (có thể hàng trăm hóa đơn, vài phút) rồi mới nhảy số 1 lần,
        # tưởng phần mềm bị treo dù vẫn chạy bình thường. as_completed() trả
        # kết quả theo ĐÚNG THỨ TỰ HOÀN THÀNH THẬT, báo tiến độ đếm dần từng
        # hóa đơn — thấy rõ đang chạy tới đâu.
        with _cf.ThreadPoolExecutor(max_workers=workers) as ex:
            futs = {ex.submit(_goi, r): r for r in ds}
            for fut in _cf.as_completed(futs):
                inv_id, dj = fut.result()
                if dj:
                    ket_qua[inv_id] = dj
                da_xong_tam = (len(can_nap) - len(ds)) + len(ket_qua)
                msg(stage="download", cur=da_xong_tam, total=len(can_nap),
                    text=f"Đang lấy nốt chi tiết dòng hàng: {da_xong_tam}/{len(can_nap)} "
                         f"(còn {len(can_nap) - da_xong_tam})")
        if ket_qua:
            cn = db()
            for inv_id, dj in ket_qua.items():
                cn.execute("UPDATE invoices SET detail_json=? WHERE id=?", (dj, inv_id))
            cn.commit(); cn.close()
        ds = [r for r in ds if r["id"] not in ket_qua]
        da_xong = len(can_nap) - len(ds)
        msg(stage="download", cur=da_xong, total=len(can_nap),
            text=f"Đang lấy nốt chi tiết dòng hàng: {da_xong}/{len(can_nap)} (còn {len(ds)})")
        if not ket_qua:
            so_vong_khong_tien += 1
            if so_vong_khong_tien >= SO_VONG_KHONG_TIEN_TOI_DA:
                # Ghi rõ TỪNG hóa đơn còn thiếu (không chỉ con số tổng) — vẫn
                # thất bại dù đã thử NHIỀU khmshdon/hệ thống khác nhau thường
                # là do API .../invoices/detail thật sự KHÔNG CÓ dữ liệu cho
                # đúng tổ hợp tham số đó (khác lỗi giới hạn tốc độ tạm thời),
                # cần biết CHÍNH XÁC hóa đơn nào mới dò tiếp được nguyên nhân.
                ds_mota = "; ".join(
                    f"{r['khhdon']} số {r['shdon']} (MST {r['nbmst']}, id={r['id']})" for r in ds[:10])
                msg(stage="warn",
                    text=f"⚠ đã thử {so_vong_khong_tien} vòng liên tiếp không lấy thêm được hóa đơn "
                         f"nào — còn {len(ds)}/{len(can_nap)} hóa đơn CHƯA lấy được chi tiết dòng hàng: "
                         f"{ds_mota}{' ...' if len(ds) > 10 else ''} (Xuất Excel sẽ tự thử lấy bù nếu cần).")
                return
        else:
            so_vong_khong_tien = 0
    msg(stage="info",
        text=f"✓ Đã lấy đủ chi tiết dòng hàng cho {len(can_nap)} hóa đơn không có file — Xuất Excel "
             f"giờ chỉ cần đọc dữ liệu đã có sẵn.")


def _tu_dong_lay_so_du_dau_ky_va_tinh_vat(cid, tu, den):
    """Tự lấy số dư đầu kỳ (chỉ tiêu [41] tờ khai GTGT kỳ trước, đọc từ thư
    mục kết xuất Năm/Quý riêng của công ty) rồi TÍNH + LƯU LUÔN tạm tính thuế
    GTGT kỳ hiện tại — để mở 'Tạm tính thuế VAT' ra là có sẵn kết quả, không
    phải tự bấm 'Lấy tự động' rồi 'Tính & Save' sau mỗi lần tra cứu.
    Dùng chung cho: tra cứu 1 công ty, tra cứu hàng loạt, VÀ công ty KHÔNG
    có mật khẩu trang Thuế (coi như 0 hóa đơn nhưng vẫn cần đúng số dư đầu kỳ).
    Trả về (ok_msg, canh_bao) — chỉ 1 trong 2 khác None."""
    ok_msg = canh_bao = None
    try:
        ky_hien_tai = _ky_tu_khoang_ngay(tu or "", den or "")
        if ky_hien_tai:
            conn_vat = db()
            comp_vat = conn_vat.execute(
                "SELECT * FROM companies WHERE id=?", (cid,)).fetchone()
            conn_vat.close()
            if comp_vat:
                gia_tri_ct41, ky_truoc_vat, _fp_vat = _doc_ct41_ky_truoc(comp_vat, ky_hien_tai)
                if gia_tri_ct41 is not None:
                    ket_qua_vat = vat_tam_tinh(cid, ky=ky_hien_tai, du_dau_ky=gia_tri_ct41)
                    vat_luu(cid, data={
                        "ky": ky_hien_tai, "du_dau_ky": gia_tri_ct41,
                        "vat_mua": ket_qua_vat["vat_mua"], "vat_ban": ket_qua_vat["vat_ban"],
                        "phai_nop": ket_qua_vat["phai_nop"],
                        "du_cuoi_ky": ket_qua_vat["du_cuoi_ky"]})
                    so_tien_fmt = f"{round(gia_tri_ct41):,}".replace(",", ".")
                    ok_msg = (
                        f"✓ Đã tự động lấy số dư đầu kỳ {so_tien_fmt} đ (từ tờ khai "
                        f"GTGT kỳ {ky_truoc_vat}) và tính tạm thuế GTGT kỳ "
                        f"{ky_hien_tai} — xem tại 'Tạm tính thuế VAT'.")
                else:
                    # KHÔNG tìm thấy tờ khai GTGT kỳ trước trong thư mục lưu
                    # file kết xuất — PHẢI báo RÕ (đỏ), không được im lặng bỏ
                    # qua, để người dùng biết mà tự nhập tay "Số dư đầu kỳ"
                    # hoặc kiểm tra lại đã cấu hình/đã có file kỳ đó chưa.
                    canh_bao = (
                        f"⚠ Không tìm thấy tờ khai GTGT của kỳ "
                        f"{ky_truoc_vat or '(không xác định được kỳ trước)'} trong thư mục "
                        f"lưu file kết xuất — CHƯA tự lấy được 'Số dư đầu kỳ' cho kỳ "
                        f"{ky_hien_tai}. Hãy kiểm tra đã cấu hình đúng 'Thư mục lưu file kết "
                        f"xuất' và đã có file kết xuất kỳ đó chưa (mục Sửa công ty), hoặc tự "
                        f"nhập tay trong khung 'Tạm tính thuế VAT'.")
    except Exception as e:
        canh_bao = f"⚠ Không tự lấy được số dư đầu kỳ/tính tạm thuế GTGT: {str(e)[:120]}"
    return ok_msg, canh_bao


def _tu_dong_ket_xuat_bao_cao(cid, tu, den, msg, total_saved=0, file_saved=0,
                              file_thieu_tong=0, tk_mua=None, tk_ban=None, co_loi=False,
                              luu_ket_xuat=True):
    """Tự động kết xuất Excel + XML GTGT (01/GTGT) + XML TNCN (05/KK-TNCN) —
    dùng chung cho tra cứu hàng loạt, công ty KHÔNG có mật khẩu trang Thuế,
    VÀ tra cứu 1 công ty (để tự động kiểm tra đối chiếu + XML ngay khi tra
    cứu xong). luu_ket_xuat=False: vẫn xuất + kiểm tra như thường nhưng
    KHÔNG ép lưu vào thư mục Năm/Quý đã cấu hình (chỉ để KIỂM TRA, không
    phải người dùng chủ động bấm lưu — file vẫn ra Desktop như xuất thường).
    msg: callback(**kw) ghi tiến độ."""
    tk_mua = tk_mua or {"got": 0, "exp": 0}
    tk_ban = tk_ban or {"got": 0, "exp": 0}
    luu = 1 if luu_ket_xuat else 0
    # Kết quả 2 phần kiểm tra (Đối chiếu + XML vs bảng kê) — gộp lại thành 1
    # trạng thái DUY NHẤT lưu vào công ty (banner XANH/ĐỎ), theo đúng yêu cầu
    # người dùng: báo rõ "có lệch" hay "không lệch" chứ không chỉ im lặng khi ổn.
    da_kiem_tra_doi_chieu = da_kiem_tra_xml = False
    lech_doi_chieu_found = lech_xml_found = False
    cac_dong_lech = []
    try:
        msg(stage="info", text="Đang tự động kết xuất Excel" + (" vào thư mục lưu file kết xuất..." if luu_ket_xuat else "..."))
        resp_excel = export_excel(cid, luu_ket_xuat=luu, tu_ngay=(tu or ""),
                                  den_ngay=(den or ""), mo_file=0)
        msg(stage="info", text="✓ Đã kết xuất Excel" + (" vào thư mục theo Năm/Quý" if luu_ket_xuat else ""))
        # Sheet "Đối chiếu" trong file vừa xuất có phát hiện hóa đơn LỆCH
        # (Chi tiết vs Bảng kê) không — báo RÕ (không chỉ im lặng nằm
        # trong file) để người dùng biết mà mở file kiểm tra lại, thay vì
        # phải tự mở từng file Excel của từng công ty ra xem mới biết.
        try:
            so_lech_ban = int(resp_excel.headers.get("X-So-Lech-Ban", "0"))
            so_lech_mua = int(resp_excel.headers.get("X-So-Lech-Mua", "0"))
            so_ts_lech_ban = int(resp_excel.headers.get("X-So-Ts-Lech-Ban", "0"))
            so_ts_lech_mua = int(resp_excel.headers.get("X-So-Ts-Lech-Mua", "0"))
        except Exception:
            so_lech_ban = so_lech_mua = so_ts_lech_ban = so_ts_lech_mua = 0
        da_kiem_tra_doi_chieu = True
        if so_lech_ban or so_lech_mua:
            lech_doi_chieu_found = True
            ve_lech = []
            if so_lech_ban:
                ve_lech.append(f"bán ra {so_lech_ban}")
            if so_lech_mua:
                ve_lech.append(f"mua vào {so_lech_mua}")
            dong = (f"⚠ Sheet 'Đối chiếu' trong file Excel vừa xuất phát hiện "
                    f"{so_lech_ban + so_lech_mua} hóa đơn LỆCH ({', '.join(ve_lech)}) "
                    f"giữa Chi tiết và Bảng kê — hãy mở file kiểm tra lại kỹ (mục "
                    f"'CHI TIẾT HÓA ĐƠN LỆCH' trong sheet Đối chiếu).")
            cac_dong_lech.append(dong)
            msg(stage="warn", text=dong,
                total_saved=total_saved, file_saved=file_saved,
                file_thieu=file_thieu_tong,
                tk_mua_got=tk_mua["got"], tk_mua_exp=tk_mua["exp"],
                tk_ban_got=tk_ban["got"], tk_ban_exp=tk_ban["exp"],
                loi_tra_cuu=co_loi, lech_doi_chieu=True)
        if so_ts_lech_ban or so_ts_lech_mua:
            lech_doi_chieu_found = True
            ve_ts = []
            if so_ts_lech_ban:
                ve_ts.append(f"bán ra {so_ts_lech_ban}")
            if so_ts_lech_mua:
                ve_ts.append(f"mua vào {so_ts_lech_mua}")
            dong_ts = (f"⚠ Sheet 'Đối chiếu' phát hiện {so_ts_lech_ban + so_ts_lech_mua} dòng hàng "
                      f"({', '.join(ve_ts)}) có nhãn Thuế suất KHÔNG khớp Tiền thuế thật (thường do "
                      f"hóa đơn giảm thuế NĐ44) — mục 'DÒNG THUẾ SUẤT KHÔNG KHỚP TIỀN THUẾ' trong "
                      f"sheet Đối chiếu.")
            cac_dong_lech.append(dong_ts)
            msg(stage="warn", text=dong_ts,
                total_saved=total_saved, file_saved=file_saved,
                file_thieu=file_thieu_tong,
                tk_mua_got=tk_mua["got"], tk_mua_exp=tk_mua["exp"],
                tk_ban_got=tk_ban["got"], tk_ban_exp=tk_ban["exp"],
                loi_tra_cuu=co_loi, lech_doi_chieu=True)
    except Exception as e:
        msg(stage="warn", text=f"Không tự kết xuất được Excel: {str(e)[:120]}")
    # Kèm luôn file XML tờ khai GTGT (01/GTGT) và TNCN (05/KK-TNCN)
    # vào cùng thư mục Năm/Quý để nộp HTKK — mỗi cái độc lập, lỗi cái
    # này không chặn cái kia.
    try:
        res_htkk = export_htkk(cid, tu=(tu or ""), den=(den or ""),
                               luu_ket_xuat=luu, mo_file=0)
        msg(stage="info", text="✓ Đã kết xuất XML tờ khai GTGT (01/GTGT)")
        da_kiem_tra_xml = True
        # Báo NGAY trong tiến độ tra cứu hàng loạt nếu công ty này bị LỆCH số
        # liệu giữa bảng kê và XML — để người dùng biết công ty nào cần kiểm
        # tra lại mà không phải mở từng công ty ra xem (đã LƯU LẠI persistent
        # ở _export_htkk_impl, ở đây chỉ thêm hiển thị NGAY trong log tiến độ).
        if isinstance(res_htkk, dict) and res_htkk.get("lech_bk"):
            lech_xml_found = True
            cac_dong_lech.append(res_htkk["canh_bao"])
            msg(stage="warn", text=res_htkk["canh_bao"], lech_bk=True)
        # Báo NGAY (không tự ẩn — đã LƯU LẠI persistent ở _export_htkk_impl
        # qua _luu_thue_vat_phai_nop) nếu kỳ này công ty PHÁT SINH PHẢI NỘP
        # thuế GTGT (chỉ tiêu [40]), kèm số tiền cụ thể — để biết ngay công
        # ty nào phải nộp và nộp bao nhiêu mà không phải tự mở XML ra xem,
        # cho cả tra cứu 1 công ty lẫn tra cứu hàng loạt.
        if isinstance(res_htkk, dict) and round(res_htkk.get("thue_phai_nop") or 0) > 0:
            dong_vat = (f"🔴 Công ty PHẢI NỘP thuế GTGT — kỳ {res_htkk.get('thue_phai_nop_ky', '')}: "
                       f"{round(res_htkk['thue_phai_nop']):,.0f}đ (chỉ tiêu [40] trên XML 01/GTGT).")
            msg(stage="info", text=dong_vat, vat_phai_nop=True,
               vat_phai_nop_so_tien=round(res_htkk["thue_phai_nop"]))
    except Exception as e:
        msg(stage="warn", text=f"Không tự kết xuất được XML GTGT: {str(e)[:120]}")
    # LƯU LẠI trạng thái đối chiếu TỔNG HỢP — CHỈ khi cả 2 phần đều kiểm tra
    # được (không lỗi giữa chừng), để tránh báo "XANH, không lệch" nhầm khi
    # thực ra 1 phần chưa kiểm tra được do lỗi.
    if da_kiem_tra_doi_chieu and da_kiem_tra_xml:
        if cac_dong_lech:
            # \n\n giữa 2 cảnh báo (đối chiếu / XML) để tách dòng rõ ràng khi
            # hiện trong banner (dễ đọc hơn 1 đoạn văn dài dính liền nhau).
            _luu_ket_qua_doi_chieu(cid, True, "\n\n".join(cac_dong_lech))
        else:
            _luu_ket_qua_doi_chieu(
                cid, False,
                "✓ Không lệch — sheet 'Đối chiếu' không phát hiện hóa đơn lệch, số liệu XML khớp "
                "TỔNG CỘNG bảng kê Mua vào/Bán ra.")
    try:
        export_htkk_tncn(cid, tu=(tu or ""), den=(den or ""),
                         luu_ket_xuat=luu, mo_file=0)
        msg(stage="info", text="✓ Đã kết xuất XML tờ khai TNCN (05/KK-TNCN)")
    except Exception as e:
        msg(stage="warn", text=f"Không tự kết xuất được XML TNCN: {str(e)[:120]}")


# ---------- TRA CỨU & TẢI HÓA ĐƠN (streaming tiến độ) ----------
def _run_fetch_job(cid: int, body: dict):
    """Lõi tra cứu + tải hóa đơn cho MỘT công ty (chạy đồng bộ trong thread).

    Giả định: FETCH_JOBS[cid] đã được khởi tạo bởi nơi gọi, và token còn hiệu lực.
    Dùng chung cho tra cứu 1 công ty (/api/fetch) và tra cứu hàng loạt
    (/api/fetch-batch).

    body: {
      tu_ngay, den_ngay,
      loai_list: ["purchase","sold"],
      he_thong_list: ["query","sco-query"],
      dl_buy:  ["xml","pdf"]  # định dạng tải cho mua vào (rỗng = không tải)
      dl_sell: ["xml","pdf"]  # định dạng tải cho bán ra
    }
    """
    client = get_client(cid)

    tu = body.get("tu_ngay")
    den = body.get("den_ngay")
    loai_list = body.get("loai_list", ["purchase", "sold"])
    he_thong_list = body.get("he_thong_list", ["query", "sco-query"])
    lay_ngan_hang = body.get("lay_ngan_hang", False)  # mặc định KHÔNG lấy HĐ ngân hàng
    dl_map = {
        "purchase": body.get("dl_buy", []),
        "sold": body.get("dl_sell", []),
    }

    def la_hoa_don_ngan_hang(inv):
        """Nhận diện hóa đơn ngân hàng/phí dịch vụ NH qua tên người bán."""
        ten = (inv.get("nbten") or "").upper()
        tu_khoa = ["NGAN HANG", "NGÂN HÀNG", "BANK", "TMCP", "THƯƠNG MẠI CỔ PHẦN",
                   "VIETCOMBANK", "VIETINBANK", "AGRIBANK", "BIDV", "TECHCOMBANK",
                   "SACOMBANK", "ACB", "MBBANK", "VPBANK", "TPBANK", "SHB"]
        return any(k in ten for k in tu_khoa)

    conn0 = db()
    comp = conn0.execute("SELECT * FROM companies WHERE id=?", (cid,)).fetchone()
    save_dir = (comp["save_dir"] or "").strip() if comp else ""
    conn0.close()

    def msg(**kw):
        # Ghi tiến độ vào job thay vì yield (để chạy nền, không phụ thuộc trình duyệt)
        job = FETCH_JOBS.get(cid)
        if job is not None:
            job["messages"].append(kw)
            job["last"] = kw
        # Lưu LỖI/GHI CHÚ vào công ty (DB) để không bị mất khi thông báo/toast tự
        # tắt — người dùng mở lại công ty vẫn thấy đúng ghi chú lần tra cứu gần
        # nhất. "done" mà KHÔNG còn thiếu file nào thì mới xóa ghi chú cũ đi —
        # nếu vẫn còn file chưa tải được (dữ liệu bảng đã đủ, chỉ thiếu file XML)
        # thì vẫn GIỮ ghi chú lại để người dùng biết còn hóa đơn nào cần tải lại.
        stage = kw.get("stage")
        if stage == "error":
            _luu_loi_tra_cuu(cid, kw.get("text") or "")
        elif stage == "done":
            if kw.get("file_thieu"):
                _luu_loi_tra_cuu(cid, kw.get("text") or "")
            else:
                _xoa_loi_tra_cuu(cid)
        return None

    def run():
        conn = db()
        try:
            # Ghi nhớ TRẠNG THÁI (tthai) của các hóa đơn ĐÃ CÓ trước khi xóa —
            # dùng để phát hiện hóa đơn bị THAY THẾ/ĐIỀU CHỈNH so với lần tra
            # cứu trước (vd hóa đơn số 10 lần trước "mới" (1), lần này trang
            # Thuế báo đã "bị thay thế" (4) -> PHẢI tải lại, không dùng file cũ).
            # Ghi nhớ luôn detail_json ĐÃ LẤY ĐƯỢC (nếu có) — hóa đơn "không mã"
            # (ttxly=6, không có file XML) tốn hẳn 1 lượt gọi mạng riêng
            # (_dam_bao_du_chi_tiet_hoa_don) mới lấy được chi tiết dòng hàng.
            # Trước đây MỖI LẦN tra cứu lại đều XÓA HẲN dòng cũ (kể cả
            # detail_json đã lấy được từ lần trước) rồi CHÈN LẠI dòng mới
            # KHÔNG có detail_json — nên hóa đơn không mã bị lấy lại chi tiết
            # qua mạng TỪ ĐẦU ở MỌI lần tra cứu, dù trạng thái hóa đơn không
            # đổi gì cả. Nay GIỮ LẠI detail_json cũ nếu trạng thái (tthai)
            # KHÔNG đổi — hóa đơn bị thay thế/điều chỉnh (tthai đổi) vẫn phải
            # lấy lại chi tiết mới, không dùng bản cũ.
            old_status = {}
            old_detail_json = {}
            for r in conn.execute(
                    "SELECT khmshdon, khhdon, shdon, loai, he_thong, tthai, detail_json "
                    "FROM invoices WHERE company_id=?", (cid,)):
                key = (str(r["khmshdon"] or ""), str(r["khhdon"] or ""),
                       str(r["shdon"] or ""), r["loai"], r["he_thong"])
                old_status[key] = str(r["tthai"] or "")
                if r["detail_json"]:
                    old_detail_json[key] = r["detail_json"]
            # KHÔNG xóa dữ liệu cũ ngay từ đầu nữa — TRƯỚC ĐÂY xóa sạch hết rồi
            # mới tra cứu lại, nên nếu lượt tra cứu MỚI này lại LỖI (vd 1 trạng
            # thái mua vào lỗi dù đã thử lại) thì dữ liệu CŨ (đã lưu từ lần
            # TRƯỚC thành công) cũng biến mất theo — nhìn như phần mềm "tự mất
            # dữ liệu". Nay chỉ xóa dữ liệu cũ CỦA TỪNG LOẠI (mua/bán x hệ
            # thống) NGAY TRƯỚC KHI lưu kết quả MỚI THÀNH CÔNG của đúng loại
            # đó — loại nào lỗi thì GIỮ NGUYÊN dữ liệu cũ, không bị mất.
            msg(stage="start", text="Bắt đầu tra cứu...")

            total_saved = 0
            file_saved = 0
            file_thieu_tong = 0   # số file XML KHÔNG tải được (sau khi đã thử lại), gộp cả kỳ
            file_thieu_mota = []  # mô tả cụ thể (tên công ty + số HĐ) từng nhóm file thiếu
            # LỖI NGOẠI LỆ xảy ra NGAY TRONG bước tải file (vd lỗi tạo thư mục,
            # lỗi liệt kê file đã có...) khiến CẢ KHỐI tải file của 1 loại (mua/
            # bán) bị bỏ dở giữa chừng — khác với "loi_file" (từng hóa đơn lẻ
            # không tải được, đã có cảnh báo + đếm vào file_thieu_tong ở trên).
            # TRƯỚC ĐÂY lỗi này CHỈ hiện ở dòng log TRỰC TIẾP lúc đang chạy, KHÔNG
            # được đưa vào done_text/banner tổng kết cuối cùng -> nếu người dùng
            # không xem kịp dòng log lúc đó, xem lại sau sẽ KHÔNG THẤY DẤU VẾT
            # gì của lỗi (loại hóa đơn đó lặng lẽ có 0 file, không tính là
            # "thiếu" cũng không báo lỗi) — trông như "không có vấn đề gì" dù
            # thực ra cả loại hóa đơn đó chưa tải được file nào. Ghi lại đây để
            # LUÔN xuất hiện trong banner tổng kết cuối, không bị mất dấu.
            loi_tai_file_ngoai_le = []
            # đếm theo loại để tổng kết: {loai: {"exp": tổng trang Thuế báo, "got": số lấy được}}
            thongke = {"purchase": {"exp": 0, "got": 0}, "sold": {"exp": 0, "got": 0}}
            # Đánh dấu RIÊNG khi 1 loại (mua/bán) bị LỖI THẬT SỰ dù đã thử lại —
            # PHẢI phân biệt với "0 hóa đơn" hợp lệ, để KHÔNG BAO GIỜ báo "Hoàn tất"
            # sạch sẽ khi thực ra chưa tra cứu được (nguyên nhân gốc của việc phần
            # mềm "báo xong" dù bán ra bị lỗi/rớt mạng giữa chừng).
            loai_that_bai = {"purchase": False, "sold": False}
            ly_do_loi = {"purchase": [], "sold": []}   # lý do CỤ THỂ (kỹ thuật) của từng lỗi
            target_dir = None
            if save_dir:
                try:
                    os.makedirs(save_dir, exist_ok=True)
                    target_dir = save_dir
                except Exception as e:
                    msg(stage="warn", text=f"Không tạo được thư mục lưu: {e}")

            khoa_tonghop = threading.Lock()  # bảo vệ biến gộp khi các tổ hợp
            # (mua/bán × thường/máy tính tiền) chạy SONG SONG với nhau
            # Dùng CHUNG limiter với thanh trượt "Số lượng tải song song" —
            # không tách riêng máy tính tiền/hóa đơn điện tử thường nữa.
            mtt_limiter_query = (FETCH_JOBS.get(cid) or {}).get("limiter")
            # Chỉ cho phép 1 tổ hợp tự đăng nhập lại tại 1 thời điểm — 4 tổ hợp
            # dùng CHUNG 1 client/token, nên nếu token hết hạn giữa chừng, CẢ 4
            # có thể cùng phát hiện gần như đồng thời; không có khoá này sẽ có
            # nhiều lượt tự giải captcha + đăng nhập chạy song song vô ích.
            khoa_relogin = threading.Lock()

            def _xu_ly_to_hop(loai, he_thong):
                # Mua vào/bán ra (cả 2 hệ thống) chạy SONG SONG với nhau —
                # trước đây hoàn toàn TUẦN TỰ (mua thường -> mua MTT -> bán
                # thường -> bán MTT), nên 1 tổ hợp bị kẹt (vd máy tính tiền
                # đang thử lại 504 nhiều lần) khiến các tổ hợp CÒN LẠI phải
                # đợi dù không liên quan gì tới lỗi đó. Kết nối DB RIÊNG cho
                # từng tổ hợp (không dùng chung "conn" ngoài — vốn chỉ còn
                # dùng để đọc old_status trước khi các tổ hợp bắt đầu).
                nonlocal total_saved, file_saved, file_thieu_tong
                loai_txt = "mua vào" if loai == "purchase" else "bán ra"
                ht_txt = " (máy tính tiền)" if he_thong == "sco-query" else ""
                _job = FETCH_JOBS.get(cid)
                if _job and _job.get("cancel"):
                    msg(stage="warn", text="Đã dừng tra cứu (chuyển sang công ty khác)")
                    return
                msg(stage="query",
                    text=f"Đang tra cứu hóa đơn {loai_txt}{ht_txt}...")
                conn = db()
                try:
                    # Thử tối đa 2 LƯỢT trước khi báo lỗi hẳn. QUAN TRỌNG: lượt
                    # 2 (nếu cần) CHỈ dò lại ĐÚNG các đoạn (tháng × trạng thái)
                    # đã lỗi ở lượt 1 (chi_cac_doan) — KHÔNG dò lại từ đầu toàn
                    # bộ khoảng ngày. Trước đây hễ có lỗi riêng phần (vd mua vào
                    # máy tính tiền: 1/3 trạng thái của 1 tháng bị rớt mạng dù
                    # mọi tháng/trạng thái khác đều OK) là dò lại TOÀN BỘ từ đầu
                    # (có khi cả năm), rất lâu và vô ích vì tuyệt đại đa số đã
                    # thành công — nhất là hệ thống máy tính tiền hay bị lỗi
                    # mạng vặt, khiến "không có phát sinh" vẫn phải chờ rất lâu.
                    invs = None
                    exp0_gop = 0
                    loi_cuoi = None
                    loi_rieng = []
                    cac_doan_loi = None
                    bo_qua_404 = False
                    # Trước đây chỉ thử lại tối đa 2 lượt, và CHỈ thử lại khi có
                    # lỗi RÕ RÀNG (loi_rieng) — nếu trang Thuế báo total nhiều
                    # hơn số lấy được nhưng KHÔNG kèm lỗi cụ thể nào (vd 1 hóa
                    # đơn lặng lẽ rơi mất giữa 2 trang phân trang), phần mềm chỉ
                    # CẢNH BÁO ("có thể thiếu — nên tra cứu lại") rồi coi như
                    # xong, bắt người dùng phải tự bấm tra cứu lại — trái với
                    # yêu cầu "phải tải đầy đủ mới xong quá trình tải". Nay tăng
                    # số lượt thử VÀ coi luôn trường hợp "thiếu so với total"
                    # (dù không có lỗi cụ thể) là CHƯA XONG, tự động dò lại toàn
                    # bộ khoảng ngày cho tới khi khớp đủ hoặc hết số lượt thử.
                    SO_LAN_THU = 6
                    for lan_thu in range(SO_LAN_THU):
                        # Kiểm tra NGAY ĐẦU mỗi lượt thử — nếu người dùng đã chuyển
                        # sang công ty khác (hoặc bấm dừng) giữa chừng, dừng HẲN ở
                        # đây, không bắt đầu thêm lượt thử/tháng/trang nào nữa.
                        if (FETCH_JOBS.get(cid) or {}).get("cancel"):
                            msg(stage="warn",
                                text=f"⏹ {loai_txt}{ht_txt}: đã dừng tra cứu theo yêu cầu "
                                     f"(chuyển sang công ty khác)")
                            return
                        # Đoạn CỤ THỂ sẽ dùng cho LƯỢT GỌI NÀY (None/rỗng ở lượt đầu,
                        # hoặc khi client không có/không còn đoạn lỗi cụ thể để dò
                        # riêng -> lượt này sẽ dò lại TOÀN BỘ khoảng ngày).
                        doan_dung_de_goi = cac_doan_loi
                        try:
                            moi, moi_total, loi_rieng, cac_doan_loi = client.query_invoices(
                                tu, den, loai=loai, he_thong=he_thong,
                                progress=lambda t: msg(stage="query", text=f"{loai_txt}{ht_txt}: {t}"),
                                chi_cac_doan=doan_dung_de_goi,
                                mtt_limiter=(mtt_limiter_query if he_thong == "sco-query" else None),
                                cancel_check=lambda: bool((FETCH_JOBS.get(cid) or {}).get("cancel")))
                            loi_cuoi = None
                            # query_invoices có thể trả về BÌNH THƯỜNG (không raise)
                            # với dữ liệu THIẾU nếu bị hủy giữa chừng lúc đang gộp
                            # kết quả các tháng/đoạn — kiểm tra lại NGAY sau khi có
                            # kết quả để không hiểu nhầm "thiếu" này là lỗi cần thử
                            # lại (đằng nào cũng đã bị hủy, thử lại chỉ tốn công).
                            if (FETCH_JOBS.get(cid) or {}).get("cancel"):
                                msg(stage="warn",
                                    text=f"⏹ {loai_txt}{ht_txt}: đã dừng tra cứu theo yêu cầu "
                                         f"(chuyển sang công ty khác)")
                                return
                        except Exception as e:
                            es = str(e)
                            if "CANCELLED" in es:
                                msg(stage="warn",
                                    text=f"⏹ {loai_txt}{ht_txt}: đã dừng tra cứu theo yêu cầu "
                                         f"(chuyển sang công ty khác)")
                                return
                            if "TOKEN_EXPIRED" in es:
                                # TỰ ĐỘNG đăng nhập lại (nếu công ty có lưu mật
                                # khẩu) rồi thử lại tiếp, thay vì DỪNG NGAY bắt
                                # người dùng tự bấm đăng nhập lại rồi tra cứu lại
                                # từ đầu — phần mềm đã có sẵn cơ chế tự đăng
                                # nhập (dùng cho tra cứu hàng loạt/xuất Excel),
                                # chỉ là trước đây KHÔNG được áp dụng ở đây.
                                conn_relog = db()
                                comp_relog = conn_relog.execute(
                                    "SELECT password FROM companies WHERE id=?", (cid,)).fetchone()
                                conn_relog.close()
                                if comp_relog and comp_relog["password"] and lan_thu < SO_LAN_THU - 1:
                                    # Token CŨ (đã hết hạn) vẫn còn là 1 chuỗi
                                    # KHÁC RỖNG bình thường — raise exception
                                    # không tự xoá nó — nên KHÔNG thể chỉ kiểm
                                    # tra "client.token có giá trị hay không" để
                                    # biết đã được làm mới hay chưa. Phải SO
                                    # SÁNH với giá trị token NGAY TRƯỚC lúc chờ
                                    # khoá: nếu đã ĐỔI KHÁC, nghĩa là 1 tổ hợp
                                    # khác vừa đăng nhập lại xong trong lúc chờ.
                                    token_truoc_khi_cho = client.token
                                    with khoa_relogin:
                                        if client.token != token_truoc_khi_cho:
                                            ok_dn = True
                                        else:
                                            msg(stage="warn",
                                                text=f"⚠ {loai_txt}{ht_txt}: Token hết hạn giữa chừng — "
                                                     f"đang tự động đăng nhập lại...")
                                            # Dùng trình duyệt ẩn vẽ captcha CHÍNH
                                            # XÁC (như /api/auto-login, xuất Excel)
                                            # thay vì rớt về svglib kém chính xác
                                            # hơn — tăng tỉ lệ tự đăng nhập lại
                                            # thành công, đỡ mất hẳn phần dữ liệu
                                            # còn lại của lượt tra cứu này.
                                            drv_relog = _mo_trinh_duyet_captcha()
                                            try:
                                                ok_dn, tb_dn, _, _ = _tu_dong_dang_nhap(
                                                    cid, so_lan=5, drv=drv_relog)
                                            finally:
                                                _dong_trinh_duyet_captcha(drv_relog)
                                    if ok_dn:
                                        msg(stage="info",
                                            text=f"✓ {loai_txt}{ht_txt}: đã tự đăng nhập lại thành công, "
                                                 f"đang tiếp tục tra cứu...")
                                        continue
                                    msg(stage="error",
                                        text=f"Token hết hạn — tự đăng nhập lại thất bại ({tb_dn}), "
                                             f"cần đăng nhập lại thủ công")
                                    return
                                msg(stage="error", text="Token hết hạn, cần đăng nhập lại")
                                return
                            if he_thong == "sco-query" and "404" in es:
                                bo_qua_404 = True
                                break
                            loi_cuoi = es
                            loi_rieng = []
                            if lan_thu < SO_LAN_THU - 1:
                                cho = 30 if ("429" in es or "quá nhiều" in es) else 8
                                msg(stage="warn",
                                    text=f"⚠ {loai_txt}{ht_txt}: {es[:140]}. Đang chờ {cho}s rồi thử lại...")
                                time.sleep(cho)
                            continue

                        if not doan_dung_de_goi:
                            # Lượt này KHÔNG dò theo đoạn cụ thể (lượt đầu, hoặc client
                            # không hỗ trợ/không còn đoạn lỗi cụ thể để retry riêng) ->
                            # kết quả là dò lại TOÀN BỘ khoảng ngày -> THAY THẾ hoàn
                            # toàn kết quả/tổng kỳ vọng lượt trước (không cộng dồn,
                            # tránh đếm trùng khiến báo "thiếu" sai dù đã lấy đủ).
                            invs = moi
                            exp0_gop = moi_total or 0
                        else:
                            # Lượt này CHỈ dò ĐÚNG đoạn bị lỗi trước đó -> CỘNG DỒN
                            # (khử trùng) vào kết quả đã có của các đoạn khác.
                            if invs is None:
                                invs = moi
                            else:
                                seen_now = {(iv.get("khmshdon"), iv.get("khhdon"),
                                            iv.get("shdon"), iv.get("nbmst")) for iv in invs}
                                for iv in moi:
                                    key = (iv.get("khmshdon"), iv.get("khhdon"),
                                          iv.get("shdon"), iv.get("nbmst"))
                                    if key not in seen_now:
                                        invs.append(iv); seen_now.add(key)
                            exp0_gop += moi_total or 0

                        # Không raise lỗi nhưng vẫn có thể lỗi RIÊNG PHẦN (vd 1 trong 3
                        # trạng thái mua vào lỗi dù 2 cái kia OK) — CŨNG PHẢI thử lại
                        # (chưa xong = chưa dừng), không chỉ khi raise hẳn.
                        loi_rieng = loi_rieng or []
                        cac_doan_loi = cac_doan_loi or []
                        # THIẾU so với total (dù KHÔNG có lỗi cụ thể nào) — cũng
                        # coi là CHƯA XONG, phải dò lại (xem giải thích ở SO_LAN_THU).
                        con_thieu = bool(exp0_gop) and len(invs or []) < exp0_gop
                        if not loi_rieng and not con_thieu:
                            break   # lấy sạch, không lỗi gì, không thiếu -> xong, khỏi thử thêm
                        if lan_thu < SO_LAN_THU - 1:
                            # QUAN TRỌNG: chọn thông báo theo cac_doan_loi (đoạn CỤ THỂ sẽ
                            # được dùng cho lượt sau, xem 'doan_dung_de_goi' đầu vòng lặp),
                            # KHÔNG chỉ theo loi_rieng — kể cả khi KHÔNG có lỗi/exception rõ
                            # ràng nào (chỉ thiếu số lượng so với total), _gop() ở
                            # query_invoices giờ đã ghi nhận ĐÚNG (các) tháng còn thiếu vào
                            # cac_doan_loi, nên lượt sau CHỈ dò lại đúng (các) tháng đó —
                            # KHÔNG còn phải dò lại TOÀN BỘ khoảng ngày (có khi nhiều tháng)
                            # chỉ vì thiếu vài hóa đơn ở 1 tháng — trước đây thông báo (và cả
                            # thực tế dò lại) luôn nói "TOÀN BỘ kỳ" trong trường hợp này dù
                            # không cần thiết, rất mất thời gian với công ty nhiều hóa đơn.
                            if cac_doan_loi:
                                ly_do = (f"{len(loi_rieng)} lượt bị lỗi riêng phần ({'; '.join(loi_rieng[:2])})"
                                         if loi_rieng else
                                         f"trang Thuế báo {exp0_gop} hóa đơn nhưng mới lấy {len(invs or [])}")
                                msg(stage="warn",
                                    text=f"⚠ {loai_txt}{ht_txt}: {ly_do} — đang dò LẠI ĐÚNG "
                                         f"{len(cac_doan_loi)} đoạn còn thiếu/lỗi (không dò lại từ đầu), "
                                         f"chưa dừng...")
                            else:
                                msg(stage="warn",
                                    text=f"⚠ {loai_txt}{ht_txt}: trang Thuế báo {exp0_gop} hóa đơn "
                                         f"nhưng mới lấy {len(invs or [])} — đang dò LẠI TOÀN BỘ kỳ "
                                         f"này để lấy đủ (lần {lan_thu + 2}/{SO_LAN_THU}), chưa dừng...")
                            time.sleep(10)

                    if bo_qua_404:
                        msg(stage="warn", text=f"{loai_txt}{ht_txt}: không có (404) — bỏ qua")
                        return
                    if loi_cuoi is not None:
                        # Đã thử lại vẫn lỗi -> ĐÂY LÀ LỖI THẬT SỰ, không phải "0 hóa đơn".
                        # KHÔNG được continue âm thầm mà không đánh dấu — nếu không, phần
                        # tổng kết cuối cùng không biết loại này đã THẤT BẠI và có thể
                        # báo "Hoàn tất" sạch sẽ dù trang Thuế thực ra có dữ liệu.
                        with khoa_tonghop:
                            loai_that_bai[loai] = True
                            ly_do_loi[loai].append(f"{loai_txt}{ht_txt}: {loi_cuoi[:200]}")
                        msg(stage="error",
                            text=f"✗ {loai_txt}{ht_txt}: LỖI, CHƯA TRA CỨU ĐƯỢC dù đã thử lại — "
                                 f"{loi_cuoi[:140]}. KẾT QUẢ {loai_txt.upper()} CÓ THỂ THIẾU — "
                                 f"NÊN TRA CỨU LẠI riêng kỳ/công ty này (dữ liệu {loai_txt}{ht_txt} "
                                 f"đã lưu từ lần tra cứu trước — NẾU CÓ — vẫn được GIỮ NGUYÊN, "
                                 f"không bị xóa).")
                        return

                    if loi_rieng:
                        with khoa_tonghop:
                            loai_that_bai[loai] = True
                            ly_do_loi[loai].append(
                                f"{loai_txt}{ht_txt}: một phần bị lỗi ({len(loi_rieng)} lượt) dù đã "
                                f"tra cứu lại {SO_LAN_THU} lượt — {'; '.join(loi_rieng[:3])}")
                        msg(stage="warn",
                            text=f"⚠ {loai_txt}{ht_txt}: một phần bị lỗi dù đã tra cứu lại "
                                 f"{SO_LAN_THU} lượt ({len(loi_rieng)} lượt còn lỗi) — KẾT QUẢ CÓ "
                                 f"THỂ THIẾU. Chi tiết: {'; '.join(loi_rieng[:3])}")

                    exp0 = exp0_gop
                    # Số lượng lấy được THẬT SỰ (gộp cả các lượt retry theo đoạn lỗi)
                    # — KHÔNG dùng client.last_query_got vì sau khi retry theo
                    # chi_cac_doan, giá trị đó chỉ phản ánh riêng lượt retry (1 vài
                    # đoạn nhỏ), không phải tổng cộng dồn toàn kỳ.
                    got_gop = len(invs) if invs else 0
                    if not invs:
                        if exp0:
                            # Trang Thuế báo CÓ hóa đơn nhưng ta lấy được 0 -> chắc chắn
                            # có vấn đề, TUYỆT ĐỐI không được coi là "không có dữ liệu".
                            with khoa_tonghop:
                                loai_that_bai[loai] = True
                                ly_do_loi[loai].append(
                                    f"{loai_txt}{ht_txt}: Thuế báo có {exp0} hóa đơn nhưng lấy được 0")
                            msg(stage="error",
                                text=f"✗ {loai_txt}{ht_txt}: Trang Thuế báo có {exp0} hóa đơn "
                                     f"nhưng KHÔNG lấy được cái nào — LỖI, nên tra cứu LẠI (dữ liệu "
                                     f"{loai_txt}{ht_txt} đã lưu từ lần trước — nếu có — vẫn được "
                                     f"GIỮ NGUYÊN, không bị xóa).")
                        else:
                            # XÁC NHẬN THẬT SỰ 0 hóa đơn (không phải lỗi) -> được phép
                            # xóa dữ liệu CŨ của đúng loại này (phản ánh đúng hiện trạng).
                            conn.execute(
                                "DELETE FROM invoices WHERE company_id=? AND loai=? AND he_thong=?",
                                (cid, loai, he_thong))
                            conn.commit()
                            msg(stage="found",
                                text=f"{loai_txt}{ht_txt}: 0 hóa đơn (không có dữ liệu trong kỳ)",
                                total_saved=total_saved)
                        return

                    if not lay_ngan_hang:
                        truoc = len(invs)
                        invs = [iv for iv in invs if not la_hoa_don_ngan_hang(iv)]
                        bo = truoc - len(invs)
                        if bo > 0:
                            msg(stage="info",
                                text=f"Đã loại {bo} hóa đơn ngân hàng khỏi {loai_txt}{ht_txt}")

                    # CHỈ xóa dữ liệu CŨ của đúng loại này NGAY TRƯỚC KHI lưu kết quả
                    # MỚI (đã xác nhận tra cứu được) — loại khác lỗi thì không đụng tới.
                    conn.execute(
                        "DELETE FROM invoices WHERE company_id=? AND loai=? AND he_thong=?",
                        (cid, loai, he_thong))
                    # Chẩn đoán vì sao detail_json của hóa đơn "không mã" (ttxly=6)
                    # đôi khi KHÔNG được giữ lại qua các lần tra cứu (người dùng báo
                    # ĐÃ tra cứu xong hẳn 1 lần — bước "Đang lấy nốt chi tiết dòng
                    # hàng" chạy 100% — nhưng lần tra cứu SAU lại phải lấy lại TỪ
                    # ĐẦU cho gần như toàn bộ) — đếm cụ thể để biết ĐÚNG nguyên nhân
                    # (chưa từng có old_detail_json / có nhưng key không khớp / có
                    # khớp key nhưng tthai lệch) thay vì đoán.
                    _km_tong = _km_co_cu = _km_khop_key = _km_giu_duoc = 0
                    _km_vi_du_lech = []
                    for inv in invs:
                        try:
                            # Hóa đơn bán hàng (Mẫu số 2 — hộ/cá nhân kinh doanh
                            # KHÔNG chịu VAT) trang Thuế trả tgtcthue (tiền hàng
                            # CHƯA thuế) = 0/rỗng vì không tách thuế, CHỈ có tổng
                            # tiền thanh toán (tgtttbso). Trước đây lưu thẳng 0,
                            # khiến "Tổng tiền chưa VAT" và các báo cáo tổng hợp
                            # HIỆN 0 dù hóa đơn có giá trị thật — nhìn như phần
                            # mềm "không ghi nhận" hóa đơn dù đã tải được. Với
                            # hóa đơn không VAT (tgtthue=0), tiền CHƯA thuế PHẢI
                            # BẰNG tổng tiền thanh toán -> lấy tgtttbso làm dự
                            # phòng khi tgtcthue rỗng/0.
                            tgtcthue_v = _to_num(inv.get("tgtcthue"))
                            tgtttbso_v = _to_num(inv.get("tgtttbso"))
                            if not tgtcthue_v and tgtttbso_v:
                                tgtcthue_v = tgtttbso_v
                            # Trạng thái KHÔNG đổi so với lần tra cứu trước -> giữ lại
                            # detail_json đã lấy được (nếu có), khỏi phải lấy lại qua
                            # mạng ở bước _dam_bao_du_chi_tiet_hoa_don (chủ yếu áp
                            # dụng cho hóa đơn "không mã" — vốn không có file XML để
                            # so sánh "đã có file" như các hóa đơn thường).
                            key_dj = (str(inv.get("khmshdon", "")), str(inv.get("khhdon", "")),
                                     str(inv.get("shdon", "")), loai, he_thong)
                            tthai_moi_dj = str(inv.get("tthai", ""))
                            tthai_cu_dj = old_status.get(key_dj)
                            dj_giu_lai = (old_detail_json.get(key_dj)
                                         if tthai_cu_dj == tthai_moi_dj else None)
                            if str(inv.get("ttxly") or "").strip() == "6":
                                _km_tong += 1
                                if key_dj in old_detail_json:
                                    _km_co_cu += 1
                                if tthai_cu_dj is not None:
                                    _km_khop_key += 1
                                    if dj_giu_lai:
                                        _km_giu_duoc += 1
                                    elif key_dj in old_detail_json and len(_km_vi_du_lech) < 3:
                                        _km_vi_du_lech.append(
                                            f"{inv.get('khhdon')} {inv.get('shdon')}: "
                                            f"tthai cũ={tthai_cu_dj!r} mới={tthai_moi_dj!r}")
                            conn.execute("""
                                INSERT OR IGNORE INTO invoices
                                (company_id, loai, he_thong, nbmst, nbten, nmmst,
                                 khmshdon, khhdon, shdon,
                                 tdlap, tgtcthue, tgtthue, tgtttbso, tthai, raw, detail_json)
                                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                            """, (
                                cid, loai, he_thong,
                                inv.get("nbmst"), inv.get("nbten"), inv.get("nmmst"),
                                str(inv.get("khmshdon", "")), inv.get("khhdon"), str(inv.get("shdon", "")),
                                inv.get("tdlap"),
                                tgtcthue_v, inv.get("tgtthue"), inv.get("tgtttbso"),
                                str(inv.get("tthai", "")),
                                json.dumps(inv, ensure_ascii=False),
                                dj_giu_lai,
                            ))
                        except Exception:
                            pass
                    conn.commit()
                    if _km_tong:
                        msg(stage="info",
                            text=f"🔬 chẩn đoán giữ chi tiết hóa đơn không mã ({loai_txt}{ht_txt}): "
                                 f"{_km_tong} hóa đơn không mã trong lượt này, {_km_co_cu} từng có "
                                 f"detail_json cũ, {_km_khop_key} khớp được với lần tra cứu trước "
                                 f"(còn lại là hóa đơn MỚI/chưa từng thấy), {_km_giu_duoc} giữ lại "
                                 f"được detail_json"
                                 + (f" — VÍ DỤ LỆCH TRẠNG THÁI: {'; '.join(_km_vi_du_lech)}"
                                    if _km_vi_du_lech else ""))
                    # so sánh với tổng kỳ vọng từ trang Thuế (trước khi lọc ngân hàng)
                    exp = exp0
                    got_raw = got_gop
                    with khoa_tonghop:
                        total_saved += len(invs)
                        thongke[loai]["exp"] += exp
                        thongke[loai]["got"] += got_raw
                    if exp and got_raw < exp:
                        # Đã thử lại đủ SO_LAN_THU lượt (dò lại TOÀN BỘ kỳ mỗi
                        # lần) mà VẪN thiếu — không còn là "cảnh báo nhẹ" nữa,
                        # đây là CHƯA HOÀN THÀNH thật sự (người dùng yêu cầu
                        # "phải tải đầy đủ mới xong quá trình tải"), nên đánh
                        # dấu THẤT BẠI để dòng tổng kết cuối cùng phản ánh đúng
                        # (không được báo "Hoàn tất" khi còn thiếu hóa đơn).
                        with khoa_tonghop:
                            loai_that_bai[loai] = True
                            ly_do_loi[loai].append(
                                f"{loai_txt}{ht_txt}: đã dò lại {SO_LAN_THU} lượt vẫn thiếu "
                                f"({got_raw}/{exp} HĐ)")
                        msg(stage="error",
                            text=f"✗ {loai_txt}{ht_txt}: Trang Thuế báo có {exp} HĐ nhưng chỉ lấy "
                                 f"được {got_raw} DÙ ĐÃ DÒ LẠI {SO_LAN_THU} LƯỢT — CHƯA HOÀN THÀNH, "
                                 f"nên tra cứu LẠI kỳ này (hoặc chuyển chế độ Chậm & an toàn).")
                    elif exp:
                        msg(stage="info",
                            text=f"✓ {loai_txt}{ht_txt}: Đã lấy đủ {got_raw}/{exp} hóa đơn theo trang Thuế")
                    msg(stage="found",
                        text=f"Tìm thấy {len(invs)} hóa đơn {loai_txt}{ht_txt}",
                        total_saved=total_saved)

                    fmts = dl_map.get(loai, [])
                    if fmts and target_dir and invs:
                      try:
                        sub = os.path.join(target_dir, f"{loai_txt}".replace(" ", "_"))
                        os.makedirs(sub, exist_ok=True)
                        n = len(invs)

                        # INDEX FILE ĐÃ CÓ trong thư mục này (1 lần, tránh quét lại mỗi
                        # hóa đơn) — dùng để BỎ QUA tải hóa đơn đã có file đọc được trên
                        # máy, tránh tải đi tải lại (chỉ cần lấy hóa đơn mới phát sinh).
                        # Khoá theo (ký hiệu, số hoá đơn, MST người bán) — KHÔNG được
                        # bỏ MST khỏi khoá: nhiều người bán khác nhau có thể trùng
                        # ký hiệu + số hoá đơn (vd cả 2 đều "C26MTT" số "246"), nếu chỉ
                        # khoá theo (ký hiệu, số) sẽ nhận NHẦM file của hóa đơn công ty
                        # khác là "đã tải" cho hóa đơn đang xét.
                        _file_index_dl = {}
                        _file_index_dl_2 = {}   # dự phòng cho file cũ không có MST trong tên
                        for fn in os.listdir(sub):
                            low = fn.lower()
                            if not (low.endswith(".xml") or low.endswith(".zip")):
                                continue
                            name = fn.rsplit(".", 1)[0]
                            parts = name.split("_")
                            if len(parts) < 2:
                                continue
                            f_khh, f_sho = parts[0], parts[1].lstrip("0") or "0"
                            path2 = os.path.join(sub, fn)

                            def _uu_tien_xml(prev, low=low):
                                return prev is None or (prev.lower().endswith(".zip") and low.endswith(".xml"))
                            if len(parts) >= 3:
                                # Chuẩn hóa MST trong khoá (bỏ dấu gạch/khoảng
                                # trắng) — MST cùng 1 người bán đôi khi trang
                                # Thuế trả về LỆCH ĐỊNH DẠNG giữa các lần tra
                                # cứu khác nhau (có/không hậu tố chi nhánh), nếu
                                # so khớp CHUỖI Y HỆT sẽ không nhận ra file ĐÃ
                                # CÓ SẴN trên máy (nhìn như file "chưa tải" dù
                                # thực ra đã tải, khiến tải lại không cần thiết).
                                key3 = (f_khh, f_sho, _chuan_mst(parts[2])[:10])
                                if _uu_tien_xml(_file_index_dl.get(key3)):
                                    _file_index_dl[key3] = path2
                            else:
                                key2 = (f_khh, f_sho)
                                if _uu_tien_xml(_file_index_dl_2.get(key2)):
                                    _file_index_dl_2[key2] = path2

                        # Ghi lại LÝ DO CỤ THỂ khi 1 hóa đơn ĐÃ CÓ file trên máy nhưng
                        # vẫn phải tải lại (không được bỏ qua) — trước đây người dùng
                        # chỉ thấy "vẫn tải lại" dù file cũ rõ ràng còn đó, không biết
                        # vì sao (trạng thái đổi thật, hay file cũ đọc lỗi, hay không
                        # khớp được với file cũ do sai khoá) để tự kiểm tra/báo lại.
                        ly_do_tai_lai_du_co_file = []

                        def _tai_1_file(inv):
                            if (FETCH_JOBS.get(cid) or {}).get("cancel"):
                                return "cancelled"
                            nbmst = inv.get("nbmst", "")
                            khhdon = inv.get("khhdon", "")
                            khmshdon = inv.get("khmshdon", "")
                            shdon = inv.get("shdon", "")
                            base = f"{khhdon}_{shdon}_{nbmst}"
                            if "xml" not in fmts:
                                return "ok"   # không yêu cầu tải xml -> coi như "xong"
                            # Hóa đơn "Tổng cục thuế đã nhận KHÔNG MÃ" (ttxly=6): không
                            # có file XML để tải (trang Thuế không cấp mã cho loại này).
                            # KHÔNG gọi API chi tiết ở đây — từng thử "lấy luôn chi tiết
                            # ngay lúc tra cứu" nhưng việc bắn thêm hàng trăm request
                            # chi tiết XEN LẪN các request tải file (chạy song song
                            # nhiều luồng) khiến tường lửa trang Thuế coi là tấn công
                            # và CHẶN CẢ IP ở tầng kết nối (trình duyệt cũng không vào
                            # được — ERR_HTTP2_PROTOCOL_ERROR), người dùng đã xác nhận
                            # cứ tra cứu là bị chặn. Chi tiết dòng hàng của loại hóa
                            # đơn này sẽ được lấy ở bước KẾT XUẤT EXCEL (đã có sẵn cơ
                            # chế thử lại kiên nhẫn + phương án dự phòng tổng tiền theo
                            # bảng kê) — một điểm gọi mạng duy nhất, dễ kiểm soát nhịp.
                            if str(inv.get("ttxly") or "").strip() == "6":
                                return "khong_ma"

                            # ĐÃ CÓ FILE + ĐỌC ĐƯỢC + TRẠNG THÁI (tthai) KHÔNG ĐỔI so với
                            # lần tra cứu trước -> BỎ QUA, không tải lại trên trang Thuế.
                            # Nếu tthai đã đổi (hóa đơn bị THAY THẾ/ĐIỀU CHỈNH kể từ lần
                            # trước) thì VẪN PHẢI tải lại để lấy đúng bản mới nhất.
                            key = (str(khmshdon or ""), str(khhdon or ""),
                                   str(shdon or ""), loai, he_thong)
                            tthai_cu = old_status.get(key)
                            tthai_moi = str(inv.get("tthai") or "")
                            fkey = (str(khhdon or ""), str(shdon or "").lstrip("0") or "0", _chuan_mst(nbmst)[:10])
                            fpath = _file_index_dl.get(fkey) or _file_index_dl_2.get(fkey[:2])
                            if fpath:
                                doc_duoc = _doc_kiem_tra_file_hoadon(fpath)
                                if (tthai_cu is None or tthai_cu == tthai_moi) and doc_duoc:
                                    # File đã có sẵn trên máy từ TRƯỚC (không tải lại) —
                                    # vẫn tranh thủ đối chiếu/tự sửa ngày lập theo đúng
                                    # file này, phòng khi hóa đơn được lưu TỪ TRƯỚC lúc
                                    # có bản sửa lỗi lệch ngày (file cũ không đổi, chỉ
                                    # cách đọc/đối chiếu ngày mới thêm sau).
                                    try:
                                        with open(fpath, "rb") as _f:
                                            _sua_ngay_lap_tu_xml(cid, inv, loai, he_thong, _f.read())
                                    except Exception:
                                        pass
                                    return "skip"
                                # ĐÃ CÓ file (tìm khớp key) nhưng KHÔNG được bỏ qua —
                                # ghi rõ lý do cụ thể để biết chính xác vì sao vẫn phải
                                # tải lại (thay vì chỉ thấy "vẫn tải lại" không rõ vì sao).
                                if len(ly_do_tai_lai_du_co_file) < 10:
                                    if not doc_duoc:
                                        ly_do_tai_lai_du_co_file.append(
                                            f"{khhdon} {shdon}: file cũ có nhưng KHÔNG đọc được ({fpath})")
                                    else:
                                        ly_do_tai_lai_du_co_file.append(
                                            f"{khhdon} {shdon}: trạng thái đổi ({tthai_cu} → {tthai_moi})")

                            # Xin phép qua limiter trước khi THỰC SỰ gọi mạng — cho
                            # phép người dùng CHỈNH số luồng đồng thời ngay trong lúc
                            # đang tải (xem set_limit ở endpoint /api/fetch-song-song),
                            # không cần dừng lại/chạy lại từ đầu. DÙNG CHUNG 1 limiter
                            # cho cả hóa đơn điện tử thường lẫn máy tính tiền — không
                            # tách riêng nữa, theo yêu cầu.
                            _job_ct = FETCH_JOBS.get(cid) or {}
                            limiter = _job_ct.get("limiter")
                            if limiter:
                                limiter.acquire()
                            try:
                                try:
                                    zdata = client.download_xml(nbmst, khhdon, khmshdon,
                                                                shdon, loai, he_thong)
                                except Exception:
                                    zdata = None
                            finally:
                                if limiter:
                                    limiter.release()
                            if zdata:
                                try:
                                    _save_invoice_files(sub, base, zdata)
                                    _sua_ngay_lap_tu_xml(cid, inv, loai, he_thong, zdata)
                                    return "ok"
                                except Exception:
                                    return "fail"
                            return "fail"

                        # TẢI SONG SONG (thay vì từng file 1) để rút ngắn thời gian chờ —
                        # mỗi file là 1 request mạng riêng tới trang Thuế, tải tuần tự
                        # từng cái 1 với hàng chục/hàng trăm hóa đơn khiến tổng thời gian
                        # cộng dồn rất lâu dù mỗi file không lỗi gì. Executor tạo với
                        # TỐI ĐA 32 luồng (trần cứng) — số luồng THỰC SỰ hoạt động cùng
                        # lúc do DynamicLimiter (FETCH_JOBS[cid]["limiter"]) quyết định,
                        # chỉnh được ngay trong lúc đang tải qua /api/fetch-song-song.
                        SO_LUONG_SONG_SONG = 32

                        def _tai_nhieu_file(ds_inv, nhan):
                            """Tải song song danh sách hóa đơn.
                            Trả về (so_thanh_cong, ds_loi, so_bo_qua_da_co_san, so_khong_ma)."""
                            if (FETCH_JOBS.get(cid) or {}).get("cancel"):
                                return 0, [], 0, 0
                            if getattr(client, "_token_dead", False):
                                # phiên đã hết hạn -> khỏi thử mạng, nhưng HĐ "không mã"
                                # vốn dĩ không cần tải file nên vẫn KHÔNG tính là lỗi
                                kma = [iv for iv in ds_inv if str(iv.get("ttxly") or "").strip() == "6"]
                                loi_thuc = [iv for iv in ds_inv if iv not in kma]
                                return 0, loi_thuc, 0, len(kma)
                            loi = []
                            so_ok = 0
                            so_bo_qua = 0
                            so_khong_ma = 0
                            so_xong = 0
                            n_ds = len(ds_inv)
                            with _cf.ThreadPoolExecutor(max_workers=SO_LUONG_SONG_SONG) as ex:
                                futs = {ex.submit(_tai_1_file, inv): inv for inv in ds_inv}
                                for fut in _cf.as_completed(futs):
                                    inv = futs[fut]
                                    try:
                                        kq = fut.result()
                                    except Exception:
                                        kq = "fail"
                                    so_xong += 1
                                    msg(stage="download",
                                        text=f"{nhan} {loai_txt}: {so_xong}/{n_ds} (còn {n_ds - so_xong})",
                                        cur=so_xong, total=n_ds)
                                    if kq == "skip":
                                        so_ok += 1; so_bo_qua += 1
                                    elif kq == "khong_ma":
                                        # KHÔNG cộng vào so_ok (= file_saved): hóa đơn
                                        # này thật sự không có file nào được lưu, chỉ
                                        # là KHÔNG PHẢI lỗi (không tính là loi/thiếu).
                                        so_khong_ma += 1
                                    elif kq == "ok":
                                        so_ok += 1
                                    elif kq == "cancelled":
                                        # Đã dừng theo yêu cầu (chuyển công ty khác) —
                                        # KHÔNG tính là lỗi (không thử lại), chỉ đơn
                                        # giản là chưa tải, sẽ tải lại nếu tra cứu lại.
                                        pass
                                    else:
                                        loi.append(inv)
                            return so_ok, loi, so_bo_qua, so_khong_ma

                        ok_1, loi_file, bo_qua, khong_ma = _tai_nhieu_file(invs, "Đang tải file")
                        with khoa_tonghop:
                            file_saved += ok_1

                        if ly_do_tai_lai_du_co_file:
                            msg(stage="info",
                                text=f"ℹ {loai_txt}{ht_txt}: {len(ly_do_tai_lai_du_co_file)}"
                                     f"{'+' if len(ly_do_tai_lai_du_co_file) >= 10 else ''} hóa đơn ĐÃ CÓ file "
                                     f"cũ trên máy nhưng vẫn tải lại — lý do cụ thể: "
                                     f"{'; '.join(ly_do_tai_lai_du_co_file[:10])}")

                        # THỬ LẠI 1 LƯỢT các file bị lỗi (thường do bị chặn tốc độ giữa
                        # chừng) — trước đây KHÔNG hề thử lại nên 1 lần vấp là mất file
                        # vĩnh viễn dù dữ liệu hóa đơn (bảng) vẫn tải đủ.
                        if loi_file and not getattr(client, "_token_dead", False):
                            msg(stage="warn",
                                text=f"⚠ {loai_txt}{ht_txt}: {len(loi_file)} file tải chưa được, "
                                     f"đang thử lại... [{_mo_ta_ds_hd_loi(loi_file, loai)}]")
                            time.sleep(5)
                            ok_2, loi_file, bo_qua_2, khong_ma_2 = _tai_nhieu_file(loi_file, "Thử lại file")
                            with khoa_tonghop:
                                file_saved += ok_2
                            bo_qua += bo_qua_2
                            khong_ma += khong_ma_2

                        if bo_qua:
                            msg(stage="info",
                                text=f"↷ {loai_txt}{ht_txt}: {bo_qua} hóa đơn đã có sẵn file trên máy "
                                     f"(đọc được, trạng thái không đổi) — bỏ qua, không tải lại")

                        if khong_ma:
                            # SỬA CHỮ: bước này KHÔNG hề lấy chi tiết dòng hàng ngay (xem
                            # _tai_1_file — cố tình KHÔNG gọi API chi tiết ở đây để tránh
                            # tường lửa Thuế chặn IP do gọi xen lẫn với tải file), chi tiết
                            # sẽ được lấy ở bước "lấy nốt chi tiết dòng hàng" NGAY SAU ĐÂY
                            # (hoặc lúc Xuất Excel nếu vẫn còn thiếu). Chữ cũ "chỉ ghi nhận
                            # dữ liệu chi tiết" khiến người dùng tưởng đã xong, rồi thấy
                            # bước sau vẫn phải lấy gần hết số này thì tưởng nhầm là lỗi.
                            msg(stage="info",
                                text=f"↷ {loai_txt}{ht_txt}: {khong_ma} hóa đơn 'Tổng cục thuế đã "
                                     f"nhận không mã' — không có file để tải, sẽ lấy chi tiết dòng "
                                     f"hàng ở bước riêng ngay sau khi tải file xong")

                        n_can_tai = n - khong_ma   # tổng cần tải (không tính HĐ không mã)
                        if loi_file:
                            mota_loi_file = _mo_ta_ds_hd_loi(loi_file, loai)
                            with khoa_tonghop:
                                file_thieu_tong += len(loi_file)
                                file_thieu_mota.append(f"{loai_txt}{ht_txt}: {mota_loi_file}")
                            msg(stage="warn",
                                text=f"⚠ {loai_txt}{ht_txt}: KHÔNG tải được {len(loi_file)}/{n_can_tai} file "
                                     f"(dữ liệu bảng vẫn lưu đủ) — CÁC HÓA ĐƠN CHƯA TẢI ĐƯỢC: "
                                     f"{mota_loi_file}. Chạy lại tra cứu kỳ này "
                                     f"(chế độ 'Chậm & an toàn') để tải nốt, hoặc kết xuất Excel sẽ "
                                     f"tự lấy chi tiết các hóa đơn này qua mạng khi cần.")
                        elif "xml" in fmts:
                            msg(stage="info",
                                text=f"✓ {loai_txt}{ht_txt}: đã tải đủ {n_can_tai}/{n_can_tai} file")
                      except Exception as e:
                        with khoa_tonghop:
                            loi_tai_file_ngoai_le.append(f"{loai_txt}{ht_txt}: {str(e)[:150]}")
                        msg(stage="warn",
                            text=f"Lỗi tải file {loai_txt} (dữ liệu bảng vẫn lưu): {str(e)[:100]}")
                finally:
                    conn.close()

            combos = [(loai, he_thong) for loai in loai_list for he_thong in he_thong_list]
            with _cf.ThreadPoolExecutor(max_workers=max(1, len(combos))) as ex:
                futs = [ex.submit(_xu_ly_to_hop, loai, he_thong) for loai, he_thong in combos]
                for fut in _cf.as_completed(futs):
                    fut.result()

            # Đã dừng theo yêu cầu (chuyển công ty khác/bấm dừng) giữa chừng —
            # KHÔNG được báo "Hoàn tất" (dữ liệu có thể còn dở dang do bị dừng
            # sớm, không phải vì đã tra cứu xong thật sự).
            if (FETCH_JOBS.get(cid) or {}).get("cancel"):
                msg(stage="done",
                    text=f"⏹ Đã dừng tra cứu theo yêu cầu (chuyển sang công ty khác) — "
                         f"đã lưu {total_saved} hóa đơn tính tới lúc dừng.",
                    total_saved=total_saved, file_saved=file_saved)
                return

            # ===== LẤY NỐT CHI TIẾT DÒNG HÀNG cho hóa đơn KHÔNG có file (hóa
            # đơn không mã/tải file lỗi) NGAY TẠI ĐÂY (sau khi các tổ hợp đã
            # tải file XONG HẲN, KHÔNG còn tổ hợp nào đang tải file xen lẫn) —
            # để bước Xuất Excel sau này CHỈ cần đọc dữ liệu có sẵn (file/
            # detail_json), không phải tự đi tải bù qua mạng gây treo lâu.
            # CHỈ GIỚI HẠN trong đúng khoảng ngày (tu/den) đang tra cứu lần
            # này — trước đây quét CẢ lịch sử hóa đơn công ty (mọi kỳ trước),
            # khiến số hóa đơn "đang lấy nốt chi tiết" hiện ra CAO HƠN HẲN số
            # hóa đơn thật của kỳ đang tra cứu (vd kỳ chỉ có 229 tờ nhưng lại
            # thấy "410 hóa đơn"), gây hiểu nhầm là lỗi dù thực ra chỉ đang
            # dọn luôn hóa đơn tồn đọng từ các kỳ khác.
            # PHẢI gộp qua _gop_hoa_don_trung_he_thong TRƯỚC khi lọc kỳ —
            # 1 hóa đơn thật đôi khi có 2 DÒNG riêng trong 'invoices' (hệ
            # thống 'query' và 'sco-query' cùng trả về, xem giải thích ở hàm
            # đó); mọi báo cáo (Xuất Excel/XML) chỉ dùng ĐÚNG 1 dòng "giữ
            # lại" sau khi gộp, dòng còn lại không cần lấy chi tiết làm gì —
            # nếu không gộp trước, số hóa đơn hiện ra vẫn cao gần gấp đôi số
            # tờ thật (vd 400 dù kỳ chỉ có ~233 tờ) dù ĐÃ giới hạn đúng kỳ.
            chi_ids_ky = None
            try:
                _d1 = datetime.datetime.strptime(tu, "%d/%m/%Y").date() if tu else None
                _d2 = datetime.datetime.strptime(den, "%d/%m/%Y").date() if den else None
            except Exception:
                _d1 = _d2 = None
            if _d1 and _d2:
                try:
                    _conn_ky = db()
                    _rows_ky = _gop_hoa_don_trung_he_thong(_conn_ky.execute(
                        "SELECT * FROM invoices WHERE company_id=?", (cid,)).fetchall())
                    _conn_ky.close()
                    chi_ids_ky = []
                    for _r in _rows_ky:
                        _s = str(_r["tdlap"] or "").split("T")[0]
                        try:
                            _d = datetime.datetime.strptime(_s, "%Y-%m-%d").date()
                        except Exception:
                            continue
                        if _d1 <= _d <= _d2:
                            chi_ids_ky.append(_r["id"])
                except Exception:
                    chi_ids_ky = None
            try:
                _dam_bao_du_chi_tiet_hoa_don(cid, client, save_dir, msg, chi_ids=chi_ids_ky)
            except Exception as e:
                msg(stage="warn", text=f"Không lấy nốt được chi tiết dòng hàng: {str(e)[:120]}")

            # ===== TỔNG KẾT số hóa đơn theo trang Thuế (để biết lấy đủ chưa) =====
            tk_mua = thongke["purchase"]
            tk_ban = thongke["sold"]
            dong_tk = []
            if "purchase" in loai_list:
                if loai_that_bai["purchase"]:
                    dong_tk.append(f"✗ Đầu vào (mua): LỖI khi tra cứu — CHƯA CHẮC ĐÃ ĐỦ "
                                   f"(mới lấy được {tk_mua['got']} HĐ) — nên tra cứu LẠI")
                elif tk_mua["exp"]:
                    dau = "✓" if tk_mua["got"] >= tk_mua["exp"] else "⚠"
                    dong_tk.append(f"{dau} Đầu vào (mua): lấy {tk_mua['got']}/{tk_mua['exp']} HĐ trang Thuế báo")
                else:
                    dong_tk.append(f"• Đầu vào (mua): lấy {tk_mua['got']} HĐ")
            if "sold" in loai_list:
                if loai_that_bai["sold"]:
                    dong_tk.append(f"✗ Đầu ra (bán): LỖI khi tra cứu — CHƯA CHẮC ĐÃ ĐỦ "
                                   f"(mới lấy được {tk_ban['got']} HĐ) — nên tra cứu LẠI")
                elif tk_ban["exp"]:
                    dau = "✓" if tk_ban["got"] >= tk_ban["exp"] else "⚠"
                    dong_tk.append(f"{dau} Đầu ra (bán): lấy {tk_ban['got']}/{tk_ban['exp']} HĐ trang Thuế báo")
                else:
                    dong_tk.append(f"• Đầu ra (bán): lấy {tk_ban['got']} HĐ")
            for d in dong_tk:
                msg(stage="info", text=d)

            # cảnh báo nếu thiếu (LỖI THẬT SỰ luôn tính là thiếu, kể cả khi 'got'
            # trùng khớp exp một cách tình cờ — vì exp lúc lỗi có thể không đáng tin)
            co_loi = loai_that_bai["purchase"] or loai_that_bai["sold"]
            thieu = (co_loi or
                     (tk_mua["exp"] and tk_mua["got"] < tk_mua["exp"]) or
                     (tk_ban["exp"] and tk_ban["got"] < tk_ban["exp"]))

            # ===== TỰ ĐỘNG LẤY SỐ DƯ ĐẦU KỲ (chỉ tiêu [41] của tờ khai GTGT kỳ
            # trước, đọc từ thư mục kết xuất Năm/Quý riêng của công ty) VÀ TÍNH
            # + LƯU LUÔN tạm tính thuế GTGT kỳ này — để mở "Tạm tính thuế VAT"
            # ra là có sẵn kết quả, không phải tự bấm "Lấy tự động" rồi "Tính &
            # Save" sau mỗi lần tra cứu (áp dụng cho cả tra cứu 1 công ty lẫn
            # hàng loạt). Chỉ làm khi tra cứu THÀNH CÔNG (không co_loi) — dữ
            # liệu hóa đơn dùng để tính vat_mua/vat_ban phải đáng tin cậy. Tính
            # TRƯỚC khi ghép done_text để nếu KHÔNG tìm thấy file kỳ trước, lời
            # cảnh báo được ghép NGAY VÀO banner tổng kết (hiện đỏ qua toast),
            # không tách thành 1 dòng thông báo lỗi RIÊNG (tránh bị hiểu nhầm
            # thành lỗi tra cứu hóa đơn thật sự, ảnh hưởng trạng thái batch).
            vat_dau_ky_ok_msg = vat_dau_ky_canh_bao = None
            if not co_loi:
                vat_dau_ky_ok_msg, vat_dau_ky_canh_bao = _tu_dong_lay_so_du_dau_ky_va_tinh_vat(cid, tu, den)

            if co_loi:
                # KHÔNG BAO GIỜ báo "Hoàn tất" khi có lỗi — phải là trạng thái LỖI rõ ràng
                loi_ben = []
                if loai_that_bai["purchase"]:
                    loi_ben.append("MUA VÀO")
                if loai_that_bai["sold"]:
                    loi_ben.append("BÁN RA")
                # Ghép LÝ DO CỤ THỂ (kỹ thuật) của từng loại lỗi vào — trước đây
                # dòng tổng kết này chỉ nói "LỖI MUA VÀO" chung chung, không nói
                # rõ NGUYÊN NHÂN (vd timeout, 500, 429...) khiến người dùng không
                # biết đang lỗi gì để xử lý.
                chi_tiet_loi = []
                for lo in ("purchase", "sold"):
                    chi_tiet_loi.extend(ly_do_loi[lo])
                done_text = (f"❌ LỖI khi tra cứu {', '.join(loi_ben)} — DỮ LIỆU CHƯA ĐẦY ĐỦ "
                            f"(hiện có {total_saved} hóa đơn: đầu vào {tk_mua['got']}, "
                            f"đầu ra {tk_ban['got']} — riêng loại LỖI ở trên vẫn đang GIỮ dữ "
                            f"liệu của lần tra cứu THÀNH CÔNG gần nhất, KHÔNG bị mất). "
                            f"BẮT BUỘC tra cứu LẠI công ty này (nên chuyển chế độ "
                            f"'Chậm & an toàn' nếu vẫn lỗi).")
                if chi_tiet_loi:
                    done_text += " NGUYÊN NHÂN: " + " | ".join(chi_tiet_loi)
            else:
                done_text = f"Hoàn tất! Đã lưu {total_saved} hóa đơn"
                if "purchase" in loai_list or "sold" in loai_list:
                    done_text += f" (đầu vào: {tk_mua['got']}, đầu ra: {tk_ban['got']})"
                if file_saved:
                    done_text += f", tải {file_saved} file vào: {target_dir}"
                if file_thieu_tong:
                    done_text += f" — ⚠ CÒN {file_thieu_tong} FILE CHƯA TẢI ĐƯỢC (dữ liệu bảng vẫn đủ)"
                    if file_thieu_mota:
                        done_text += ". CHI TIẾT: " + " | ".join(file_thieu_mota)
                if loi_tai_file_ngoai_le:
                    done_text += (f" — ❌ LỖI TẢI FILE (cả loại hóa đơn bị bỏ dở, CHƯA có file "
                                  f"nào cho phần này): " + " | ".join(loi_tai_file_ngoai_le))
                if thieu:
                    done_text += " — ⚠ CÓ THỂ THIẾU, nên tra cứu lại (chế độ Chậm & an toàn)"
                if vat_dau_ky_canh_bao:
                    done_text += f" — {vat_dau_ky_canh_bao}"
            msg(stage=("error" if co_loi else "done"), text=done_text,
                total_saved=total_saved, file_saved=file_saved,
                file_thieu=file_thieu_tong,
                tk_mua_got=tk_mua["got"], tk_mua_exp=tk_mua["exp"],
                tk_ban_got=tk_ban["got"], tk_ban_exp=tk_ban["exp"],
                loi_tra_cuu=co_loi)
            if vat_dau_ky_ok_msg:
                msg(stage="info", text=vat_dau_ky_ok_msg)

            # ===== TỰ ĐỘNG KẾT XUẤT + KIỂM TRA ĐỐI CHIẾU/XML =====
            # - TRA CỨU HÀNG LOẠT (body["batch"]=True): CHỈ tự xuất (Excel +
            #   XML) vào thư mục Năm/Quý khi TICK "Lưu file kết xuất" — không
            #   tick thì không có gì để kiểm tra (giữ nguyên hành vi cũ).
            # - TRA CỨU 1 CÔNG TY: LUÔN tự động kiểm tra đối chiếu + XML ngay
            #   khi tra cứu xong thành công (theo yêu cầu người dùng — hiện rõ
            #   banner XANH "không lệch" hoặc ĐỎ "có lệch"). Việc CÓ lưu thêm
            #   vào thư mục Năm/Quý đã cấu hình hay không TÔN TRỌNG đúng ô
            #   "Lưu file kết xuất" của công ty (frontend gửi kèm trong
            #   body["luu_ket_xuat"] khi bấm "Tra cứu hóa đơn") — tick thì lưu
            #   vào thư mục đã cấu hình, không tick thì lưu ra Desktop như
            #   xuất thủ công. TRƯỚC ĐÂY cờ này KHÔNG được gửi cho tra cứu 1
            #   công ty nên luôn bị coi là "không tick" dù đã tick trên giao
            #   diện, khiến file bị lưu THÊM ra Desktop dù đã lưu đúng vào thư
            #   mục kết xuất (nộp trùng bản, đúng lỗi người dùng phát hiện).
            la_batch = bool(body.get("batch"))
            if la_batch and body.get("luu_ket_xuat") and co_loi:
                # KHÔNG được để người dùng tick "Lưu file kết xuất" mà không thấy
                # gì xảy ra và cũng không hiểu vì sao — trước đây im lặng bỏ qua
                # hẳn bước này khi tra cứu có lỗi, trông như tính năng "không
                # hoạt động" dù thực ra là CỐ Ý (tránh xuất báo cáo từ dữ liệu
                # có thể thiếu). Nay báo RÕ để người dùng biết cần tra cứu lại.
                msg(stage="warn",
                    text="⚠ KHÔNG tự động kết xuất (Excel/XML GTGT/XML TNCN) vào thư mục lưu file kết "
                         "xuất vì lần tra cứu này CÓ LỖI — dữ liệu có thể thiếu. Hãy tra cứu lại cho "
                         "đến khi THÀNH CÔNG rồi mới kết xuất (hoặc bấm nút 'Xuất Excel'/'Kết xuất "
                         "XML' thủ công ở dưới sau khi đã tra cứu xong).")
            elif not co_loi and (la_batch and body.get("luu_ket_xuat") or not la_batch):
                _tu_dong_ket_xuat_bao_cao(cid, tu, den, msg, total_saved=total_saved,
                                          file_saved=file_saved, file_thieu_tong=file_thieu_tong,
                                          tk_mua=tk_mua, tk_ban=tk_ban, co_loi=co_loi,
                                          luu_ket_xuat=bool(body.get("luu_ket_xuat")))
        except Exception as e:
            msg(stage="error", text=f"Lỗi: {str(e)[:160]}")
        finally:
            conn.close()
            job = FETCH_JOBS.get(cid)
            if job is not None:
                job["running"] = False

    # FETCH_JOBS[cid] đã được khởi tạo bởi nơi gọi (endpoint /api/fetch hoặc batch).
    # Chạy đồng bộ trong thread của nơi gọi.
    run()


class DynamicLimiter:
    """Giới hạn số luồng ĐANG THỰC SỰ chạy đồng thời (tải file), có thể
    CHỈNH SỐ NGAY TRONG LÚC ĐANG TẢI — khác với ThreadPoolExecutor thường
    (max_workers cố định ngay từ lúc tạo, không đổi được giữa chừng). Cách
    làm: luôn tạo executor với số luồng TỐI ĐA (32), nhưng mỗi luồng phải
    "xin phép" (acquire) qua limiter này trước khi thực sự gọi mạng — chỉnh
    set_limit() sẽ áp dụng ngay cho các lượt xin phép TIẾP THEO, không cần
    dừng lại và chạy lại từ đầu. limit=0 -> tạm dừng hẳn (không luồng nào
    được xin phép) cho tới khi tăng lại."""

    def __init__(self, initial=4):
        self._cond = threading.Condition()
        self._limit = max(0, min(32, int(initial)))
        self._active = 0

    def set_limit(self, n):
        with self._cond:
            self._limit = max(0, min(32, int(n)))
            self._cond.notify_all()

    def get_limit(self):
        with self._cond:
            return self._limit

    def acquire(self):
        with self._cond:
            while self._active >= self._limit:
                self._cond.wait(timeout=1.0)
            self._active += 1

    def release(self):
        with self._cond:
            self._active -= 1
            self._cond.notify_all()


MTT_TRAN_CUNG_EXECUTOR = 16  # trần CỨNG (an toàn) cho ThreadPoolExecutor xử
# lý tháng MTT — chỉ để tạo đủ luồng cho executor, số luồng THỰC SỰ chạy
# đồng thời do "limiter" (thanh trượt "Số lượng tải song song" — DÙNG CHUNG
# cho cả hóa đơn điện tử thường lẫn máy tính tiền, không tách riêng) quyết định.


def _new_fetch_job():
    return {"messages": [], "last": None, "running": True,
            "cursor": 0, "started": time.time(), "cancel": False,
            "limiter": DynamicLimiter(SP().get("song_song", 4))}


def _sua_ngay_lap_tu_xml(cid, inv, loai, he_thong, zdata):
    """Sửa lại NGÀY LẬP (tdlap) của hóa đơn trong DB nếu ngày trong file XML
    thật (<NLap>) khác với ngày trang Thuế trả về lúc tra cứu danh sách.

    Đã gặp trường hợp: hóa đơn K26TEG/61820238 (VETC) trang Thuế TRA CỨU
    DANH SÁCH báo tdlap=2026-03-31, nhưng file XML thật (đã tải về) lại ghi
    <NLap>2026-04-01</NLap> — 2 nguồn dữ liệu của CHÍNH Tổng cục Thuế không
    khớp nhau. File XML là NGUỒN GỐC/CHUẨN nhất (chữ ký số + toàn bộ nội
    dung hóa đơn) nên khi đã tải được, dùng ngày trong XML để tự sửa lại
    cho đúng, không phụ thuộc ngày (có thể sai) của API tra cứu danh sách."""
    try:
        rows = _parse_xml_invoice(zdata)
        ngay_xml = (rows[0].get("ngay") or "").strip() if rows else ""
        if not ngay_xml:
            return
        ngay_xml_d = ngay_xml.split("T")[0]
        ngay_cu_d = str(inv.get("tdlap") or "").split("T")[0]
        if not ngay_cu_d or ngay_xml_d == ngay_cu_d:
            return
        tdlap_moi = ngay_xml if "T" in ngay_xml else f"{ngay_xml}T00:00:00"
        cn = db()
        cn.execute(
            "UPDATE invoices SET tdlap=? WHERE company_id=? AND khmshdon=? "
            "AND khhdon=? AND shdon=? AND loai=? AND he_thong=?",
            (tdlap_moi, cid, str(inv.get("khmshdon") or ""),
             str(inv.get("khhdon") or ""), str(inv.get("shdon") or ""), loai, he_thong))
        cn.commit()
        cn.close()
    except Exception:
        pass


def _sua_tdlap_theo_id(row_id, ngay_xml, tdlap_cu):
    """Như _sua_ngay_lap_tu_xml nhưng dùng khi ĐÃ CÓ id dòng + ngày đã parse
    sẵn từ XML (vd lúc xuất Excel đọc lại file đã tải trên máy) — tránh phải
    parse lại XML lần nữa và không cần dò theo khmshdon/khhdon/shdon."""
    try:
        if not ngay_xml:
            return
        ngay_xml_d = str(ngay_xml).split("T")[0]
        ngay_cu_d = str(tdlap_cu or "").split("T")[0]
        if not ngay_cu_d or ngay_xml_d == ngay_cu_d:
            return
        tdlap_moi = ngay_xml if "T" in str(ngay_xml) else f"{ngay_xml}T00:00:00"
        cn = db()
        cn.execute("UPDATE invoices SET tdlap=? WHERE id=?", (tdlap_moi, row_id))
        cn.commit()
        cn.close()
    except Exception:
        pass


def _luu_loi_tra_cuu(cid: int, text: str):
    """Lưu LỖI tra cứu gần nhất vào công ty (DB) — để không bị mất khi
    thông báo/toast trên trình duyệt tự tắt. Mở lại công ty vẫn thấy đúng
    lỗi lần tra cứu gần nhất, cho tới khi tra cứu lại THÀNH CÔNG."""
    try:
        cn = db()
        cn.execute(
            "UPDATE companies SET last_fetch_error=?, last_fetch_error_at=? WHERE id=?",
            (text or "", datetime.datetime.now().isoformat(), cid))
        cn.commit()
        cn.close()
    except Exception:
        pass


def _xoa_loi_tra_cuu(cid: int):
    try:
        cn = db()
        cn.execute(
            "UPDATE companies SET last_fetch_error=NULL, last_fetch_error_at=NULL WHERE id=?",
            (cid,))
        cn.commit()
        cn.close()
    except Exception:
        pass


def _luu_ket_qua_doi_chieu(cid: int, lech: bool, text: str):
    """Lưu KẾT QUẢ lần kiểm tra đối chiếu gần nhất (sheet 'Đối chiếu' + số
    liệu XML so với bảng kê) — LUÔN ghi, kể cả khi KHÔNG lệch, để giao diện
    phân biệt được 'chưa từng kiểm tra' (NULL) với 'đã kiểm tra, không lệch'
    (ok) thay vì chỉ im lặng khi ổn — theo đúng yêu cầu người dùng: hiện rõ
    banner XANH khi không lệch, ĐỎ khi có lệch."""
    try:
        cn = db()
        cn.execute(
            "UPDATE companies SET doi_chieu_ket_qua=?, doi_chieu_text=?, doi_chieu_at=? WHERE id=?",
            ("lech" if lech else "ok", text or "", datetime.datetime.now().isoformat(), cid))
        cn.commit()
        cn.close()
    except Exception:
        pass


def _luu_thue_vat_phai_nop(cid: int, so_tien: float, ky_text: str):
    """Lưu số thuế GTGT PHẢI NỘP trong kỳ (chỉ tiêu [40] khi kết xuất XML
    01/GTGT) — LUÔN ghi (kể cả 0, để phân biệt 'chưa kiểm tra' (NULL) với
    'đã kiểm tra, không phải nộp'), để giao diện hiện thông báo KHÔNG TỰ ẨN
    cho người dùng biết ngay công ty nào phải nộp và nộp bao nhiêu."""
    try:
        cn = db()
        cn.execute(
            "UPDATE companies SET vat_phai_nop=?, vat_phai_nop_at=?, vat_phai_nop_ky=? WHERE id=?",
            (so_tien or 0, datetime.datetime.now().isoformat(), ky_text or "", cid))
        cn.commit()
        cn.close()
    except Exception:
        pass


@app.post("/api/fetch/{cid}")
def fetch_invoices(cid: int, body: dict = Body(...)):
    """Tra cứu + tải hóa đơn cho 1 công ty (chạy nền). Trình duyệt poll
    /api/fetch-status/{cid} để lấy tiến độ."""
    client = get_client(cid)
    if not client.token:
        _luu_loi_tra_cuu(cid, "Chưa đăng nhập tài khoản thuế cho công ty này")
        raise HTTPException(401, "Chưa đăng nhập tài khoản thuế cho công ty này")
    _xoa_loi_tra_cuu(cid)   # bắt đầu lượt mới -> xóa ghi chú lỗi lần trước
    FETCH_JOBS[cid] = _new_fetch_job()
    import threading
    threading.Thread(target=lambda: _run_fetch_job(cid, body), daemon=True).start()
    return {"ok": True, "started": True}


# ---------- TRA CỨU HÀNG LOẠT (nhiều công ty cùng lúc) ----------
# Chạy CÙNG LÚC tối đa BATCH_SONG_SONG công ty (worker pool) — xong công ty
# nào thì lập tức lấy công ty tiếp theo trong hàng đợi chạy tiếp, thay vì đợi
# xong HẲN 1 công ty rồi mới bắt đầu công ty kế (tuần tự như trước). Tiến độ
# từng công ty vẫn ghi vào FETCH_JOBS[cid] như cũ, đồng thời BATCH_JOBS[batch_id]
# tổng hợp trạng thái toàn batch (current_list = các công ty đang chạy).
BATCH_SONG_SONG = 3
BATCH_JOBS = {}      # {batch_id: {...}}
_BATCH_SEQ = {"n": 0}
_seed_batch_seq()   # nối tiếp id từ batch đã lưu trong DB (tránh trùng)


def _batch_luu_db(batch_id, batch, body, trang_thai=None):
    """Ghi trạng thái batch xuống SQLite để TRA CỨU TIẾP nếu phần mềm bị tắt
    đột ngột / dừng giữa chừng. Gọi sau mỗi công ty xong (tiến độ luôn được
    lưu), nên dù mất điện/crash cũng chỉ mất tối đa dở dang 1 công ty."""
    try:
        cn = db()
        now = datetime.datetime.now().isoformat()
        cn.execute("""INSERT INTO batch_tra_cuu
            (batch_id, body_json, order_json, items_json, total, done, trang_thai, created_at, updated_at)
            VALUES (?,?,?,?,?,?,?,?,?)
            ON CONFLICT(batch_id) DO UPDATE SET
                items_json=excluded.items_json, done=excluded.done,
                trang_thai=excluded.trang_thai, updated_at=excluded.updated_at""",
            (batch_id, json.dumps(body, ensure_ascii=False),
             json.dumps(batch["order"]),
             json.dumps(batch["items"], ensure_ascii=False),
             batch["total"], batch["done"],
             trang_thai or batch.get("trang_thai", "dang_chay"), now, now))
        cn.commit(); cn.close()
    except Exception:
        pass


def _run_batch(batch_id: int, cids: list, body: dict):
    """Chạy CÙNG LÚC tối đa BATCH_SONG_SONG công ty (worker pool) — công ty
    nào xong trước thì lập tức nhường chỗ cho công ty tiếp theo trong hàng
    đợi, không phải đợi xong HẾT 1 lượt BATCH_SONG_SONG công ty rồi mới bắt
    đầu lượt kế. batch["current_list"] là danh sách cid ĐANG chạy tại một
    thời điểm (tối đa BATCH_SONG_SONG phần tử)."""
    batch = BATCH_JOBS[batch_id]
    # Trình duyệt ẩn dùng CHUNG cho cả batch để vẽ captcha chính xác khi tự
    # đăng nhập (mở LƯỜI — chỉ mở khi thật sự gặp công ty chưa đăng nhập đầu
    # tiên, và dùng lại cho các công ty/lượt thử sau, đỡ tốn thời gian mở lại
    # trình duyệt nhiều lần). Có thể có NHIỀU công ty cùng cần tự đăng nhập
    # cùng lúc (chạy song song) nhưng trình duyệt ẩn CHỈ 1 cửa sổ -> khoá lại
    # để mỗi lần chỉ 1 công ty dùng trình duyệt vẽ captcha (không tranh nhau),
    # phần TẢI HÓA ĐƠN (_run_fetch_job) của từng công ty vẫn chạy song song
    # bình thường vì mỗi công ty có phiên đăng nhập/kết nối RIÊNG.
    drv_captcha = [None, False]  # [driver_hoac_None, da_thu_mo_chua]
    drv_lock = threading.Lock()
    batch_lock = threading.Lock()   # bảo vệ batch["done"]/current_list/_batch_luu_db

    def _drv():
        with drv_lock:
            if not drv_captcha[1]:
                drv_captcha[1] = True
                drv_captcha[0] = _mo_trinh_duyet_captcha()
            return drv_captcha[0]

    def _xu_ly_khong_co_mat_khau(cid, item):
        """Công ty KHÔNG có mật khẩu trang Thuế -> coi như 0 hóa đơn đầu vào/
        đầu ra kỳ này (không có gì để tra cứu qua mạng), NHƯNG vẫn tự động lấy
        đúng số dư đầu kỳ + tính tạm thuế GTGT + kết xuất Excel/XML GTGT/XML
        TNCN như bình thường — theo yêu cầu người dùng: công ty không có mật
        khẩu thì không tra cứu được, nhưng vẫn cần nộp báo cáo đúng kỳ."""
        tu, den = body.get("tu_ngay"), body.get("den_ngay")

        def _msg(**kw):
            job = FETCH_JOBS.get(cid)
            if job is not None:
                job["messages"].append(kw)
                job["last"] = kw

        vat_ok_msg, vat_canh_bao = _tu_dong_lay_so_du_dau_ky_va_tinh_vat(cid, tu, den)
        done_text = ("Công ty chưa lưu mật khẩu trang Thuế — coi như KHÔNG có hóa đơn đầu "
                     "vào/đầu ra kỳ này, đã tự động kết xuất báo cáo (chỉ cần đúng số dư đầu kỳ).")
        if vat_canh_bao:
            done_text += f" — {vat_canh_bao}"
        _msg(stage="done", text=done_text, total_saved=0, file_saved=0, file_thieu=0,
             tk_mua_got=0, tk_mua_exp=0, tk_ban_got=0, tk_ban_exp=0, loi_tra_cuu=False)
        if vat_ok_msg:
            _msg(stage="info", text=vat_ok_msg)
        if body.get("luu_ket_xuat"):
            _tu_dong_ket_xuat_bao_cao(cid, tu, den, _msg)
        item["status"] = "done"
        item["note"] = done_text
        item["total_saved"] = 0
        item["tk_mua_got"] = item["tk_mua_exp"] = 0
        item["tk_ban_got"] = item["tk_ban_exp"] = 0
        item["lech"] = False
        for _m in (FETCH_JOBS.get(cid) or {}).get("messages", []):
            if _m.get("lech_bk"):
                item["lech_bk"] = True
                item["lech_bk_text"] = _m.get("text", "")
            if _m.get("lech_doi_chieu"):
                item["lech_doi_chieu"] = True
                item["lech_doi_chieu_text"] = _m.get("text", "")
            if _m.get("vat_phai_nop"):
                item["vat_phai_nop"] = True
                item["vat_phai_nop_text"] = _m.get("text", "")
                item["vat_phai_nop_so_tien"] = _m.get("vat_phai_nop_so_tien", 0)
        with batch_lock:
            batch["done"] += 1
            _batch_luu_db(batch_id, batch, body)

    def _xu_ly_1_cong_ty(cid):
        if batch.get("cancel"):
            return
        item = batch["items"].get(cid)
        try:
            # Đặt vào current_list + khởi tạo job NGAY TỪ ĐẦU (kể cả trước khi
            # đăng nhập) — để người dùng thấy phần mềm đang xử lý công ty nào
            # suốt bước tự đăng nhập (có thể mất vài chục giây), không chỉ lúc
            # bắt đầu tải hóa đơn.
            with batch_lock:
                batch.setdefault("current_list", []).append(cid)
            FETCH_JOBS[cid] = _new_fetch_job()
            # Xóa ghi chú lỗi lần tra cứu TRƯỚC (nếu có) NGAY KHI bắt đầu lượt
            # mới — giống HỆT tra cứu 1 công ty (/api/fetch/{cid}) — để không
            # hiện lỗi CŨ trong lúc lượt MỚI này còn đang chạy (trước đây batch
            # chỉ xóa lúc XONG, nên nếu công ty có lỗi từ trước, cả lúc đang
            # chạy lại vẫn hiện "lỗi" dù thực ra đang tra cứu bình thường).
            _xoa_loi_tra_cuu(cid)

            def _bao_tien_do(t, _cid=cid, _item=item):
                _item["note"] = t
                job = FETCH_JOBS.get(_cid)
                if job is not None:
                    kw = {"stage": "login", "text": t}
                    job["messages"].append(kw)
                    job["last"] = kw

            client = get_client(cid)
            if not client.token:
                # TỰ ĐỘNG ĐĂNG NHẬP (bằng tài khoản/mật khẩu đã lưu) thay vì bỏ
                # qua — trước đây công ty chưa đăng nhập bị SKIP hẳn, người
                # dùng phải tự đăng nhập TỪNG CÔNG TY trước khi tra cứu hàng
                # loạt. Công ty nào chưa lưu mật khẩu / tự đăng nhập thất bại
                # (vd sai mật khẩu, OCR không giải được captcha) thì mới bỏ qua.
                item["status"] = "login"
                _bao_tien_do("Đang tự động đăng nhập...")
                # Dùng trình duyệt ẩn (nếu mở được) để vẽ captcha CHÍNH XÁC như
                # lúc người dùng tự bấm nút trên giao diện, thay vì svglib gần
                # đúng — tăng hẳn tỉ lệ thành công. so_lan=8 vẫn cao hơn mức 5-6
                # lần người dùng thường cần, để dự phòng khi thi thoảng vẫn đọc sai.
                # progress=_bao_tien_do -> báo rõ đang thử lần mấy, không "im
                # lặng" trong lúc chờ (có thể mất vài chục giây).
                ok, thong_bao, _, _ = _tu_dong_dang_nhap(
                    cid, so_lan=8, drv=_drv(), progress=_bao_tien_do)
                if not ok:
                    if thong_bao == "Công ty chưa lưu mật khẩu — không thể tự đăng nhập":
                        # Công ty KHÔNG có mật khẩu trang Thuế -> KHÔNG có gì để
                        # tra cứu qua mạng (không phải lỗi cần xử lý) -> coi như
                        # 0 hóa đơn đầu vào/đầu ra kỳ này, VẪN tự động kết xuất
                        # báo cáo (chỉ cần đúng số dư đầu kỳ) thay vì bỏ qua hẳn.
                        _xu_ly_khong_co_mat_khau(cid, item)
                        return
                    item["status"] = "skipped"
                    item["note"] = f"Tự đăng nhập thất bại: {thong_bao}"
                    _luu_loi_tra_cuu(cid, item["note"])
                    with batch_lock:
                        batch["done"] += 1
                        _batch_luu_db(batch_id, batch, body)
                    return
            item["status"] = "running"
            with batch_lock:
                _batch_luu_db(batch_id, batch, body)
            try:
                _run_fetch_job(cid, body)   # chạy đồng bộ trong thread riêng của công ty này
                last = (FETCH_JOBS.get(cid) or {}).get("last") or {}
                item["total_saved"] = last.get("total_saved", 0)
                # Số hóa đơn LẤY ĐƯỢC so với số trang Thuế BÁO (tk_..._got/exp,
                # do _run_fetch_job ghi vào msg() cuối cùng) — để báo LỆCH hay
                # không ngay trên khung tra cứu hàng loạt, không phải mở từng
                # công ty ra xem mới biết.
                mua_got, mua_exp = last.get("tk_mua_got", 0), last.get("tk_mua_exp", 0)
                ban_got, ban_exp = last.get("tk_ban_got", 0), last.get("tk_ban_exp", 0)
                item["tk_mua_got"], item["tk_mua_exp"] = mua_got, mua_exp
                item["tk_ban_got"], item["tk_ban_exp"] = ban_got, ban_exp
                item["lech"] = bool(last.get("loi_tra_cuu")
                                     or (mua_exp and mua_got < mua_exp)
                                     or (ban_exp and ban_got < ban_exp))
                # LỆCH SỐ LIỆU XML (TỔNG CỘNG BK Mua vào/Bán ra khác chỉ tiêu
                # [23][24][25]/[34][35]) — do _tu_dong_ket_xuat_bao_cao ghi
                # (msg lech_bk=True) SAU KHI đã xuất XML ở cuối lượt tra cứu,
                # nên phải quét TOÀN BỘ job["messages"] (không chỉ "last" —
                # "last" thường bị các thông báo xuất Excel/XML TNCN sau đó
                # ghi đè mất) mới không bỏ sót cảnh báo này trong batch.
                for _m in (FETCH_JOBS.get(cid) or {}).get("messages", []):
                    if _m.get("lech_bk"):
                        item["lech_bk"] = True
                        item["lech_bk_text"] = _m.get("text", "")
                    if _m.get("lech_doi_chieu"):
                        item["lech_doi_chieu"] = True
                        item["lech_doi_chieu_text"] = _m.get("text", "")
                    if _m.get("vat_phai_nop"):
                        item["vat_phai_nop"] = True
                        item["vat_phai_nop_text"] = _m.get("text", "")
                        item["vat_phai_nop_so_tien"] = _m.get("vat_phai_nop_so_tien", 0)
                if last.get("stage") == "error":
                    item["status"] = "error"
                    item["note"] = last.get("text", "Lỗi")
                else:
                    item["status"] = "done"
                    item["note"] = last.get("text", "Hoàn tất")
            except Exception as e:
                item["status"] = "error"
                item["note"] = str(e)[:160]
                _luu_loi_tra_cuu(cid, item["note"])
            with batch_lock:
                batch["done"] += 1
                # LƯU TIẾN ĐỘ sau MỖI công ty -> tắt đột ngột chỉ mất dở dang 1 cty
                _batch_luu_db(batch_id, batch, body)
        except Exception as e:
            # Lưới an toàn CUỐI CÙNG — bất kỳ lỗi bất ngờ nào (kể cả ngoài
            # phần tra cứu, vd lỗi khi tự đăng nhập) TUYỆT ĐỐI không được để
            # công ty này "kẹt" mãi ở trạng thái pending/running mà không ai
            # biết, vì batch chạy NHIỀU luồng cùng lúc nên lỗi ở đây sẽ không
            # tự nổi lên console như code chạy tuần tự trước đây.
            item["status"] = "error"
            item["note"] = str(e)[:160]
            with batch_lock:
                batch["done"] += 1
                _batch_luu_db(batch_id, batch, body)
        finally:
            with batch_lock:
                cl = batch.setdefault("current_list", [])
                if cid in cl:
                    cl.remove(cid)

    try:
        with _cf.ThreadPoolExecutor(max_workers=BATCH_SONG_SONG) as executor:
            for cid in cids:
                executor.submit(_xu_ly_1_cong_ty, cid)
            # thoát khỏi khối "with" tự động CHỜ hết mọi công ty đã nộp vào
            # hàng đợi xong (kể cả những công ty còn đang chạy lúc cancel) —
            # đúng với hành vi cũ: bấm Dừng KHÔNG ngắt ngang công ty đang chạy,
            # chỉ không bắt đầu công ty MỚI nào nữa (_xu_ly_1_cong_ty tự kiểm
            # tra cancel ngay đầu hàm với các công ty chưa kịp bắt đầu).
    finally:
        batch["running"] = False
        batch["current_list"] = []
        _dong_trinh_duyet_captcha(drv_captcha[0])
        # Còn công ty nào CHƯA xong (do người dùng bấm Dừng giữa chừng) -> đánh
        # dấu 'tam_dung' để lần sau mở khung sẽ mời TIẾP TỤC phần còn dở dang.
        # Nếu đã chạy hết vòng (tất cả công ty đều được xử lý) -> 'hoan_tat'.
        con_do_dang = any(it["status"] in ("pending", "login", "running")
                          for it in batch["items"].values())
        _batch_luu_db(batch_id, batch, body,
                      trang_thai="tam_dung" if con_do_dang else "hoan_tat")


@app.post("/api/fetch-batch")
def fetch_batch(body: dict = Body(...)):
    """Tra cứu nhiều công ty một lần.
    body: { cids: [1,2,3], tu_ngay, den_ngay, loai_list, he_thong_list,
            dl_buy, dl_sell, lay_ngan_hang }
    Trả về { batch_id }. Poll /api/fetch-batch-status/{batch_id} để theo dõi."""
    cids = body.get("cids") or []
    cids = [int(c) for c in cids]
    if not cids:
        raise HTTPException(400, "Chưa chọn công ty nào")
    # Đánh dấu để _run_fetch_job biết đây là TRA CỨU HÀNG LOẠT (không phải 1
    # công ty đơn lẻ) — quyết định có tự động kiểm tra đối chiếu/XML NGAY cả
    # khi KHÔNG tick "Lưu file kết xuất" hay không (chỉ áp dụng cho tra cứu 1
    # công ty; hàng loạt vẫn giữ đúng hành vi cũ: không tick = không xuất gì).
    body["batch"] = True

    conn = db()
    rows = conn.execute(
        "SELECT id, ten, mst FROM companies WHERE id IN (%s)"
        % ",".join("?" * len(cids)), cids).fetchall()
    conn.close()
    ten_map = {r["id"]: (r["ten"] or r["mst"]) for r in rows}
    # giữ đúng thứ tự người dùng chọn, chỉ lấy công ty có thật
    cids = [c for c in cids if c in ten_map]
    if not cids:
        raise HTTPException(404, "Không tìm thấy công ty đã chọn")

    return _khoi_dong_batch(cids, ten_map, body)


def _khoi_dong_batch(cids, ten_map, body, items_cu=None):
    """Tạo + chạy 1 batch mới. items_cu (nếu có): trạng thái cũ để GIỮ số HĐ đã
    lấy của công ty đã xong khi tiếp tục batch dở dang (chỉ chạy lại cty chưa xong)."""
    import threading
    # batch_id nối tiếp cả các batch đã lưu trong DB (tránh trùng id cũ)
    _BATCH_SEQ["n"] += 1
    batch_id = _BATCH_SEQ["n"]

    def _mk_item(c):
        it = {"cid": c, "ten": ten_map[c], "status": "pending",
              "total_saved": 0, "note": "", "lech": False,
              "tk_mua_got": 0, "tk_mua_exp": 0, "tk_ban_got": 0, "tk_ban_exp": 0,
              "lech_bk": False, "lech_bk_text": "",
              "lech_doi_chieu": False, "lech_doi_chieu_text": "",
              "vat_phai_nop": False, "vat_phai_nop_text": "", "vat_phai_nop_so_tien": 0}
        if items_cu and str(c) in items_cu and items_cu[str(c)].get("status") == "done":
            old = items_cu[str(c)]
            it.update(status="done", total_saved=old.get("total_saved", 0),
                      note=old.get("note", "Đã xong ở lần trước"),
                      lech=old.get("lech", False),
                      tk_mua_got=old.get("tk_mua_got", 0), tk_mua_exp=old.get("tk_mua_exp", 0),
                      tk_ban_got=old.get("tk_ban_got", 0), tk_ban_exp=old.get("tk_ban_exp", 0),
                      lech_bk=old.get("lech_bk", False), lech_bk_text=old.get("lech_bk_text", ""),
                      lech_doi_chieu=old.get("lech_doi_chieu", False),
                      lech_doi_chieu_text=old.get("lech_doi_chieu_text", ""),
                      vat_phai_nop=old.get("vat_phai_nop", False),
                      vat_phai_nop_text=old.get("vat_phai_nop_text", ""),
                      vat_phai_nop_so_tien=old.get("vat_phai_nop_so_tien", 0))
        return it

    items = {c: _mk_item(c) for c in cids}
    da_xong = sum(1 for it in items.values() if it["status"] == "done")
    # công ty CẦN chạy (chưa xong) — công ty đã xong thì giữ nguyên, bỏ qua
    cids_chay = [c for c in cids if items[c]["status"] != "done"]
    BATCH_JOBS[batch_id] = {
        "running": True,
        "cancel": False,
        "total": len(cids),
        "done": da_xong,
        "current_list": [],   # danh sách cid ĐANG chạy (tối đa BATCH_SONG_SONG)
        "started": time.time(),
        "order": cids,
        "items": items,
        "trang_thai": "dang_chay",
    }
    # đánh dấu MỌI batch dở dang CŨ thành 'hoan_tat' (không mời tiếp tục nữa) —
    # chỉ giữ đúng 1 batch mới nhất để tránh nhiều lời mời chồng chéo
    try:
        cn = db()
        cn.execute("UPDATE batch_tra_cuu SET trang_thai='hoan_tat' "
                   "WHERE trang_thai IN ('dang_chay','tam_dung')")
        cn.commit(); cn.close()
    except Exception:
        pass
    _batch_luu_db(batch_id, BATCH_JOBS[batch_id], body)
    threading.Thread(target=lambda: _run_batch(batch_id, cids_chay, body),
                     daemon=True).start()
    return {"ok": True, "batch_id": batch_id}


@app.get("/api/fetch-batch-do-dang")
def fetch_batch_do_dang():
    """Trả về batch tra cứu ĐANG DỞ DANG (bị tắt đột ngột / dừng giữa chừng) để
    mời người dùng TIẾP TỤC. None nếu không có."""
    try:
        cn = db()
        row = cn.execute(
            "SELECT * FROM batch_tra_cuu WHERE trang_thai IN ('dang_chay','tam_dung') "
            "ORDER BY batch_id DESC LIMIT 1").fetchone()
        cn.close()
    except Exception:
        return {"co": False}
    if not row:
        return {"co": False}
    # đang thực sự chạy trong bộ nhớ (chưa tắt) -> không phải "dở dang cần tiếp"
    mem = BATCH_JOBS.get(row["batch_id"])
    if mem and mem.get("running"):
        return {"co": False}
    try:
        items = json.loads(row["items_json"] or "{}")
        body = json.loads(row["body_json"] or "{}")
    except Exception:
        return {"co": False}
    con_lai = [it for it in items.values() if it.get("status") != "done"]
    if not con_lai:
        return {"co": False}
    return {
        "co": True,
        "batch_id": row["batch_id"],
        "total": row["total"],
        "da_xong": row["total"] - len(con_lai),
        "con_lai": len(con_lai),
        "tu_ngay": body.get("tu_ngay", ""),
        "den_ngay": body.get("den_ngay", ""),
        "ten_con_lai": [it.get("ten", "") for it in con_lai][:20],
    }


@app.post("/api/fetch-batch-tiep-tuc/{batch_id}")
def fetch_batch_tiep_tuc(batch_id: int):
    """Tiếp tục 1 batch dở dang: chỉ chạy các công ty CHƯA xong, giữ nguyên
    kết quả các công ty đã xong ở lần trước."""
    cn = db()
    row = cn.execute("SELECT * FROM batch_tra_cuu WHERE batch_id=?", (batch_id,)).fetchone()
    if not row:
        cn.close()
        raise HTTPException(404, "Không tìm thấy lượt tra cứu dở dang")
    try:
        body = json.loads(row["body_json"] or "{}")
        items = json.loads(row["items_json"] or "{}")
        order = json.loads(row["order_json"] or "[]")
    except Exception:
        cn.close()
        raise HTTPException(400, "Dữ liệu lượt tra cứu dở dang bị hỏng")
    # lấy tên công ty còn tồn tại (công ty đã xoá thì bỏ)
    order = [int(c) for c in order]
    rows = cn.execute(
        "SELECT id, ten, mst FROM companies WHERE id IN (%s)"
        % (",".join("?" * len(order)) or "NULL"), order).fetchall() if order else []
    cn.close()
    ten_map = {r["id"]: (r["ten"] or r["mst"]) for r in rows}
    order = [c for c in order if c in ten_map]
    if not order:
        raise HTTPException(404, "Các công ty của lượt tra cứu dở dang không còn tồn tại")
    return _khoi_dong_batch(order, ten_map, body, items_cu=items)


