# ============================================================
#  XUẤT KHO (form MISA "Xuất kho") — dò mã hàng từ TỒN KHO cho
#  từng dòng bán ra (Chi tiết BÁN RA), có trừ tồn tuần tự để không
#  gán quá số hàng thực còn trong kho.
#
#  Quy trình: 1) import file "Tổng hợp tồn kho" (MISA) -> Sheet TON
#             2) import file có sheet "Chi tiết BÁN RA" -> nguồn GIATHANH
#             3) dò mã tự động (đúng tên / gần đúng tên, có trừ tồn)
#             4) người dùng sửa tay các dòng chưa dò được (gợi ý mã+tên+giá)
#             5) xuất file "Xuất kho" (form MISA) từ GIATHANH đã gắn mã
# ============================================================
# điểm giống tối thiểu (0..1) để tự động gắn mã khi KHÔNG có ứng viên "mạnh"
# (trùng y hệt hoặc 1 chuỗi nằm trong chuỗi kia) — trường hợp hiếm, đòi hỏi rất giống.
_XK_NGUONG_FUZZY = 0.95

def _chuan_ten_hang_xk(s):
    """Chuẩn hoá tên hàng để so khớp: bỏ dấu, viết hoa, bỏ nội dung trong
    ngoặc (vd '(N)' — chỉ là ký hiệu phụ/nguồn hàng, không phải tên khác
    mặt hàng), rồi bỏ mọi ký tự không phải chữ/số."""
    import re as _re_xk
    s = _re_xk.sub(r'\([^)]*\)', '', _khong_dau(s).upper())
    return _re_xk.sub(r'[^A-Z0-9]', '', s)

def _diem_giong_ten_xk(a, b):
    """Điểm giống nhau 2 chuỗi ĐÃ chuẩn hoá (0..1), theo tỉ lệ ký tự khớp."""
    import difflib
    if not a or not b:
        return 0.0
    return difflib.SequenceMatcher(None, a, b).ratio()

def _manh_xk(a, b):
    """Ứng viên 'mạnh': tên ĐÃ chuẩn hoá trùng y hệt, hoặc 1 chuỗi nằm trong chuỗi kia
    (vd chỉ lệch hậu tố 'CM', dấu * hay -... — coi như CÙNG một mặt hàng).
    KHÔNG dùng cho các mặt hàng chỉ đơn thuần giống nhau về CHỮ (vd khác kích cỡ
    160/180 ở cùng 1 vị trí) — loại đó phải qua ngưỡng fuzzy riêng, chặt hơn."""
    if not a or not b:
        return False
    return a == b or a in b or b in a

def _trich_kich_thuoc_xk(ten):
    """Trích các cụm 'kích thước' dạng số/chữ ghép bằng 'x' trong tên hàng
    GỐC (vd 'D47xH50', 'L28.5xW28.5xH16', '54x54x50', 'D41xH8') -> tập hợp
    chuỗi đã chuẩn hoá (viết hoa, bỏ khoảng trắng, dấu ',' -> '.') để so
    khớp. Chạy trên tên GỐC (không qua _chuan_ten_hang_xk) vì kích thước
    thường nằm trong ngoặc (vd '(KT:D47xH50 cm)') — phần _chuan_ten_hang_xk
    CẮT BỎ để so tên chính, nên phải trích riêng trước khi cắt.

    Cùng 1 kích thước xuất hiện ở cả 2 tên là tín hiệu CHẮC CHẮN nhất để
    nhận ra đúng mặt hàng, kể cả khi phần tên chữ viết khác hẳn nhau (vd
    'Chân kê... Acacia Wooden Stand, Light brown' ở tên bán nhưng 'Chân đế'
    trong Tồn kho — chỉ trùng đúng kích thước 'L28.5xW28.5xH16')."""
    import re as _re_kt
    ra = set()
    for m in _re_kt.finditer(
            r'[A-Za-z]?\d+(?:[.,]\d+)?(?:\s*[xX]\s*[A-Za-z]?\d+(?:[.,]\d+)?){1,4}', str(ten or "")):
        tok = _re_kt.sub(r'\s+', '', m.group(0)).upper().replace(',', '.')
        if tok:
            ra.add(tok)
    return ra

def _kich_thuoc_khop_xk(a, b):
    """True nếu 2 tên hàng GỐC cùng chứa ít nhất 1 cụm kích thước giống hệt."""
    ka, kb = _trich_kich_thuoc_xk(a), _trich_kich_thuoc_xk(b)
    return bool(ka and kb and (ka & kb))

def _ma_ngoac_gop_xk(ten):
    """Gộp NGUYÊN mỗi cụm trong ngoặc đơn của tên hàng GỐC thành 1 mã liền
    (vd '(ASH50-CT)' -> 'ASH50CT', '(ASH30 - MTWT)' -> 'ASH30MTWT') — mã
    kiểu/màu ngắn (hậu tố 2 ký tự như 'CT','WT') thường nằm NGAY TRONG ngoặc
    kèm mã chính, tách rời riêng ra dễ bị loại vì quá ngắn/nhầm lẫn (khác
    _ma_trong_ngoac_tokhai — tách rời, dùng cho mô tả tờ khai hải quan nhiều
    lớp) nên ở đây GIỮ NGUYÊN VẸN cả cụm rồi so khớp liên tục."""
    import re as _re_g
    ra = set()
    for grp in _re_g.findall(r'\(([^)]*)\)', str(ten or "")):
        tok = _re_g.sub(r'[^A-Za-z0-9]', '', _khong_dau(grp).upper())
        if len(tok) >= 4:
            ra.add(tok)
    return ra

def _ma_ngoac_khop_xk(a, b):
    """True nếu tên GỐC a có 1 cụm-trong-ngoặc gộp liền (_ma_ngoac_gop_xk)
    xuất hiện làm chuỗi con LIÊN TỤC trong tên GỐC b (không phân biệt hoa/
    thường/dấu, không cần còn nguyên ngoặc ở phía b — vd 'ASH50CT' khớp cả
    khi b viết 'ASH50 - CT' không có ngoặc)."""
    ma_a = _ma_ngoac_gop_xk(a)
    if not ma_a:
        return False
    b_chuan = _chuan_ten_tokhai(b)
    return any(tok in b_chuan for tok in ma_a)

def _kd2(s):
    """_khong_dau() rồi thay nốt 'đ'->'d' (NFD không tách được chữ Đ ra dấu riêng)."""
    return _khong_dau(s).replace("đ", "d")

def _doc_file_ton_kho(wb):
    """Đọc file 'Tổng hợp tồn kho' (báo cáo MISA, tiêu đề gộp ô 2 dòng: nhóm
    Đầu kỳ/Nhập kho/Xuất kho/Cuối kỳ ở dòng trên, Số lượng/Giá trị ở dòng dưới)
    -> list {ma,ten,dvt,ton,gia}. Dò tiêu đề theo CHỮ, không phụ thuộc cột."""
    ws = wb.worksheets[0]
    hdr_row = None
    for r in range(1, min(ws.max_row, 10) + 1):
        vals = [_kd2(ws.cell(r, c).value) for c in range(1, ws.max_column + 1)]
        if any("ma hang" in v for v in vals) and any("ten hang" in v for v in vals):
            hdr_row = r
            break
    if not hdr_row:
        return []
    ncol = ws.max_column
    top = [_kd2(ws.cell(hdr_row, c).value) for c in range(1, ncol + 1)]
    sub = [_kd2(ws.cell(hdr_row + 1, c).value) for c in range(1, ncol + 1)]
    top_ff, last = [], ""
    for v in top:                 # dò xuôi qua các ô đã gộp (merge) không có giá trị
        if v:
            last = v
        top_ff.append(last)

    def find_combo(*keys):
        for i in range(ncol):
            c = f"{top_ff[i]} {sub[i]}"
            if all(k in c for k in keys):
                return i
        return -1

    i_ma = next((i for i, v in enumerate(top) if "ma hang" in v), -1)
    i_ten = next((i for i, v in enumerate(top) if "ten hang" in v), -1)
    i_dvt = next((i for i, v in enumerate(top) if v == "dvt" or "don vi tinh" in v), -1)
    i_sl = find_combo("cuoi ky", "so luong")
    i_gt = find_combo("cuoi ky", "gia tri")
    if i_ma < 0 or i_ten < 0:
        return []
    gop = {}
    for r in range(hdr_row + 2, ws.max_row + 1):
        ma = str(ws.cell(r, i_ma + 1).value or "").strip()
        if not ma:               # bỏ dòng 'Tên kho : ...' / dòng tổng
            continue
        ten = str(ws.cell(r, i_ten + 1).value or "").strip()
        dvt = str(ws.cell(r, i_dvt + 1).value or "").strip() if i_dvt >= 0 else ""
        sl = _to_num(ws.cell(r, i_sl + 1).value) if i_sl >= 0 else 0
        gt = _to_num(ws.cell(r, i_gt + 1).value) if i_gt >= 0 else 0
        sl = sl if isinstance(sl, (int, float)) else 0
        gt = gt if isinstance(gt, (int, float)) else 0
        if ma in gop:
            gop[ma]["ton"] += sl
            gop[ma]["gt"] += gt
        else:
            gop[ma] = {"ma": ma, "ten": ten, "dvt": dvt, "ton": sl, "gt": gt}
    out = []
    for it in gop.values():
        gia = round(it["gt"] / it["ton"]) if it["ton"] else 0
        out.append({"ma": it["ma"], "ten": it["ten"], "dvt": it["dvt"],
                    "ton": it["ton"], "gia": gia})
    return out

def _xk_src_cols(header):
    """Tìm cột trong sheet nguồn 'Chi tiết BÁN RA'."""
    hlow = [str(h or "").strip().lower() for h in header]
    def find(eqs, contains):
        for i, h in enumerate(hlow):
            if h in eqs:
                return i
        for i, h in enumerate(hlow):
            if any(k in h for k in contains):
                return i
        return -1
    return {
        "kh": find(("ký hiệu",), ("ký hiệu",)),
        "sohd": find(("số hđ",), ("số hđ", "số hoá đơn", "số hóa đơn")),
        "ngay": find(("ngày",), ("ngày",)),
        "ten": find(("tên hàng hóa/dịch vụ",), ("tên hàng",)),
        "dvt": find(("đvt",), ("đvt", "đơn vị tính")),
        "sl": find(("số lượng",), ("số lượng",)),
        "dgia": find(("đơn giá",), ("đơn giá",)),
        "tt": find(("thành tiền",), ("thành tiền",)),
    }

def _xk_key_ngay(ngay):
    """Khoá sắp xếp theo ngày tăng dần, nhận dd/mm/yyyy hoặc yyyy-mm-dd."""
    s = str(ngay or "").strip().replace("-", "/")
    p = s.split("/")
    if len(p) == 3:
        if len(p[0]) == 4:                       # đã là yyyy/mm/dd
            return f"{p[0]}-{p[1].zfill(2)}-{p[2].zfill(2)}"
        return f"{p[2]}-{p[1].zfill(2)}-{p[0].zfill(2)}"
    return s

def _gen_xk_giathanh(ton_rows, src_header, src_rows, hoc_ma=None, giathanh_cu=None):
    """Ghép mã hàng (từ TON) cho từng dòng bán ra (Chi tiết BÁN RA), TRỪ TỒN
    tuần tự theo ngày tăng dần — mặt hàng nào hết tồn (<=0) sẽ KHÔNG gán nữa.

    Nhiều mặt hàng trong TON có TÊN TRÙNG NHAU nhưng khác mã (vd 1 mã do phần
    mềm sinh 'HH00033-8' và 1 mã đã có sẵn trong MISA 'MH90' cho CÙNG 1 sản
    phẩm) -> tự LẤY LUÔN mã còn đủ tồn, KHÔNG hỏi lại: ưu tiên mã đã được HỌC
    (hoc_ma: tên chuẩn hoá -> mã) từ lần người dùng tự gắn trước đó nếu vẫn đủ
    tồn; nếu không, ưu tiên mã XUẤT HIỆN TRƯỚC theo đúng thứ tự trong file tồn
    kho (ton_rows) — dùng HẾT mã đứng trước rồi mới bắt đầu dùng tới mã đứng
    sau, không ưu tiên theo tồn nhiều/ít. Chỉ TÁCH DÒNG (cộng dồn nhiều mã,
    cũng theo đúng thứ tự đó) khi không mã đơn nào đủ cả số lượng cần bán.

    giathanh_cu (nếu có): GIATHANH đang có SẴN (lần dò trước / gán tay / vừa
    Import giá thành) — GIỮ NGUYÊN mã đã gán cho ĐÚNG dòng hóa đơn (khớp theo
    Số HĐ + Tên sản phẩm), trừ tồn TRƯỚC cho các dòng đó rồi mới dò tiếp phần
    còn lại — để bấm lại "Dò mã hàng tự động" KHÔNG xóa mất phần đã làm trước
    đó (đã xác nhận qua báo cáo thật: Import giá thành xong bấm Dò mã hàng tự
    động làm mất sạch các dòng vừa import, vì trước đây hàm này luôn dò lại
    TOÀN BỘ từ đầu, không biết gì tới GIATHANH đang có)."""
    col = _xk_src_cols(src_header)
    hoc_ma = hoc_ma or {}

    def gv(r, i):
        return r[i] if 0 <= i < len(r) else ""

    ton_list = [dict(it, con_lai=_to_num(it.get("ton")) or 0,
                     ten_chuan=_chuan_ten_hang_xk(it.get("ten")))
                for it in (ton_rows or [])]
    ton_by_ma = {tn["ma"]: tn for tn in ton_list}

    items = []
    for r in (src_rows or []):
        ten = str(gv(r, col["ten"]) or "").strip()
        if not ten:
            continue
        items.append({
            "khhdon": str(gv(r, col["kh"]) or ""), "sohd": str(gv(r, col["sohd"]) or ""),
            "ngay": str(gv(r, col["ngay"]) or ""), "ten_sp": ten,
            "dvt": str(gv(r, col["dvt"]) or ""), "sl": _to_num(gv(r, col["sl"])) or 0,
            "dgia": _to_num(gv(r, col["dgia"])), "tt": _to_num(gv(r, col["tt"])),
        })
    items.sort(key=lambda it: _xk_key_ngay(it["ngay"]))

    # dòng đã "khoá" bởi Import tờ khai xuất khẩu (giá vốn lấy thẳng từ tờ
    # khai hải quan thật, không liên quan Tồn kho nội bộ) -> giữ NGUYÊN vẹn,
    # không cho Dò mã hàng tự động động vào / trừ tồn đè lên, khớp theo (Số
    # HĐ, Tên chuẩn hoá) — bấm lại "Dò mã hàng tự động" không được xoá mất
    # dữ liệu đã import từ tờ khai, giống hệt cách giữ mã đã gán tay bên dưới.
    out_khoa = []
    khoa = {}
    for r in (giathanh_cu or []):
        if not r.get("khoa_tokhai"):
            continue
        key = (str(r.get("sohd") or "").strip(), _chuan_ten_hang_xk(r.get("ten_sp")))
        khoa.setdefault(key, r)
    if khoa:
        con_lai_items = []
        for it in items:
            key = (it["sohd"], _chuan_ten_hang_xk(it["ten_sp"]))
            if key in khoa:
                out_khoa.append(khoa[key])
            else:
                con_lai_items.append(it)
        items = con_lai_items

    # gom mã đã gán trước đó theo khoá (Số HĐ, Tên chuẩn hoá) — chỉ giữ dòng
    # ĐẦU TIÊN gặp mỗi khoá (dòng bị TÁCH thành nhiều mã do thiếu tồn dùng
    # chung 1 khoá, không tái tạo đúng — để dò lại bình thường an toàn hơn).
    giu_lai = {}
    for r in (giathanh_cu or []):
        ma = str(r.get("ma") or "").strip()
        if not ma:
            continue
        key = (str(r.get("sohd") or "").strip(), _chuan_ten_hang_xk(r.get("ten_sp")))
        if key in giu_lai:
            continue
        giu_lai[key] = {"ma": ma, "ten_xk": r.get("ten_xk", ""),
                        "dvt_xk": r.get("dvt_xk", ""), "gia_xk": r.get("gia_xk", "")}

    # trừ tồn TRƯỚC cho các dòng giữ được mã cũ (chỉ khi mã đó CÒN ĐỦ tồn cho
    # đúng số lượng dòng này — không đủ thì bỏ qua, để dò lại bình thường,
    # tránh âm tồn kho ngầm không cảnh báo)
    giu_assign = {}
    for it in items:
        key = (it["sohd"], _chuan_ten_hang_xk(it["ten_sp"]))
        giu = giu_lai.get(key)
        if not giu:
            continue
        tn = ton_by_ma.get(giu["ma"])
        sl_can = it["sl"] if isinstance(it["sl"], (int, float)) else 0
        if not tn or tn["con_lai"] < sl_can:
            continue
        tn["con_lai"] -= sl_can
        rec = dict(it)
        rec.update(ma=giu["ma"], ten_xk=giu["ten_xk"] or tn["ten"],
                   dvt_xk=giu["dvt_xk"] or tn["dvt"],
                   gia_xk=giu["gia_xk"] if giu["gia_xk"] not in (None, "") else tn["gia"],
                   goi_y=[], mo_ho=False, thieu_ton=False)
        giu_assign[id(it)] = rec

    def goi_y_cho(ten_chuan, manh):
        manh_ma = {tn["ma"] for tn in manh}
        scored = sorted(
            ({"ma": tn["ma"], "ten": tn["ten"], "dvt": tn["dvt"], "gia": tn["gia"],
              "con_lai": tn["con_lai"], "manh": tn["ma"] in manh_ma,
              "diem": round(_diem_giong_ten_xk(ten_chuan, tn["ten_chuan"]), 3)}
             for tn in ton_list), key=lambda x: (-x["manh"], -x["diem"]))
        return [s for s in scored[:6] if s["diem"] > 0.3 or s["manh"]]

    def dong_trong(it, sl_thieu, ten_chuan, manh):
        rec = dict(it, sl=sl_thieu)
        rec.update(ma="", ten_xk="", dvt_xk="", gia_xk="", mo_ho=True, thieu_ton=True,
                   goi_y=goi_y_cho(ten_chuan, manh))
        return rec

    out = list(out_khoa)
    for it in items:
        pre = giu_assign.get(id(it))
        if pre:
            out.append(pre)
            continue
        ten_chuan = _chuan_ten_hang_xk(it["ten_sp"])
        sl_can = it["sl"] if isinstance(it["sl"], (int, float)) else 0
        tt_goc = it.get("tt")
        candidates = [tn for tn in ton_list if tn["con_lai"] > 0]
        # cùng kích thước (vd 'D47xH50', 'L28.5xW28.5xH16') hoặc cùng mã
        # kiểu/màu trong ngoặc (vd '(ASH50-CT)' khớp 'ASH50 - CT') coi là
        # 'mạnh' như trùng tên — tín hiệu chắc chắn để nhận đúng mặt hàng dù
        # phần tên chữ viết khác hẳn nhau (xem _trich_kich_thuoc_xk /
        # _ma_ngoac_khop_xk).
        manh = [tn for tn in candidates if _manh_xk(ten_chuan, tn["ten_chuan"])
               or _kich_thuoc_khop_xk(it["ten_sp"], tn["ten"])
               or _ma_ngoac_khop_xk(it["ten_sp"], tn["ten"])]
        pool = manh
        if not pool:                                 # không có ứng viên 'mạnh' -> fuzzy chặt
            best, best_diem = None, 0.0
            for tn in candidates:
                d = _diem_giong_ten_xk(ten_chuan, tn["ten_chuan"])
                if d > best_diem:
                    best, best_diem = tn, d
            if best and best_diem >= _XK_NGUONG_FUZZY:
                pool = [best]
        if not pool:                                  # không tìm thấy tên nào khớp
            out.append(dong_trong(it, sl_can, ten_chuan, manh))
            continue
        # Nhiều mã trùng/gần trùng tên (vd 1 mã do phần mềm sinh + 1 mã cũ có sẵn
        # trong MISA cho cùng sản phẩm) -> LẤY LUÔN mã còn đủ tồn cho số lượng
        # bán, KHÔNG hỏi lại — ưu tiên mã đã HỌC trước đó nếu vẫn đủ tồn, rồi đến
        # mã XUẤT HIỆN TRƯỚC theo đúng thứ tự trong file tồn kho (pool đã giữ
        # nguyên thứ tự đó) — dùng HẾT mã đứng trước rồi mới chuyển sang mã
        # đứng sau, không ưu tiên theo tồn nhiều/ít.
        ma_hoc = hoc_ma.get(ten_chuan)
        pick = next((tn for tn in pool if tn["ma"] == ma_hoc and tn["con_lai"] >= sl_can), None)
        if not pick:
            pick = next((tn for tn in pool if tn["con_lai"] >= sl_can), None)
        if pick:
            pick["con_lai"] -= sl_can
            rec = dict(it)
            rec.update(ma=pick["ma"], ten_xk=pick["ten"], dvt_xk=pick["dvt"],
                       gia_xk=pick["gia"], goi_y=[], mo_ho=False, thieu_ton=False)
            out.append(rec)
            continue
        # KHÔNG mã đơn nào đủ cả số lượng -> TÁCH DÒNG: cộng dồn nhiều mã lại,
        # LẤY THEO ĐÚNG THỨ TỰ xuất hiện trong file tồn kho (dùng hết mã đứng
        # trước mới lấy tới mã đứng sau) cho đến khi đủ số lượng bán; phần còn
        # thiếu (nếu tổng tồn cả nhóm vẫn không đủ) tách thành 1 dòng riêng để
        # trống, kèm gợi ý, cho người dùng tự gắn mã khác.
        can_lay = sl_can
        da_dung_tien = 0
        for tn in pool:
            if can_lay <= 0 or tn["con_lai"] <= 0:
                continue
            lay = min(tn["con_lai"], can_lay)
            tn["con_lai"] -= lay
            can_lay -= lay
            if isinstance(tt_goc, (int, float)) and sl_can:
                tt_phan = round(tt_goc - da_dung_tien) if can_lay <= 0 else round(tt_goc * lay / sl_can)
            else:
                tt_phan = tt_goc
            da_dung_tien += tt_phan if isinstance(tt_phan, (int, float)) else 0
            rec = dict(it, sl=lay, tt=tt_phan)
            rec.update(ma=tn["ma"], ten_xk=tn["ten"], dvt_xk=tn["dvt"], gia_xk=tn["gia"],
                       goi_y=[], mo_ho=False, thieu_ton=False)
            out.append(rec)
        if can_lay > 0:                                # vẫn còn thiếu sau khi gộp cả nhóm
            tt_thieu = round(tt_goc - da_dung_tien) if isinstance(tt_goc, (int, float)) else tt_goc
            rec = dict(it, sl=can_lay, tt=tt_thieu)
            rec.update(ma="", ten_xk="", dvt_xk="", gia_xk="", mo_ho=True, thieu_ton=True,
                       goi_y=goi_y_cho(ten_chuan, manh))
            out.append(rec)
    return out

def _xk_hop_nhat_giathanh(ton_rows, ctbr_header, ctbr_rows, hoc_ma, giathanh_cu,
                          giu_ngoai_ctbr=True):
    """Chạy _gen_xk_giathanh() rồi (nếu giu_ngoai_ctbr) CỘNG THÊM nguyên vẹn
    các dòng trong giathanh_cu KHÔNG khớp bất kỳ dòng nào trong 'Chi tiết BÁN
    RA' (ctbr) hiện có (theo khoá Số HĐ + Tên sản phẩm). _gen_xk_giathanh()
    CHỈ dựng danh sách dòng từ ctbr — nếu giathanh_cu (từ lần dò trước/gán
    tay/Import giá thành) có dòng KHÔNG khớp ctbr hiện tại thì dòng đó sẽ bị
    RỚT MẤT hoàn toàn nếu chỉ dùng thẳng kết quả _gen_xk_giathanh().

    giu_ngoai_ctbr=True (dùng cho "Import giá thành"): đã xác nhận qua báo
    cáo thật — file Import giá thành 558 dòng, ctbr chỉ còn 224 dòng, kết quả
    cuối chỉ còn 230 dòng (mất 328 dòng có thật) nếu KHÔNG giữ — cần giữ vì
    file giá thành người dùng tự chuẩn bị có thể có dòng KHÔNG khớp ctbr do
    sai khác định dạng, vẫn là dữ liệu THẬT của họ.

    giu_ngoai_ctbr=False (dùng cho "Dò mã hàng tự động"): KHÔNG giữ — nếu
    giữ, mỗi lần import 1 KỲ MỚI (vd chỉ có dữ liệu tháng 8) thì giathanh_cu
    của KỲ TRƯỚC (tháng 7, không khớp ctbr tháng 8 hiện tại) vẫn bị cộng dồn
    mãi vào GIÁTHÀNH, hiện lẫn cả 2 tháng dù người dùng chỉ import 1 tháng —
    đã xác nhận qua báo cáo thật. "Dò mã hàng tự động" phải phản ánh ĐÚNG
    TRỌN VẸN dữ liệu Nhập Liệu ĐANG import (đúng bằng ctbr hiện tại), không
    tự cộng dồn dữ liệu KỲ CŨ không còn liên quan."""
    ket_qua = _gen_xk_giathanh(ton_rows, ctbr_header, ctbr_rows, hoc_ma, giathanh_cu)
    if not giu_ngoai_ctbr:
        return ket_qua
    col_ctbr = _xk_src_cols(ctbr_header or [])

    def gv(r, i):
        return r[i] if 0 <= i < len(r) else ""

    key_ctbr = set()
    for r in (ctbr_rows or []):
        ten = str(gv(r, col_ctbr["ten"]) or "").strip()
        if not ten:
            continue
        key_ctbr.add((str(gv(r, col_ctbr["sohd"]) or "").strip(), _chuan_ten_hang_xk(ten)))
    them_ngoai_ctbr = [r for r in (giathanh_cu or [])
                      if (str(r.get("sohd") or "").strip(),
                          _chuan_ten_hang_xk(r.get("ten_sp"))) not in key_ctbr]
    return ket_qua + them_ngoai_ctbr

def _vn_so_hq(v):
    """Số kiểu VNĐ trên tờ khai hải quan ('4.380.936', '292.062,4', '11,2') ->
    số thực; '' / '-' / rỗng -> ''."""
    s = str(v if v is not None else "").strip()
    if not s or s == "-":
        return ""
    s = s.replace(" ", "").replace(".", "").replace(",", ".")
    try:
        f = float(s)
        return int(f) if f == int(f) else f
    except Exception:
        return ""

def _rut_gon_mota_tokhai(s):
    """Cắt phần đặc tả sau dấu phẩy đầu tiên (kích thước/xuất xứ/tình trạng...)
    trong mô tả hàng hoá của tờ khai hải quan, chỉ giữ TÊN HÀNG cốt lõi trước
    đó, để so khớp với Tên Sản Phẩm nội bộ (cách viết khác mô tả đầy đủ trên
    tờ khai) chính xác hơn."""
    return str(s or "").split(",")[0].strip()

def _chuan_ten_tokhai(s):
    """Chuẩn hoá tên hàng để so khớp tờ khai xuất khẩu <-> Tên Sản Phẩm nội
    bộ: bỏ dấu, viết hoa, bỏ ký tự không phải chữ/số — KHÔNG bỏ nội dung
    trong ngoặc như _chuan_ten_hang_xk (mô tả HQ đặt mã kiểu/màu/size NGAY
    TRONG ngoặc, vd '(ASH30 - MTWT)' — đây lại là phần PHÂN BIỆT quan trọng
    nhất giữa các dòng hàng gần giống nhau, bỏ đi sẽ mất khả năng phân biệt)."""
    import re as _re_tk
    return _re_tk.sub(r'[^A-Z0-9]', '', _khong_dau(s).upper())

def _ma_trong_ngoac_tokhai(mo_ta):
    """Trích các 'mã' ngắn (>=3 ký tự) trong ngoặc đơn của mô tả hàng hoá tờ
    khai HQ (vd '(ASH30 - MTWT)' -> ['ASH30','MTWT']) — thường là mã kiểu/
    màu/size dùng phân biệt các dòng hàng gần giống nhau, hay được công ty
    dùng lại (dù viết khác cách) trong Tên Sản Phẩm nội bộ."""
    import re as _re_tk
    ra = []
    for grp in _re_tk.findall(r'\(([^)]*)\)', str(mo_ta or "")):
        for tok in _re_tk.split(r'[^A-Za-z0-9]+', grp):
            tok = tok.strip().upper()
            if len(tok) >= 3:
                ra.append(tok)
    return ra

def _doc_to_khai_xuat_khau(content):
    """Đọc file 'Tờ khai hàng hoá xuất khẩu (thông quan)' (.xls xuất từ
    VNACCS/ECUS — nhiều trang in, mỗi dòng hàng là 1 khối lặp đánh dấu bằng ô
    '<01>','<02>'... ở cột thứ 3 của sheet 'TKX') -> {so_to_khai, so_hoa_don,
    ngay_dang_ky, hang:[{ten,dvt,sl,gia_vnd,tt_vnd}]}. LẤY GIÁ TRỊ VNĐ (Đơn
    giá/Trị giá TÍNH THUẾ (S)) — không lấy Trị giá/Đơn giá hoá đơn bằng USD
    trên tờ khai, theo đúng yêu cầu chỉ lấy thông tin Việt Nam đồng."""
    import xlrd, re as _re_hq
    book = xlrd.open_workbook(file_contents=content)
    ten_sheet = "TKX" if "TKX" in book.sheet_names() else book.sheet_names()[0]
    sh = book.sheet_by_name(ten_sheet)

    def cell(r, c):
        return sh.cell_value(r, c) if 0 <= r < sh.nrows and 0 <= c < sh.ncols else ""

    def timo_nhan(r_tu, r_den, nhan):
        """Tìm dòng có 1 ô == nhan trong [r_tu, r_den), trả (giá trị ô KHÔNG
        RỖNG đầu tiên sau đó trên cùng dòng, chỉ-số-dòng)."""
        for r in range(r_tu, min(r_den, sh.nrows)):
            for c in range(sh.ncols):
                if str(cell(r, c)).strip() == nhan:
                    for c2 in range(c + 1, sh.ncols):
                        v = cell(r, c2)
                        if v not in ("", None):
                            return v, r
                    return None, r
        return None, None

    so_to_khai, _ = timo_nhan(0, 80, "Số tờ khai")
    if isinstance(so_to_khai, float) and so_to_khai == int(so_to_khai):
        so_to_khai = int(so_to_khai)
    so_hoa_don = ""
    for r in range(0, min(sh.nrows, 80)):
        for c in range(sh.ncols):
            if str(cell(r, c)).strip() == "Số hóa đơn":
                rest = [str(cell(r, c2)).strip() for c2 in range(c + 1, sh.ncols)
                        if cell(r, c2) not in ("", None, "-")]
                so_hoa_don = "-".join(rest)
                break
        if so_hoa_don:
            break
    ngay_dang_ky, _ = timo_nhan(0, 80, "Ngày đăng ký")
    ngay_dang_ky = str(ngay_dang_ky or "").strip().split(" ")[0]

    markers = [r for r in range(sh.nrows)
               if isinstance(cell(r, 2), str) and _re_hq.match(r"^<\d+>$", str(cell(r, 2)).strip())]
    hang = []
    for i, m in enumerate(markers):
        m_den = markers[i + 1] if i + 1 < len(markers) else sh.nrows
        ten, _ = timo_nhan(m, m_den, "Mô tả hàng hóa")
        if not ten:
            continue
        sl, r_sl = timo_nhan(m, m_den, "Số lượng (1)")
        dvt = ""
        if r_sl is not None:
            vals_dong = [cell(r_sl, c) for c in range(sh.ncols) if cell(r_sl, c) not in ("", None)]
            if vals_dong:
                dvt = str(vals_dong[-1]).strip()
        gia_vnd, _ = timo_nhan(m, m_den, "Đơn giá tính thuế")
        tt_vnd, _ = timo_nhan(m, m_den, "Trị giá tính thuế (S)")
        hang.append({"ten": str(ten).strip(), "dvt": dvt,
                    "sl": _vn_so_hq(sl), "gia_vnd": _vn_so_hq(gia_vnd), "tt_vnd": _vn_so_hq(tt_vnd)})
    return {"so_to_khai": str(so_to_khai or "").strip(), "so_hoa_don": so_hoa_don,
            "ngay_dang_ky": ngay_dang_ky, "hang": hang}

_XK_NGUONG_FUZZY_TOKHAI = 0.5

def _xk_da_ghi_xuat(r):
    """Dòng GIATHANH đã có dữ liệu xuất kho (mã hàng HOẶC giá vốn/SL kho đã
    gán) hay chưa — dùng để KHÔNG GHI ĐÈ khi Import tờ khai xuất khẩu, theo
    đúng yêu cầu chỉ xử lý dòng chưa có dữ liệu."""
    return bool(str(r.get("ma") or "").strip()) or \
        r.get("gia_xk") not in (None, "") or r.get("sl_kho") not in (None, "")

def _xk_ghep_to_khai_xuat_khau(giathanh_rows, hang_list, so_hoa_don, so_to_khai="", ngay_dang_ky=""):
    """Ghép từng dòng hàng của tờ khai xuất khẩu (Tên hàng/ĐVT/Số lượng/Đơn
    giá VNĐ) vào ĐÚNG 1 dòng GIATHANH (Xuất Kho) theo tên gần giống nhất
    (chuẩn hoá + tính điểm giống, dùng lại logic của Dò mã hàng tự động,
    nhưng ngưỡng lỏng hơn — mô tả trên tờ khai hải quan viết đầy đủ/khác cách
    công ty đặt Tên Sản Phẩm nội bộ). CHỈ điền vào dòng CHƯA có dữ liệu xuất
    kho (_xk_da_ghi_xuat==False) — dòng đã có bỏ qua, không ghi đè (KHÔNG đụng
    tới Số HĐ/Ngày/Đơn giá/Thành tiền BÁN của dòng đã có, đó là dữ liệu hoá
    đơn bán thật). so_hoa_don (số hoá đơn thương mại trên tờ khai) chỉ dùng để
    THU HẸP phạm vi so khớp — nếu khớp với 'Số HĐ' đang có sẵn trong GIATHANH
    thì ưu tiên so khớp trong phạm vi các dòng cùng hoá đơn đó trước.

    Dòng hàng nào KHÔNG khớp được dòng GIATHANH nào (kể cả khi GIATHANH đang
    RỖNG — cho phép import tờ khai xuất khẩu TRƯỚC, chưa cần Dò mã hàng tự
    động/Import giá thành trước như trước đây) -> TỰ TẠO 1 dòng MỚI thẳng từ
    dữ liệu tờ khai (mutate giathanh_rows ngay tại chỗ, người gọi tự lưu lại):
    Số HĐ = Số tờ khai, Ngày = Ngày đăng ký (ngày tờ khai), Đơn giá = Đơn giá
    tính thuế, Thành tiền = Trị giá tính thuế (S) — theo đúng yêu cầu.

    Đánh dấu dòng vừa gán/tạo bằng khoa_tokhai=True để 'Dò mã hàng tự động'
    sau này không đụng vào (xem _gen_xk_giathanh)."""
    so_hd_chuan = str(so_hoa_don or "").strip().upper()
    theo_hd = [r for r in giathanh_rows
              if so_hd_chuan and so_hd_chuan in str(r.get("sohd") or "").strip().upper()]
    pham_vi = theo_hd or giathanh_rows

    da_dung = set()
    ket = []
    for h in hang_list:
        ten_chuan = _chuan_ten_tokhai(_rut_gon_mota_tokhai(h["ten"]))
        ma_tokens = _ma_trong_ngoac_tokhai(h["ten"])
        best, best_diem = None, 0.0
        for r in pham_vi:
            if id(r) in da_dung or _xk_da_ghi_xuat(r):
                continue
            ten_r_chuan = _chuan_ten_tokhai(r.get("ten_sp"))
            diem = _diem_giong_ten_xk(ten_chuan, ten_r_chuan)
            if _manh_xk(ten_chuan, ten_r_chuan):
                diem += 1.0
            # mã kiểu/màu/size trong ngoặc ('ASH30','MTWT'...) khớp NGUYÊN
            # VẸN trong tên nội bộ -> tín hiệu phân biệt mạnh nhất giữa các
            # dòng hàng gần giống nhau (khác đúng màu/size), ưu tiên tuyệt đối.
            if ma_tokens and all(tok in ten_r_chuan for tok in ma_tokens):
                diem += 2.0
            if diem > best_diem:
                best, best_diem = r, diem
        if best and best_diem >= _XK_NGUONG_FUZZY_TOKHAI:
            best["ten_xk"] = h["ten"]
            best["dvt_xk"] = h["dvt"]
            best["sl_kho"] = h["sl"]
            best["gia_xk"] = h["gia_vnd"]
            best["khoa_tokhai"] = True
            da_dung.add(id(best))
            ket.append({"ten": h["ten"], "sohd": best.get("sohd", ""), "trang_thai": "đã gắn"})
        else:
            moi = {"khhdon": "", "sohd": so_to_khai or "", "ngay": ngay_dang_ky,
                  "ten_sp": h["ten"], "dvt": h["dvt"], "sl": h["sl"],
                  "dgia": h["gia_vnd"], "tt": h["tt_vnd"],
                  "ma": "", "ten_xk": h["ten"], "dvt_xk": h["dvt"],
                  "sl_kho": h["sl"], "gia_xk": h["gia_vnd"], "khoa_tokhai": True}
            giathanh_rows.append(moi)
            da_dung.add(id(moi))
            ket.append({"ten": h["ten"], "sohd": so_to_khai or "", "trang_thai": "dòng mới (tạo từ tờ khai)"})
    return ket

XK_GIATHANH_XUAT_HEADERS = ["Tồn kho", "Số HĐ", "Ngày", "Tên Sản Phẩm", "ĐVT", "Số lượng",
    "Đơn giá", "Thành tiền", "Mã hàng kho", "Tên hàng xuất kho", "ĐVT kho", "SL kho",
    "Đơn Giá kho", "Thành Tiền kho", "Lợi nhuận", "Tỷ lệ % Lãi/Lỗ"]

def _gen_giathanh_export_rows(ton_rows, giathanh_rows):
    """Mirror hệt các cột hiển thị trên lưới màn hình Xuất Kho (giống hàm
    xkRowsToNl ở JS): Tồn kho CHẠY DẦN theo mã (trừ dần từ trên xuống), SL/Đơn
    giá kho fallback về SL/-- bán khi dòng chưa gắn mã, Lợi nhuận = Thành
    tiền BÁN - Thành Tiền kho (giá vốn) và Tỷ lệ % lãi/lỗ tính trên Thành
    tiền BÁN — để file xuất khớp đúng những gì người dùng thấy trên màn
    hình."""
    ton_map = {str(t.get("ma") or "").strip(): _to_num(t.get("ton")) or 0 for t in (ton_rows or [])}
    da_dung = {}
    out = []
    for r in (giathanh_rows or []):
        sl_kho = r.get("sl_kho")
        if sl_kho in (None, ""):
            sl_kho = r.get("sl")
        gia_xk = r.get("gia_xk")
        sl_n, gia_n = _to_num(sl_kho), _to_num(gia_xk)
        tt_kho = round(sl_n * gia_n) if isinstance(sl_n, (int, float)) and isinstance(gia_n, (int, float)) else ""
        ma = str(r.get("ma") or "").strip()
        ton = ""
        if ma and ma in ton_map:
            sl_ban = _to_num(r.get("sl"))
            da_dung[ma] = da_dung.get(ma, 0) + (sl_ban if isinstance(sl_ban, (int, float)) else 0)
            ton = ton_map[ma] - da_dung[ma]
        ban_n = _to_num(r.get("tt"))
        loi_nhuan, ty_le = "", ""
        if isinstance(ban_n, (int, float)) and tt_kho != "":
            loi_nhuan = round(ban_n - tt_kho)
            ty_le = f"{(loi_nhuan / ban_n * 100):.1f}%" if ban_n else ""
        out.append([ton, r.get("sohd", ""), r.get("ngay", ""), r.get("ten_sp", ""), r.get("dvt", ""),
                    r.get("sl", ""), r.get("dgia", ""), r.get("tt", ""),
                    ma, r.get("ten_xk", ""), r.get("dvt_xk", ""), sl_kho, gia_xk, tt_kho,
                    loi_nhuan, ty_le])
    return out

def _xk_gan_ma_truc_tiep(ton_rows, giathanh_cu, hoc_ma=None):
    """Dò mã hàng tự động TRỰC TIẾP trên GIATHANH đang có sẵn (khớp tên với
    Tồn kho, trừ tồn tuần tự), dùng khi CHƯA có 'Chi tiết BÁN RA' nhưng
    GIATHANH đã có dữ liệu từ nguồn khác (vd Import tờ khai xuất khẩu) —
    không bắt buộc phải có Chi tiết BÁN RA mới dò mã được, cứ có dữ liệu
    trong phần mềm là xử lý.

    CHỈ gán thêm Mã hàng kho cho dòng CHƯA có mã — KHÔNG đụng tới Tên/ĐVT/
    Đơn giá kho nếu dòng đó ĐÃ CÓ SẴN (vd giá vốn thật lấy từ tờ khai xuất
    khẩu), chỉ điền thêm khi các ô đó đang trống. KHÔNG BAO GIỜ gán mã khiến
    tồn kho âm — dòng không tìm được tên khớp HOẶC không mã nào còn đủ tồn
    thì để trống Mã hàng kho (giữ đơn giản, không tách dòng phức tạp như dò
    mã từ Chi tiết BÁN RA)."""
    hoc_ma = hoc_ma or {}
    ton_list = [dict(it, con_lai=_to_num(it.get("ton")) or 0,
                     ten_chuan=_chuan_ten_hang_xk(it.get("ten")))
                for it in (ton_rows or [])]
    ton_by_ma = {tn["ma"]: tn for tn in ton_list}
    # Trừ tồn TRƯỚC cho các dòng ĐÃ CÓ mã (từ lần dò/gán trước đó, có thể
    # thuộc NHIỀU đợt Import tờ khai xuất khẩu khác nhau) — nếu không, mỗi
    # lần bấm lại "Dò mã hàng tự động" đều tính lại từ tồn GỐC, không biết gì
    # về phần đã dùng ở các lần trước -> gán CHỒNG lặp lại, ra tồn kho ÂM
    # (đã xác nhận qua báo cáo thật, mã bị gán vượt tồn nhiều lần liên tiếp).
    for r in giathanh_cu:
        ma = str(r.get("ma") or "").strip()
        tn = ton_by_ma.get(ma) if ma else None
        if not tn:
            continue
        sl_kho = r.get("sl_kho") if r.get("sl_kho") not in (None, "") else r.get("sl")
        sl_da_dung = _to_num(sl_kho)
        tn["con_lai"] -= sl_da_dung if isinstance(sl_da_dung, (int, float)) else 0
    out = []
    for r in giathanh_cu:
        if str(r.get("ma") or "").strip():
            out.append(r)
            continue
        ten_chuan = _chuan_ten_hang_xk(r.get("ten_sp"))
        sl_kho = r.get("sl_kho") if r.get("sl_kho") not in (None, "") else r.get("sl")
        sl_can = _to_num(sl_kho)
        sl_can = sl_can if isinstance(sl_can, (int, float)) else 0
        candidates = [tn for tn in ton_list if tn["con_lai"] > 0] or ton_list
        # cùng kích thước hoặc cùng mã kiểu/màu trong ngoặc coi là 'mạnh' như
        # trùng tên — xem _trich_kich_thuoc_xk / _ma_ngoac_khop_xk.
        manh = [tn for tn in candidates if _manh_xk(ten_chuan, tn["ten_chuan"])
               or _kich_thuoc_khop_xk(r.get("ten_sp"), tn["ten"])
               or _ma_ngoac_khop_xk(r.get("ten_sp"), tn["ten"])]
        pool = manh
        if not pool:
            best, best_diem = None, 0.0
            for tn in candidates:
                d = _diem_giong_ten_xk(ten_chuan, tn["ten_chuan"])
                if d > best_diem:
                    best, best_diem = tn, d
            if best and best_diem >= _XK_NGUONG_FUZZY:
                pool = [best]
        if not pool:
            out.append(r)
            continue
        ma_hoc = hoc_ma.get(ten_chuan)
        pick = next((tn for tn in pool if tn["ma"] == ma_hoc and tn["con_lai"] >= sl_can), None)
        if not pick:
            pick = next((tn for tn in pool if tn["con_lai"] >= sl_can), None)
        if not pick:
            # KHÔNG mã nào còn đủ tồn -> để trống, KHÔNG ép gán ra tồn kho âm.
            out.append(r)
            continue
        pick["con_lai"] -= sl_can
        rec = dict(r, ma=pick["ma"])
        if not str(rec.get("ten_xk") or "").strip():
            rec["ten_xk"] = pick["ten"]
        if not str(rec.get("dvt_xk") or "").strip():
            rec["dvt_xk"] = pick["dvt"]
        if rec.get("gia_xk") in (None, ""):
            rec["gia_xk"] = pick["gia"]
        out.append(rec)
    return out

def _xk_cuoi_thang(ngay):
    """'dd/mm/yyyy' của NGÀY CUỐI THÁNG chứa ngày truyền vào (dd/mm/yyyy hoặc yyyy-mm-dd)."""
    import calendar
    s = str(ngay or "").strip()
    d = m = y = None
    if "/" in s:
        p = s.split("/")
        if len(p) == 3:
            d, m, y = p
    elif "-" in s:
        p = s.split("-")
        if len(p) == 3:
            (y, m, d) = p if len(p[0]) == 4 else (p[2], p[1], p[0])
    if not (m and y):
        return "", "", ""
    try:
        mi, yi = int(m), int(y)
    except Exception:
        return "", "", ""
    last_day = calendar.monthrange(yi, mi)[1]
    return f"{last_day:02d}/{mi:02d}/{yi}", str(mi), str(yi)

XUAT_KHO_HEADERS = [
    "Hiển thị trên sổ", "Loại xuất kho", "Ngày hạch toán (*)", "Ngày chứng từ (*)",
    "Số chứng từ (*)", "Mẫu số HĐ", "Ký hiệu HĐ", "Mã đối tượng", "Tên đối tượng",
    "Địa chỉ/Bộ phận", "Tên người nhận/Của", "Lý do xuất/Về việc", "Nhân viên bán hàng",
    "Kèm theo", "Số lệnh điều động", "Ngày lệnh điều động", "Người vận chuyển",
    "Tên người vận chuyển", "Hợp đồng số", "Phương tiện vận chuyển", "Xuất tại kho",
    "Địa chỉ kho xuất", "Nhập tại chi nhánh", "Tên chi nhánh", "MST chi nhánh",
    "Nhập tại kho", "Địa chỉ kho nhập", "Mã hàng (*)", "Tên hàng", "Là hàng khuyến mại",
    "Kho (*)", "Hàng hóa giữ hộ/bán hộ", "TK Nợ (*)", "TK Có (*)", "ĐVT", "Số lượng",
    "Đơn giá bán", "Thành tiền", "Đơn giá vốn", "Tiền vốn", "Số lô", "Hạn sử dụng",
    "Đối tượng", "Khoản mục CP", "Đơn vị", "Đối tượng THCP", "Công trình",
    "Đơn đặt hàng", "Hợp đồng bán", "CP không hợp lý", "Mã thống kê"]

def _xk_kiem_tra_vuot_ton(ton_rows, giathanh_rows):
    """Kiểm tra tổng SL kho đã gán cho mỗi Mã hàng kho (cộng dồn TẤT CẢ dòng
    trong giathanh_rows, không phân biệt dòng nào tách/dòng nào gán tay) có
    VƯỢT tồn kho thật (Sheet TON) hay không -> trả về list các mã bị vượt
    kèm số đã gán/tồn thật/vượt bao nhiêu, sắp xếp vượt nhiều nhất lên đầu.
    Dùng để CHẶN xuất file 'Xuất kho' khi dữ liệu chưa hợp lệ — đã xảy ra
    thật: MISA từ chối ghi sổ NGUYÊN CẢ chứng từ vì chỉ 1 vài mã bị gán vượt
    tồn (dữ liệu gán mã có thể đã bị vượt từ nhiều đợt Import tờ khai xuất
    khẩu/Dò mã hàng tự động/gán tay khác nhau CỘNG DỒN LẠI, dù mỗi thao tác
    lúc gán tưởng như hợp lệ riêng lẻ)."""
    ton_map = {str(t.get("ma") or "").strip(): _to_num(t.get("ton")) or 0 for t in (ton_rows or [])}
    da_dung = {}
    for r in (giathanh_rows or []):
        ma = str(r.get("ma") or "").strip()
        if not ma:
            continue
        sl_kho = r.get("sl_kho") if r.get("sl_kho") not in (None, "") else r.get("sl")
        sl_n = _to_num(sl_kho)
        da_dung[ma] = da_dung.get(ma, 0) + (sl_n if isinstance(sl_n, (int, float)) else 0)
    vuot = []
    for ma, dung in da_dung.items():
        if ma not in ton_map:
            continue
        ton = ton_map[ma]
        if dung > ton:
            vuot.append({"ma": ma, "da_gan": dung, "ton": ton, "vuot": round(dung - ton, 3)})
    vuot.sort(key=lambda x: -x["vuot"])
    return vuot

def _gen_xuat_kho_rows(giathanh_rows):
    """Từ các dòng GIATHANH đã gắn mã (bỏ dòng chưa gắn) -> mảng dòng form MISA
    'Xuất kho'. Ngày hạch toán/chứng từ = CUỐI THÁNG của hoá đơn cuối cùng (mới
    nhất) trong lô; Số chứng từ = 'XK T{tháng}/{năm}' theo tháng đó."""
    rows = [r for r in (giathanh_rows or []) if str(r.get("ma") or "").strip()]
    if not rows:
        return [], ""
    ngay_cuoi = max(rows, key=lambda r: _xk_key_ngay(r.get("ngay")))["ngay"]
    ngay_ht, thang, nam = _xk_cuoi_thang(ngay_cuoi)
    so_ct = f"XK T{thang}/{nam}"
    out = []
    for r in rows:
        row = [""] * len(XUAT_KHO_HEADERS)
        row[0] = 0
        row[2] = ngay_ht; row[3] = ngay_ht; row[4] = so_ct
        row[27] = r.get("ma", "")                 # AB Mã hàng
        row[28] = r.get("ten_xk") or r.get("ten_sp", "")   # AC Tên hàng
        row[30] = "HH"                             # AE Kho
        row[32] = "632"; row[33] = "1561"          # AG Nợ / AH Có
        row[34] = r.get("dvt_xk") or r.get("dvt", "")      # AI ĐVT
        sl_kho = r.get("sl_kho")
        row[35] = sl_kho if sl_kho not in (None, "", 0) else r.get("sl", "")  # AJ Số lượng
        out.append(row)
    return out, so_ct

@app.post("/api/xk/import-ton/{cid}")
async def xk_import_ton(cid: int, request: Request):
    """Import file 'Tổng hợp tồn kho' (báo cáo MISA) -> lưu làm Sheet TON."""
    import openpyxl, io as _io
    form = await request.form()
    files = form.getlist("files") or ([form.get("file")] if form.get("file") else [])
    if not files:
        raise HTTPException(400, "Chưa chọn file")
    gop = {}
    so_file_ok, loi = 0, []
    for up in files:
        if up is None:
            continue
        fn = getattr(up, "filename", "file")
        try:
            content = await up.read()
            wb = openpyxl.load_workbook(_io.BytesIO(content), data_only=True)
        except Exception as e:
            loi.append(f"{fn}: không đọc được ({e})"); continue
        rows = _doc_file_ton_kho(wb)
        if not rows:
            loi.append(f"{fn}: không thấy cột 'Mã hàng'/'Tên hàng' (không đúng mẫu 'Tổng hợp tồn kho')")
            continue
        for it in rows:
            gop[it["ma"]] = it            # file sau đè file trước (mới nhất thắng)
        so_file_ok += 1
    if not gop:
        raise HTTPException(400, "Không đọc được dữ liệu tồn kho từ file đã chọn. " + "; ".join(loi[:3]))
    ton_rows = list(gop.values())
    data = _doc_du_lieu_cty(cid)
    data["xk_ton"] = ton_rows
    _ghi_du_lieu_cty(cid, data)
    return {"ok": True, "so_file": so_file_ok, "so_dong": len(ton_rows), "loi": loi[:5]}

@app.post("/api/xk/import-tokhai-xuatkhau/{cid}")
async def xk_import_tokhai_xuatkhau(cid: int, request: Request):
    """Import 1 hoặc nhiều file 'Tờ khai hàng hoá xuất khẩu (thông quan)' (.xls
    từ VNACCS/ECUS) -> lấy Tên hàng/ĐVT/Số lượng/Đơn giá (VNĐ THẬT theo tờ
    khai hải quan, không phải giá vốn ước tính từ Tồn kho) của từng dòng hàng,
    ghép vào ĐÚNG dòng GIATHANH (Xuất Kho) đang có theo tên gần giống nhất —
    dòng nào không khớp được (kể cả khi GIATHANH đang RỖNG, import tờ khai
    xuất khẩu TRƯỚC khi 'Dò mã hàng tự động'/Import giá thành cũng được) thì
    TỰ TẠO dòng mới thẳng từ tờ khai. CHỈ điền vào dòng CHƯA có dữ liệu xuất
    kho (chưa gán mã/giá vốn/SL kho) — dòng đã có SẴN dữ liệu trước đó thì BỎ
    QUA, không ghi đè, theo đúng yêu cầu."""
    form = await request.form()
    files = form.getlist("files") or ([form.get("file")] if form.get("file") else [])
    if not files:
        raise HTTPException(400, "Chưa chọn file")
    data = _doc_du_lieu_cty(cid)
    giathanh = data.get("xk_giathanh") or []
    chi_tiet, loi, tong_hang = [], [], 0
    for up in files:
        if up is None:
            continue
        fn = getattr(up, "filename", "file")
        try:
            content = await up.read()
            tk = _doc_to_khai_xuat_khau(content)
        except Exception as e:
            loi.append(f"{fn}: không đọc được ({e})"); continue
        if not tk["hang"]:
            loi.append(f"{fn}: không thấy dòng hàng nào (không đúng mẫu 'Tờ khai hàng hoá xuất khẩu')")
            continue
        tong_hang += len(tk["hang"])
        chi_tiet.extend(_xk_ghep_to_khai_xuat_khau(giathanh, tk["hang"], tk.get("so_hoa_don"),
                                                    tk.get("so_to_khai", ""), tk.get("ngay_dang_ky", "")))
    if tong_hang == 0:
        raise HTTPException(400, "Không đọc được dữ liệu từ file đã chọn. " + "; ".join(loi[:3]))
    data["xk_giathanh"] = giathanh
    _ghi_du_lieu_cty(cid, data)
    so_gan = sum(1 for k in chi_tiet if k["trang_thai"] == "đã gắn")
    so_moi = sum(1 for k in chi_tiet if k["trang_thai"] == "dòng mới (tạo từ tờ khai)")
    return {"ok": True, "so_dong_to_khai": tong_hang, "so_gan": so_gan, "so_moi": so_moi,
            "chi_tiet": chi_tiet[:80], "loi": loi[:5]}

