# ============================================================
#  TỰ ĐỘNG HOÁ CỬA SỔ MISA THẬT (Thêm tờ khai > Lấy dữ liệu > Cất) — theo
#  ĐÚNG yêu cầu: KHÔNG tự tính chỉ tiêu (dù từ Excel bảng kê hay từ số cái
#  MISA), để CHÍNH MISA tự tính bằng công cụ "Lấy dữ liệu" sẵn có của nó
#  (đọc thẳng Mua vào/Bán ra MISA đang có) — giống hệt người dùng tự bấm
#  tay. Đây là cửa sổ ứng dụng Windows THẬT (MISA SME.NET), KHÔNG phải
#  trang web, nên phải dùng pywinauto (điều khiển UI Automation) — CÙNG kỹ
#  thuật đã dùng cho hộp thoại nhập PIN chữ ký số (_dvc_nhap_pin_ky_so),
#  KHÁC ở chỗ đây là điều khiển cả 1 CỬA SỔ ỨNG DỤNG lớn (nhiều nút/tab)
#  chứ không phải 1 hộp thoại nhỏ. CHƯA BIẾT chính xác tên/automation_id
#  từng nút trên máy thật của người dùng — nên làm CHẨN ĐOÁN (chỉ đọc,
#  liệt kê cây điều khiển) TRƯỚC, giống hệt phương pháp đã dùng để dò cấu
#  trúc CSDL MISA (SUAllocation/FADepreciation/TADeclaration...), chỉ khác
#  đối tượng dò là UI thay vì bảng CSDL.
# ============================================================
def _misa_ui_import_pywinauto():
    try:
        from pywinauto import Desktop
        return Desktop
    except ImportError:
        return None


def _misa_ui_lay_cua_so_dang_mo():
    Desktop = _misa_ui_import_pywinauto()
    if not Desktop:
        return None, ("Chưa cài thư viện pywinauto (cần để tự điều khiển cửa sổ MISA — "
                      "đóng phần mềm, chạy lại start.bat để tự cài, rồi thử lại.")
    try:
        return Desktop(backend="uia"), None
    except Exception as e:
        return None, f"Không mở được Desktop UI Automation: {e}"


_MISA_UI_LOAI_TRU_TIEU_DE = ("chrome", "token manager", "taskbar", "program manager",
                             "nvidia", "hoa don dien tu", "claude")


def _misa_ui_ten_tien_trinh(pid):
    """Tên file .exe của 1 tiến trình theo PID — dùng để nhận diện cửa sổ
    MISA CHẮC CHẮN hơn nhiều so với đoán theo tiêu đề (đối chiếu dữ liệu
    thật: cửa sổ MISA hiện tiêu đề mặc định 'MainWindow', không có chữ
    MISA nào, dễ đoán nhầm/bỏ sót — cửa sổ tiêu đề RỖNG cũng có thể chính
    là MISA nếu bị bộ lọc theo tiêu đề loại bỏ oan). Trả None nếu không
    đọc được (vd tiến trình chạy quyền admin, tiến trình này không đủ
    quyền — TỰ NÓ cũng là 1 tín hiệu chẩn đoán hữu ích)."""
    try:
        import ctypes
        from ctypes import wintypes
        PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
        h = ctypes.windll.kernel32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
        if not h:
            return None
        try:
            buf = ctypes.create_unicode_buffer(260)
            size = wintypes.DWORD(260)
            ok = ctypes.windll.kernel32.QueryFullProcessImageNameW(h, 0, buf, ctypes.byref(size))
            return buf.value if ok else None
        finally:
            ctypes.windll.kernel32.CloseHandle(h)
    except Exception:
        return None


def _misa_ui_co_ve_la_misa(w):
    """Đoán 1 cửa sổ Windows đang mở CÓ THỂ là MISA SME — dò theo tiêu đề
    (không dấu, không phân biệt hoa/thường) chứa 'misa', hoặc nội dung bên
    trong nhắc tới 'GTGT'/'Tờ khai'/'Thuế'. Đối chiếu dữ liệu thật: MISA
    SME.NET (WPF) KHÔNG luôn đặt tiêu đề cửa sổ rõ ràng — chỉ hiện tên
    control mặc định 'MainWindow' (không đổi theo nội dung, không có chữ
    'MISA' nào) — nên bất kỳ cửa sổ 'Window' nào có tiêu đề KHÔNG rỗng và
    KHÔNG khớp danh sách ĐÃ BIẾT chắc chắn KHÔNG phải MISA (trình duyệt,
    phần mềm quản lý token, các pane hệ thống...) cũng coi là ứng viên.
    ĐÂY LÀ TÍN HIỆU DỰ PHÒNG — ưu tiên nhận diện theo TÊN TIẾN TRÌNH
    (_misa_ui_ten_tien_trinh) đáng tin hơn nhiều, xem _misa_ui_chan_doan_cua_so."""
    try:
        tieu_de = _khong_dau(w.window_text() or "").lower()
    except Exception:
        return False
    if not tieu_de:
        return False
    if "misa" in tieu_de:
        return True
    if any(k in tieu_de for k in ("gtgt", "to khai", "thue", "khau tru")):
        return True
    if any(k in tieu_de for k in _MISA_UI_LOAI_TRU_TIEU_DE):
        return False
    try:
        if w.element_info.control_type != "Window":
            return False
    except Exception:
        pass
    return True


def _misa_ui_dump_cay(w, sau_toi_da=5, so_luong_toi_da=400):
    """Dump cây điều khiển (control_type + text + automation_id) của 1 cửa
    sổ, GIỚI HẠN độ sâu + số lượng để không tràn (cửa sổ MISA có thể có
    hàng trăm/nghìn ô lưới) — CHỈ ĐỌC, không bấm/gõ gì. Trả kèm "loi_con"
    nếu chính lần lấy children() ĐẦU TIÊN (của cửa sổ gốc) bị lỗi — KHÔNG
    nuốt lỗi âm thầm nữa, vì cây rỗng hoàn toàn (0 con) thường là dấu hiệu
    bị chặn quyền (UAC) chứ không phải cửa sổ thật sự trống."""
    ket = []
    dem = [0]
    loi_con_goc = [None]

    def _di(ctrl, sau):
        if dem[0] >= so_luong_toi_da or sau > sau_toi_da:
            return
        try:
            if not ctrl.is_visible():
                return
        except Exception:
            pass
        try:
            loai = ctrl.element_info.control_type
        except Exception:
            loai = "?"
        try:
            text = (ctrl.window_text() or "").strip()
        except Exception:
            text = ""
        try:
            auto_id = ctrl.element_info.automation_id or ""
        except Exception:
            auto_id = ""
        dang_chu_y = loai in ("Button", "Edit", "CheckBox", "RadioButton", "ComboBox",
                              "TabItem", "MenuItem", "TreeItem", "Text")
        if text or auto_id or dang_chu_y:
            if text or auto_id:
                dem[0] += 1
                ket.append({"sau": sau, "loai": loai, "text": text[:80], "automation_id": auto_id})
        try:
            con = ctrl.children()
        except Exception as e:
            con = []
            if sau == 0:
                loi_con_goc[0] = f"{type(e).__name__}: {e}"
        for c in con:
            if dem[0] >= so_luong_toi_da:
                break
            _di(c, sau + 1)

    _di(w, 0)
    return ket, loi_con_goc[0]


def _misa_ui_dang_admin():
    """Tiến trình phần mềm này (server.py) có đang chạy VỚI QUYỀN
    ADMINISTRATOR không — UI Automation KHÔNG THỂ đọc được cây điều khiển
    của 1 ứng dụng chạy quyền admin nếu tiến trình đang dò KHÔNG chạy
    admin (Windows chặn theo thiết kế, không phải lỗi phần mềm) — đây là
    nguyên nhân RẤT THƯỜNG GẶP khi tìm thấy đúng cửa sổ nhưng cây điều
    khiển trả về HOÀN TOÀN RỖNG (0 con) như trường hợp vừa gặp."""
    try:
        import ctypes
        return bool(ctypes.windll.shell32.IsUserAnAdmin())
    except Exception:
        return None


def _misa_ui_chan_doan_cua_so():
    """CHẨN ĐOÁN (CHỈ ĐỌC, không bấm/gõ gì) — liệt kê MỌI cửa sổ Windows
    top-level đang mở (KỂ CẢ tiêu đề rỗng — lần trước lọc theo tiêu đề có
    thể đã bỏ oan đúng cửa sổ MISA thật), nhận diện theo TÊN TIẾN TRÌNH
    (.exe) — đáng tin hơn nhiều so với đoán theo tiêu đề, vì MISA SME.NET
    chỉ hiện tiêu đề mặc định 'MainWindow' không có chữ MISA nào (đã xác
    nhận qua dữ liệu thật). Dump cây điều khiển của cửa sổ THEO ĐÚNG TIẾN
    TRÌNH MISA (và số lượng con ngay cấp 1, để phân biệt cửa sổ THẬT SỰ
    trống với cửa sổ bị chặn đọc)."""
    desk, loi = _misa_ui_lay_cua_so_dang_mo()
    if loi:
        return {"loi": loi}

    tat_ca = []
    try:
        for w in desk.windows():
            try:
                if not w.is_visible():
                    continue
                pid = None
                try:
                    pid = w.process_id()
                except Exception:
                    pass
                ten_tt = _misa_ui_ten_tien_trinh(pid) if pid else None
                so_con_cap1 = None
                try:
                    so_con_cap1 = len(w.children())
                except Exception:
                    so_con_cap1 = "lỗi"
                rect = None
                try:
                    r = w.rectangle()
                    rect = {"trai": r.left, "tren": r.top, "rong": r.width(), "cao": r.height()}
                except Exception:
                    pass
                tat_ca.append({"tieu_de": w.window_text(), "loai": w.element_info.control_type,
                              "pid": pid, "tien_trinh": ten_tt, "so_con_cap1": so_con_cap1,
                              "kich_thuoc": rect})
            except Exception:
                continue
    except Exception as e:
        return {"loi": f"Lỗi liệt kê cửa sổ: {e}"}

    # Ưu tiên nhận diện theo TÊN TIẾN TRÌNH chứa 'misa'; dự phòng theo tiêu
    # đề (_misa_ui_co_ve_la_misa) nếu không tiến trình nào khớp (vd không
    # đọc được tên tiến trình do quyền admin).
    ung_vien_pid = set()
    for x in tat_ca:
        tt = (x.get("tien_trinh") or "").lower()
        if "misa" in tt:
            ung_vien_pid.add(x["pid"])

    chi_tiet = []
    co_cay_rong = False
    da_dump = set()
    if ung_vien_pid:
        for w in desk.windows():
            try:
                if not w.is_visible():
                    continue
                pid = w.process_id()
                if pid not in ung_vien_pid or pid in da_dump:
                    continue
                da_dump.add(pid)
                cay, loi_con = _misa_ui_dump_cay(w)
                if len(cay) <= 1:
                    co_cay_rong = True
                chi_tiet.append({"tieu_de": w.window_text(), "pid": pid,
                                 "cay_dieu_khien": cay, "loi_lay_con": loi_con})
            except Exception as e:
                co_cay_rong = True
                chi_tiet.append({"loi": str(e)})
    else:
        ung_vien = []
        try:
            for w in desk.windows():
                try:
                    if w.is_visible() and _misa_ui_co_ve_la_misa(w):
                        ung_vien.append(w)
                except Exception:
                    continue
        except Exception:
            pass
        for w in ung_vien[:4]:
            try:
                cay, loi_con = _misa_ui_dump_cay(w)
                if len(cay) <= 1:
                    co_cay_rong = True
                chi_tiet.append({"tieu_de": w.window_text(),
                                 "cay_dieu_khien": cay, "loi_lay_con": loi_con})
            except Exception as e:
                co_cay_rong = True
                chi_tiet.append({"tieu_de": w.window_text() if hasattr(w, "window_text") else "?",
                                 "loi": str(e)})

    dang_admin = _misa_ui_dang_admin()
    ghi_chu = None
    if co_cay_rong:
        if dang_admin is False:
            ghi_chu = ("⚠ Cây điều khiển RỖNG (chỉ có chính cửa sổ, 0 con thật) — phần mềm này ĐANG "
                       "KHÔNG chạy quyền Administrator (dang_admin=False). Nếu MISA SME đang chạy VỚI "
                       "quyền Administrator (rất hay gặp với phần mềm kế toán), Windows sẽ CHẶN hoàn "
                       "toàn việc đọc cây điều khiển từ tiến trình không phải admin — giới hạn của "
                       "Windows, không phải lỗi phần mềm. CÁCH SỬA: chuột phải vào start.bat → 'Run as "
                       "administrator' → mở lại phần mềm này VỚI quyền Administrator (giống MISA), rồi "
                       "thử chẩn đoán lại. Kiểm tra thêm: xem trường 'tien_trinh' trong "
                       "'tat_ca_cua_so_dang_mo' có đọc được tên .exe của MISA không — nếu ĐỀU là null, "
                       "đó CŨNG là dấu hiệu quyền admin đang chặn.")
        else:
            ghi_chu = ("⚠ Cây điều khiển RỖNG dù phần mềm này đã chạy quyền Administrator — có thể MISA "
                       "đang ở trạng thái tối thiểu/che khuất, hoặc bản MISA này KHÔNG hỗ trợ UI "
                       "Automation đầy đủ cho các control tự vẽ (custom-drawn) trong lưới/form. Hãy đảm "
                       "bảo MISA đang MỞ, HIỆN RÕ trên màn hình (không thu nhỏ) rồi thử lại; nếu vẫn rỗng "
                       "thì rất có thể phải chuyển hướng khác (không tự động hoá UI được).")

    return {"tat_ca_cua_so_dang_mo": tat_ca, "cua_so_misa_theo_tien_trinh": sorted(ung_vien_pid),
            "cua_so_nghi_la_misa": chi_tiet,
            "phan_mem_nay_dang_chay_quyen_admin": dang_admin, "ghi_chu": ghi_chu}


@app.get("/api/misa-ui/chan-doan-cua-so")
def misa_ui_chan_doan_cua_so():
    """CHẨN ĐOÁN cửa sổ MISA (chỉ đọc) — xem _misa_ui_chan_doan_cua_so."""
    return _misa_ui_chan_doan_cua_so()


def _misa_tinh_chi_tieu_gtgt_tu_misa(cur, tu_ngay, den_ngay):
    """Tính chỉ tiêu 01/GTGT TRỰC TIẾP từ Mua vào/Bán ra ĐÃ CÓ SẴN trong
    MISA (SAVoucher+SAVoucherDetail bán ra; PUVoucher+PUVoucherDetail nhập
    kho/không qua kho + PUService+PUServiceDetail dịch vụ mua vào) — KHÔNG
    qua Excel bảng kê/eTax nữa, theo đúng yêu cầu ("dùng dữ liệu trên MISA
    đã nhập"). CHỈ tính chứng từ ĐÃ GHI SỔ (IsPostedFinance=1), RefDate
    trong [tu_ngay, den_ngay]. Trả ct23..ct36 (CHƯA gồm ct22/ct40.../ct43 —
    những chỉ tiêu này cần số dư đầu kỳ CHUYỂN TỪ QUÝ TRƯỚC, tính ở hàm gọi).

    GIỚI HẠN ĐÃ BIẾT (không ảnh hưởng số thuế phải nộp/được khấu trừ):
    VATRate=0 trên SAVoucherDetail dùng CHUNG cho cả "chịu thuế 0%" LẪN
    "không chịu thuế GTGT (KCT)" — chính hàm ghi Bán hàng của phần mềm
    này (_misa_ghi_ban_hang, xem _chuan_thue_suat) cũng không phân biệt
    được 2 trường hợp khi ghi, nên không thể tách lại từ dữ liệu đã ghi.
    KHÔNG ảnh hưởng ct28/ct36/ct40/ct43 (số thuế thật) vì CẢ 2 nhóm đều
    thuế = 0đ — chỉ ảnh hưởng cách chia doanh thu giữa dòng [26] (KCT) và
    [29] (chịu thuế 0%) trên tờ khai (thông tin trình bày). Mặc định gộp
    hết vào [29], để [26]=0."""
    def _tong2(sql, tham_so):
        r = cur.execute(sql, tham_so).fetchone()
        v1 = _snum(r[0]) if r and r[0] is not None else 0
        v2 = _snum(r[1]) if r and r[1] is not None else 0
        return v1, v2

    ds_mua1, thue_mua1 = _tong2(
        "SELECT ISNULL(SUM(d.Amount),0), ISNULL(SUM(d.VATAmount),0) "
        "FROM PUVoucherDetail d JOIN PUVoucher h ON h.RefID=d.RefID "
        "WHERE h.IsPostedFinance=1 AND h.RefDate>=? AND h.RefDate<=?",
        (tu_ngay, den_ngay))
    ds_mua2, thue_mua2 = _tong2(
        "SELECT ISNULL(SUM(d.Amount),0), ISNULL(SUM(d.VATAmount),0) "
        "FROM PUServiceDetail d JOIN PUService h ON h.RefID=d.RefID "
        "WHERE h.IsPostedFinance=1 AND h.RefDate>=? AND h.RefDate<=?",
        (tu_ngay, den_ngay))
    ct23 = round(ds_mua1 + ds_mua2)
    ct24 = round(thue_mua1 + thue_mua2)
    ct23a, ct24a = 0, 0
    ct25 = ct24

    def _tong_ban(dieu_kien_rate, tham_so_rate=()):
        sql = ("SELECT ISNULL(SUM(d.Amount),0), ISNULL(SUM(d.VATAmount),0) "
               "FROM SAVoucherDetail d JOIN SAVoucher h ON h.RefID=d.RefID "
               "WHERE h.IsPostedFinance=1 AND h.RefDate>=? AND h.RefDate<=?" +
               (" AND " + dieu_kien_rate if dieu_kien_rate else ""))
        return _tong2(sql, (tu_ngay, den_ngay) + tham_so_rate)

    ds_0, _thue_0 = _tong_ban("ISNULL(d.VATRate,0)=0")
    ds_5, thue_5 = _tong_ban("d.VATRate=5")
    ds_810, thue_810 = _tong_ban("d.VATRate IN (8,10)")

    ct26 = 0   # gộp hết vào ct29 — xem giới hạn KCT/0% ở trên
    ct29 = round(ds_0)
    ct30, ct31 = round(ds_5), round(thue_5)
    ct32, ct33 = round(ds_810), round(thue_810)
    ct32a = 0
    ct27 = ct29 + ct30 + ct32
    ct28 = ct31 + ct33
    ct34 = ct26 + ct27
    ct35 = ct28
    ct36 = ct35 - ct25
    return {"ct23": ct23, "ct23a": ct23a, "ct24": ct24, "ct24a": ct24a, "ct25": ct25,
            "ct26": ct26, "ct27": ct27, "ct28": ct28, "ct29": ct29,
            "ct30": ct30, "ct31": ct31, "ct32": ct32, "ct32a": ct32a, "ct33": ct33,
            "ct34": ct34, "ct35": ct35, "ct36": ct36, "ct37": 0, "ct38": 0, "ct39a": 0}


def _misa_chan_doan_kiem_tra_cheo_gtgt(cid, database, quy, nam):
    """KIỂM TRA CHÉO (CHỈ ĐỌC, không ghi gì) — tính chỉ tiêu 01/GTGT TRỰC
    TIẾP từ Mua vào/Bán ra đã có trong MISA (_misa_tinh_chi_tieu_gtgt_tu_misa)
    cho 1 quý ĐÃ CÓ tờ khai thật trong MISA, rồi SO SÁNH với đúng số liệu
    THẬT đã lưu (TADeclarationDetail) — để kiểm chứng công thức tính MỚI
    trước khi dùng để ghi tờ khai mới. Chọn quý người dùng CHẮC CHẮN đã có
    tờ khai thật trong MISA."""
    conn = _misa_sql_connect(cid, database=database)
    try:
        cur = conn.cursor()
        thang_dau = (quy - 1) * 3 + 1
        thang_cuoi = thang_dau + 2
        ngay_cuoi = calendar.monthrange(nam, thang_cuoi)[1]
        tu_ngay = datetime.datetime(nam, thang_dau, 1)
        den_ngay = datetime.datetime(nam, thang_cuoi, ngay_cuoi, 23, 59, 59)
        tinh_moi = _misa_tinh_chi_tieu_gtgt_tu_misa(cur, tu_ngay, den_ngay)

        ky_hien_thi = f"Quý {quy} năm {nam}"
        r = cur.execute(
            "SELECT RefID FROM TADeclaration WHERE RefType=5005 AND DeclarationTerm=?",
            ky_hien_thi).fetchone()
        if not r:
            return {"loi": f"Chưa có tờ khai thật cho {ky_hien_thi} trong MISA để đối chiếu — "
                            f"chọn quý khác đã có tờ khai."}
        refid = r[0]
        that = {}
        for item_code, val in cur.execute(
                "SELECT ItemCode, Value FROM TADeclarationDetail WHERE RefID=?", refid).fetchall():
            that[item_code] = val

        so_sanh = []
        for item_code, ct_key in _MISA_ANH_XA_CHI_TIEU_GTGT:
            if ct_key not in tinh_moi:
                continue
            gt_that_raw = that.get(item_code)
            gt_moi = tinh_moi[ct_key]
            khop = None
            if gt_that_raw not in (None, ""):
                khop = (round(_snum(gt_that_raw)) == gt_moi)
            so_sanh.append({"chi_tieu": item_code, "gia_tri_that_trong_misa": gt_that_raw,
                            "gia_tri_tinh_moi": gt_moi, "khop": khop})
        so_khop = sum(1 for x in so_sanh if x["khop"] is True)
        so_lech = sum(1 for x in so_sanh if x["khop"] is False)

        # Nếu Item23/24 (mua vào) LỆCH — dò thêm 2 hướng để tìm nguồn mua
        # vào bị THIẾU: (1) GLVoucherDetail (Phiếu kế toán khác) có thể
        # chứa dòng thuế GTGT mua vào ghi THỦ CÔNG, KHÔNG qua module Mua
        # hàng chính thức (PUVoucher/PUService) nên bị bỏ sót; (2) dò giá
        # trị CHÊNH LỆCH THẬT trên MỌI bảng số liệu (kỹ thuật đã dùng
        # thành công để tìm SUAllocation/FADepreciation trước đây).
        goi_y = None
        muc23 = next((x for x in so_sanh if x["chi_tieu"] == "Item23"), None)
        muc24 = next((x for x in so_sanh if x["chi_tieu"] == "Item24"), None)
        if (muc23 and muc23["khop"] is False) or (muc24 and muc24["khop"] is False):
            lech_ds = round(_snum(muc23["gia_tri_that_trong_misa"])) - muc23["gia_tri_tinh_moi"] if muc23 else 0
            lech_thue = round(_snum(muc24["gia_tri_that_trong_misa"])) - muc24["gia_tri_tinh_moi"] if muc24 else 0
            gl_rows = []
            try:
                sql_gl = ("SELECT d.RefID, d.Description, d.DebitAccount, d.CreditAccount, "
                         "d.Amount, d.VATRate, d.VATAmount, h.RefNoFinance, h.RefDate, h.JournalMemo "
                         "FROM GLVoucherDetail d JOIN GLVoucher h ON h.RefID=d.RefID "
                         "WHERE h.IsPostedFinance=1 AND h.RefDate>=? AND h.RefDate<=? "
                         "AND d.VATRate IS NOT NULL AND ISNULL(d.VATAmount,0)<>0 "
                         "AND d.DebitAccount LIKE '133%'")
                for r2 in cur.execute(sql_gl, (tu_ngay, den_ngay)).fetchall():
                    gl_rows.append({
                        "RefID": str(r2[0]), "Description": r2[1], "DebitAccount": r2[2],
                        "CreditAccount": r2[3], "Amount": _snum(r2[4]), "VATRate": r2[5],
                        "VATAmount": _snum(r2[6]), "RefNoFinance": r2[7],
                        "RefDate": r2[8].isoformat() if hasattr(r2[8], "isoformat") else r2[8],
                        "JournalMemo": r2[9]})
            except Exception as e:
                gl_rows = [{"loi": str(e)}]
            do_tim_gt = None
            if lech_ds or lech_thue:
                gia_tri_biet = [v for v in (round(lech_ds), round(lech_thue)) if v]
                if gia_tri_biet:
                    do_tim_gt = _misa_tim_bang_chua_so_tien(cur, gia_tri_biet)
            goi_y = {"lech_gia_tri": lech_ds, "lech_thue": lech_thue,
                    "glvoucherdetail_133_nghi_van": gl_rows,
                    "do_tim_gia_tri_lech_khap_moi_bang": do_tim_gt}

        return {"ky": ky_hien_thi, "so_khop": so_khop, "so_lech": so_lech, "so_sanh": so_sanh,
                "goi_y_mua_vao_thieu": goi_y}
    finally:
        conn.close()


@app.get("/api/misa-sql/kiem-tra-cheo-gtgt/{cid}")
def misa_sql_kiem_tra_cheo_gtgt(cid: int, quy: int, nam: int, database: str = ""):
    """KIỂM TRA CHÉO (chỉ đọc) — xem _misa_chan_doan_kiem_tra_cheo_gtgt.
    Chọn quy/nam của 1 quý ĐÃ CÓ tờ khai thật trong MISA để đối chiếu công
    thức tính MỚI (trực tiếp từ Mua vào/Bán ra trong MISA) với số liệu
    thật đã lưu."""
    database = (database or "").strip() or (_misa_sql_cfg(cid).get("database") or "")
    if not database:
        raise HTTPException(400, "Chưa cấu hình kết nối/CSDL MISA.")
    return _misa_chan_doan_kiem_tra_cheo_gtgt(cid, database, quy, nam)


# AppendixTypeID (GUID) của 2 phụ lục "Bảng kê bán ra" (BKBR-01-1/GTGT) /
# "Bảng kê mua vào" (BKMV-01-2/GTGT) — HỌC ĐƯỢC từ dữ liệu MISA thật (dò
# TADeclarationAppendix thật, đối chiếu AppendixID nào được TA_011GTGT_Detail
# (bán ra) hay TA_012GTGT_Detail (mua vào) tham chiếu tới — xem
# _misa_chan_doan_appendixtype_gtgt). ĐÂY LÀ HẰNG SỐ CỦA CHÍNH PHẦN MỀM
# MISA (không đổi theo công ty) — thiếu đánh dấu 2 phụ lục này khiến màn
# "Tờ khai" hiện toàn số 0 dù TADeclarationDetail đã có đúng số liệu
# (xác nhận qua thử nghiệm thật).
_MISA_APPENDIXTYPE_BAN_RA_BKBR011 = "C508F7CA-FCE7-4F9F-B155-DD54A1F25115"
_MISA_APPENDIXTYPE_MUA_VAO_BKMV012 = "C144B6D7-37F6-4C8F-ABBD-6A7693531DDB"
# 2 AppendixTypeID CÒN LẠI luôn xuất hiện CÙNG 2 mã trên trong MỌI tờ khai
# 01/GTGT thật đã dò (xác nhận qua 2 tờ khai thật khác kỳ, cùng công ty) —
# chưa xác định rõ tên phụ lục tương ứng (không có TA_011/TA_012_Detail nào
# tham chiếu tới, có thể là phụ lục 01-3/GTGT hoặc metadata nội bộ của MISA)
# nhưng CẦN đính kèm đủ cả 4 thì mục [23]/[24]/[25] (mua vào) trên màn "Tờ
# khai" mới hiện đúng số — thiếu 2 mã này (dù đã đính kèm đúng BKBR/BKMV)
# vẫn khiến [23]/[24]/[25] hiện 0 dù TADeclarationDetail đã lưu đúng số và
# tổng phụ lục BKMV-01-2 đã đúng (xác nhận qua thử nghiệm thật, kể cả sau
# khi đóng mở lại tờ khai trong MISA).
_MISA_APPENDIXTYPE_PHU_LUC_3 = "675C11FB-43CF-47EA-8C60-BF97C758F1E7"
_MISA_APPENDIXTYPE_PHU_LUC_4 = "F146468B-DB0A-42EE-8F03-514CA9754D24"


def _misa_nhom_ban_ra(vat_rate):
    """Nhóm chỉ tiêu trên BKBR-01-1/GTGT theo thuế suất — form 01/GTGT chỉ có
    3 nhóm thuế thật (0%/5%/10%), KHÔNG có nhóm 8% riêng: hóa đơn thuế suất
    8% (giảm theo NĐ44...) vẫn xếp chung nhóm '14' (10%) — xác nhận qua dữ
    liệu thật (TaxRate lưu danh nghĩa 10, TaxAmount đã lưu SẴN số thuế sau
    giảm 2%, DeductionsTaxAmount lưu phần giảm riêng — copy nguyên 3 giá trị
    này từ SAVoucherDetail nên không cần tự tính lại giảm trừ)."""
    try:
        v = round(_snum(vat_rate))
    except Exception:
        v = None
    if v == 0:
        return "12"
    if v == 5:
        return "13"
    return "14"


def _misa_dien_chi_tiet_hoa_don_gtgt(cur, cols_011, cols_012, tu_ngay_sql, den_ngay_sql,
                                       ref_id, appendix_id_banra, appendix_id_muavao):
    """Dựng danh sách dòng CHI TIẾT TỪNG HÓA ĐƠN cho 2 phụ lục BKBR-01-1
    (bán ra, từ SAVoucher/SAVoucherDetail) và BKMV-01-2 (mua vào, từ
    PUVoucher/PUVoucherDetail + PUService/PUServiceDetail) — thử nghiệm thật
    cho thấy màn 'Tờ khai' của MISA tính lại tổng TỪ những dòng này (không
    đọc thẳng TADeclarationDetail đã lưu), nên thiếu bước này thì tờ khai
    hiện toàn số 0 dù chỉ tiêu chính đã đúng. Trả (rows_011, rows_012), mỗi
    dòng gộp theo (chứng từ, thuế suất) — đúng cấu trúc thật đã dò được qua
    _misa_chan_doan_chi_tiet_phu_luc_gtgt."""
    import uuid as _uuid
    rows_011, rows_012 = [], []
    if cols_011:
        try:
            ban_ra = cur.execute(
                "SELECT h.RefID, h.BranchID, h.InvNo, h.InvSeries, h.InvDate, "
                "h.AccountObjectName, h.AccountObjectTaxCode, h.RefType, "
                "h.IsReductionInvoice, d.VATRate, "
                "SUM(d.Amount), SUM(d.VATAmount), SUM(d.DeductionsTaxAmount) "
                "FROM SAVoucherDetail d JOIN SAVoucher h ON h.RefID=d.RefID "
                "WHERE h.IsPostedFinance=1 AND h.RefDate>=? AND h.RefDate<=? "
                "GROUP BY h.RefID, h.BranchID, h.InvNo, h.InvSeries, h.InvDate, "
                "h.AccountObjectName, h.AccountObjectTaxCode, h.RefType, "
                "h.IsReductionInvoice, d.VATRate",
                (tu_ngay_sql, den_ngay_sql)).fetchall()
        except Exception:
            ban_ra = []
        dem_nhom = {}
        for (vrid, branch_id, inv_no, inv_series, inv_date, ten, mst, ref_type,
             is_giam, vat_rate, turnover, tax_amt, ded_tax) in ban_ra:
            nhom = _misa_nhom_ban_ra(vat_rate)
            dem_nhom[nhom] = dem_nhom.get(nhom, 0) + 1
            r = {real: _misa_gia_tri_mac_dinh(t) for real, t in cols_011.values()}
            _misa_gan(r, cols_011, str(_uuid.uuid4()), "RefDetailID")
            _misa_gan(r, cols_011, ref_id, "RefID")
            _misa_gan(r, cols_011, appendix_id_banra, "AppendixID")
            _misa_gan(r, cols_011, vrid, "VoucherRefID")
            _misa_gan(r, cols_011, inv_series, "InvSeries")
            _misa_gan(r, cols_011, inv_no, "InvNo")
            _misa_gan(r, cols_011, inv_date, "InvDate")
            _misa_gan(r, cols_011, ten, "AccountObjectName")
            _misa_gan(r, cols_011, mst, "CompanyTaxCode")
            _misa_gan(r, cols_011, round(_snum(turnover)), "TurnOverAmount")
            _misa_gan(r, cols_011, _snum(vat_rate) if vat_rate is not None else 0, "TaxRate")
            _misa_gan(r, cols_011, round(_snum(tax_amt)), "TaxAmount")
            _misa_gan(r, cols_011, nhom, "GroupName")
            _misa_gan(r, cols_011, dem_nhom[nhom], "SortOrder")
            _misa_gan(r, cols_011, ref_type, "VoucherRefType")
            _misa_gan(r, cols_011, branch_id, "VoucherBranchID")
            _misa_gan(r, cols_011, 0, "AmountDecimalDigits")
            _misa_gan(r, cols_011, bool(is_giam), "IsReductionInvoice")
            _misa_gan(r, cols_011, round(_snum(ded_tax)), "DeductionsTaxAmount")
            _misa_gan(r, cols_011, 0, "ToolClickType")
            rows_011.append(r)

    if cols_012:
        def _mua_vao(sql, tham_so, tien_to):
            try:
                return cur.execute(sql, tham_so).fetchall()
            except Exception:
                return []
        mua_nk = _mua_vao(
            "SELECT h.RefID, h.BranchID, h.RefType, h.AccountObjectID, "
            "d.InvNo, d.InvSeries, d.InvDate, d.TaxAccountObjectName, "
            "d.TaxAccountObjectTaxCode, d.VATRate, SUM(d.Amount), SUM(d.VATAmount) "
            "FROM PUVoucherDetail d JOIN PUVoucher h ON h.RefID=d.RefID "
            "WHERE h.IsPostedFinance=1 AND h.RefDate>=? AND h.RefDate<=? "
            "GROUP BY h.RefID, h.BranchID, h.RefType, h.AccountObjectID, d.InvNo, "
            "d.InvSeries, d.InvDate, d.TaxAccountObjectName, d.TaxAccountObjectTaxCode, "
            "d.VATRate", (tu_ngay_sql, den_ngay_sql), "NK")
        mua_dv = _mua_vao(
            "SELECT h.RefID, h.BranchID, h.RefType, h.AccountObjectID, "
            "d.InvNo, d.InvSeries, d.InvDate, d.TaxAccountObjectName, "
            "d.TaxAccountObjectTaxCode, d.VATRate, SUM(d.Amount), SUM(d.VATAmount) "
            "FROM PUServiceDetail d JOIN PUService h ON h.RefID=d.RefID "
            "WHERE h.IsPostedFinance=1 AND h.RefDate>=? AND h.RefDate<=? "
            "GROUP BY h.RefID, h.BranchID, h.RefType, h.AccountObjectID, d.InvNo, "
            "d.InvSeries, d.InvDate, d.TaxAccountObjectName, d.TaxAccountObjectTaxCode, "
            "d.VATRate", (tu_ngay_sql, den_ngay_sql), "DV")
        so_thu_tu = 0
        for nguon, tien_to in ((mua_nk, "NK"), (mua_dv, "DV")):
            for (vrid, branch_id, ref_type, acc_obj_id, inv_no, inv_series, inv_date,
                 ten, mst, vat_rate, turnover, tax_amt) in nguon:
                so_thu_tu += 1
                voucher_ref_no = (tien_to + str(inv_no or "") + str(mst or ""))[:20]
                r = {real: _misa_gia_tri_mac_dinh(t) for real, t in cols_012.values()}
                _misa_gan(r, cols_012, str(_uuid.uuid4()), "RefDetailID")
                _misa_gan(r, cols_012, ref_id, "RefID")
                _misa_gan(r, cols_012, appendix_id_muavao, "AppendixID")
                _misa_gan(r, cols_012, vrid, "VoucherRefID")
                _misa_gan(r, cols_012, "", "InvoiceTemplate")
                _misa_gan(r, cols_012, inv_series, "InvSeries")
                _misa_gan(r, cols_012, inv_no, "InvNo")
                _misa_gan(r, cols_012, inv_date, "InvDate")
                _misa_gan(r, cols_012, ten, "AccountObjectName")
                _misa_gan(r, cols_012, mst, "CompanyTaxCode")
                _misa_gan(r, cols_012, round(_snum(turnover)), "TurnOverAmount")
                _misa_gan(r, cols_012, _snum(vat_rate) if vat_rate is not None else 0, "TaxRate")
                _misa_gan(r, cols_012, round(_snum(tax_amt)), "TaxAmount")
                _misa_gan(r, cols_012, so_thu_tu, "SortOrder")
                _misa_gan(r, cols_012, ref_type, "VoucherRefType")
                _misa_gan(r, cols_012, voucher_ref_no, "VoucherRefNo")
                _misa_gan(r, cols_012, branch_id, "VoucherBranchID")
                _misa_gan(r, cols_012, "01", "GroupName")
                _misa_gan(r, cols_012, "1", "PurchasePurposeCode")
                _misa_gan(r, cols_012, acc_obj_id, "AccountObjectID")
                _misa_gan(r, cols_012, 0, "OriginRefType")
                _misa_gan(r, cols_012, "", "InvestmentProjectCode")
                _misa_gan(r, cols_012, False, "IsVoucherImport")
                rows_012.append(r)
    return rows_011, rows_012


def _misa_tao_to_khai_khau_tru_gtgt(cid, database, preview=True, tu_quy=None, tu_nam=None, so_quy=4):
    """Tự động tạo Tờ khai 01/GTGT (TT80) + hạch toán 'Khấu trừ thuế GTGT'
    (Nợ 33311/Có 1331) TỪNG QUÝ thẳng vào MISA — hạch toán CHỈ TẠO, KHÔNG tự
    ghi sổ (IsPostedFinance=False, theo yêu cầu — người dùng tự kiểm tra rồi
    bấm "Ghi sổ" trong MISA). Chỉ tiêu ct23-ct36 tính
    TRỰC TIẾP từ Mua vào/Bán ra ĐÃ CÓ SẴN trong MISA
    (_misa_tinh_chi_tieu_gtgt_tu_misa — KHÔNG qua Excel/eTax nữa, theo
    đúng yêu cầu "dùng dữ liệu trên MISA đã nhập"), ĐÃ KIỂM TRA CHÉO khớp
    100% với tờ khai thật (xem nút "🔬 Kiểm tra chéo công thức GTGT").
    ct22 (số dư đầu kỳ) LẤY TỪ ct43 (còn được khấu trừ chuyển kỳ sau) của
    quý LIỀN TRƯỚC — ưu tiên đọc từ tờ khai THẬT đã có trong MISA cho quý
    đó, chỉ dùng số vừa tự tính khi quý trước đó CŨNG do đợt chạy này tạo.

    CẤU TRÚC đã xác nhận qua nhiều đợt chẩn đoán dữ liệu MISA thật:
    - TADeclaration (RefType=5005, TemplateNo='01/GTGT') +
      TADeclarationDetail (kiểu EAV: ItemCode='ItemN' + Value dạng CHUỖI)
      = Tờ khai 01/GTGT. Mã chỉ tiêu khớp ĐÚNG số chỉ tiêu ctN (xem
      _MISA_ANH_XA_CHI_TIEU_GTGT), riêng Item21 luôn để trống (""),
      Item37/Item38 lưu dạng "0.0000", Item42/42a/42b luôn "0".
    - GLVoucher (RefType=4011) + GLVoucherDetail (1 dòng Nợ 33311/Có
      1331, TK/diễn giải CỐ ĐỊNH học từ dữ liệu thật) = bút toán Khấu trừ
      thuế. TotalAmount = MIN(OutputAmount, DeductionAmount) — công thức
      đã ĐƯỢC CHỨNG MINH khớp chính xác dữ liệu thật (kể cả trường hợp
      hiếm đầu vào < đầu ra); OutputAmount=ct35 (tổng thuế đầu ra),
      DeductionAmount=ct22+ct25 (khớp đúng
      DeductionAmountLastPeriod+DeductionAmountThisPeriod trên mọi dòng
      thật đã đối chiếu).

    Cũng ghi TADeclarationAppendix đánh dấu ĐỦ 4 phụ lục — Bảng kê bán ra
    (BKBR-01-1/GTGT, AppendixTypeID=_MISA_APPENDIXTYPE_BAN_RA_BKBR011), Bảng
    kê mua vào (BKMV-01-2/GTGT, AppendixTypeID=
    _MISA_APPENDIXTYPE_MUA_VAO_BKMV012), và 2 phụ lục chưa rõ tên
    (_MISA_APPENDIXTYPE_PHU_LUC_3/4) — MỌI tờ khai 01/GTGT thật đã dò đều
    có đủ 4 mã này (xác nhận qua 2 tờ khai thật khác kỳ). THIẾU dù chỉ 1
    trong 4 khiến màn "Tờ khai" của MISA hiện sai/thiếu số dù
    TADeclarationDetail và tổng phụ lục đã đúng — xác nhận qua thử nghiệm
    thật: thiếu 2 mã "chưa rõ tên" khiến riêng mục [23]/[24]/[25] (mua vào)
    hiện 0 dù đã đính kèm đúng BKBR/BKMV và dù đóng mở lại tờ khai
    (xem _misa_chan_doan_appendixtype_gtgt, _misa_chan_doan_appendix_day_du_gtgt).

    Xác nhận thêm qua thử nghiệm thật: màn "Tờ khai" của MISA KHÔNG đọc
    thẳng TADeclarationDetail để hiển thị — nó TÍNH LẠI tổng từ chi tiết
    TỪNG hóa đơn trong 2 phụ lục (TA_011GTGT_Detail bán ra/
    TA_012GTGT_Detail mua vào — xem _misa_chan_doan_chi_tiet_phu_luc_gtgt).
    Vì vậy _misa_dien_chi_tiet_hoa_don_gtgt cũng ghi đủ chi tiết từng hóa
    đơn (từ SAVoucher/SAVoucherDetail bán ra; PUVoucher/PUVoucherDetail +
    PUService/PUServiceDetail mua vào) vào 2 bảng này, gộp theo
    (chứng từ, thuế suất) — kể cả hóa đơn giảm 2% thuế GTGT (copy nguyên
    TaxRate/TaxAmount/DeductionsTaxAmount đã lưu sẵn trên SAVoucherDetail,
    không tự tính lại phần giảm).

    GIỚI HẠN ĐÃ BIẾT: xem _misa_tinh_chi_tieu_gtgt_tu_misa (KCT/0% gộp
    chung, không ảnh hưởng số thuế thật). CHƯA ghi TADeclarationGeneral
    (siêu dữ liệu chữ ký/mã hồ sơ...) — người dùng cần tự mở tờ khai trong
    MISA bổ sung nếu cần trước khi thật sự ký/nộp. Cấu trúc ghi chi tiết
    phụ lục MỚI xây dựng lần đầu (dựa trên dò 1 tờ khai thật), CHƯA qua
    nhiều lần kiểm chứng thực tế như Ghi Tăng CCDC/TSCĐ.

    preview=True: chỉ tính toán, KHÔNG ghi gì (rollback)."""
    import re
    import uuid as _uuid

    so_quy = max(1, int(so_quy or 4))

    conn = _misa_sql_connect(cid, database=database)
    conn.autocommit = False
    try:
        cur = conn.cursor()

        if not tu_quy or not tu_nam:
            # Tự tiếp nối: tìm quý/năm LỚN NHẤT trong CÁC tờ khai 01/GTGT
            # ĐÃ CÓ (DeclarationTerm "Quý N năm YYYY"), bắt đầu từ quý KẾ
            # TIẾP — TRƯỚC ĐÂY bị lỗi mặc định về quý DƯƠNG LỊCH HIỆN TẠI
            # (bỏ sót mọi quý còn thiếu giữa tờ khai cũ nhất và hiện tại,
            # xác nhận qua thử nghiệm thật: có tờ khai thật ở Quý 2/2025
            # nhưng phần mềm lại tạo thẳng Quý 3/2026, bỏ qua Quý 3-4/2025
            # và Quý 1-2/2026). Chỉ dùng quý dương lịch hiện tại khi CHƯA
            # có tờ khai 01/GTGT nào (không có điểm mốc để tiếp nối).
            max_q_that, max_y_that = None, None
            try:
                for (term,) in cur.execute(
                        "SELECT DeclarationTerm FROM TADeclaration WHERE RefType=5005").fetchall():
                    m = re.match(r"Quý\s*(\d+)\s*năm\s*(\d+)", str(term or "").strip())
                    if not m:
                        continue
                    q_t, y_t = int(m.group(1)), int(m.group(2))
                    if max_y_that is None or (y_t, q_t) > (max_y_that, max_q_that):
                        max_y_that, max_q_that = y_t, q_t
            except Exception:
                pass
            if max_y_that is not None:
                tu_quy, tu_nam = max_q_that + 1, max_y_that
                if tu_quy > 4:
                    tu_quy, tu_nam = 1, max_y_that + 1
            else:
                now = datetime.datetime.now()
                tu_quy = (now.month - 1) // 3 + 1
                tu_nam = now.year
        else:
            tu_quy, tu_nam = int(tu_quy), int(tu_nam)

        theo_quy = []
        for i in range(so_quy):
            q = tu_quy + i
            y = tu_nam + (q - 1) // 4
            q = ((q - 1) % 4) + 1
            thang_dau = (q - 1) * 3 + 1
            thang_cuoi = thang_dau + 2
            ngay_cuoi = calendar.monthrange(y, thang_cuoi)[1]
            theo_quy.append({"quy": q, "nam": y, "thang_dau": thang_dau,
                             "thang_cuoi": thang_cuoi, "ngay_cuoi": ngay_cuoi})

        cols_tk = _misa_cot_bang_that(cur, "TADeclaration")
        cols_tkd = _misa_cot_bang_that(cur, "TADeclarationDetail")
        cols_glv = _misa_cot_bang_that(cur, "GLVoucher")
        cols_glvd = _misa_cot_bang_that(cur, "GLVoucherDetail")
        cols_ta = _misa_cot_bang_that(cur, "TADeclarationAppendix")
        cols_011 = _misa_cot_bang_that(cur, "TA_011GTGT_Detail")
        cols_012 = _misa_cot_bang_that(cur, "TA_012GTGT_Detail")
        if not (cols_tk and cols_tkd and cols_glv and cols_glvd):
            raise HTTPException(
                400, "Không tìm thấy đủ bảng TADeclaration/TADeclarationDetail/"
                     "GLVoucher/GLVoucherDetail trong CSDL MISA đang kết nối.")

        mau_tk = _misa_mau_dong_that(cur, "TADeclaration", "RefType=5005")
        if not mau_tk:
            raise HTTPException(
                400, "Chưa có tờ khai 01/GTGT (TT80) nào trong MISA để học cấu trúc — "
                     "hãy vào MISA, mục 'Thuế > TT80 - Tờ khai thuế GTGT khấu trừ', "
                     "tạo tay ít nhất 1 tờ khai rồi thử lại.")
        mau_glv = _misa_mau_dong_that(cur, "GLVoucher", "RefType=4011")
        mau_glvd = _misa_mau_dong_that(
            cur, "GLVoucherDetail", "DebitAccount=? AND CreditAccount=?", ("33311", "1331"))
        if not mau_glv or not mau_glvd:
            raise HTTPException(
                400, "Chưa có bút toán 'Khấu trừ thuế GTGT' nào trong MISA để học cấu trúc — "
                     "hãy tạo tay ít nhất 1 bút toán trên MISA rồi thử lại.")

        max_so_nvk = 0
        try:
            for (rf,) in cur.execute(
                    "SELECT RefNoFinance FROM GLVoucher WHERE RefNoFinance LIKE 'NVK%'").fetchall():
                m = re.search(r"NVK(\d+)", str(rf or ""))
                if m:
                    max_so_nvk = max(max_so_nvk, int(m.group(1)))
        except Exception:
            pass
        suffix_mau = ""
        m2 = re.match(r"NVK\d+(.*)$", str(mau_glv.get("RefNoFinance") or ""))
        if m2:
            suffix_mau = m2.group(1)

        da_co_tk, da_co_glv = set(), set()
        try:
            for (term,) in cur.execute(
                    "SELECT DeclarationTerm FROM TADeclaration WHERE RefType=5005").fetchall():
                da_co_tk.add(str(term or "").strip())
        except Exception:
            pass
        try:
            for (jm,) in cur.execute(
                    "SELECT JournalMemo FROM GLVoucher WHERE RefType=4011").fetchall():
                da_co_glv.add(str(jm or "").strip())
        except Exception:
            pass

        branch_id = mau_tk.get("BranchID") or _misa_branch_id(cur)
        max_reforder = 0
        try:
            r0 = cur.execute("SELECT ISNULL(MAX(RefOrder),0) FROM GLVoucher").fetchone()
            max_reforder = (r0[0] or 0) if r0 else 0
        except Exception:
            pass

        def _lay_item43_that(ky):
            """Đọc [43] (còn được khấu trừ chuyển kỳ sau) THẬT đã lưu cho 1
            quý, dùng làm số dư đầu kỳ [22] của quý KẾ TIẾP — None nếu quý
            đó chưa có tờ khai thật trong MISA."""
            try:
                r = cur.execute(
                    "SELECT d.Value FROM TADeclarationDetail d "
                    "JOIN TADeclaration h ON h.RefID=d.RefID "
                    "WHERE h.RefType=5005 AND h.DeclarationTerm=? AND d.ItemCode='Item43'",
                    ky).fetchone()
                return round(_snum(r[0])) if r and r[0] not in (None, "") else None
            except Exception:
                return None

        q_truoc = tu_quy - 1
        y_truoc = tu_nam
        if q_truoc < 1:
            q_truoc, y_truoc = 4, y_truoc - 1
        ct22_hien_tai = _lay_item43_that(f"Quý {q_truoc} năm {y_truoc}") or 0

        ket = []
        for dong in theo_quy:
            q, y = dong["quy"], dong["nam"]
            ky_hien_thi = f"Quý {q} năm {y}"
            memo = f"Khấu trừ thuế GTGT quý {q} năm {y}"
            if ky_hien_thi in da_co_tk or memo in da_co_glv:
                ct43_that = _lay_item43_that(ky_hien_thi)
                if ct43_that is not None:
                    ct22_hien_tai = ct43_that
                ket.append({"ky": ky_hien_thi, "trang_thai": "bỏ qua — đã có tờ khai/bút toán quý này"})
                continue

            tu_ngay_sql = datetime.datetime(y, dong["thang_dau"], 1)
            den_ngay_sql = datetime.datetime(y, dong["thang_cuoi"], dong["ngay_cuoi"], 23, 59, 59)
            ct = _misa_tinh_chi_tieu_gtgt_tu_misa(cur, tu_ngay_sql, den_ngay_sql)
            ct["ct22"] = ct22_hien_tai
            con_lai = ct["ct36"] - ct["ct22"] + ct["ct37"] - ct["ct38"] - ct["ct39a"]
            ct["ct40a"] = max(con_lai, 0)
            ct["ct40b"] = 0
            ct["ct40"] = max(ct["ct40a"] - ct["ct40b"], 0)
            ct["ct41"] = max(-con_lai, 0)
            ct["ct42"] = 0
            ct["ct43"] = max(ct["ct41"] - ct["ct42"], 0)

            output_amount = round(_snum(ct.get("ct35")))
            ded_last = round(_snum(ct.get("ct22")))
            ded_this = round(_snum(ct.get("ct25")))
            deduction_amount = ded_last + ded_this
            tong_kt = min(output_amount, deduction_amount)

            tk_id = str(_uuid.uuid4())
            tk_row = {real: _misa_gia_tri_mac_dinh(t) for real, t in cols_tk.values()}
            _misa_gan(tk_row, cols_tk, tk_id, "RefID")
            _misa_gan(tk_row, cols_tk, branch_id, "BranchID")
            _misa_gan(tk_row, cols_tk, 5005, "RefType")
            _misa_gan(tk_row, cols_tk, "01/GTGT", "TemplateNo")
            _misa_gan(tk_row, cols_tk, "TT80 - Tờ khai thuế GTGT khấu trừ (01/GTGT)", "DeclarationName")
            _misa_gan(tk_row, cols_tk, ky_hien_thi, "DeclarationTerm")
            _misa_gan(tk_row, cols_tk, datetime.datetime(y, dong["thang_dau"], 1), "FromDate")
            _misa_gan(tk_row, cols_tk, datetime.datetime(y, dong["thang_cuoi"], dong["ngay_cuoi"]), "ToDate")
            _misa_gan(tk_row, cols_tk, True, "IsFirstDeclaration")
            _misa_gan(tk_row, cols_tk, datetime.datetime.now(), "CreatedDate")
            _misa_gan(tk_row, cols_tk, mau_tk.get("CareerCode") or "00", "CareerCode")
            _misa_gan(tk_row, cols_tk, mau_tk.get("CareerName"), "CareerName")
            _misa_gan(tk_row, cols_tk, bool(mau_tk.get("IsShowRefNo")), "IsShowRefNo")
            _misa_gan(tk_row, cols_tk, bool(mau_tk.get("IsTT195")), "IsTT195")
            _misa_gan(tk_row, cols_tk, bool(mau_tk.get("IsCollection")), "IsCollection")
            _misa_gan(tk_row, cols_tk, bool(mau_tk.get("IsIncludeIndirectTax")), "IsIncludeIndirectTax")
            _misa_gan(tk_row, cols_tk, mau_tk.get("ProvinceCode"), "ProvinceCode")
            _misa_gan(tk_row, cols_tk, mau_tk.get("ProvinceName"), "ProvinceName")
            _misa_gan(tk_row, cols_tk, mau_tk.get("DepartmentTaxCode"), "DepartmentTaxCode")
            _misa_gan(tk_row, cols_tk, mau_tk.get("DepartmentTaxName"), "DepartmentTaxName")
            _misa_gan(tk_row, cols_tk, mau_tk.get("PaymentTaxCode"), "PaymentTaxCode")
            _misa_gan(tk_row, cols_tk, mau_tk.get("PaymentTaxName"), "PaymentTaxName")
            _misa_gan(tk_row, cols_tk, mau_tk.get("WardOrCommuneCode"), "WardOrCommuneCode")
            _misa_gan(tk_row, cols_tk, mau_tk.get("WardOrCommuneName"), "WardOrCommuneName")
            _misa_gan(tk_row, cols_tk, True, "IsCreateNew")

            det_rows = []

            def _them_ct(item_code, gia_tri_chuoi):
                d = {real: _misa_gia_tri_mac_dinh(t) for real, t in cols_tkd.values()}
                _misa_gan(d, cols_tkd, str(_uuid.uuid4()), "RefDetailID")
                _misa_gan(d, cols_tkd, tk_id, "RefID")
                _misa_gan(d, cols_tkd, item_code, "ItemCode")
                _misa_gan(d, cols_tkd, 5, "DataType")
                _misa_gan(d, cols_tkd, gia_tri_chuoi, "Value")
                det_rows.append(d)

            _them_ct("Item21", "")
            for item_code, ct_key in _MISA_ANH_XA_CHI_TIEU_GTGT:
                _them_ct(item_code, str(round(_snum(ct.get(ct_key)))))
            _them_ct("Item37", "0.0000")
            _them_ct("Item38", "0.0000")
            _them_ct("Item42", "0")
            _them_ct("Item42a", "0")
            _them_ct("Item42b", "0")

            appendix_rows = []
            appendix_id_banra = str(_uuid.uuid4())
            appendix_id_muavao = str(_uuid.uuid4())
            if cols_ta:
                for appendix_id, appendix_type_id in (
                        (appendix_id_banra, _MISA_APPENDIXTYPE_BAN_RA_BKBR011),
                        (appendix_id_muavao, _MISA_APPENDIXTYPE_MUA_VAO_BKMV012),
                        (str(_uuid.uuid4()), _MISA_APPENDIXTYPE_PHU_LUC_3),
                        (str(_uuid.uuid4()), _MISA_APPENDIXTYPE_PHU_LUC_4)):
                    a = {real: _misa_gia_tri_mac_dinh(t) for real, t in cols_ta.values()}
                    _misa_gan(a, cols_ta, appendix_id, "AppendixID")
                    _misa_gan(a, cols_ta, tk_id, "RefID")
                    _misa_gan(a, cols_ta, appendix_type_id, "AppendixTypeID")
                    appendix_rows.append(a)

            chi_tiet_ban_ra, chi_tiet_mua_vao = [], []
            if cols_ta:
                chi_tiet_ban_ra, chi_tiet_mua_vao = _misa_dien_chi_tiet_hoa_don_gtgt(
                    cur, cols_011, cols_012, tu_ngay_sql, den_ngay_sql,
                    tk_id, appendix_id_banra, appendix_id_muavao)

            max_so_nvk += 1
            refno_moi = f"NVK{max_so_nvk}{suffix_mau}"
            glv_id = str(_uuid.uuid4())
            ngay_ct = datetime.datetime(y, dong["thang_cuoi"], dong["ngay_cuoi"])
            glv_row = {real: _misa_gia_tri_mac_dinh(t) for real, t in cols_glv.values()}
            _misa_gan(glv_row, cols_glv, glv_id, "RefID")
            _misa_gan(glv_row, cols_glv, 0, "DisplayOnBook")
            _misa_gan(glv_row, cols_glv, 4011, "RefType")
            max_reforder += 1
            _misa_gan(glv_row, cols_glv, max_reforder, "RefOrder")
            _misa_gan(glv_row, cols_glv, ngay_ct, "RefDate")
            _misa_gan(glv_row, cols_glv, ngay_ct, "PostedDate")
            _misa_gan(glv_row, cols_glv, refno_moi, "RefNoFinance")
            # Theo yêu cầu: chỉ TẠO chứng từ khấu trừ, KHÔNG tự ghi sổ — để
            # người dùng tự kiểm tra rồi bấm "Ghi sổ" trong MISA.
            _misa_gan(glv_row, cols_glv, False, "IsPostedFinance")
            _misa_gan(glv_row, cols_glv, False, "IsPostedManagement")
            _misa_gan(glv_row, cols_glv, memo, "JournalMemo")
            _misa_gan(glv_row, cols_glv, tong_kt, "TotalAmountOC")
            _misa_gan(glv_row, cols_glv, tong_kt, "TotalAmount")
            _misa_gan(glv_row, cols_glv, branch_id, "BranchID")
            _misa_gan(glv_row, cols_glv, "VND", "CurrencyID")
            _misa_gan(glv_row, cols_glv, 1, "ExchangeRate")
            _misa_gan(glv_row, cols_glv, output_amount, "OutputAmount")
            _misa_gan(glv_row, cols_glv, deduction_amount, "DeductionAmount")
            _misa_gan(glv_row, cols_glv, q, "Month")
            _misa_gan(glv_row, cols_glv, y, "Year")
            _misa_gan(glv_row, cols_glv, datetime.datetime.now(), "CreatedDate")
            _misa_gan(glv_row, cols_glv, mau_glv.get("CreatedBy") or "ADMIN", "CreatedBy")
            _misa_gan(glv_row, cols_glv, datetime.datetime.now(), "ModifiedDate")
            _misa_gan(glv_row, cols_glv, mau_glv.get("ModifiedBy") or "ADMIN", "ModifiedBy")
            _misa_gan(glv_row, cols_glv, False, "ReceiptType")
            _misa_gan(glv_row, cols_glv, ded_last, "DeductionAmountLastPeriod")
            _misa_gan(glv_row, cols_glv, ded_this, "DeductionAmountThisPeriod")
            _misa_gan(glv_row, cols_glv, False, "IsOnceSettlementAdvance")
            _misa_gan(glv_row, cols_glv, 0, "AdvancedAmount")
            _misa_gan(glv_row, cols_glv, 0, "AdvancedAmountOC")
            _misa_gan(glv_row, cols_glv, 1, "PeriodTypeVATDeduction")
            _misa_gan(glv_row, cols_glv, False, "IsExecuted")
            _misa_gan(glv_row, cols_glv, 0, "DiffAmount")
            _misa_gan(glv_row, cols_glv, 0, "DiffAmountOC")

            glvd_row = {real: _misa_gia_tri_mac_dinh(t) for real, t in cols_glvd.values()}
            _misa_gan(glvd_row, cols_glvd, str(_uuid.uuid4()), "RefDetailID")
            _misa_gan(glvd_row, cols_glvd, glv_id, "RefID")
            _misa_gan(glvd_row, cols_glvd, "Thuế GTGT được khấu trừ của hàng hóa, dịch vụ", "Description")
            _misa_gan(glvd_row, cols_glvd, "33311", "DebitAccount")
            _misa_gan(glvd_row, cols_glvd, "1331", "CreditAccount")
            _misa_gan(glvd_row, cols_glvd, tong_kt, "AmountOC")
            _misa_gan(glvd_row, cols_glvd, tong_kt, "Amount")
            _misa_gan(glvd_row, cols_glvd, False, "UnResonableCost")
            _misa_gan(glvd_row, cols_glvd, 0, "SortOrder")
            _misa_gan(glvd_row, cols_glvd, 0, "VATAmount")
            _misa_gan(glvd_row, cols_glvd, 0, "VATAmountOC")
            _misa_gan(glvd_row, cols_glvd, False, "IsListOnTaxDeclaration")
            _misa_gan(glvd_row, cols_glvd, 0, "LastExchangeRate")
            _misa_gan(glvd_row, cols_glvd, False, "NotIncludeInvoice")
            _misa_gan(glvd_row, cols_glvd, 3, "BusinessType")

            if not preview:
                lc = list(tk_row.keys())
                cur.execute("INSERT INTO TADeclaration ([%s]) VALUES (%s)" %
                           ("],[".join(lc), ",".join(["?"] * len(lc))), [tk_row[c] for c in lc])
                for d in det_rows:
                    lc = list(d.keys())
                    cur.execute("INSERT INTO TADeclarationDetail ([%s]) VALUES (%s)" %
                               ("],[".join(lc), ",".join(["?"] * len(lc))), [d[c] for c in lc])
                lc = list(glv_row.keys())
                cur.execute("INSERT INTO GLVoucher ([%s]) VALUES (%s)" %
                           ("],[".join(lc), ",".join(["?"] * len(lc))), [glv_row[c] for c in lc])
                lc = list(glvd_row.keys())
                cur.execute("INSERT INTO GLVoucherDetail ([%s]) VALUES (%s)" %
                           ("],[".join(lc), ",".join(["?"] * len(lc))), [glvd_row[c] for c in lc])
                for a in appendix_rows:
                    lc = list(a.keys())
                    cur.execute("INSERT INTO TADeclarationAppendix ([%s]) VALUES (%s)" %
                               ("],[".join(lc), ",".join(["?"] * len(lc))), [a[c] for c in lc])
                for d in chi_tiet_ban_ra:
                    lc = list(d.keys())
                    cur.execute("INSERT INTO TA_011GTGT_Detail ([%s]) VALUES (%s)" %
                               ("],[".join(lc), ",".join(["?"] * len(lc))), [d[c] for c in lc])
                for d in chi_tiet_mua_vao:
                    lc = list(d.keys())
                    cur.execute("INSERT INTO TA_012GTGT_Detail ([%s]) VALUES (%s)" %
                               ("],[".join(lc), ",".join(["?"] * len(lc))), [d[c] for c in lc])

            da_co_tk.add(ky_hien_thi)
            da_co_glv.add(memo)
            ct22_hien_tai = ct["ct43"]
            ket.append({"ky": ky_hien_thi, "trang_thai": "sẽ tạo" if preview else "đã tạo",
                       "thue_dau_ra": output_amount, "thue_duoc_khau_tru": deduction_amount,
                       "so_tien_khau_tru": tong_kt, "so_ct_khau_tru": refno_moi,
                       "so_dong_hoa_don_ban_ra": len(chi_tiet_ban_ra),
                       "so_dong_hoa_don_mua_vao": len(chi_tiet_mua_vao)})

        if preview:
            conn.rollback()
        else:
            conn.commit()
        return {"preview": preview, "database": database, "so_quy": len(ket), "danh_sach": ket,
                "tu_quy": tu_quy, "tu_nam": tu_nam, "so_quy_yeu_cau": so_quy}
    except HTTPException:
        conn.rollback()
        raise
    except Exception as e:
        conn.rollback()
        raise HTTPException(400, f"Lỗi tạo tờ khai GTGT / hạch toán khấu trừ: {e}")
    finally:
        conn.close()


@app.post("/api/misa-sql/to-khai-khau-tru-gtgt/{cid}")
def misa_sql_to_khai_khau_tru_gtgt(cid: int, preview: int = 1, database: str = "",
                                   tu_quy: int = 0, tu_nam: int = 0, so_quy: int = 4):
    """Tự động tạo Tờ khai 01/GTGT + hạch toán Khấu trừ thuế GTGT từng quý
    thẳng vào MISA (xem _misa_tao_to_khai_khau_tru_gtgt). tu_quy (1-4)/
    tu_nam: để trống (0) = tự tiếp nối quý kế tiếp sau tờ khai gần nhất.
    so_quy: số quý xử lý, mặc định 4."""
    database = (database or "").strip() or (_misa_sql_cfg(cid).get("database") or "")
    if not database:
        raise HTTPException(400, "Chưa cấu hình kết nối/CSDL MISA. Mở '🗄 Kết nối CSDL MISA', "
                                 "kết nối tới dữ liệu THỬ trước.")
    return _misa_tao_to_khai_khau_tru_gtgt(
        cid, database, preview=bool(preview),
        tu_quy=tu_quy or None, tu_nam=tu_nam or None, so_quy=so_quy)


# ============================================================
#  ĐỐI CHIẾU CÔNG NỢ (Giai đoạn 1: so sánh — CHỈ ĐỌC) + ĐỀ XUẤT BÙ CÔNG NỢ
#  "TREO" (Giai đoạn 2: tự tìm hóa đơn tiền mặt bị lỡ ghi công nợ, không ai
#  bao giờ thu/chi qua sổ, đề xuất — CHỈ GHI khi người dùng xác nhận từng
#  dòng). Dựa trên cấu trúc CSDL MISA THẬT của công ty (file CauTrucMISA
#  người dùng cung cấp) — AccountObjectLedger là sổ chi tiết công nợ theo
#  đối tượng (chỉ có dữ liệu cho chứng từ ĐÃ GHI SỔ); công ty này ghi nhận
#  giao dịch ngân hàng thực tế (đồng bộ Ngân hàng điện tử — cột
#  IsCreateFromEBHistory) ở 2 bảng RIÊNG theo chiều: BADeposit/BADepositDetail
#  (nộp tiền — thu tiền KH) và BAWithDraw/BAWithDrawDetail (rút tiền — chi
#  tiền NCC/Ủy nhiệm chi).
# ============================================================
def _misa_doi_chieu_cong_no(cid, database, loai="kh", tu_ngay=None, den_ngay=None):
    """Giai đoạn 1 — CHỈ ĐỌC, dựng lại đúng báo cáo MISA có sẵn: 'Báo cáo >
    Bán hàng > Tổng hợp công nợ phải thu khách hàng' (loai='kh', TK 131) /
    'Báo cáo > Mua hàng > Tổng hợp công nợ phải trả nhà cung cấp' (loai=
    'ncc', TK 331) — đọc THẲNG từ AccountObjectLedger theo khoảng ngày
    [tu_ngay, den_ngay] (lọc theo RefDate, dạng 'YYYY-MM-DD' hoặc
    'DD/MM/YYYY'; để trống = không giới hạn): Dư đầu kỳ (phát sinh trước
    tu_ngay) + Phát sinh Nợ/Có trong kỳ + Dư cuối kỳ, theo từng đối tượng.
    Nhóm theo AccountObjectID (đúng như MISA — 'Mã khách hàng/Mã NCC' trên
    báo cáo là AccountObjectCode, KHÔNG phải MST/AccountObjectTaxCode — rất
    nhiều đối tượng như 'Khách lẻ' hoặc NCC nước ngoài không có MST riêng
    nên nhóm theo MST làm rớt mất phần lớn danh sách, đã xác nhận qua đối
    chiếu file Excel 'Tổng hợp công nợ phải trả' thật của người dùng: nhóm
    theo MST chỉ còn 11/68 dòng). KHÔNG phụ thuộc Bảng kê Đầu ra/Đầu vào của
    phần mềm — dùng được cả khi hóa đơn được nhập/import thẳng vào MISA qua
    đường khác. Chỉ tính chứng từ ĐÃ GHI SỔ (đúng bản chất AccountObjectLedger)."""
    if loai not in ("kh", "ncc"):
        raise HTTPException(400, "loai phải là 'kh' hoặc 'ncc'.")
    tk_prefix = "131" if loai == "kh" else "331"
    tu_dt = _misa_doc_ngay(tu_ngay) if tu_ngay else None
    den_dt = _misa_doc_ngay(den_ngay) if den_ngay else None
    if den_dt:
        den_dt = den_dt.replace(hour=23, minute=59, second=59)

    conn = _misa_sql_connect(cid, database=database)
    try:
        cur = conn.cursor()
        rows = cur.execute(
            "SELECT AccountObjectID, ISNULL(AccountObjectCode,''), ISNULL(AccountObjectName,''), "
            "ISNULL(AccountObjectTaxCode,''), RefDate, DebitAmount, CreditAmount "
            "FROM AccountObjectLedger WHERE AccountNumber LIKE ? AND AccountObjectID IS NOT NULL",
            tk_prefix + "%").fetchall()
    finally:
        conn.close()

    agg = {}
    for aoid, ma, ten, mst, refdate, debit, credit in rows:
        key = str(aoid)
        if den_dt and refdate and refdate > den_dt:
            continue   # sau kỳ báo cáo -> bỏ qua hẳn
        d = agg.setdefault(key, {"ma": ma or "", "ten": ten or "", "mst": mst or "",
                                 "du_dau_no": 0.0, "du_dau_co": 0.0, "ps_no": 0.0, "ps_co": 0.0})
        if ma and not d["ma"]:
            d["ma"] = ma
        if ten and not d["ten"]:
            d["ten"] = ten
        debit = float(debit or 0)
        credit = float(credit or 0)
        if tu_dt and refdate and refdate < tu_dt:
            d["du_dau_no"] += debit
            d["du_dau_co"] += credit
        else:
            d["ps_no"] += debit
            d["ps_co"] += credit

    danh_sach = []
    for key, d in agg.items():
        du_dau = (d["du_dau_no"] - d["du_dau_co"]) if loai == "kh" else (d["du_dau_co"] - d["du_dau_no"])
        du_cuoi = (du_dau + d["ps_no"] - d["ps_co"]) if loai == "kh" else (du_dau + d["ps_co"] - d["ps_no"])
        if abs(round(du_cuoi)) < 1:
            continue   # đã hết công nợ (dư cuối kỳ = 0) -> không cần hiện, chỉ quan tâm đối tượng còn chênh lệch
        danh_sach.append({
            "account_object_id": key,
            "ma": d["ma"] or d["mst"] or "(không mã)", "ten": d["ten"], "mst": d["mst"],
            "du_dau_ky_no": round(max(du_dau, 0)), "du_dau_ky_co": round(max(-du_dau, 0)),
            "phat_sinh_no": round(d["ps_no"]), "phat_sinh_co": round(d["ps_co"]),
            "du_cuoi_ky_no": round(max(du_cuoi, 0)), "du_cuoi_ky_co": round(max(-du_cuoi, 0)),
            "du_cuoi_ky": round(du_cuoi),
        })
    danh_sach.sort(key=lambda x: (x["ma"]))
    return {"loai": loai, "database": database, "tu_ngay": tu_ngay, "den_ngay": den_ngay,
            "danh_sach": danh_sach}


@app.get("/api/misa-sql/doi-chieu-cong-no/{cid}")
def misa_sql_doi_chieu_cong_no(cid: int, loai: str = "kh", database: str = "",
                               tu_ngay: str = "", den_ngay: str = ""):
    database = (database or "").strip() or (_misa_sql_cfg(cid).get("database") or "")
    if not database:
        raise HTTPException(400, "Chưa cấu hình kết nối/CSDL MISA. Mở '🗄 Kết nối CSDL MISA', "
                                 "kết nối tới dữ liệu THỬ trước.")
    return _misa_doi_chieu_cong_no(cid, database, loai=loai, tu_ngay=tu_ngay or None,
                                   den_ngay=den_ngay or None)


def _misa_ngay_str(d):
    return d.strftime("%Y-%m-%d") if hasattr(d, "strftime") else str(d or "")


def _misa_la_dong_thue(tk):
    """Dòng thuế GTGT — TK đối ứng 133x (thuế GTGT đầu vào, mua hàng/NCC)
    hoặc 3331x (thuế GTGT đầu ra, bán hàng/KH). Dùng chung để tách 1 hóa đơn
    thành 2 THÀNH PHẦN: 'gt' (giá trị hàng hóa/dịch vụ) và 'vat' (thuế GTGT)
    — cho phép khớp công nợ Tầng 2 theo TỪNG THÀNH PHẦN khi khách/NCC chỉ
    thanh toán 1 PHẦN của hóa đơn trong 1 lần chuyển khoản gộp nhiều hóa đơn."""
    t = str(tk or "").strip()
    return t.startswith("133") or t.startswith("3331") or t.startswith("33311")


def _misa_doi_tuong_hoa_don(cur, tk_prefix, loai, account_object_id=None):
    """Danh sách hóa đơn (dòng phát sinh Nợ/Có TK 131/331 trong
    AccountObjectLedger, gộp theo RefID = 1 hóa đơn) theo từng đối tượng —
    KHÔNG mô phỏng FIFO, dùng để khớp trực tiếp với từng khoản thanh toán.
    Mỗi hóa đơn (hd) có thêm 'gt'/'vat' — tổng giá trị hàng hóa/dịch vụ và
    tổng thuế GTGT riêng (theo _misa_la_dong_thue) — để Tầng 2 có thể khớp
    theo TỪNG THÀNH PHẦN khi cần (hóa đơn bị 'tách' giữa 2 lần thanh toán).
    account_object_id: chỉ lấy 1 đối tượng (dùng cho màn chi tiết công nợ)."""
    phat_sinh_col = "DebitAmount" if loai == "kh" else "CreditAmount"
    sql = ("SELECT AccountObjectID, ISNULL(AccountObjectCode,''), ISNULL(AccountObjectTaxCode,''), "
          "ISNULL(AccountObjectName,''), RefID, InvNo, InvDate, RefDate, %s, "
          "ISNULL(CorrespondingAccountNumber,'') "
          "FROM AccountObjectLedger WHERE AccountNumber LIKE ? AND AccountObjectID IS NOT NULL "
          "AND %s > 0" % (phat_sinh_col, phat_sinh_col))
    params = [tk_prefix + "%"]
    if account_object_id:
        sql += " AND AccountObjectID = ?"
        params.append(account_object_id)
    rows = cur.execute(sql, params).fetchall()
    doi_tuong = {}
    for aoid, ma, mst, ten, refid, invno, invdate, refdate, tien, tk in rows:
        aoid = str(aoid)
        d = doi_tuong.setdefault(aoid, {"ma": ma or mst or "", "ten": ten or "", "hoa_don": {}})
        if ma and not d["ma"]:
            d["ma"] = ma
        if ten and not d["ten"]:
            d["ten"] = ten
        hd = d["hoa_don"].setdefault(str(refid), {"ref_id": str(refid), "inv_no": invno,
                                                    "inv_date": invdate or refdate, "so_tien": 0.0,
                                                    "gt": 0.0, "vat": 0.0})
        tien = float(tien or 0)
        hd["so_tien"] += tien
        if _misa_la_dong_thue(tk):
            hd["vat"] += tien
        else:
            hd["gt"] += tien
    for d in doi_tuong.values():
        d["hoa_don"] = list(d["hoa_don"].values())
    return doi_tuong


def _misa_doi_tuong_thanh_toan(cur, loai, account_object_id=None):
    """Danh sách khoản thanh toán NGÂN HÀNG THẬT theo từng đối tượng —
    loai='kh': NỘP tiền vào TK (thu tiền KH), bảng BADeposit/BADepositDetail,
    dòng Có 131; loai='ncc': RÚT tiền từ TK (chi tiền NCC — đúng bản chất
    'Ủy nhiệm chi'/UNC), bảng RIÊNG BAWithDraw/BAWithDrawDetail (KHÁC hẳn
    BADeposit — xác nhận qua đối chiếu thật: RefNoFinance='UNC076/3/2025',
    AccountObjectName='CÔNG TY TNHH OXYGEN RETAIL' nằm trong BAWithDraw,
    KHÔNG có trong BADeposit — dùng nhầm BADepositDetail cho NCC khiến tầng
    1/2 không tìm thấy khoản thanh toán nào, mọi hóa đơn NCC đều lọt vào
    tầng 3 dù thực tế đã có thanh toán), dòng Nợ 331."""
    if loai == "kh":
        master, detail, tk_cot, tk_val = "BADeposit", "BADepositDetail", "CreditAccount", "131%"
    else:
        master, detail, tk_cot, tk_val = "BAWithDraw", "BAWithDrawDetail", "DebitAccount", "331%"
    sql = ("SELECT bd.AccountObjectID, b.RefDate, bd.Amount, bd.RefID "
          "FROM %s bd JOIN %s b ON bd.RefID = b.RefID "
          "WHERE bd.AccountObjectID IS NOT NULL AND bd.%s LIKE ? AND bd.Amount > 0"
          % (detail, master, tk_cot))
    params = [tk_val]
    if account_object_id:
        sql += " AND bd.AccountObjectID = ?"
        params.append(account_object_id)
    rows = cur.execute(sql, params).fetchall()
    doi_tuong = {}
    for aoid, refdate, tien, refid in rows:
        doi_tuong.setdefault(str(aoid), []).append(
            {"ref_id": str(refid), "date": refdate, "so_tien": float(tien or 0)})
    return doi_tuong


def _misa_khop_1_2(doi_tuong_hd, doi_tuong_tt, cua_so_thang=3, max_to_hop=8, dung_sai=20_000,
                   truoc_ngay=7):
    """Chạy Tầng 1 (khớp 1-1 chính xác) + Tầng 2 (khớp tổ hợp nhiều hóa đơn,
    kể cả hóa đơn KHÔNG liên tiếp — ví dụ HĐ 1;2;5 mà bỏ qua 3;4, vì khách/NCC
    gộp nhiều hóa đơn để thanh toán 1 cục) — MUTATE cờ 'matched' trên từng hóa
    đơn (hd)/khoản thanh toán (tt) ngay trong doi_tuong_hd/doi_tuong_tt, trả về
    (tang1, tang2, khong_ro).

    Tầng 2 xử lý các khoản thanh toán THEO THỨ TỰ NGÀY (sớm nhất trước, đúng
    kiểu kế toán đối chiếu 'từ trên xuống, cộng dồn'), với 2 bước cho MỖI
    khoản thanh toán:
      (a) thử khớp tổ hợp các HÓA ĐƠN NGUYÊN (chưa hóa đơn nào bị tách dở);
      (b) nếu không có tổ hợp hóa đơn nguyên nào khớp, thử khớp theo TỪNG
          THÀNH PHẦN của hóa đơn ('gt'=giá trị hàng hóa/dịch vụ, 'vat'=thuế
          GTGT — theo _misa_la_dong_thue) — cho phép 1 hóa đơn bị TÁCH: 1
          phần gán cho khoản thanh toán này, phần còn lại chờ khoản sau (vì
          khách/NCC nhiều khi chỉ thanh toán 1 PHẦN của 1 hóa đơn gộp chung
          với các hóa đơn khác trong 1 lần chuyển khoản).
    Nhờ xử lý theo thứ tự ngày, hóa đơn ở đầu kỳ được ưu tiên gán cho khoản
    thanh toán SỚM NHẤT có thể trước, tránh 1 hóa đơn bị 'khớp nguyên' vào
    nhầm 1 khoản thanh toán muộn hơn trong khi lẽ ra 1 phần của nó cần dùng
    cho khoản thanh toán sớm hơn.

    dung_sai (đ): tổ hợp Tầng 2 được chấp nhận khớp dù lệch tối đa dung_sai
    đồng so với khoản thanh toán thật (bù phí chuyển khoản ngân hàng khi gộp
    nhiều hóa đơn) — CHỈ áp dụng khi không có tổ hợp nào khớp CHÍNH XÁC (ưu
    tiên khớp tuyệt đối trước).

    truoc_ngay (ngày): 1 khoản thanh toán chỉ được xét cho 1 hóa đơn nếu
    thanh toán đó không SỚM HƠN (ngày hóa đơn - truoc_ngay). Mặc định 7 ngày
    (nới nhẹ, an toàn). LƯU Ý: nới rộng số này có thể giúp tìm thêm được vài
    khoản khớp 'ngược thời gian' (thanh toán trước ngày hóa đơn khá lâu) —
    nhưng với NHÀ CUNG CẤP có nhiều hóa đơn GIÁ TRỊ GIỐNG/GẦN NHAU lặp lại
    hàng tháng (điện nước, thuê mặt bằng...), nới rộng cũng làm TĂNG nguy cơ
    có NHIỀU tổ hợp cùng khớp (rơi vào 'không rõ') ở CÁC khoản thanh toán
    khác — nên thử tăng dần và so sánh kết quả trước khi tin dùng.

    Dùng chung cho cả bảng tổng hợp 3 tầng (_misa_doi_chieu_3_tang) và màn
    chi tiết công nợ 1 đối tượng (_misa_chi_tiet_cong_no)."""
    dung_sai = max(0, int(dung_sai or 0))
    cua_so = datetime.timedelta(days=30 * int(cua_so_thang))
    dem_truoc = datetime.timedelta(days=max(0, int(truoc_ngay or 0)))
    tang1, tang2, khong_ro, tam_ung = [], [], [], []
    ngay_xa = datetime.datetime(1, 1, 1)

    def trong_cua_so(hd, tt):
        if not hd["inv_date"] or not tt["date"]:
            return False
        return (hd["inv_date"] - dem_truoc) <= tt["date"] <= (hd["inv_date"] + cua_so)

    def tim_to_hop(ung_vien, so_tien, nguong_lech):
        khop = []
        for k in range(2, min(max_to_hop, len(ung_vien)) + 1):
            for to_hop in itertools.combinations(ung_vien, k):
                if abs(sum(h["so_tien"] for h in to_hop) - so_tien) <= nguong_lech:
                    khop.append(to_hop)
                    if len(khop) > 1:
                        break
            if len(khop) > 1:
                break
        return khop

    def thanh_phan_con_lai(hd):
        """Các thành phần CHƯA gán cho khoản thanh toán nào của 1 hóa đơn —
        'gt'/'vat' riêng nếu hóa đơn có cả 2 (tách được), hoặc 'full' nếu
        hóa đơn chỉ có 1 loại dòng (không tách được giá trị/thuế riêng)."""
        da_dung = hd["phan_dung"]
        gt, vat = hd.get("gt", 0.0), hd.get("vat", 0.0)
        ra = []
        if gt and vat:
            if "gt" not in da_dung:
                ra.append({"hd": hd, "phan": "gt", "so_tien": gt})
            if "vat" not in da_dung:
                ra.append({"hd": hd, "phan": "vat", "so_tien": vat})
        elif "full" not in da_dung:
            ra.append({"hd": hd, "phan": "full", "so_tien": hd["so_tien"]})
        return ra

    def danh_dau_dung(hd, phan):
        hd["phan_dung"].add(phan)
        gt, vat = hd.get("gt", 0.0), hd.get("vat", 0.0)
        day_du = {"gt", "vat"} if (gt and vat) else {"full"}
        if hd["phan_dung"] >= day_du:
            hd["matched"] = True

    def danh_dau_ca_hoa_don(hd):
        """Đánh dấu TOÀN BỘ hóa đơn đã dùng (Tầng 1 hoặc tổ hợp hóa đơn
        NGUYÊN ở Tầng 2) — cả 2 thành phần gt/vat nếu có, hoặc 'full'."""
        gt, vat = hd.get("gt", 0.0), hd.get("vat", 0.0)
        if gt and vat:
            danh_dau_dung(hd, "gt")
            danh_dau_dung(hd, "vat")
        else:
            danh_dau_dung(hd, "full")

    for aoid, d in doi_tuong_hd.items():
        ma, ten = d["ma"], d["ten"]
        hds = sorted(d["hoa_don"], key=lambda h: h["inv_date"] or ngay_xa)
        for hd in hds:
            hd["matched"] = False
            hd["phan_dung"] = set()
        tts = sorted(doi_tuong_tt.get(aoid, []), key=lambda t: t["date"] or ngay_xa)
        for tt in tts:
            tt["matched"] = False

        # Tầng 1 — khớp 1-1 chính xác
        for tt in tts:
            ung_vien = [hd for hd in hds if not hd["matched"] and trong_cua_so(hd, tt)
                       and abs(hd["so_tien"] - tt["so_tien"]) <= 1]
            if len(ung_vien) == 1:
                danh_dau_ca_hoa_don(ung_vien[0])
                tt["matched"] = True
                tang1.append({"ma": ma, "ten": ten, "inv_no": ung_vien[0]["inv_no"],
                              "inv_date": _misa_ngay_str(ung_vien[0]["inv_date"]),
                              "so_tien": round(ung_vien[0]["so_tien"]),
                              "ngay_thanh_toan": _misa_ngay_str(tt["date"])})
            elif len(ung_vien) > 1:
                khong_ro.append({"ma": ma, "ten": ten, "loai_vuong": "Nhiều hóa đơn trùng giá trị",
                                 "ngay_thanh_toan": _misa_ngay_str(tt["date"]),
                                 "so_tien": round(tt["so_tien"]),
                                 "ung_vien": [{"inv_no": h["inv_no"], "inv_date": _misa_ngay_str(h["inv_date"]),
                                              "so_tien": round(h["so_tien"])} for h in ung_vien]})

        # Tầng 2 — xét khoản thanh toán CHƯA khớp ở tầng 1, THEO THỨ TỰ NGÀY
        for tt in tts:
            if tt["matched"]:
                continue

            # (a) tổ hợp các hóa đơn NGUYÊN (chưa bị tách dở phần nào)
            ung_vien_hd = [hd for hd in hds if not hd["matched"] and not hd["phan_dung"]
                          and trong_cua_so(hd, tt)]
            to_hop_khop = []
            if 2 <= len(ung_vien_hd) <= 20:
                to_hop_khop = tim_to_hop(ung_vien_hd, tt["so_tien"], 1)
                if not to_hop_khop and dung_sai > 1:
                    to_hop_khop = tim_to_hop(ung_vien_hd, tt["so_tien"], dung_sai)
            if len(to_hop_khop) == 1:
                for hd in to_hop_khop[0]:
                    danh_dau_ca_hoa_don(hd)
                tt["matched"] = True
                lech = round(tt["so_tien"] - sum(h["so_tien"] for h in to_hop_khop[0]))
                tang2.append({"ma": ma, "ten": ten, "ngay_thanh_toan": _misa_ngay_str(tt["date"]),
                              "so_tien": round(tt["so_tien"]), "lech": lech,
                              "hoa_don": [{"inv_no": h["inv_no"], "inv_date": _misa_ngay_str(h["inv_date"]),
                                          "so_tien": round(h["so_tien"])} for h in to_hop_khop[0]]})
                continue
            elif len(to_hop_khop) > 1:
                khong_ro.append({"ma": ma, "ten": ten, "loai_vuong": "Nhiều tổ hợp hóa đơn cùng khớp",
                                 "ngay_thanh_toan": _misa_ngay_str(tt["date"]),
                                 "so_tien": round(tt["so_tien"])})
                continue

            # (b) không có tổ hợp hóa đơn NGUYÊN nào khớp -> thử khớp theo
            # TỪNG THÀNH PHẦN (giá trị/thuế GTGT riêng), cho phép TÁCH hóa
            # đơn — ví dụ HĐ A + HĐ B (trọn) + 1 dòng GIÁ TRỊ (không kèm
            # thuế) của HĐ C, phần thuế GTGT của HĐ C còn lại chờ khoản
            # thanh toán sau.
            ung_vien_hd2 = [hd for hd in hds if not hd["matched"] and trong_cua_so(hd, tt)]
            don_vi = []
            for hd in ung_vien_hd2:
                don_vi.extend(thanh_phan_con_lai(hd))
            if not (2 <= len(don_vi) <= 16):
                continue   # quá nhiều thành phần -> không dò, tránh bùng nổ tổ hợp
            to_hop_dong = tim_to_hop(don_vi, tt["so_tien"], 1)
            if not to_hop_dong and dung_sai > 1:
                to_hop_dong = tim_to_hop(don_vi, tt["so_tien"], dung_sai)
            if len(to_hop_dong) == 1:
                combo = to_hop_dong[0]
                for dv in combo:
                    danh_dau_dung(dv["hd"], dv["phan"])
                tt["matched"] = True
                lech = round(tt["so_tien"] - sum(dv["so_tien"] for dv in combo))
                tang2.append({"ma": ma, "ten": ten, "ngay_thanh_toan": _misa_ngay_str(tt["date"]),
                              "so_tien": round(tt["so_tien"]), "lech": lech,
                              "hoa_don": [{"inv_no": dv["hd"]["inv_no"],
                                          "inv_date": _misa_ngay_str(dv["hd"]["inv_date"]),
                                          "so_tien": round(dv["so_tien"]),
                                          "phan": None if dv["phan"] == "full" else dv["phan"]}
                                         for dv in combo]})
            elif len(to_hop_dong) > 1:
                khong_ro.append({"ma": ma, "ten": ten, "loai_vuong": "Nhiều tổ hợp DÒNG hóa đơn cùng khớp",
                                 "ngay_thanh_toan": _misa_ngay_str(tt["date"]),
                                 "so_tien": round(tt["so_tien"])})

        # Tầng 2b — Tạm ứng/Ứng trước: 1 (hoặc nhiều) khoản thanh toán đến
        # TRƯỚC mà Tầng 1/2 không khớp được hóa đơn/tổ hợp nào gần đó, rồi
        # NHIỀU hóa đơn xuất RA SAU đó theo từng đợt (có thể rất nhiều đợt,
        # không giới hạn như tổ hợp Tầng 2) — CỘNG DỒN TUẦN TỰ theo đúng thứ
        # tự ngày (khoản thanh toán +, hóa đơn -) cho tới khi số dư lũy kế về
        # ~0 (trong ngưỡng dung_sai) thì xác nhận cả khối là 1 lần tạm ứng đã
        # được dùng hết; khối mở quá lâu (> cua_so_thang tháng) mà chưa cân
        # bằng thì bỏ dở (không đoán bừa), coi các hóa đơn/thanh toán đó vẫn
        # treo như bình thường.
        con_lai_tt = [tt for tt in tts if not tt["matched"]]
        con_lai_hd = [hd for hd in hds if not hd["matched"] and not hd["phan_dung"]]
        su_kien = sorted(
            [{"loai": "tt", "date": tt["date"] or ngay_xa, "item": tt} for tt in con_lai_tt] +
            [{"loai": "hd", "date": hd["inv_date"] or ngay_xa, "item": hd} for hd in con_lai_hd],
            key=lambda e: e["date"])
        khoi_tt, khoi_hd, running, khoi_bd = [], [], 0.0, None
        for sk in su_kien:
            if khoi_bd is not None and (sk["date"] - khoi_bd) > cua_so:
                khoi_tt, khoi_hd, running, khoi_bd = [], [], 0.0, None
            if sk["loai"] == "hd":
                if khoi_bd is None:
                    continue   # chưa có khoản tạm ứng nào đang mở -> để bước khác xử lý
                running -= sk["item"]["so_tien"]
                khoi_hd.append(sk["item"])
            else:
                if khoi_bd is None:
                    khoi_bd = sk["date"]
                running += sk["item"]["so_tien"]
                khoi_tt.append(sk["item"])
            if khoi_hd and abs(running) <= dung_sai:
                for tt in khoi_tt:
                    tt["matched"] = True
                for hd in khoi_hd:
                    danh_dau_ca_hoa_don(hd)
                tam_ung.append({"ma": ma, "ten": ten,
                                "tu_ngay": _misa_ngay_str(khoi_tt[0]["date"]),
                                "den_ngay": _misa_ngay_str(khoi_hd[-1]["inv_date"]),
                                "tong_tam_ung": round(sum(t["so_tien"] for t in khoi_tt)),
                                "tong_hoa_don": round(sum(h["so_tien"] for h in khoi_hd)),
                                "lech": round(running),
                                "thanh_toan": [{"ngay": _misa_ngay_str(t["date"]),
                                               "so_tien": round(t["so_tien"])} for t in khoi_tt],
                                "hoa_don": [{"inv_no": h["inv_no"], "inv_date": _misa_ngay_str(h["inv_date"]),
                                            "so_tien": round(h["so_tien"])} for h in khoi_hd]})
                khoi_tt, khoi_hd, running, khoi_bd = [], [], 0.0, None
    return tang1, tang2, khong_ro, tam_ung


def _misa_doi_chieu_3_tang(cid, database, loai="ncc", cua_so_thang=3, thang_qua_han=10,
                           nguong=5_000_000, max_to_hop=8, tu_ngay=None, den_ngay=None,
                           dung_sai=20_000, truoc_ngay=7):
    """Đối chiếu công nợ 3 TẦNG (CHỈ ĐỌC — tầng 1/2 chỉ liệt kê để biết,
    KHÔNG ghi gì; tầng 3 cho xuất Excel điều chỉnh, cần xác nhận riêng).

    tu_ngay/den_ngay (nếu có — ĐÚNG khung người dùng tự nhập, không cố định
    kỳ nào) lọc TRƯỚC hết danh sách HÓA ĐƠN được xét ở CẢ 3 TẦNG, theo ngày
    hóa đơn. Khoản THANH TOÁN không bị giới hạn theo khung này — thanh toán
    có thể tới sau kỳ báo cáo mà vẫn hợp lệ, do cửa sổ khớp (cua_so_thang)
    tính từ ngày hóa đơn đã xử lý việc đó. Không nhập ngày nào thì tầng 3
    dùng 'quá hạn hơn thang_qua_han tháng tính từ hôm nay' như mặc định cũ.

    Tầng 1 — khớp 1-1 chính xác: mỗi khoản thanh toán ngân hàng thật (đã
    nhập vào MISA — xem _misa_doi_tuong_thanh_toan) so số tiền với TỪNG hóa
    đơn đang nợ của ĐÚNG đối tượng đó, chỉ xét hóa đơn có ngày nằm trong cửa sổ
    [ngày hóa đơn - 7 ngày, ngày hóa đơn + cua_so_thang tháng] (thanh toán
    quá xa ngày hóa đơn thì không tính, dù trùng số tiền — coi là trùng
    ngẫu nhiên). Nếu CHỈ 1 hóa đơn khớp đúng số tiền trong cửa sổ đó -> ghi
    nhận khớp. Nếu NHIỀU hóa đơn cùng khớp (trùng giá trị) -> đưa vào
    'không rõ', không đoán bừa hóa đơn nào.

    Tầng 2 — khớp TỔ HỢP nhiều hóa đơn cộng lại đúng bằng 1 khoản thanh
    toán (tối đa max_to_hop hóa đơn/tổ hợp, tránh bùng nổ tổ hợp). Chỉ tự
    xác nhận khi có ĐÚNG 1 tổ hợp khớp; nhiều tổ hợp cùng khớp -> 'không rõ'.

    Tầng 3 — hóa đơn còn lại (không khớp được ở tầng 1/2 với bất kỳ khoản
    thanh toán ngân hàng nào), giá trị < nguong -> coi là hóa đơn tiền mặt
    bị lỡ ghi công nợ, đưa ra để xuất Excel điều chỉnh (Nợ/Có 1111 đối ứng
    131/331)."""
    if loai not in ("kh", "ncc"):
        raise HTTPException(400, "loai phải là 'kh' hoặc 'ncc'.")
    tk_prefix = "131" if loai == "kh" else "331"
    conn = _misa_sql_connect(cid, database=database)
    try:
        cur = conn.cursor()
        doi_tuong_hd = _misa_doi_tuong_hoa_don(cur, tk_prefix, loai)
        doi_tuong_tt = _misa_doi_tuong_thanh_toan(cur, loai)
    finally:
        conn.close()

    # Lọc HÓA ĐƠN theo ĐÚNG khung Từ ngày/Đến ngày người dùng nhập — áp dụng
    # cho CẢ 3 TẦNG (không chỉ tầng 3), đúng khung bất kỳ người dùng gõ vào,
    # không cố định 1 kỳ nào. Khoản THANH TOÁN không bị giới hạn theo khung
    # này — thanh toán có thể tới sau kỳ báo cáo mà vẫn hợp lệ (cửa sổ khớp
    # cua_so_thang bên dưới đã xử lý việc đó, tính từ ngày hóa đơn).
    tu_dt = _misa_doc_ngay(tu_ngay) if tu_ngay else None
    den_dt = _misa_doc_ngay(den_ngay) if den_ngay else None
    if den_dt:
        den_dt = den_dt.replace(hour=23, minute=59, second=59)
    if tu_dt or den_dt:
        for d in doi_tuong_hd.values():
            d["hoa_don"] = [hd for hd in d["hoa_don"] if hd["inv_date"]
                            and (not tu_dt or hd["inv_date"] >= tu_dt)
                            and (not den_dt or hd["inv_date"] <= den_dt)]

    tang1, tang2, khong_ro, tam_ung = _misa_khop_1_2(doi_tuong_hd, doi_tuong_tt,
                                            cua_so_thang=cua_so_thang, max_to_hop=max_to_hop,
                                            dung_sai=dung_sai, truoc_ngay=truoc_ngay)

    # Tầng 3 — hóa đơn đã được lọc đúng khung Từ ngày/Đến ngày ở bước đầu
    # (nếu có nhập); không nhập ngày nào thì dùng "quá hạn hơn N tháng".
    han = None if (tu_dt or den_dt) else (
        datetime.datetime.now() - datetime.timedelta(days=30 * int(thang_qua_han)))
    tang3 = []
    for aoid, d in doi_tuong_hd.items():
        for hd in d["hoa_don"]:
            if hd["matched"] or hd["so_tien"] >= nguong:
                continue
            if not hd["inv_date"]:
                continue
            if han is not None and hd["inv_date"] > han:
                continue
            tang3.append({"account_object_id": aoid, "mst": d["ma"], "ten": d["ten"],
                          "ref_id": hd["ref_id"], "inv_no": hd["inv_no"],
                          "inv_date": _misa_ngay_str(hd["inv_date"]), "so_tien": round(hd["so_tien"])})

    tang1.sort(key=lambda x: (x["ma"], x["inv_date"]))
    tang2.sort(key=lambda x: (x["ma"], x["ngay_thanh_toan"]))
    tam_ung.sort(key=lambda x: (x["ma"], x["tu_ngay"]))
    tang3.sort(key=lambda x: (x["mst"], x["inv_date"]))
    return {"loai": loai, "database": database, "cua_so_thang": cua_so_thang, "tu_ngay": tu_ngay,
            "den_ngay": den_ngay,
            "thang_qua_han": thang_qua_han, "nguong": nguong, "dung_sai": dung_sai,
            "truoc_ngay": truoc_ngay,
            "tang1": tang1, "tang2": tang2, "tam_ung": tam_ung, "khong_ro": khong_ro, "tang3": tang3}


@app.get("/api/misa-sql/doi-chieu-3-tang/{cid}")
def misa_sql_doi_chieu_3_tang(cid: int, loai: str = "kh", cua_so_thang: int = 3,
                              thang_qua_han: int = 10, nguong: float = 5_000_000,
                              dung_sai: float = 20_000, truoc_ngay: int = 7,
                              database: str = "", tu_ngay: str = "", den_ngay: str = ""):
    database = (database or "").strip() or (_misa_sql_cfg(cid).get("database") or "")
    if not database:
        raise HTTPException(400, "Chưa cấu hình kết nối/CSDL MISA. Mở '🗄 Kết nối CSDL MISA', "
                                 "kết nối tới dữ liệu THỬ trước.")
    return _misa_doi_chieu_3_tang(cid, database, loai=loai, cua_so_thang=cua_so_thang,
                                  thang_qua_han=thang_qua_han, nguong=nguong, dung_sai=dung_sai,
                                  truoc_ngay=truoc_ngay,
                                  tu_ngay=tu_ngay or None, den_ngay=den_ngay or None)


def _misa_chi_tiet_cong_no(cid, database, loai, account_object_id, tu_ngay=None, den_ngay=None,
                           cua_so_thang=3, max_to_hop=8, dung_sai=20_000, truoc_ngay=7,
                           nguong=5_000_000, thang_qua_han=10):
    """Chi tiết công nợ 1 đối tượng (CHỈ ĐỌC) — dựng lại đúng báo cáo MISA
    'Chi tiết công nợ phải thu/phải trả' (từng dòng chứng từ + số dư lũy
    kế theo đúng mẫu Excel người dùng cung cấp: Ngày hạch toán, Ngày chứng
    từ, Số chứng từ, Số hóa đơn, Diễn giải, TK đối ứng, Phát sinh Nợ/Có, Số
    dư Nợ/Có), CÓ kèm kết quả khớp 3 tầng cho đối tượng này.

    'treo': True (tô đỏ) CHỈ đánh dấu cho hóa đơn thật sự là ứng viên TẦNG 3
    — tức chưa khớp được thanh toán nào (kể cả Tầng 2b tạm ứng), giá trị
    dưới nguong, và đủ điều kiện quá hạn (giống hệt tiêu chí Tầng 3 trong
    _misa_doi_chieu_3_tang) — nghĩa là hóa đơn SẼ được đề xuất xử lý điều
    chỉnh về tiền mặt. Hóa đơn CHƯA khớp nhưng KHÔNG đủ điều kiện Tầng 3
    (giá trị lớn, hoặc còn quá mới) không tô đỏ — đó là công nợ bình thường
    chưa tới hạn xử lý, không phải diện cần chú ý ngay. Khi 1 hóa đơn đủ
    điều kiện tô đỏ, CẢ 2 dòng 'Giá trị hàng hóa/dịch vụ' và 'Thuế GTGT'
    đều tô đỏ (không tách theo từng phần đã khớp/chưa khớp nữa)."""
    if loai not in ("kh", "ncc"):
        raise HTTPException(400, "loai phải là 'kh' hoặc 'ncc'.")
    tk_prefix = "131" if loai == "kh" else "331"
    tu_dt = _misa_doc_ngay(tu_ngay) if tu_ngay else None
    den_dt = _misa_doc_ngay(den_ngay) if den_ngay else None
    if den_dt:
        den_dt = den_dt.replace(hour=23, minute=59, second=59)

    conn = _misa_sql_connect(cid, database=database)
    try:
        cur = conn.cursor()
        rows = cur.execute(
            "SELECT RefID, RefDate, PostedDate, ISNULL(RefNo,''), ISNULL(InvNo,''), "
            "ISNULL(JournalMemo,''), ISNULL(Description,''), ISNULL(CorrespondingAccountNumber,''), "
            "DebitAmount, CreditAmount, ISNULL(AccountObjectCode,''), ISNULL(AccountObjectName,'') "
            "FROM AccountObjectLedger WHERE AccountObjectID = ? AND AccountNumber LIKE ? "
            "ORDER BY RefDate, RefID, PostedDate", account_object_id, tk_prefix + "%").fetchall()
        doi_tuong_hd = _misa_doi_tuong_hoa_don(cur, tk_prefix, loai, account_object_id=account_object_id)
        doi_tuong_tt = _misa_doi_tuong_thanh_toan(cur, loai, account_object_id=account_object_id)
    finally:
        conn.close()

    if not rows:
        raise HTTPException(404, "Không tìm thấy chứng từ công nợ nào cho đối tượng này.")

    ma = ten = ""
    for r in rows:
        if r[10]:
            ma = r[10]
        if r[11]:
            ten = r[11]
        if ma and ten:
            break

    d = doi_tuong_hd.get(str(account_object_id), {"ma": ma, "ten": ten, "hoa_don": []})
    if tu_dt or den_dt:
        d["hoa_don"] = [hd for hd in d["hoa_don"] if hd["inv_date"]
                        and (not tu_dt or hd["inv_date"] >= tu_dt)
                        and (not den_dt or hd["inv_date"] <= den_dt)]
    tang1, tang2, khong_ro, tam_ung = _misa_khop_1_2({str(account_object_id): d}, doi_tuong_tt,
                                            cua_so_thang=cua_so_thang, max_to_hop=max_to_hop,
                                            dung_sai=dung_sai, truoc_ngay=truoc_ngay)
    # Tiêu chí TẦNG 3 y hệt _misa_doi_chieu_3_tang: chưa khớp + giá trị dưới
    # nguong + đủ điều kiện quá hạn (nếu có lọc theo tu_ngay/den_ngay thì bỏ
    # qua điều kiện quá hạn, giống hệt logic gốc).
    han3 = None if (tu_dt or den_dt) else (
        datetime.datetime.now() - datetime.timedelta(days=30 * int(thang_qua_han)))
    tang3_ref_ids = {
        hd["ref_id"] for hd in d["hoa_don"]
        if not hd["matched"] and hd["so_tien"] < nguong and hd["inv_date"]
        and (han3 is None or hd["inv_date"] <= han3)
    }
    so_treo = len(tang3_ref_ids)

    du_dau_no = du_dau_co = 0.0
    for _rid, refdate, _pd, _rn, _inv, _jm, _de, _tk, debit, credit, _ma, _ten in rows:
        if tu_dt and refdate and refdate < tu_dt:
            du_dau_no += float(debit or 0)
            du_dau_co += float(credit or 0)
    du_dau = (du_dau_no - du_dau_co) if loai == "kh" else (du_dau_co - du_dau_no)
    so_du = du_dau

    dong = [{"ngay_hach_toan": "", "ngay_chung_tu": "", "so_chung_tu": "", "so_hoa_don": "",
            "dien_giai": "Số dư đầu kỳ", "tk_doi_ung": "", "ps_no": 0, "ps_co": 0,
            "du_no": round(max(so_du, 0)), "du_co": round(max(-so_du, 0)), "treo": False}]

    # Dòng thuộc 1 HÓA ĐƠN (có Số hóa đơn) gộp còn tối đa 2 dòng hiển thị —
    # "Giá trị hàng hóa/dịch vụ" (mọi dòng không phải thuế cộng lại) và
    # "Thuế GTGT" (mọi dòng thuế cộng lại) — đúng theo mẫu Excel người dùng
    # cung cấp, không hiện chi tiết từng dòng mặt hàng/khoản mục bên trong.
    # Dòng KHÔNG có Số hóa đơn (phiếu thu/chi, điều chỉnh...) giữ nguyên.
    loc = [r for r in rows
          if not (tu_dt and r[1] and r[1] < tu_dt) and not (den_dt and r[1] and r[1] > den_dt)]
    i = 0
    while i < len(loc):
        rid, refdate, postdate, refno, invno, jm, de, tk, debit, credit, _ma, _ten = loc[i]
        if not invno:
            debit = float(debit or 0)
            credit = float(credit or 0)
            so_du += (debit - credit) if loai == "kh" else (credit - debit)
            dong.append({
                "ngay_hach_toan": _misa_ngay_str(postdate), "ngay_chung_tu": _misa_ngay_str(refdate),
                "so_chung_tu": refno, "so_hoa_don": invno, "dien_giai": jm or de,
                "tk_doi_ung": tk, "ps_no": round(debit), "ps_co": round(credit),
                "du_no": round(max(so_du, 0)), "du_co": round(max(-so_du, 0)),
                "treo": False,
            })
            i += 1
            continue
        j = i
        gt_no = gt_co = vat_no = vat_co = 0.0
        gt_tk, vat_tk = set(), set()
        while j < len(loc) and loc[j][0] == rid:
            _r2, rd2, pd2, rn2, inv2, jm2, de2, tk2, d2, c2, _m2, _t2 = loc[j]
            d2 = float(d2 or 0)
            c2 = float(c2 or 0)
            if _misa_la_dong_thue(tk2):
                vat_no += d2; vat_co += c2
                if tk2:
                    vat_tk.add(str(tk2))
            else:
                gt_no += d2; gt_co += c2
                if tk2:
                    gt_tk.add(str(tk2))
            j += 1
        # Chỉ tô đỏ hóa đơn thật sự là ứng viên TẦNG 3 (sẽ đề xuất xử lý điều
        # chỉnh về tiền mặt) — CẢ 2 dòng giá trị/thuế cùng tô đỏ khi đó, chứ
        # không tô đỏ mọi hóa đơn chỉ vì "chưa khớp" (công nợ lớn/còn mới
        # chưa tới hạn xử lý thì không phải diện cần chú ý ngay).
        treo_gt = treo_vat = str(rid) in tang3_ref_ids
        if gt_no or gt_co:
            so_du += (gt_no - gt_co) if loai == "kh" else (gt_co - gt_no)
            dong.append({
                "ngay_hach_toan": _misa_ngay_str(postdate), "ngay_chung_tu": _misa_ngay_str(refdate),
                "so_chung_tu": refno, "so_hoa_don": invno, "dien_giai": "Giá trị hàng hóa/dịch vụ",
                "tk_doi_ung": ", ".join(sorted(gt_tk)), "ps_no": round(gt_no), "ps_co": round(gt_co),
                "du_no": round(max(so_du, 0)), "du_co": round(max(-so_du, 0)), "treo": treo_gt,
            })
        if vat_no or vat_co:
            so_du += (vat_no - vat_co) if loai == "kh" else (vat_co - vat_no)
            dong.append({
                "ngay_hach_toan": _misa_ngay_str(postdate), "ngay_chung_tu": _misa_ngay_str(refdate),
                "so_chung_tu": refno, "so_hoa_don": invno, "dien_giai": "Thuế GTGT",
                "tk_doi_ung": ", ".join(sorted(vat_tk)), "ps_no": round(vat_no), "ps_co": round(vat_co),
                "du_no": round(max(so_du, 0)), "du_co": round(max(-so_du, 0)), "treo": treo_vat,
            })
        i = j

    return {"loai": loai, "account_object_id": str(account_object_id),
            "ma": d.get("ma") or ma, "ten": d.get("ten") or ten,
            "dong": dong, "tang1": tang1, "tang2": tang2, "tam_ung": tam_ung, "khong_ro": khong_ro,
            "so_treo": so_treo}


@app.get("/api/misa-sql/chi-tiet-cong-no/{cid}")
def misa_sql_chi_tiet_cong_no(cid: int, loai: str = "kh", account_object_id: str = "",
                              tu_ngay: str = "", den_ngay: str = "", cua_so_thang: int = 3,
                              max_to_hop: int = 8, dung_sai: float = 20_000, truoc_ngay: int = 7,
                              nguong: float = 5_000_000, thang_qua_han: int = 10,
                              database: str = ""):
    database = (database or "").strip() or (_misa_sql_cfg(cid).get("database") or "")
    if not database:
        raise HTTPException(400, "Chưa cấu hình kết nối/CSDL MISA. Mở '🗄 Kết nối CSDL MISA', "
                                 "kết nối tới dữ liệu THỬ trước.")
    if not account_object_id:
        raise HTTPException(400, "Thiếu account_object_id.")
    return _misa_chi_tiet_cong_no(cid, database, loai, account_object_id, tu_ngay=tu_ngay or None,
                                  den_ngay=den_ngay or None, cua_so_thang=cua_so_thang,
                                  max_to_hop=max_to_hop, dung_sai=dung_sai, truoc_ngay=truoc_ngay,
                                  nguong=nguong, thang_qua_han=thang_qua_han)


def _misa_ghi_bu_tru_treo(cid, database, loai, danh_sach, preview=True):
    """Ghi phiếu Thu tiền mặt (loai='kh': Nợ 1111/Có 131, bảng CAReceipt/
    CAReceiptDetail) hoặc Chi tiền mặt (loai='ncc': Nợ 331/Có 1111, bảng
    CAPayment/CAPaymentDetail) để tất toán các hóa đơn 'treo' NGƯỜI DÙNG ĐÃ
    XÁC NHẬN ở bước đối chiếu 3 tầng (_misa_doi_chieu_3_tang, tầng 3) — coi
    như thu/chi tiền mặt ngay lúc phát sinh nhưng trước đó lỡ ghi công nợ.
    LUÔN ghi CHƯA GHI
    SỔ (như mọi chứng từ khác phần mềm tạo) — không tự ghi sổ bằng SQL vì
    không tái tạo đủ các bảng sổ cái/công nợ phụ trợ mà thao tác Ghi sổ thật
    của MISA cập nhật; người dùng tự kiểm tra rồi Ghi sổ hàng loạt trong
    MISA."""
    if loai not in ("kh", "ncc"):
        raise HTTPException(400, "loai phải là 'kh' hoặc 'ncc'.")
    if not danh_sach:
        raise HTTPException(400, "Danh sách trống — không có gì để ghi.")
    import uuid as _uuid
    master_table = "CAReceipt" if loai == "kh" else "CAPayment"
    detail_table = master_table + "Detail"
    tk_congno = "131" if loai == "kh" else "331"
    conn = _misa_sql_connect(cid, database=database)
    conn.autocommit = False
    try:
        cur = conn.cursor()
        branch_id = _misa_branch_id(cur)
        cols_m = _misa_cot_bang_that(cur, master_table)
        cols_d = _misa_cot_bang_that(cur, detail_table)
        if not cols_m or not cols_d:
            raise HTTPException(
                400, "Không tìm thấy bảng %s/%s trong CSDL MISA đang kết nối."
                % (master_table, detail_table))
        # Gỡ các phiếu CHƯA GHI SỔ do CHÍNH phần mềm tạo ở lần chạy TRƯỚC
        # (CustomField10=_PM_MARK) trước khi ghi lại — tránh tồn đọng phiếu
        # ghi nhầm RefType (rác) mỗi lần người dùng chạy lại sau khi sửa
        # tham số. KHÔNG BAO GIỜ đụng phiếu đã ghi sổ (IsPostedFinance=1),
        # dù phiếu đó do phần mềm tạo trước đó.
        if not preview:
            try:
                cur.execute(
                    "DELETE FROM %s WHERE RefID IN (SELECT RefID FROM %s "
                    "WHERE CustomField10=? AND ISNULL(IsPostedFinance,0)=0)"
                    % (detail_table, master_table), _PM_MARK)
                cur.execute(
                    "DELETE FROM %s WHERE CustomField10=? AND ISNULL(IsPostedFinance,0)=0"
                    % master_table, _PM_MARK)
            except Exception:
                pass
        reftype_rows = cur.execute(
            "SELECT RefType, RefTypeName FROM SYSRefType WHERE MasterTableName=?",
            master_table).fetchall()
        if not reftype_rows:
            raise HTTPException(400, "Không tìm thấy RefType cho bảng %s trong SYSRefType." % master_table)
        # Ưu tiên đúng loại "trả nhà cung cấp"/"của khách hàng" (vd RefType
        # 1021 "Phiếu chi trả tiền nhà cung cấp") — xác nhận qua chẩn đoán
        # thật: lọc theo "tiền mặt" đơn thuần từng trúng nhầm RefType 1023
        # "Chi tiền mặt nộp thuế TNCN" (tên cũng có chữ "tiền mặt" nhưng SAI
        # hẳn mục đích — Quỹ MISA không hiện phiếu ghi nhầm loại này).
        tu_khoa_dung = "nhà cung cấp" if loai == "ncc" else "khách hàng"
        tu_khoa_loai_tru = ("thuế", "lương", "bảo hiểm", "nhập khẩu", "tạm ứng")
        reftype = next(
            (int(r[0]) for r in reftype_rows if tu_khoa_dung in str(r[1] or "").lower()),
            next((int(r[0]) for r in reftype_rows
                  if "tiền mặt" in str(r[1] or "").lower()
                  and not any(k in str(r[1] or "").lower() for k in tu_khoa_loai_tru)),
                 int(reftype_rows[0][0])))
        max_reforder_row = cur.execute("SELECT MAX(RefOrder) FROM %s" % master_table).fetchone()
        reforder = int(max_reforder_row[0] or 0) if max_reforder_row else 0
        now = datetime.datetime.now()
        seq = {}
        so_ghi = 0
        ket_qua = []
        for it in danh_sach:
            aoid = it.get("account_object_id")
            so_tien = _to_num(it.get("so_tien")) or 0
            if not aoid or so_tien <= 0:
                continue
            try:
                ngay_dt = datetime.datetime.fromisoformat(str(it.get("inv_date"))[:19])
            except Exception:
                ngay_dt = now
            mk = (ngay_dt.month, ngay_dt.year)
            seq[mk] = seq.get(mk, 0) + 1
            prefix = "PTMT" if loai == "kh" else "PCMT"
            so_ct = ("%s%03d/T%s/%s" % (prefix, seq[mk], ngay_dt.month, ngay_dt.year))[:20]
            memo = ("Thu tiền mặt bù công nợ treo HĐ %s" if loai == "kh"
                   else "Chi tiền mặt bù công nợ treo HĐ %s") % (it.get("inv_no") or "")
            reforder += 1
            refid = str(_uuid.uuid4())
            if not preview:
                row_m = {real: _misa_gia_tri_mac_dinh(t) for real, t in cols_m.values()}
                _misa_gan(row_m, cols_m, refid, "RefID")
                _misa_gan(row_m, cols_m, reftype, "RefType")
                _misa_gan(row_m, cols_m, ngay_dt, "RefDate")
                _misa_gan(row_m, cols_m, ngay_dt, "PostedDate")
                _misa_gan(row_m, cols_m, so_ct, "RefNoFinance")
                _misa_gan(row_m, cols_m, False, "IsPostedFinance")
                _misa_gan(row_m, cols_m, False, "IsPostedManagement")
                _misa_gan(row_m, cols_m, aoid, "AccountObjectID")
                _misa_gan(row_m, cols_m, memo, "JournalMemo")
                _misa_gan(row_m, cols_m, "VND", "CurrencyID")
                _misa_gan(row_m, cols_m, 1, "ExchangeRate")
                _misa_gan(row_m, cols_m, so_tien, "TotalAmountOC")
                _misa_gan(row_m, cols_m, so_tien, "TotalAmount")
                _misa_gan(row_m, cols_m, branch_id, "BranchID")
                _misa_gan(row_m, cols_m, 0, "DisplayOnBook")
                _misa_gan(row_m, cols_m, reforder, "RefOrder")
                _misa_gan(row_m, cols_m, now, "CreatedDate")
                _misa_gan(row_m, cols_m, "PhanMem", "CreatedBy")
                _misa_gan(row_m, cols_m, _PM_MARK, "CustomField10")
                cs = list(row_m.keys())
                cur.execute("INSERT INTO %s ([%s]) VALUES (%s)" %
                           (master_table, "],[".join(cs), ",".join(["?"] * len(cs))),
                           [row_m[c] for c in cs])

                row_d = {real: _misa_gia_tri_mac_dinh(t) for real, t in cols_d.values()}
                _misa_gan(row_d, cols_d, str(_uuid.uuid4()), "RefDetailID")
                _misa_gan(row_d, cols_d, refid, "RefID")
                _misa_gan(row_d, cols_d, memo, "Description")
                _misa_gan(row_d, cols_d, "1111" if loai == "kh" else tk_congno, "DebitAccount")
                _misa_gan(row_d, cols_d, tk_congno if loai == "kh" else "1111", "CreditAccount")
                _misa_gan(row_d, cols_d, so_tien, "AmountOC")
                _misa_gan(row_d, cols_d, so_tien, "Amount")
                _misa_gan(row_d, cols_d, aoid, "AccountObjectID")
                _misa_gan(row_d, cols_d, 1, "SortOrder")
                _misa_gan(row_d, cols_d, False, "UnResonableCost")
                cs = list(row_d.keys())
                cur.execute("INSERT INTO %s ([%s]) VALUES (%s)" %
                           (detail_table, "],[".join(cs), ",".join(["?"] * len(cs))),
                           [row_d[c] for c in cs])
            so_ghi += 1
            ket_qua.append({"mst": it.get("mst"), "ten": it.get("ten"), "inv_no": it.get("inv_no"),
                            "so_tien": so_tien, "so_ct": so_ct})
        if preview:
            conn.rollback()
        else:
            conn.commit()
        return {"preview": preview, "loai": loai, "so_ghi": so_ghi, "danh_sach": ket_qua}
    except HTTPException:
        conn.rollback()
        raise
    except Exception as e:
        conn.rollback()
        raise HTTPException(400, "Lỗi khi ghi vào MISA (đã hoàn tác, không ghi gì): %s" % str(e)[:400])
    finally:
        conn.close()


@app.post("/api/misa-sql/ghi-bu-tru-treo/{cid}")
async def misa_sql_ghi_bu_tru_treo(cid: int, request: Request, loai: str = "kh", preview: int = 1,
                                   database: str = ""):
    """body: {danh_sach: [...]} — lấy từ /api/misa-sql/de-xuat-bu-tru (có thể
    người dùng bỏ bớt dòng không muốn ghi)."""
    database = (database or "").strip() or (_misa_sql_cfg(cid).get("database") or "")
    if not database:
        raise HTTPException(400, "Chưa cấu hình kết nối/CSDL MISA. Mở '🗄 Kết nối CSDL MISA', "
                                 "kết nối tới dữ liệu THỬ trước.")
    body = await request.json()
    danh_sach = body.get("danh_sach") or []
    return _misa_ghi_bu_tru_treo(cid, database, loai, danh_sach, preview=bool(preview))


def _misa_don_phieu_bu_tru_loi(cid, database, loai):
    """Gỡ các phiếu CHƯA GHI SỔ do _misa_ghi_bu_tru_treo tạo (CustomField10=
    _PM_MARK) — dùng khi chuyển sang cách khác (xuất Excel 'Nghiệp vụ khác'
    để import) và không cần các phiếu Thu/Chi tiền mặt đã ghi thử qua SQL
    nữa, tránh trùng/rác. KHÔNG BAO GIỜ đụng phiếu đã ghi sổ."""
    if loai not in ("kh", "ncc"):
        raise HTTPException(400, "loai phải là 'kh' hoặc 'ncc'.")
    master_table = "CAReceipt" if loai == "kh" else "CAPayment"
    detail_table = master_table + "Detail"
    conn = _misa_sql_connect(cid, database=database)
    conn.autocommit = False
    try:
        cur = conn.cursor()
        cur.execute(
            "DELETE FROM %s WHERE RefID IN (SELECT RefID FROM %s "
            "WHERE CustomField10=? AND ISNULL(IsPostedFinance,0)=0)"
            % (detail_table, master_table), _PM_MARK)
        so_xoa = cur.execute(
            "DELETE FROM %s OUTPUT deleted.RefID WHERE CustomField10=? "
            "AND ISNULL(IsPostedFinance,0)=0" % master_table, _PM_MARK).rowcount
        conn.commit()
        return {"so_xoa": so_xoa}
    except Exception as e:
        conn.rollback()
        raise HTTPException(400, "Lỗi khi gỡ (đã hoàn tác): %s" % str(e)[:400])
    finally:
        conn.close()


@app.post("/api/misa-sql/don-phieu-bu-tru-loi/{cid}")
def misa_sql_don_phieu_bu_tru_loi(cid: int, loai: str = "kh", database: str = ""):
    database = (database or "").strip() or (_misa_sql_cfg(cid).get("database") or "")
    if not database:
        raise HTTPException(400, "Chưa cấu hình kết nối/CSDL MISA. Mở '🗄 Kết nối CSDL MISA', "
                                 "kết nối tới dữ liệu THỬ trước.")
    return _misa_don_phieu_bu_tru_loi(cid, database, loai)


def _misa_chan_doan_bu_tru(cid, database, loai="ncc"):
    """CHẨN ĐOÁN (CHỈ ĐỌC) — dùng khi phiếu Thu/Chi tiền mặt do
    _misa_ghi_bu_tru_treo tạo (CustomField10=_PM_MARK) ghi "thành công"
    (không lỗi SQL) nhưng KHÔNG hiện trên lưới MISA 'Quỹ > Thu, chi tiền'.
    Lấy TOÀN BỘ cột (SELECT *, không chọn lọc — tránh bỏ sót cột khác biệt
    thật) của phiếu phần mềm vừa tạo, đối chiếu song song với 1 phiếu THẬT
    (không do phần mềm tạo, nếu công ty có sẵn) để tìm đúng cột gây khác
    biệt (RefType/BranchID/DisplayOnBook/IsPostedCashBookFinance...)."""
    if loai not in ("kh", "ncc"):
        raise HTTPException(400, "loai phải là 'kh' hoặc 'ncc'.")
    master_table = "CAReceipt" if loai == "kh" else "CAPayment"
    conn = _misa_sql_connect(cid, database=database)
    try:
        cur = conn.cursor()
        cur.execute("SELECT TOP 3 * FROM %s WHERE CustomField10=? ORDER BY CreatedDate DESC"
                   % master_table, _PM_MARK)
        cols = [c[0] for c in cur.description]
        cua_minh = [dict(zip(cols, r)) for r in cur.fetchall()]
        cur.execute("SELECT COUNT(*) FROM %s WHERE CustomField10=?" % master_table, _PM_MARK)
        so_dong_cua_minh = cur.fetchone()[0]
        cur.execute("SELECT TOP 1 * FROM %s WHERE ISNULL(CustomField10,'')<>? "
                   "ORDER BY CreatedDate DESC" % master_table, _PM_MARK)
        r = cur.fetchone()
        that = dict(zip([c[0] for c in cur.description], r)) if r else None
        # TOÀN BỘ RefType khả dĩ (tra SYSRefType) — RefType phần mềm đang
        # chọn CÓ THỂ không đúng loại "Chi/Thu tiền mặt" thật MISA cần (view
        # Quỹ đọc dữ liệu có khả năng lọc/derive theo RefType, xem CAType ở
        # View_CAReceiptPayment) — liệt kê hết để đối chiếu bằng mắt.
        cac_reftype = [{"reftype": int(rt), "ten": tn} for rt, tn in cur.execute(
            "SELECT RefType, RefTypeName FROM SYSRefType WHERE MasterTableName=?",
            master_table).fetchall()]
        # Đếm số dòng THẬT (không do phần mềm tạo) theo từng RefType — RefType
        # nào có nhiều dòng thật nhất mới chắc chắn là loại MISA thật sự dùng
        # cho lưới Quỹ, thay vì suy đoán qua tên.
        dem_reftype_that = {int(rt): n for rt, n in cur.execute(
            "SELECT RefType, COUNT(*) FROM %s WHERE ISNULL(CustomField10,'')<>? "
            "GROUP BY RefType" % master_table, _PM_MARK).fetchall()}
        for it in cac_reftype:
            it["so_dong_that"] = dem_reftype_that.get(it["reftype"], 0)
        cac_reftype.sort(key=lambda x: -x["so_dong_that"])
        # Bảng CHI TIẾT (Nợ/Có/Số tiền) của phiếu vừa tạo — kiểm tra riêng vì
        # trước đây chỉ soi bảng master, có thể dòng chi tiết bị thiếu/sai
        # (vd DebitAccount/CreditAccount không khớp Account thật) khiến view
        # Quỹ không đủ dữ liệu xác định đây là phiếu tiền mặt.
        detail_table = master_table + "Detail"
        chi_tiet = []
        if cua_minh:
            cur.execute("SELECT * FROM %s WHERE RefID=?" % detail_table, cua_minh[0]["RefID"])
            dcols = [c[0] for c in cur.description]
            chi_tiet = [dict(zip(dcols, r)) for r in cur.fetchall()]
        # Danh sách TK thật có trong Danh mục Kế toán — kiểm tra "331"/"1111"
        # có đúng khớp AccountNumber thật không (có thể cần hậu tố NCC/NH).
        tk_that = [str(a) for (a,) in cur.execute(
            "SELECT AccountNumber FROM Account WHERE AccountNumber IN (?,?,?,?)",
            "331", "1111", "131", "1121").fetchall()]
        # Lấy THẲNG định nghĩa SQL thật của view mà lưới "Quỹ > Thu, chi
        # tiền" nhiều khả năng đọc qua (View_CAReceiptPayment) — thay vì tiếp
        # tục đoán cột nào gây lọc mất, đọc đúng JOIN/WHERE thật MISA dùng.
        view_sql = None
        trong_view = None
        try:
            row_v = cur.execute(
                "SELECT OBJECT_DEFINITION(OBJECT_ID('View_CAReceiptPayment'))").fetchone()
            view_sql = row_v[0] if row_v else None
        except Exception as e:
            view_sql = "(không đọc được định nghĩa view: %s)" % str(e)[:200]
        if cua_minh:
            try:
                row_c = cur.execute(
                    "SELECT COUNT(*) FROM View_CAReceiptPayment WHERE RefID=?",
                    cua_minh[0]["RefID"]).fetchone()
                trong_view = int(row_c[0]) if row_c else 0
            except Exception as e:
                trong_view = "(lỗi: %s)" % str(e)[:200]
        # Chi nhánh (BranchID) đang dùng có khớp đúng 1 OrganizationUnit thật
        # không — liệt kê hết để so, vì view có cột OrganizationUnitName
        # NOTNULL (nghi vấn INNER JOIN theo BranchID).
        chi_nhanh = [{"id": str(oid), "ten": ten, "co_cha": pid is not None} for oid, ten, pid in
                    cur.execute("SELECT OrganizationUnitID, OrganizationUnitName, ParentID "
                               "FROM OrganizationUnit").fetchall()]
    finally:
        conn.close()

    def don_gian(d):
        if not d:
            return d
        return {k: (str(v) if v is not None else None) for k, v in d.items()}

    return {"loai": loai, "bang": master_table, "so_dong_cua_minh": so_dong_cua_minh,
            "cua_minh": [don_gian(x) for x in cua_minh], "that": don_gian(that),
            "cac_reftype": cac_reftype, "chi_tiet": [don_gian(x) for x in chi_tiet],
            "tk_that_co": tk_that, "view_sql": view_sql, "trong_view": trong_view,
            "chi_nhanh": chi_nhanh}


@app.get("/api/misa-sql/chan-doan-bu-tru/{cid}")
def misa_sql_chan_doan_bu_tru(cid: int, loai: str = "ncc", database: str = ""):
    database = (database or "").strip() or (_misa_sql_cfg(cid).get("database") or "")
    if not database:
        raise HTTPException(400, "Chưa cấu hình kết nối/CSDL MISA. Mở '🗄 Kết nối CSDL MISA', "
                                 "kết nối tới dữ liệu THỬ trước.")
    return _misa_chan_doan_bu_tru(cid, database, loai=loai)


# ============================================================
#  XUẤT EXCEL "Chứng từ nghiệp vụ khác" (mẫu Import Excel GỐC của MISA,
#  bảng GLVoucher/GLVoucherDetail) để BÙ CÔNG NỢ TREO — thay cho việc ghi
#  thẳng SQL vào CAReceipt/CAPayment (đã xác nhận có 1 tầng cache riêng của
#  MISA — CAReceiptPaymentList — không tự cập nhật khi ghi thẳng SQL, khiến
#  phiếu không hiện trên lưới Quỹ dù dữ liệu đúng). Xuất Excel rồi người
#  dùng tự Import qua đúng chức năng "Nghiệp vụ khác > Import Excel" của
#  MISA — đi qua ĐÚNG luồng ứng dụng thật, không có rủi ro cache như trên.
# ============================================================
_GLVOUCHER_HEADERS = [
    "Hiển thị trên sổ", "Ngày chứng từ (*)", "Ngày hạch toán (*)", "Số chứng từ (*)",
    "Diễn giải", "Hạn thanh toán", "Loại tiền", "Tỷ giá", "Diễn giải (Hạch toán)",
    "TK Nợ (*)", "TK Có (*)", "Số tiền", "Số tiền quy đổi", "Đối tượng Nợ", "Đối tượng Có",
    "TK ngân hàng", "Khoản mục CP", "Đơn vị", "Đối tượng THCP", "Công trình", "Hợp đồng bán",
    "CP không hợp lý", "Mã thống kê", "Diễn giải (Thuế)", "TK thuế GTGT", "Tiền thuế GTGT",
    "% thuế GTGT", "Tỷ lệ tính thuế (Thuế suất KHAC)", "Giá trị HHDV chưa thuế", "Mẫu số HĐ",
    "Ngày hóa đơn", "Ký hiệu HĐ", "Số hóa đơn", "Nhóm HHDV mua vào", "Mã đối tượng thuế",
    "Tên đối tượng thuế", "Mã số thuế đối tượng thuế",
]


def _xuat_excel_dieu_chinh_cong_no(cid, loai, danh_sach):
    """Xuất file Excel đúng mẫu 'Chứng từ nghiệp vụ khác' của MISA — mỗi
    dòng trong danh_sach (lấy từ tang3 của /api/misa-sql/doi-chieu-3-tang,
    người dùng có thể bỏ bớt) thành 1 bút toán điều chỉnh công nợ về 0: loai='ncc' -> Nợ
    331 (giảm phải trả)/Có 1111 (coi như đã chi tiền mặt), đối tượng gán ở
    cột 'Đối tượng Nợ'; loai='kh' -> Nợ 1111/Có 131 (coi như đã thu tiền
    mặt), đối tượng gán ở cột 'Đối tượng Có' — đúng TK có gắn đối tượng
    trong từng bút toán. Ngày chứng từ/hạch toán lấy theo ĐÚNG ngày hóa đơn
    gốc (không phải hôm nay) để bút toán nằm đúng kỳ phát sinh công nợ."""
    import openpyxl
    from openpyxl.styles import Font, PatternFill
    from openpyxl.utils import get_column_letter
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Chứng từ nghiệp vụ khác"
    for c, h in enumerate(_GLVOUCHER_HEADERS, 1):
        ws.cell(1, c).value = h
        ws.cell(1, c).font = Font(bold=True, color="FFFFFF")
        ws.cell(1, c).fill = PatternFill("solid", fgColor="2E5C8A")
    tk_no, tk_co = ("331", "1111") if loai == "ncc" else ("1111", "131")
    seq = {}
    r = 2
    for it in danh_sach:
        so_tien = _to_num(it.get("so_tien")) or 0
        if so_tien <= 0:
            continue
        ma = str(it.get("mst") or it.get("ma") or "").strip()
        ten = str(it.get("ten") or "").strip()
        inv_no = str(it.get("inv_no") or "").strip()
        try:
            ngay_dt = datetime.datetime.strptime(str(it.get("inv_date") or "")[:10], "%Y-%m-%d")
        except Exception:
            ngay_dt = datetime.datetime.now()
        mk = (ngay_dt.month, ngay_dt.year)
        seq[mk] = seq.get(mk, 0) + 1
        so_ct = ("DCCN%03d/T%s/%s" % (seq[mk], ngay_dt.month, ngay_dt.year))[:20]
        dien_giai = ("Điều chỉnh công nợ treo HĐ %s - %s" % (inv_no, ten)).strip(" -")
        row = [""] * len(_GLVOUCHER_HEADERS)
        row[1] = ngay_dt.strftime("%d/%m/%Y")
        row[2] = ngay_dt.strftime("%d/%m/%Y")
        row[3] = so_ct
        row[4] = dien_giai
        row[6] = "VND"
        row[7] = 1
        row[8] = dien_giai
        row[9] = tk_no
        row[10] = tk_co
        row[11] = so_tien
        row[12] = so_tien
        if loai == "ncc":
            row[13] = ma
        else:
            row[14] = ma
        for c, v in enumerate(row, 1):
            cell = ws.cell(r, c)
            cell.value = v
            if c == 12 or c == 13:
                cell.number_format = "#,##0"
        r += 1
    for c in range(1, len(_GLVOUCHER_HEADERS) + 1):
        ws.column_dimensions[get_column_letter(c)].width = 18
    ws.freeze_panes = "A2"
    fname = "DieuChinhCongNo_%s_%s.xlsx" % (loai, datetime.datetime.now().strftime("%d%m%Y_%H%M"))
    path = os.path.join(DOWNLOAD_DIR, fname)
    wb.save(path)
    import shutil
    for d in (_get_desktop_dir(), (_du_lieu_cty_path(cid) and os.path.dirname(_du_lieu_cty_path(cid)))):
        if d and os.path.isdir(d):
            try:
                shutil.copy(path, os.path.join(d, fname))
            except Exception:
                pass
    return path, r - 2


@app.post("/api/misa-sql/xuat-dieu-chinh-cong-no/{cid}")
async def misa_xuat_dieu_chinh_cong_no(cid: int, request: Request, loai: str = "ncc"):
    if loai not in ("kh", "ncc"):
        raise HTTPException(400, "loai phải là 'kh' hoặc 'ncc'.")
    body = await request.json()
    danh_sach = body.get("danh_sach") or []
    if not danh_sach:
        raise HTTPException(400, "Danh sách trống — không có gì để xuất.")
    path, so_dong = _xuat_excel_dieu_chinh_cong_no(cid, loai, danh_sach)
    fname = os.path.basename(path)
    return _resp_xuat(path, fname, {"X-So-Dong": str(so_dong)})


# ============================================================
#  IMPORT TỰ ĐỘNG TOÀN BỘ — chạy lần lượt mọi luồng ghi vào MISA đã có,
#  theo ĐÚNG THỨ TỰ phụ thuộc dữ liệu (KH/NCC trước Bán hàng vì Bán hàng cần
#  AccountObjectID; Danh mục Hàng hóa trước Mua hàng vì Mua hàng cần
#  InventoryItemID). Bước nào KHÔNG có dữ liệu đã lưu -> tự BỎ QUA, không
#  báo lỗi (đúng yêu cầu). Mỗi bước dùng LẠI ĐÚNG hàm ghi đã kiểm chứng của
#  từng chức năng riêng lẻ — không viết lại logic ghi.
# ============================================================
def _misa_tom_tat_buoc(r):
    """Tóm tắt 1 dòng kết quả của 1 bước (số thêm/bỏ qua/ghi đè...) để hiện
    trong dòng tiến độ — cùng logic với misaTomTatBuoc() phía JS."""
    if not r:
        return "xong"
    phan = []
    if r.get("so_chungtu") is not None:
        phan.append(f"{r['so_chungtu']} chứng từ")
    if r.get("so_them") is not None:
        phan.append(f"thêm {r['so_them']}")
    if r.get("so_ghi_de"):
        phan.append(f"ghi đè {r['so_ghi_de']}")
    if r.get("so_trung"):
        phan.append(f"bỏ qua (đã có) {r['so_trung']}")
    if r.get("so_don_vi_moi"):
        phan.append(f"{r['so_don_vi_moi']} ĐVT mới")
    if r.get("so_bo_qua_kh"):
        phan.append(f"bỏ qua thiếu KH {r['so_bo_qua_kh']}")
    if r.get("so_chung_tu") is not None:
        phan.append(f"{r['so_chung_tu']} chứng từ")
    if r.get("so_dong") is not None and "danh_sach" in r:
        phan.append(f"{r['so_dong']} dòng")
    if r.get("so_quy") is not None and "danh_sach" in r:
        phan.append(f"{r['so_quy']} quý")
    if not phan and r.get("ghi_chu"):
        return r["ghi_chu"]
    return ", ".join(phan) or "xong"


def _misa_import_tu_dong(cid, database, preview=True, ghi_de=False, bao=None,
                         tu_thang=None, den_thang=None,
                         gtgt_tu_quy=None, gtgt_tu_nam=None, gtgt_den_quy=None, gtgt_den_nam=None):
    """Chạy lần lượt: 1) Danh mục KH/NCC  2) Bảng kê Đầu ra (Bán hàng)
    3) Danh mục Hàng hóa/NVL/TSCĐ/CCDC (sinh từ Bảng kê Đầu vào đã lưu)
    4) Mua hàng Nhập kho/Không qua kho/Dịch vụ (Bảng kê Đầu vào đã lưu)
    5) Ghi tăng CCDC/TSCĐ (Bảng kê Đầu vào đã lưu, TK Nợ 242x/211x),
    Phân bổ chi phí CCDC tự động, Tính khấu hao TSCĐ tự động
    6) Tờ khai GTGT + Khấu trừ tự động (BƯỚC CUỐI — chạy sau khi Bán
    hàng/Mua hàng đã có dữ liệu, vì chỉ tiêu tờ khai tính trực tiếp từ 2
    bảng đó).
    Chứng từ (Bán hàng/Mua hàng) LUÔN ghi ở trạng thái CHƯA GHI SỔ như mọi
    khi (không tự Ghi sổ bằng SQL — xem giải thích lý do an toàn ở nơi gọi
    API này); Ghi tăng CCDC/TSCĐ vẫn ghi ĐÃ GHI SỔ như thiết kế sẵn có (ghi
    tăng danh mục không sinh bút toán, không có tầng "Ghi sổ" riêng); Phân
    bổ CCDC/Khấu hao TSCĐ tạo chứng từ hàng tháng theo khung tu_thang/
    den_thang (yyyy-mm) người dùng chọn — để trống cả 2 = mỗi bước tự chọn
    12 tháng kể từ chứng từ PBCC/KH gần nhất đã có (giống chạy riêng lẻ
    từng nút "🤖 ... tự động"); bút toán Khấu trừ thuế GTGT ở bước 6 cũng
    CHƯA GHI SỔ như Bán hàng/Mua hàng.
    gtgt_tu_quy/gtgt_tu_nam/gtgt_den_quy/gtgt_den_nam: khung Quý/Năm cho
    bước 6 (Tờ khai GTGT) — để trống cả 4 = tự tiếp nối tờ khai thật gần
    nhất (xem _misa_tao_to_khai_khau_tru_gtgt), chỉ trống "đến" = chạy 4
    quý kể từ "từ".
    ghi_de mặc định TẮT (False) — chứng từ nào ĐÃ CÓ trong MISA (trùng với
    dữ liệu đang import, kể cả chứng từ CHƯA ghi sổ do chính đợt chạy
    trước tạo) sẽ tự BỎ QUA (đếm vào "so_trung"), KHÔNG ghi đè; chỉ ghi
    thêm chứng từ CHƯA có — theo đúng yêu cầu "chỉ xử lý những chứng từ
    chưa có thôi".
    bao(text): callback báo tiến độ từng bước (công ty nhiều dữ liệu chạy
    khá lâu — không có callback thì chạy âm thầm như cũ)."""
    if bao is None:
        bao = lambda *_a: None
    buoc = []

    tu_thang_kh = (tu_thang or "").strip() or None
    so_thang_kh = 12
    if tu_thang_kh and (den_thang or "").strip():
        try:
            y0, m0 = [int(x) for x in tu_thang_kh.split("-")]
            y1, m1 = [int(x) for x in den_thang.strip().split("-")]
            so_thang_kh = max(1, (y1 * 12 + m1) - (y0 * 12 + m0) + 1)
        except Exception:
            pass

    def chay(ten, fn):
        bao(f"▶ Đang xử lý: {ten}...")
        try:
            r = fn()
            buoc.append({"ten": ten, "ket_qua": r})
            tien_to = "Xem trước" if preview else "Đã ghi"
            bao(f"✓ {ten} — {tien_to}: {_misa_tom_tat_buoc(r)}")
        except HTTPException as e:
            msg = str(e.detail)
            if any(k in msg for k in ("Chưa có", "trống", "Không có")):
                buoc.append({"ten": ten, "bo_qua": msg})
                bao(f"⏭ Bỏ qua: {ten} — {msg}")
            else:
                buoc.append({"ten": ten, "loi": msg})
                bao(f"✗ Lỗi: {ten} — {msg}")
        except Exception as e:
            emsg = str(e)[:300]
            buoc.append({"ten": ten, "loi": emsg})
            bao(f"✗ Lỗi: {ten} — {emsg}")

    chay("1. Danh mục KH/NCC", lambda: _misa_ghi_khncc(cid, database, preview=preview))

    chay("2. Bảng kê Đầu ra (Bán hàng)",
         lambda: _misa_ghi_ban_hang(cid, database, preview=preview, ghi_de=ghi_de))

    dl_in = nhap_lieu_get(cid, "in")
    header_in, rows_in = dl_in.get("header") or [], dl_in.get("rows") or []

    def _lam_danh_muc(loai):
        if not rows_in:
            raise HTTPException(400, "Chưa có Bảng kê Đầu vào đã lưu.")
        all_rows, so_moi = _gen_danh_muc(cid, loai, header_in, rows_in)
        if not all_rows:
            raise HTTPException(400, "Không có mã nào thuộc danh mục này trong Bảng kê Đầu vào.")
        if not preview:
            _luu_danh_muc(cid, loai, all_rows)
        misa_rows = [[r[0], r[1], r[2], r[3]] for r in all_rows] if loai in ("hh", "nvl") \
            else [[r[0], r[1], r[2]] for r in all_rows]
        return _misa_ghi_hang_hoa(cid, database, misa_rows, preview=preview, loai=loai)

    chay("3a. Danh mục Hàng hóa", lambda: _lam_danh_muc("hh"))
    chay("3b. Danh mục NVL", lambda: _lam_danh_muc("nvl"))
    chay("3c. Danh mục TSCĐ", lambda: _lam_danh_muc("tscd"))
    chay("3d. Danh mục CCDC", lambda: _lam_danh_muc("ccdc"))

    chay("4a. Nhập kho vào MISA",
         lambda: _misa_ghi_mua_hang(cid, database, "nk", preview=preview, ghi_de=ghi_de))
    chay("4b. Không qua kho vào MISA",
         lambda: _misa_ghi_mua_hang(cid, database, "kqk", preview=preview, ghi_de=ghi_de))
    chay("4c. Dịch vụ vào MISA",
         lambda: _misa_ghi_mua_hang_dv(cid, database, preview=preview, ghi_de=ghi_de))

    chay("5a. Ghi tăng CCDC",
         lambda: _misa_ghi_tang_ccdc(cid, database, preview=preview, ghi_de=ghi_de))
    chay("5b. Ghi tăng TSCĐ",
         lambda: _misa_ghi_tang_tscd(cid, database, preview=preview, ghi_de=ghi_de))

    chay("5c. Phân bổ chi phí CCDC tự động",
         lambda: _misa_phan_bo_ccdc(cid, database, preview=preview,
                                    tu_thang=tu_thang_kh, so_thang=so_thang_kh))
    chay("5d. Tính khấu hao TSCĐ tự động",
         lambda: _misa_khau_hao_tscd(cid, database, preview=preview,
                                     tu_thang=tu_thang_kh, so_thang=so_thang_kh))

    # Bước CUỐI CÙNG — chạy sau khi Bán hàng/Mua hàng đã có dữ liệu (chỉ
    # tiêu tờ khai tính từ chính các bảng đó), theo yêu cầu đưa vào cuối
    # luồng "Import tự động toàn bộ".
    gtgt_so_quy = 4
    if gtgt_tu_quy and gtgt_tu_nam and gtgt_den_quy and gtgt_den_nam:
        gtgt_so_quy = max(1, (int(gtgt_den_nam) * 4 + int(gtgt_den_quy)) -
                             (int(gtgt_tu_nam) * 4 + int(gtgt_tu_quy)) + 1)
    chay("6. Tờ khai GTGT + Khấu trừ tự động",
         lambda: _misa_tao_to_khai_khau_tru_gtgt(cid, database, preview=preview,
                                                 tu_quy=gtgt_tu_quy, tu_nam=gtgt_tu_nam,
                                                 so_quy=gtgt_so_quy))

    bao("✅ Xem trước xong — chưa ghi gì." if preview else "✅ Đã chạy xong toàn bộ.")
    return {"database": database, "preview": preview, "cac_buoc": buoc}


# Job chạy NỀN cho "Import tự động toàn bộ" — công ty nhiều dữ liệu (nhiều
# chứng từ) có thể mất vài phút, nên chạy trong 1 thread riêng + trình duyệt
# poll /api/misa-sql/import-tu-dong-status/{cid} để hiện tiến độ TỪNG BƯỚC,
# giống hệt cơ chế FETCH_JOBS/_new_fetch_job() dùng cho tra cứu hóa đơn.
MISA_IMPORT_JOBS = {}   # {cid: {"messages": [...], "running": bool, "result": dict|None}}


@app.post("/api/misa-sql/import-tu-dong-start/{cid}")
def misa_sql_import_tu_dong_start(cid: int, preview: int = 1, database: str = "", ghi_de: int = 0,
                                  tu_thang: str = "", den_thang: str = "",
                                  gtgt_tu_quy: str = "", gtgt_tu_nam: str = "",
                                  gtgt_den_quy: str = "", gtgt_den_nam: str = ""):
    """Bắt đầu chạy NỀN toàn bộ luồng import vào MISA — xem
    _misa_import_tu_dong. ghi_de mặc định TẮT (0) cho luồng tự động này —
    chứng từ (Bán hàng/Mua hàng...) đã có sẵn trong MISA (trùng với dữ liệu
    đang import) sẽ tự BỎ QUA, không ghi đè; chỉ ghi thêm chứng từ CHƯA có.
    tu_thang/den_thang (yyyy-mm): khung tháng cho 2 bước Phân bổ chi phí
    CCDC/Tính khấu hao TSCĐ tự động, để trống = tự chọn.
    gtgt_tu_quy/gtgt_tu_nam/gtgt_den_quy/gtgt_den_nam: khung Quý/Năm cho
    bước Tờ khai GTGT + Khấu trừ, để trống cả 4 = tự tiếp nối tờ khai thật
    gần nhất. Trả về ngay, trình duyệt poll
    /api/misa-sql/import-tu-dong-status/{cid} để lấy tiến độ."""
    database = (database or "").strip() or (_misa_sql_cfg(cid).get("database") or "")
    if not database:
        raise HTTPException(400, "Chưa cấu hình kết nối/CSDL MISA. Mở '🗄 Kết nối CSDL MISA', "
                                 "kết nối tới dữ liệu THỬ trước.")
    job = {"messages": [], "running": True, "started": time.time(), "result": None}
    MISA_IMPORT_JOBS[cid] = job

    def _bao(text):
        job["messages"].append({"text": text, "t": time.time()})

    def _so_int(s):
        s = (s or "").strip()
        return int(s) if s.isdigit() else None

    def _chay_nen():
        try:
            job["result"] = _misa_import_tu_dong(
                cid, database, preview=bool(preview), ghi_de=bool(ghi_de), bao=_bao,
                tu_thang=tu_thang, den_thang=den_thang,
                gtgt_tu_quy=_so_int(gtgt_tu_quy), gtgt_tu_nam=_so_int(gtgt_tu_nam),
                gtgt_den_quy=_so_int(gtgt_den_quy), gtgt_den_nam=_so_int(gtgt_den_nam))
        except Exception as e:
            _bao(f"✗ Lỗi không mong đợi — đã dừng: {str(e)[:300]}")
        finally:
            job["running"] = False

    threading.Thread(target=_chay_nen, daemon=True).start()
    return {"ok": True, "started": True}


@app.get("/api/misa-sql/import-tu-dong-status/{cid}")
def misa_sql_import_tu_dong_status(cid: int, cursor: int = 0):
    """Trả về các dòng tiến độ MỚI kể từ cursor — trình duyệt poll endpoint
    này để hiện quá trình chạy (giống /api/fetch-status)."""
    job = MISA_IMPORT_JOBS.get(cid)
    if not job:
        return {"running": False, "messages": [], "cursor": 0, "result": None, "no_job": True}
    msgs = job["messages"][cursor:]
    return {"running": job["running"], "messages": msgs, "cursor": cursor + len(msgs),
            "result": None if job["running"] else job["result"]}


@app.get("/api/danh-muc-ncc/{cid}")
def danh_muc_ncc(cid: int):
    """Tạo file Danh mục KH/NCC từ dữ liệu hóa đơn mua vào + bán ra.
    Lấy MST + tên từ Chi tiết MUA VÀO (nbmst/nbten) và BK Bán ra (nmmst/nmten).
    Lọc trùng MST, loại MST công ty mình. Trả về file Excel theo form mẫu MISA."""
    import openpyxl
    from openpyxl.styles import Font, PatternFill, Alignment
    conn = db()
    rows = conn.execute(
        "SELECT loai, nbmst, nbten, nmmst, raw FROM invoices WHERE company_id=?", (cid,)).fetchall()
    comp = conn.execute("SELECT mst FROM companies WHERE id=?", (cid,)).fetchone()
    conn.close()
    mst_cty = str(comp["mst"] or "").strip() if comp else ""

    def chuan_hoa_mst(s):
        """Chuẩn hóa MST: bỏ khoảng trắng, dấu gạch, chỉ giữ chữ số và chữ cái."""
        s = str(s or "").strip().replace("-", "").replace(" ", "").replace(".", "")
        return s

    def dinh_dang_mst(s):
        """MST 13 số (đơn vị trực thuộc) -> 10 số + '-' + 3 số: 0312320573003
        -> 0312320573-003. MST khác giữ nguyên."""
        s = chuan_hoa_mst(s)
        if len(s) == 13 and s.isdigit():
            return s[:10] + "-" + s[10:]
        return s

    # thu thập MST + tên (unique, lọc trùng)
    ds = {}  # {mst_chuan: ten}
    for r in rows:
        if r["loai"] == "purchase":
            mst = chuan_hoa_mst(r["nbmst"])
            ten = str(r["nbten"] or "").strip()
        else:
            try:
                raw = json.loads(r["raw"]) if r["raw"] else {}
            except Exception:
                raw = {}
            mst = chuan_hoa_mst(r["nmmst"] or raw.get("nmmst", ""))
            ten = str(raw.get("nmten", "") or "").strip()
        # bỏ qua: trống, MST công ty mình
        if not mst or mst == chuan_hoa_mst(mst_cty):
            continue
        # chỉ lấy lần đầu (tên dài hơn ưu tiên)
        if mst not in ds or (len(ten) > len(ds[mst])):
            ds[mst] = ten

    # ===== ĐỌC THÊM TỪ NHẬP LIỆU (bảng kê đã import vào nhap_lieu) =====
    try:
        conn2 = db()
        nl_rows = conn2.execute(
            "SELECT loai, header_json, rows_json FROM nhap_lieu WHERE company_id=?", (cid,)).fetchall()
        conn2.close()
        for nl in nl_rows:
            try:
                hdr = json.loads(nl["header_json"]) if nl["header_json"] else []
                data = json.loads(nl["rows_json"]) if nl["rows_json"] else []
            except Exception:
                continue
            hdr_low = [str(h or "").strip().lower() for h in hdr]
            # tìm cột MST và tên
            ci_mst = ci_ten = -1
            for i, h in enumerate(hdr_low):
                if ci_mst < 0 and ("mst" in h and ("bán" in h or "mua" in h or "ncc" in h or "cung" in h)):
                    ci_mst = i
                if ci_ten < 0 and ("người" in h and ("bán" in h or "mua" in h)):
                    ci_ten = i
            # fallback: cột có "mst" hoặc "mã số thuế"
            if ci_mst < 0:
                for i, h in enumerate(hdr_low):
                    if "mst" in h or "mã số thuế" in h:
                        ci_mst = i; break
            if ci_ten < 0:
                for i, h in enumerate(hdr_low):
                    if "tên" in h and ("bán" in h or "mua" in h or "ncc" in h or "khách" in h):
                        ci_ten = i; break
            if ci_mst < 0:
                continue
            for row in data:
                if ci_mst >= len(row):
                    continue
                mst = chuan_hoa_mst(row[ci_mst])
                ten = str(row[ci_ten] if ci_ten >= 0 and ci_ten < len(row) else "").strip()
                if not mst or mst == chuan_hoa_mst(mst_cty):
                    continue
                if mst not in ds or (ten and len(ten) > len(ds.get(mst, ""))):
                    ds[mst] = ten
    except Exception:
        pass

    # sắp xếp theo MST
    items = sorted(ds.items(), key=lambda x: x[0])

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Danh mục NCC"
    # header
    headers = ["Là tổ chức/cá nhân", "Là khách hàng", "Mã nhà cung cấp (*)",
               "Tên nhà cung cấp (*)", "Địa chỉ", "Mã số thuế",
               "Điện thoại", "Fax", "Email", "Website", "Nhóm KH/NCC"]
    ws.append(headers)
    for c in range(1, len(headers) + 1):
        cell = ws.cell(1, c)
        cell.font = Font(bold=True, color="FFFFFF")
        cell.fill = PatternFill("solid", fgColor="2E5C8A")

    for i, (mst, ten) in enumerate(items, 2):
        mst_hien = dinh_dang_mst(mst)              # 13 số -> 0312320573-003
        ws.cell(i, 1).value = 0                    # A: Là tổ chức/cá nhân = 0
        ws.cell(i, 2).value = 1                    # B: Là khách hàng = 1
        ws.cell(i, 3).value = mst_hien             # C: Mã NCC = MST (có gạch nếu 13 số)
        ws.cell(i, 3).number_format = "@"          # ép kiểu chữ để giữ số 0 đầu + dấu '-'
        ws.cell(i, 4).value = ten                  # D: Tên NCC
        # F: Mã số thuế = MST nếu là số hợp lệ và KHÔNG phải CCCD 12 số
        ws.cell(i, 6).value = mst_hien if (mst.isdigit() and len(mst) != 12) else ""
        ws.cell(i, 6).number_format = "@"

    # format
    from openpyxl.utils import get_column_letter
    ws.column_dimensions["A"].width = 18
    ws.column_dimensions["B"].width = 14
    ws.column_dimensions["C"].width = 20
    ws.column_dimensions["D"].width = 40
    ws.column_dimensions["E"].width = 30
    ws.column_dimensions["F"].width = 20
    ws.freeze_panes = "A2"
    if ws.max_row > 1:
        ws.auto_filter.ref = f"A1:{get_column_letter(len(headers))}{ws.max_row}"

    fname = f"DanhMuc_KHNCC_{mst_cty}.xlsx"
    path = os.path.join(DOWNLOAD_DIR, fname)
    wb.save(path)
    desktop = _get_desktop_dir()
    if desktop and os.path.isdir(desktop):
        try:
            import shutil
            shutil.copy(path, os.path.join(desktop, fname))
        except Exception:
            pass
    return _resp_xuat(path, fname)


@app.post("/api/import-excel/{cid}")
async def import_excel(cid: int, request: Request, ky: str = ""):
    """
    Import file Excel đã kiểm tra/điều chỉnh. Đọc sheet 'Chi tiết MUA VÀO' và
    'Chi tiết BÁN RA', tính tổng doanh số + thuế (bán ra tách theo thuế suất),
    lưu vào imported_data. Sau khi import, xuất XML và tạm tính VAT dùng số này.
    """
    import openpyxl, io as _io
    from starlette.concurrency import run_in_threadpool
    form = await request.form()
    up = form.get("file")
    if up is None:
        raise HTTPException(400, "Chưa chọn file Excel")
    content = await up.read()

    def _xu_ly():
        # Toàn bộ xử lý CPU-bound (mở + dò từng dòng file Excel + ghi DB) chạy
        # ở THREAD RIÊNG qua run_in_threadpool — làm trực tiếp trên vòng lặp
        # asyncio sẽ CHẶN ĐỨNG toàn bộ server (mọi request khác treo cứng, kể
        # cả trang chủ) khi file nhiều dòng, khiến trình duyệt báo "Failed to
        # fetch" (đã xác nhận: file ~15.000 dòng làm server đơ hẳn, không phản
        # hồi bất kỳ request nào, kể cả trang chủ).
        try:
            wb = openpyxl.load_workbook(_io.BytesIO(content), data_only=True)
        except Exception as e:
            raise HTTPException(400, f"Không đọc được file Excel: {e}")

        def _sach(s):
            # bỏ khoảng trắng thường + non-breaking space, phòng file bị chỉnh tay
            return str(s or "").replace("\xa0", " ").strip().lower()

        def col_idx(ws, ten, row=1):
            for c in range(1, ws.max_column + 1):
                if _sach(ws.cell(row, c).value) == ten.lower():
                    return c
            return None

        def _grid(ws):
            # Đọc CẢ SHEET 1 LẦN bằng iter_rows (tuần tự, rất nhanh) rồi tra
            # cứu qua list trong bộ nhớ — thay vì gọi ws.cell(r, c).value lặp
            # lại hàng chục nghìn lần. ws.cell() truy cập ngẫu nhiên CHẬM HƠN
            # iter_rows() TỚI HÀNG TRĂM LẦN với sheet nhiều dòng (đã đo thực
            # tế: file ~15.000 dòng mất VÀI PHÚT với ws.cell(), chỉ ~0.2 giây
            # với iter_rows) — đây là nguyên nhân THẬT SỰ khiến import file
            # lớn "treo" rất lâu, phía trình duyệt tưởng mất kết nối và báo
            # "Failed to fetch".
            return [list(row) for row in ws.iter_rows(values_only=True)]

        def _o(grid, r, c):
            row = grid[r - 1] if 0 < r <= len(grid) else None
            return row[c - 1] if row is not None and 0 < c <= len(row) else None

        mua_ds = mua_thue = 0
        mua_ds_nk = mua_thue_nk = 0     # TRONG ĐÓ: phần hàng NHẬP KHẨU (tờ khai NK) -> [23a]/[24a]
        mua_rows = 0
        mua_sheet_found = "BK Mua vào" in wb.sheetnames
        ban_sheet_found = "BK Bán ra" in wb.sheetnames
        ban = {"0": {"ds": 0, "thue": 0}, "5": {"ds": 0, "thue": 0},
               "8": {"ds": 0, "thue": 0}, "10": {"ds": 0, "thue": 0},
               "KCT": {"ds": 0, "thue": 0}}

        def num(v):
            try:
                return float(v)
            except Exception:
                return 0

        def norm_ts(v):
            s = str(v or "").replace("%", "").strip()
            if s in ("0", "5", "8", "10"):
                return s
            return None

        _TTHAI_MA_TU_MOTA = {v.lower(): k for k, v in TTHAI_DESC.items()}

        def _ma_trang_thai(mota_hoac_ma):
            """'Hóa đơn mới' -> '1' (chấp nhận cả khi ô đã ghi sẵn mã số)."""
            s = str(mota_hoac_ma or "").strip()
            if s in TTHAI_DESC:
                return s
            return _TTHAI_MA_TU_MOTA.get(s.lower(), "1")

        def _ngay_iso(v):
            """'dd/mm/yyyy' (hoặc đã là yyyy-mm-dd) -> 'yyyy-mm-dd'. '' nếu không đọc được."""
            s = str(v or "").strip()
            if not s:
                return ""
            if "-" in s and len(s.split("-")[0]) == 4:
                return s.split("T")[0].split()[0]
            try:
                d, m, y = s.split("/")
                return f"{int(y):04d}-{int(m):02d}-{int(d):02d}"
            except Exception:
                return ""

        mst_cty = str((conn := db()).execute(
            "SELECT mst FROM companies WHERE id=?", (cid,)).fetchone()["mst"] or "").strip()
        conn.close()
        mua_invoices = []   # hóa đơn MUA VÀO đọc được đầy đủ (để GHI ĐÈ bảng invoices)
        ban_invoices = []   # hóa đơn BÁN RA đọc được đầy đủ

        # ===== MUA VÀO: đọc từ sheet 'BK Mua vào' =====
        # Dò dòng tiêu đề ở vài dòng đầu (không giả định luôn ở dòng 1) — cùng cách
        # làm với BÁN RA bên dưới, để không bỏ sót khi file có thêm dòng tiêu đề/khoảng trắng.
        if mua_sheet_found:
            ws = wb["BK Mua vào"]
            g_mua = _grid(ws)
            c_ds = c_thue = c_kh = c_tt = None
            c_shdon = c_ngay = c_mst = c_ten = c_tt_bso = None
            hdr_row = 1
            for r in range(1, min(ws.max_row, 15) + 1):
                for c in range(1, ws.max_column + 1):
                    v = _sach(_o(g_mua, r, c))
                    if v == "doanh số mua chưa thuế":
                        c_ds = c; hdr_row = r
                    elif v == "thuế gtgt":
                        c_thue = c; hdr_row = max(hdr_row, r)
                    elif v in ("ký hiệu", "ki hieu"):
                        c_kh = c
                    elif v in ("trạng thái", "trang thai"):
                        c_tt = c
                    elif v in ("số hoá đơn", "số hóa đơn", "so hoa don"):
                        c_shdon = c
                    elif v in ("ngày lập", "ngay lap"):
                        c_ngay = c
                    elif v in ("mst người bán", "mst nguoi ban"):
                        c_mst = c
                    elif v in ("tên người bán", "ten nguoi ban"):
                        c_ten = c
                    elif v in ("tổng thanh toán", "tong thanh toan"):
                        c_tt_bso = c
                if c_ds:
                    break
            for r in range(hdr_row + 1, ws.max_row + 1):
                full = " ".join(str(v or "") for v in g_mua[r - 1])
                if not full.strip():
                    continue
                kh = _sach(_o(g_mua, r, c_kh)) if c_kh else ""
                low_full = full.lower()
                # Bỏ dòng TỔNG CỘNG / Tổng nhóm — nhận biết bằng Ký hiệu ĐỂ TRỐNG
                # (dòng dữ liệu luôn có Ký hiệu). TUYỆT ĐỐI không lọc theo chữ 'tổng'
                # chung chung như trước, vì sẽ bỏ nhầm hóa đơn của NCC có TÊN chứa
                # 'TỔNG' (vd 'TỔNG CÔNG TY HÀNG KHÔNG VIỆT NAM', 'TỔNG CÔNG TY CP
                # BƯU CHÍNH VIETTEL') -> thiếu doanh số/thuế mua vào.
                if (c_kh and not kh) or "tổng cộng" in low_full or "tổng nhóm" in low_full:
                    continue
                got = False
                row_ds = row_thue = 0
                if c_ds:
                    row_ds = num(_o(g_mua, r, c_ds))
                    mua_ds += row_ds
                    got = True
                if c_thue:
                    row_thue = num(_o(g_mua, r, c_thue))
                    mua_thue += row_thue
                    got = True
                # Nhận biết dòng HÀNG NHẬP KHẨU (tờ khai NK): Ký hiệu = 'TKNK' hoặc
                # Trạng thái ghi 'Tờ khai nhập khẩu' -> tách riêng cho [23a]/[24a].
                tt_stt = _sach(_o(g_mua, r, c_tt)) if c_tt else ""
                if got and ("tknk" in kh or "nhập khẩu" in tt_stt or "nhap khau" in tt_stt):
                    mua_ds_nk += row_ds
                    mua_thue_nk += row_thue
                if got:
                    mua_rows += 1
                    # ĐỦ Ký hiệu + Số hóa đơn -> lưu thành 1 dòng hóa đơn đầy đủ để
                    # GHI ĐÈ bảng invoices (không chỉ cộng số tổng như trước) — để
                    # "Xuất Excel tổng hợp" dùng ĐÚNG dữ liệu vừa import, đúng kỳ.
                    if c_shdon:
                        shdon_v = str(_o(g_mua, r, c_shdon) or "").strip()
                        if shdon_v:
                            ngay_iso = _ngay_iso(_o(g_mua, r, c_ngay)) if c_ngay else ""
                            tt_bso = num(_o(g_mua, r, c_tt_bso)) if c_tt_bso else (row_ds + row_thue)
                            mua_invoices.append({
                                "khmshdon": "1", "khhdon": _o(g_mua, r, c_kh) or "",
                                "shdon": shdon_v, "tdlap": ngay_iso,
                                "nbmst": str(_o(g_mua, r, c_mst) or "").strip() if c_mst else "",
                                "nbten": _o(g_mua, r, c_ten) or "" if c_ten else "",
                                "nmmst": mst_cty,
                                "tgtcthue": row_ds, "tgtthue": row_thue, "tgtttbso": tt_bso or (row_ds + row_thue),
                                "tthai": _ma_trang_thai(_o(g_mua, r, c_tt)) if c_tt else "1",
                            })

        # ===== BÁN RA: đọc từ sheet 'BK Bán ra' (tách nhóm theo dòng tiêu đề) =====
        if "BK Bán ra" in wb.sheetnames:
            ws = wb["BK Bán ra"]
            g_ban = _grid(ws)
            c_ds = col_idx(ws, "Doanh số bán chưa thuế")
            c_thue = col_idx(ws, "Thuế GTGT")
            c_khms = col_idx(ws, "Ký hiệu mẫu")
            c_kh_b = col_idx(ws, "Ký hiệu HĐ") or col_idx(ws, "Ký hiệu")
            c_shdon_b = col_idx(ws, "Số hóa đơn") or col_idx(ws, "Số Hoá Đơn")
            c_ngay_b = col_idx(ws, "Ngày lập")
            c_mst_b = col_idx(ws, "MST người mua")
            c_ten_b = col_idx(ws, "Tên người mua")
            c_tt_b = col_idx(ws, "Trạng thái")
            # nếu không tìm thấy header (do có tiêu đề phía trên), dò theo cột cố định
            if not c_ds:
                # tìm dòng header chứa "Doanh số bán chưa thuế"
                for r in range(1, min(ws.max_row, 30) + 1):
                    for c in range(1, ws.max_column + 1):
                        v = str(_o(g_ban, r, c) or "")
                        if "Doanh số bán chưa thuế" in v:
                            c_ds = c
                        if v.strip() == "Thuế GTGT":
                            c_thue = c
                    if c_ds:
                        break
            cur_nhom = None
            ban_rows = 0
            for r in range(1, ws.max_row + 1):
                # gộp text cả dòng để phát hiện tiêu đề nhóm / dòng tổng
                row_vals = g_ban[r - 1]
                full = " ".join(str(v or "") for v in row_vals)
                low = full.lower()
                head3 = " ".join(str(v or "") for v in row_vals[0:3])
                # dòng tiêu đề nhóm thuế suất
                if "thuế suất" in head3.lower() or "%" in head3 or "không chịu thuế" in head3.lower():
                    # PHẢI kiểm tra "10%" TRƯỚC "0%": '0%' là CHUỖI CON của '10%'
                    # (vd head3='...chịu thuế suất 10%' vẫn chứa '0%'), nên nếu
                    # kiểm tra '0%' trước sẽ nhận NHẦM nhóm 10% thật thành nhóm
                    # 0% -> mất trắng số thuế của nhóm 10% khi import Excel.
                    if "10%" in head3: cur_nhom = "10"
                    elif "0%" in head3: cur_nhom = "0"
                    elif "5%" in head3: cur_nhom = "5"
                    elif "8%" in head3: cur_nhom = "8"
                    elif "không chịu" in head3.lower(): cur_nhom = "KCT"
                    continue
                # BỎ dòng tổng (Tổng nhóm / TỔNG CỘNG) — dùng CỤM TỪ cụ thể, KHÔNG
                # lọc theo chữ 'tổng' chung chung để tránh bỏ nhầm hóa đơn của khách
                # hàng có TÊN chứa 'TỔNG' (vd 'TỔNG CÔNG TY ...').
                if "tổng cộng" in low or "tổng nhóm" in low:
                    continue
                # Dòng phải có Số hóa đơn mới tính là hóa đơn thật — bỏ qua các
                # dòng tổng phụ KHÔNG có nhãn "Tổng nhóm"/"TỔNG CỘNG" mà người
                # dùng tự chèn thêm khi chỉnh tay file Excel (vd 1 dòng chỉ ghi
                # số tiền cộng dồn "chịu thuế" trước dòng TỔNG CỘNG cuối cùng —
                # xác nhận qua file thật của người dùng). Trước đây bất kỳ dòng
                # nào có số tiền khác 0 đều bị cộng dồn, khiến dòng tổng phụ này
                # bị tính TRÙNG với chính các hóa đơn đã cộng phía trên, làm
                # doanh số/thuế nhóm đó bị nhân đôi trên tờ khai xuất ra.
                shdon_v = str(_o(g_ban, r, c_shdon_b) or "").strip() if c_shdon_b else ""
                if c_shdon_b and not shdon_v:
                    continue
                ds = num(_o(g_ban, r, c_ds)) if c_ds else 0
                th = num(_o(g_ban, r, c_thue)) if c_thue else 0
                if (ds or th) and cur_nhom in ban:
                    ban[cur_nhom]["ds"] += ds
                    ban[cur_nhom]["thue"] += th
                    ban_rows += 1
                    if c_shdon_b:
                        if shdon_v:
                            ngay_iso = _ngay_iso(_o(g_ban, r, c_ngay_b)) if c_ngay_b else ""
                            ban_invoices.append({
                                "khmshdon": str(_o(g_ban, r, c_khms) or "1").strip() if c_khms else "1",
                                "khhdon": _o(g_ban, r, c_kh_b) or "" if c_kh_b else "",
                                "shdon": shdon_v, "tdlap": ngay_iso,
                                "nmmst": str(_o(g_ban, r, c_mst_b) or "").strip() if c_mst_b else "",
                                "nmten": _o(g_ban, r, c_ten_b) or "" if c_ten_b else "",
                                "nbmst": mst_cty,
                                "tgtcthue": ds, "tgtthue": th, "tgtttbso": ds + th,
                                "tthai": _ma_trang_thai(_o(g_ban, r, c_tt_b)) if c_tt_b else "1",
                                # Nhóm thuế suất đọc được từ TIÊU ĐỀ NHÓM của
                                # sheet 'BK Bán ra' ('0'/'5'/'8'/'10'/'KCT') —
                                # LƯU LẠI để khi xuất XML 01/GTGT vẫn phân
                                # loại đúng chỉ tiêu [26]/[29]-[33], vì hóa
                                # đơn import KHÔNG có chi tiết dòng hàng
                                # (ltsuat) để tự suy ra nhóm như hóa đơn tra
                                # cứu — thiếu trường này thì KCT/10% import
                                # sẽ không phân biệt được, lại rơi về đoán mò.
                                "nhom_ts": cur_nhom,
                            })
        else:
            ban_rows = 0

        # ===== GHI ĐÈ bảng 'invoices' (danh sách chi tiết dùng cho Xuất Excel tổng
        # hợp) bằng ĐÚNG dữ liệu vừa import — trước đây import chỉ lưu SỐ TỔNG
        # (imported_data), không đụng tới 'invoices', nên sau khi import "Xuất
        # Excel tổng hợp" (đọc từ 'invoices') vẫn hiện dữ liệu TRA CỨU/IMPORT CŨ
        # của kỳ trước, không phải dữ liệu vừa import. File "đã kiểm tra" là bản
        # CHÍNH THỨC/CUỐI CÙNG của kỳ đang import -> THAY THẾ TOÀN BỘ danh sách cũ
        # (giống hệt cách 1 lượt tra cứu mới thay thế dữ liệu cũ), KHÔNG cộng dồn
        # lẫn với kỳ trước — CHỈ áp dụng riêng cho loại (mua/bán) đọc được đủ Ký
        # hiệu + Số hóa đơn; loại không đọc được cột này thì GIỮ NGUYÊN dữ liệu cũ
        # (file cũ/thiếu cột thì vẫn chỉ lưu số tổng như trước, không đụng invoices).
        # Gộp các dòng CÙNG 1 hóa đơn thật (cùng MST người bán + Ký hiệu + Số
        # hóa đơn) thành 1 dòng duy nhất trước khi ghi vào bảng 'invoices' —
        # sheet 'BK Mua vào' đôi khi có 1 hóa đơn tách thành NHIỀU DÒNG (vd 1
        # dòng hàng hóa 8% + 1 dòng 'Tổng tiền phí' KCT riêng, cùng Ký hiệu/Số
        # hóa đơn). Bảng 'invoices' lưu 1 DÒNG/hóa đơn (không phải theo từng
        # dòng hàng) và khoá UNIQUE không phân biệt được nhiều dòng cùng Ký
        # hiệu/Số hóa đơn khi import (he_thong='import', khmshdon luôn '1')
        # -> INSERT OR REPLACE ghi đè, ÂM THẦM MẤT dòng trước đó, khiến tổng
        # mua vào ghi vào 'invoices' bị THIẾU so với tổng thật của bảng kê
        # (đúng lỗi người dùng phát hiện: [23]/[24]/[25] lệch so với TỔNG
        # CỘNG của 'BK Mua vào').
        if mua_invoices:
            gop = {}
            for inv in mua_invoices:
                key = (_chuan_mst(inv["nbmst"]), str(inv["khhdon"] or "").strip(),
                       str(inv["shdon"] or "").strip())
                if key not in gop:
                    gop[key] = dict(inv)
                else:
                    g = gop[key]
                    g["tgtcthue"] = (g["tgtcthue"] or 0) + (inv["tgtcthue"] or 0)
                    g["tgtthue"] = (g["tgtthue"] or 0) + (inv["tgtthue"] or 0)
                    g["tgtttbso"] = (g["tgtttbso"] or 0) + (inv["tgtttbso"] or 0)
            mua_invoices = list(gop.values())

        so_dong_ghi_de = 0
        if mua_invoices or ban_invoices:
            conn_gd = db()
            if mua_invoices:
                conn_gd.execute(
                    "DELETE FROM invoices WHERE company_id=? AND loai='purchase'", (cid,))
                for inv in mua_invoices:
                    conn_gd.execute("""
                        INSERT OR REPLACE INTO invoices
                        (company_id, loai, he_thong, nbmst, nbten, nmmst,
                         khmshdon, khhdon, shdon, tdlap, tgtcthue, tgtthue, tgtttbso, tthai, raw)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                    """, (cid, "purchase", "import", inv["nbmst"], inv["nbten"], inv["nmmst"],
                          inv["khmshdon"], inv["khhdon"], inv["shdon"], inv["tdlap"],
                          inv["tgtcthue"], inv["tgtthue"], inv["tgtttbso"], inv["tthai"],
                          json.dumps({"tthai": inv["tthai"], "nguon": "import_excel"}, ensure_ascii=False)))
                    so_dong_ghi_de += 1
            if ban_invoices:
                conn_gd.execute(
                    "DELETE FROM invoices WHERE company_id=? AND loai='sold'", (cid,))
                for inv in ban_invoices:
                    conn_gd.execute("""
                        INSERT OR REPLACE INTO invoices
                        (company_id, loai, he_thong, nbmst, nbten, nmmst,
                         khmshdon, khhdon, shdon, tdlap, tgtcthue, tgtthue, tgtttbso, tthai, raw)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                    """, (cid, "sold", "import", inv["nbmst"], "", inv["nmmst"],
                          inv["khmshdon"], inv["khhdon"], inv["shdon"], inv["tdlap"],
                          inv["tgtcthue"], inv["tgtthue"], inv["tgtttbso"], inv["tthai"],
                          json.dumps({"tthai": inv["tthai"], "nguon": "import_excel",
                                      "nhom_ts": inv.get("nhom_ts")}, ensure_ascii=False)))
                    so_dong_ghi_de += 1
            conn_gd.commit()
            conn_gd.close()

        # Sau khi GHI ĐÈ 'invoices' -> TỰ ĐỘNG xuất lại ngay file Excel "Bảng
        # kê hóa đơn" (BangKe_HoaDon_{mst}...xlsx, kể cả lưu vào thư mục kết
        # xuất đã cấu hình nếu có). "Kết xuất XML" (từ bản .18) CHỈ đọc số
        # liệu từ file bảng kê ĐÃ LƯU TRÊN ĐĨA, không hề đụng tới 'invoices'
        # nữa — nếu không xuất lại NGAY ở đây, file bảng kê trên đĩa vẫn giữ
        # snapshot TRƯỚC KHI import, nên dù 'invoices' đã ghi đè đúng số liệu
        # vừa import, "Kết xuất XML" vẫn ra số liệu CŨ (đã xác nhận đúng
        # nguyên nhân qua dữ liệu thật: import xong, XML vẫn giữ nguyên số cũ
        # dù đã sửa/kiểm tra lại file, vì file bảng kê chưa được xuất lại).
        if so_dong_ghi_de:
            try:
                export_excel(cid, luu_ket_xuat=1, tu_ngay="", den_ngay="", mo_file=0)
            except Exception:
                pass

        conn = db()
        conn.execute("""
            INSERT INTO imported_data (company_id, ky, mua_ds, mua_thue,
                mua_ds_nk, mua_thue_nk,
                ban_ds_0, ban_ds_5, ban_thue_5, ban_ds_8, ban_thue_8,
                ban_ds_10, ban_thue_10, ban_ds_kct, updated_at)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            ON CONFLICT(company_id, ky) DO UPDATE SET
                mua_ds=excluded.mua_ds, mua_thue=excluded.mua_thue,
                mua_ds_nk=excluded.mua_ds_nk, mua_thue_nk=excluded.mua_thue_nk,
                ban_ds_0=excluded.ban_ds_0, ban_ds_5=excluded.ban_ds_5,
                ban_thue_5=excluded.ban_thue_5, ban_ds_8=excluded.ban_ds_8,
                ban_thue_8=excluded.ban_thue_8, ban_ds_10=excluded.ban_ds_10,
                ban_thue_10=excluded.ban_thue_10, ban_ds_kct=excluded.ban_ds_kct,
                updated_at=excluded.updated_at
        """, (cid, ky, round(mua_ds), round(mua_thue),
              round(mua_ds_nk), round(mua_thue_nk), round(ban["0"]["ds"]),
              round(ban["5"]["ds"]), round(ban["5"]["thue"]),
              round(ban["8"]["ds"]), round(ban["8"]["thue"]),
              round(ban["10"]["ds"]), round(ban["10"]["thue"]),
              round(ban["KCT"]["ds"]),
              datetime.datetime.now().isoformat()))
        conn.commit()
        conn.close()
        return {
            "ok": True, "ky": ky,
            "mua_ds": round(mua_ds), "mua_thue": round(mua_thue), "mua_rows": mua_rows,
            "mua_ds_nk": round(mua_ds_nk), "mua_thue_nk": round(mua_thue_nk),
            "mua_sheet_found": mua_sheet_found,
            "ban_thue": round(sum(b["thue"] for b in ban.values())),
            "ban_8_ds": round(ban["8"]["ds"]), "ban_rows": ban_rows,
            "ban_sheet_found": ban_sheet_found,
            "so_dong_ghi_de": so_dong_ghi_de,
        }

    return await run_in_threadpool(_xu_ly)


def _get_imported(cid, ky=""):
    """Lấy dữ liệu đã import ĐÚNG KỲ. Nếu kỳ này chưa import -> None (dùng tra cứu).
    Chỉ khi không truyền kỳ (ky='') mới lấy bản import mới nhất."""
    conn = db()
    row = None
    if ky:
        # chỉ lấy import KHỚP ĐÚNG kỳ đang xem
        row = conn.execute("SELECT * FROM imported_data WHERE company_id=? AND ky=?",
                           (cid, ky)).fetchone()
    else:
        # không có kỳ -> lấy bản mới nhất (vd gọi không kèm kỳ)
        row = conn.execute(
            "SELECT * FROM imported_data WHERE company_id=? ORDER BY updated_at DESC LIMIT 1",
            (cid,)).fetchone()
    conn.close()
    return row


@app.get("/api/imported/{cid}")
def get_imported_api(cid: int, ky: str = ""):
    """Trả dữ liệu đã import để màn hình hiển thị (nếu có)."""
    row = _get_imported(cid, ky)
    if not row:
        return {"has_import": False}
    d = dict(row)
    mua_ds = _to_num(d["mua_ds"]) or 0
    mua_thue = _to_num(d["mua_thue"]) or 0
    ban_ds = sum((_to_num(d[k]) or 0) for k in
                 ["ban_ds_0", "ban_ds_5", "ban_ds_8", "ban_ds_10"])
    ban_thue = sum((_to_num(d[k]) or 0) for k in
                   ["ban_thue_5", "ban_thue_8", "ban_thue_10"])
    return {
        "has_import": True, "ky": d["ky"],
        "mua_ds": round(mua_ds), "mua_thue": round(mua_thue),
        "ban_ds": round(ban_ds), "ban_thue": round(ban_thue),
        "updated_at": d["updated_at"],
    }


@app.delete("/api/imported/{cid}")
def del_imported_api(cid: int):
    """Xóa dữ liệu import -> quay lại dùng dữ liệu tra cứu."""
    conn = db()
    conn.execute("DELETE FROM imported_data WHERE company_id=?", (cid,))
    conn.commit()
    conn.close()
    return {"ok": True}


def _khoang_ngay_ky(ky):
    """'MM/YYYY' hoặc 'QX/YYYY' -> (d_tu, d_den) của đúng kỳ đó (tháng thì
    trọn tháng, quý thì trọn 3 tháng). (None, None) nếu ky không hợp lệ."""
    import calendar as _cal
    ky = (ky or "").strip()
    if not ky or "/" not in ky:
        return None, None
    try:
        a, b = ky.split("/", 1)
        a = a.strip().upper()
        yyyy = int(b.strip())
        if a.startswith("Q") and a[1:].isdigit():
            q = max(1, min(4, int(a[1:])))
            mm1 = (q - 1) * 3 + 1
            mm2 = mm1 + 2
            d_tu = datetime.date(yyyy, mm1, 1)
            d_den = datetime.date(yyyy, mm2, _cal.monthrange(yyyy, mm2)[1])
        else:
            mm = int(a)
            d_tu = datetime.date(yyyy, mm, 1)
            d_den = datetime.date(yyyy, mm, _cal.monthrange(yyyy, mm)[1])
        return d_tu, d_den
    except Exception:
        return None, None


def _tong_thue_nk_tokhai(cid, ky):
    """Tổng thuế GTGT hàng nhập khẩu (bảng tokhai_nhap — import RIÊNG từ tờ
    khai hải quan, KHÔNG phải import bảng kê Excel) của ĐÚNG kỳ đang tính."""
    d_tu, d_den = _khoang_ngay_ky(ky)
    if not d_tu:
        return 0
    conn = db()
    tk_rows = conn.execute(
        "SELECT ngay_dk, items_json FROM tokhai_nhap WHERE company_id=?", (cid,)).fetchall()
    conn.close()
    tong = 0
    for tkr in tk_rows:
        s = str(tkr["ngay_dk"] or "").split("T")[0]
        try:
            d = datetime.datetime.strptime(s, "%Y-%m-%d").date()
        except Exception:
            continue
        if not (d_tu <= d <= d_den):
            continue
        try:
            its = json.loads(tkr["items_json"]) if tkr["items_json"] else []
        except Exception:
            its = []
        for it in its:
            tong += round(it.get("tien_thue_gtgt", 0) or 0)
    return tong


@app.get("/api/vat-tmtinh/{cid}")
def vat_tam_tinh(cid: int, response: Response, ky: str = "", du_dau_ky: float = None):
    """
    Tạm tính thuế VAT trong kỳ:
      - vat_mua: tổng VAT đầu vào (từ hóa đơn mua, loại HĐ thay thế/hủy)
      - vat_ban: tổng VAT đầu ra (từ hóa đơn bán)
      - du_dau_ky: số thuế còn được khấu trừ kỳ trước chuyển sang (người dùng nhập
        hoặc tự lấy 'du_cuoi_ky' của kỳ trước nếu đã lưu)
    Công thức: chenh = vat_ban - vat_mua - du_dau_ky
      chenh > 0 -> phải nộp = chenh ; du_cuoi_ky = 0
      chenh <= 0 -> phải nộp = 0 ; du_cuoi_ky = -chenh (chuyển kỳ sau)
    """
    # KHÔNG được để trình duyệt CACHE endpoint này — đây là hành động tính
    # toán LẠI mỗi lần bấm, dùng GET nên trình duyệt có thể tự phục vụ lại
    # response CŨ (cùng URL/tham số) mà KHÔNG hề gọi lại server, khiến người
    # dùng tưởng đã tính lại nhưng thực ra vẫn thấy đúng kết quả CŨ dù dữ
    # liệu công ty (import/tra cứu lại) đã thay đổi.
    response.headers["Cache-Control"] = "no-store"
    conn = db()
    comp = conn.execute("SELECT * FROM companies WHERE id=?", (cid,)).fetchone()
    rows = _gop_hoa_don_trung_he_thong(
        conn.execute("SELECT * FROM invoices WHERE company_id=?", (cid,)).fetchall())
    if not comp:
        conn.close()
        raise HTTPException(404, "Không tìm thấy công ty")

    def loai_bo(r):
        try:
            raw = json.loads(r["raw"]) if r["raw"] else {}
        except Exception:
            raw = {}
        tt = str(raw.get("tthai", r["tthai"]) or "").strip()
        if tt in ("4", "6"):
            return True
        # loại HĐ không đủ điều kiện cấp mã
        kq = str(raw.get("ttxly", "") or "").strip().lower()
        kq_mota = _mo_ta_ket_qua(raw.get("ttxly", "")).lower()
        if kq == "4" or "không đủ điều kiện" in kq or "không đủ điều kiện" in kq_mota:
            return True
        return False

    # Thuế GTGT hàng NHẬP KHẨU từ bảng tokhai_nhap (import RIÊNG tờ khai hải
    # quan) — TRƯỚC ĐÂY hàm này hoàn toàn không cộng khoản này, nên sau khi
    # import tờ khai nhập khẩu, phần tạm tính VẪN GIỮ NGUYÊN như chưa import.
    thue_nk_rieng = _tong_thue_nk_tokhai(cid, ky)

    # ƯU TIÊN dữ liệu đã import từ Excel (nếu có); nếu không, dùng dữ liệu tra cứu
    imp = _get_imported(cid, ky)
    canh_bao_nk = ""
    if imp:
        vat_mua = _to_num(imp["mua_thue"]) or 0
        # Nếu file Excel bảng kê ĐÃ có sẵn dòng hàng nhập khẩu (ký hiệu TKNK) thì
        # mua_thue đã bao gồm thuế NK rồi — KHÔNG cộng thêm lần nữa (giống hệt
        # cách tính của tờ khai chính thức ở /api/xuat-to-khai) để tránh trùng.
        imp_nk_thue = _to_num(imp["mua_thue_nk"]) or 0 if "mua_thue_nk" in imp.keys() else 0
        if not imp_nk_thue:
            vat_mua += thue_nk_rieng
        elif round(imp_nk_thue) != round(thue_nk_rieng):
            # Dữ liệu "đã kiểm tra" (đóng băng lúc import) có phần thuế NK KHÁC
            # với tính lại TRỰC TIẾP từ tờ khai nhập khẩu đang có cho đúng kỳ
            # này -> rất có thể đã import thêm/xoá tờ khai nhập khẩu SAU lần
            # import "dữ liệu đã kiểm tra" gần nhất, số liệu đang dùng bị CŨ.
            canh_bao_nk = (
                f"⚠ Tờ khai nhập khẩu đang có tổng thuế GTGT hàng NK đúng kỳ này là "
                f"{round(thue_nk_rieng):,} đ, nhưng số đang dùng để tạm tính (từ dữ liệu 'đã kiểm tra') "
                f"là {round(imp_nk_thue):,} đ — CHÊNH LỆCH {round(thue_nk_rieng - imp_nk_thue):,} đ. "
                f"Hãy Xuất Excel tổng hợp rồi Import lại 'dữ liệu đã kiểm tra' để cập nhật trước khi nộp tờ khai.")
        vat_ban = (_to_num(imp["ban_thue_5"]) or 0) + (_to_num(imp["ban_thue_8"]) or 0) \
                  + (_to_num(imp["ban_thue_10"]) or 0)
        nguon = "import"
    else:
        vat_mua = vat_ban = 0
        for r in rows:
            if loai_bo(r):
                continue
            if r["loai"] == "purchase":
                vat_mua += _to_num(r["tgtthue"]) or 0
            elif r["loai"] == "sold":
                vat_ban += _to_num(r["tgtthue"]) or 0
        # Hóa đơn tra cứu từ trang Thuế KHÔNG bao giờ có tờ khai nhập khẩu (đây
        # là dữ liệu hải quan, nhập riêng) -> luôn cộng thêm.
        vat_mua += thue_nk_rieng
        nguon = "tra cứu"

    # số dư đầu kỳ: ưu tiên giá trị truyền vào; nếu None thì lấy du_cuoi_ky kỳ trước
    if du_dau_ky is None:
        prev = None
        prev_ky = _ky_lien_truoc(ky)   # hỗ trợ cả 'MM/YYYY' và 'QX/YYYY'
        if prev_ky:
            prev = conn.execute(
                "SELECT du_cuoi_ky FROM vat_balance WHERE company_id=? AND ky=?",
                (cid, prev_ky)).fetchone()
        du_dau_ky = (prev["du_cuoi_ky"] if prev and prev["du_cuoi_ky"] else 0) or 0
        # nếu kỳ này đã lưu rồi, lấy lại số dư đầu kỳ đã lưu
        cur = conn.execute(
            "SELECT du_dau_ky FROM vat_balance WHERE company_id=? AND ky=?",
            (cid, ky)).fetchone()
        if cur and cur["du_dau_ky"] is not None:
            du_dau_ky = cur["du_dau_ky"]

    chenh = vat_ban - vat_mua - (du_dau_ky or 0)
    phai_nop = chenh if chenh > 0 else 0
    du_cuoi_ky = -chenh if chenh <= 0 else 0
    conn.close()
    return {
        "ky": ky, "vat_mua": round(vat_mua), "vat_ban": round(vat_ban),
        "du_dau_ky": round(du_dau_ky or 0),
        "phai_nop": round(phai_nop), "du_cuoi_ky": round(du_cuoi_ky),
        "nguon": nguon, "canh_bao_nk": canh_bao_nk,
    }


def _nam_quy_cua_ky(ky):
    """Tách 'ky' ('QX/YYYY' hoặc 'MM/YYYY') -> (nam:int, quy:int 1-4).
    Kỳ tháng cũng quy về đúng quý chứa tháng đó (chỉ dùng để XÁC ĐỊNH thư
    mục Năm/Quý lưu file kết xuất — không phải quyết định loại kỳ kê khai
    tháng/quý). Trả (None, None) nếu không phân tích được."""
    ky = (ky or "").strip()
    if "/" not in ky:
        return None, None
    a, b = ky.split("/", 1)
    a = a.strip().upper()
    try:
        nam = int(b.strip())
    except Exception:
        return None, None
    if a.startswith("Q") and a[1:].isdigit():
        return nam, max(1, min(4, int(a[1:])))
    try:
        thang = int(a)
    except Exception:
        return None, None
    return nam, (thang - 1) // 3 + 1


def _doc_ct41_ky_truoc(comp, ky_hien_tai):
    """Tự động đọc chỉ tiêu [41] (thuế GTGT còn được khấu trừ chuyển kỳ
    sau) từ file XML tờ khai 01/GTGT của KỲ LIỀN TRƯỚC ky_hien_tai, tìm
    trong thư mục lưu file kết xuất riêng của công ty (cấu trúc Năm/Quý
    hoặc Năm/Tháng nếu công ty kê khai theo tháng) — dùng làm 'Số dư đầu
    kỳ' (chỉ tiêu [22]) cho kỳ hiện tại, thay vì phải tự mở file cũ ra
    chép tay số liệu.
    Trả (gia_tri_hoac_None, ky_truoc, duong_dan_file_hoac_None)."""
    import re as _re_ct41
    ky_truoc = _ky_lien_truoc(ky_hien_tai)
    if not ky_truoc:
        return None, "", None
    a_truoc = ky_truoc.split("/", 1)[0].strip().upper()
    if a_truoc.startswith("Q"):
        nam, quy = _nam_quy_cua_ky(ky_truoc)
        if not nam:
            return None, ky_truoc, None
        fp, _ung_vien = _tim_file_nop_theo_cong_ty(comp, "GTGT", nam, quy, "")
    else:
        # Kỳ trước là THÁNG — tìm ĐÚNG theo đúng tháng đó, KHÔNG quy về quý
        # chứa nó nữa: trước đây _nam_quy_cua_ky() quy tháng về quý rồi tìm
        # theo cấu trúc Năm/Quý (Quý N cả 3 tháng) — với công ty kê khai
        # theo THÁNG (tự tổ chức thư mục Năm/THANG N — xem _thu_muc_ket_xuat_ky)
        # thì tìm sai thư mục/không khớp kỳ trong tên file -> không lấy được
        # số dư đầu kỳ (đã xác nhận qua tờ khai thật của công ty HOÀNG CHÂU
        # HOÀNG, kỳ tháng 06/2026: chỉ tiêu [22] không lấy đúng số dư cuối kỳ
        # tháng 05/2026). Nay tìm thẳng theo khoảng ngày ĐÚNG 1 THÁNG đó.
        try:
            mm, yyyy = _ky_ve_thang(ky_truoc)
            nam = int(yyyy)
        except Exception:
            return None, ky_truoc, None
        export_dir = (comp["export_dir"] if comp and "export_dir" in comp.keys() else "") or ""
        fp = None
        if export_dir:
            last_day = calendar.monthrange(nam, int(mm))[1]
            tu_ngay = f"01/{mm}/{yyyy}"
            den_ngay = f"{last_day:02d}/{mm}/{yyyy}"
            dich = _thu_muc_ket_xuat_ky(export_dir, tu_ngay, den_ngay)
            if dich:
                fp, _ung_vien = _tim_file_nop_to_khai(dich, comp["mst"], "GTGT")
    if not fp:
        return None, ky_truoc, None
    try:
        with open(fp, encoding="utf-8-sig") as f:
            xml = f.read()
        m = _re_ct41.search(r"<ct41>(.*?)</ct41>", xml, _re_ct41.DOTALL)
        if m:
            return (_to_num(m.group(1).strip()) or 0), ky_truoc, fp
    except Exception:
        pass
    return None, ky_truoc, fp


@app.get("/api/vat-du-dau-ky-tu-dong/{cid}")
def vat_du_dau_ky_tu_dong(cid: int, ky: str = ""):
    """Tự động lấy 'Số dư đầu kỳ' từ chỉ tiêu [41] của tờ khai GTGT kỳ
    liền trước (đọc file XML đã lưu trong thư mục kết xuất Năm/Quý riêng
    của công ty), thay vì phải tự tìm file cũ ra chép tay."""
    if not ky:
        raise HTTPException(400, "Thiếu kỳ kê khai")
    conn = db()
    comp = conn.execute("SELECT * FROM companies WHERE id=?", (cid,)).fetchone()
    conn.close()
    if not comp:
        raise HTTPException(404, "Không tìm thấy công ty")
    gia_tri, ky_truoc, fp = _doc_ct41_ky_truoc(comp, ky)
    if gia_tri is None:
        raise HTTPException(
            404, f"Không tìm thấy tờ khai GTGT của kỳ {ky_truoc or '(không xác định được kỳ trước)'} "
                 f"trong thư mục lưu file kết xuất của công ty này — hãy kiểm tra đã cấu hình đúng "
                 f"'Thư mục lưu file kết xuất' và đã có file kết xuất kỳ đó chưa (mục 'Sửa công ty').")
    return {"ok": True, "du_dau_ky": gia_tri, "ky_truoc": ky_truoc, "file": os.path.basename(fp)}


@app.post("/api/vat-tmtinh/{cid}")
def vat_luu(cid: int, data: dict = Body(...)):
    """Lưu số dư VAT của kỳ (gọi khi bấm Save)."""
    ky = data.get("ky", "")
    if not ky:
        raise HTTPException(400, "Thiếu kỳ kê khai")
    conn = db()
    conn.execute("""
        INSERT INTO vat_balance (company_id, ky, du_dau_ky, vat_mua, vat_ban,
                                 phai_nop, du_cuoi_ky, updated_at)
        VALUES (?,?,?,?,?,?,?,?)
        ON CONFLICT(company_id, ky) DO UPDATE SET
            du_dau_ky=excluded.du_dau_ky, vat_mua=excluded.vat_mua,
            vat_ban=excluded.vat_ban, phai_nop=excluded.phai_nop,
            du_cuoi_ky=excluded.du_cuoi_ky, updated_at=excluded.updated_at
    """, (cid, ky, data.get("du_dau_ky", 0), data.get("vat_mua", 0),
          data.get("vat_ban", 0), data.get("phai_nop", 0),
          data.get("du_cuoi_ky", 0), datetime.datetime.now().isoformat()))
    conn.commit()
    conn.close()
    return {"ok": True}


def _tim_file_bang_ke_moi_nhat(mst, save_dir, export_dir=None, d_tu=None, d_den=None):
    """Tìm file Excel 'Bảng kê hóa đơn' (BangKe_HoaDon_{mst}...xlsx) ĐÃ XUẤT
    VÀ LƯU SẴN trên máy. Trả đường dẫn hoặc None nếu không tìm thấy.

    ƯU TIÊN thư mục 'Thư mục lưu file kết xuất' (export_dir) NGƯỜI DÙNG đã tự
    cấu hình cho công ty (đúng thư mục Năm/Quý của kỳ đang xuất) — đây là nơi
    người dùng CHỦ ĐỘNG chọn, đáng tin hơn hẳn thư mục 'downloads' nội bộ của
    phần mềm (thư mục này CHUNG cho mọi công ty, và nếu phần mềm được cài bên
    trong 1 ổ đồng bộ như OneDrive thì Date Modified của file cũ trong đó có
    thể bị hệ thống đồng bộ tự "chạm" lại, khiến bản CŨ bị chọn nhầm thay vì
    bản vừa xuất — đã xác nhận đúng nguyên nhân qua dữ liệu thật của người
    dùng). CHỈ khi export_dir không có sẵn bản nào cho đúng kỳ này mới rơi về
    tìm trong (downloads nội bộ, save_dir) và chọn bản mới nhất theo mtime
    như trước."""
    import glob
    if export_dir and d_tu and d_den:
        try:
            dich = _thu_muc_ket_xuat_ky(
                export_dir, d_tu.strftime("%d/%m/%Y"), d_den.strftime("%d/%m/%Y"))
        except Exception:
            dich = None
        if dich and os.path.isdir(dich):
            try:
                ung_vien_kx = glob.glob(os.path.join(dich, f"BangKe_HoaDon_{mst}*.xlsx"))
            except Exception:
                ung_vien_kx = []
            if ung_vien_kx:
                return max(ung_vien_kx, key=lambda p: os.path.getmtime(p))
    ung_vien = []
    for thu_muc in (DOWNLOAD_DIR, save_dir):
        if thu_muc and os.path.isdir(thu_muc):
            try:
                ung_vien += glob.glob(os.path.join(thu_muc, f"BangKe_HoaDon_{mst}*.xlsx"))
            except Exception:
                pass
    if not ung_vien:
        return None
    return max(ung_vien, key=lambda p: os.path.getmtime(p))


def _doc_mua_vao_tu_file_bang_ke(mst, save_dir, d_tu, d_den, export_dir=None):
    """Đọc tổng MUA VÀO (doanh số + thuế GTGT) TRỰC TIẾP từ file Excel 'Bảng
    kê hóa đơn' đã xuất và lưu sẵn trên máy (sheet 'BK Mua vào') — cùng
    nguyên tắc với _doc_nhom_ban_ra_tu_file_bang_ke (xem giải thích ở đó):
    Kết xuất XML KHÔNG tự tra cứu/gọi mạng nữa, chỉ dựa vào số liệu đã có sẵn
    trong bảng kê (đã gồm sẵn 'Tổng tiền phí' — sheet đó CỘNG SẴN dòng phí
    riêng vào danh sách, không cần tính lại). Đọc TỪNG DÒNG hóa đơn, tự lọc
    theo đúng khoảng ngày (d_tu..d_den) của kỳ đang xuất XML (sheet liệt kê
    CẢ LỊCH SỬ hóa đơn công ty, không lọc theo đúng kỳ khai).
    Trả về {'ds','thue','ds_full','thue_full'} — kể cả khi bằng 0 (công ty
    KHÔNG phát sinh mua vào kỳ này là chuyện bình thường, không phải lỗi).
    CHỈ trả None khi KHÔNG tìm/đọc được file hoặc sheet 'BK Mua vào' — tức
    thật sự chưa có dữ liệu để tin cậy, chứ không phải "có nhưng bằng 0"."""
    fpath = _tim_file_bang_ke_moi_nhat(mst, save_dir, export_dir, d_tu, d_den)
    if not fpath:
        return None
    # QUAN TRỌNG: mở workbook read_only mà KHÔNG gọi wb.close() sẽ giữ
    # NGUYÊN handle file mở (openpyxl read_only stream trực tiếp từ file
    # zip, không tự đóng khi hết hàm) — Windows/OneDrive coi file này vẫn
    # đang "được dùng" bởi tiến trình phần mềm, khiến người dùng mở file
    # bằng Excel để sửa tay xong KHÔNG SAVE ĐƯỢC ("Document not saved")
    # dù chỉ đang ĐỌC, không hề ghi gì (đã xác nhận đúng nguyên nhân qua
    # dữ liệu thật của người dùng). Bọc try/finally để LUÔN đóng lại ngay
    # khi đọc xong, dù đọc lỗi hay đúng ở giữa chừng.
    wb = None
    try:
        import openpyxl
        wb = openpyxl.load_workbook(fpath, data_only=True, read_only=True)
        if "BK Mua vào" not in wb.sheetnames:
            return None
        ws = wb["BK Mua vào"]
        ds = thue = ds_full = thue_full = 0
        ds_nk = thue_nk = 0   # TRONG ĐÓ: riêng hàng NHẬP KHẨU (dòng 'TKNK') -> [23a]/[24a]
        for row in ws.iter_rows(min_row=2, values_only=True):
            stt = row[0] if len(row) > 0 else None
            if not isinstance(stt, (int, float)):
                continue   # bỏ dòng "TỔNG CỘNG"/trống — chỉ lấy dòng hóa đơn thật (cột A = STT số)
            ds_o = row[8] if len(row) > 8 else 0     # cột I: Doanh số mua chưa thuế
            thue_o = row[9] if len(row) > 9 else 0   # cột J: Thuế GTGT
            ds_o = ds_o if isinstance(ds_o, (int, float)) else 0
            thue_o = thue_o if isinstance(thue_o, (int, float)) else 0
            ds_full += ds_o; thue_full += thue_o
            ngay_raw = row[3] if len(row) > 3 else None   # cột D: Ngày lập
            d = None
            if isinstance(ngay_raw, (datetime.date, datetime.datetime)):
                d = ngay_raw.date() if isinstance(ngay_raw, datetime.datetime) else ngay_raw
            elif isinstance(ngay_raw, str) and "/" in ngay_raw:
                try:
                    d = datetime.datetime.strptime(ngay_raw.strip(), "%d/%m/%Y").date()
                except Exception:
                    d = None
            if not (d and d_tu <= d <= d_den):
                continue
            ds += ds_o; thue += thue_o
            # Ký hiệu 'TKNK' (cột B) hoặc Trạng thái 'Tờ khai nhập khẩu' (cột L)
            # -> dòng hàng NHẬP KHẨU, tách riêng cho [23a]/[24a]. Tính TRỰC TIẾP
            # từ CHÍNH file bảng kê đang đọc (giống hệt cách tính [23]/[24] ở
            # trên) — TRƯỚC ĐÂY phần này lấy từ 1 bảng cache riêng
            # (imported_data.mua_ds_nk, chỉ được ghi 1 LẦN lúc "Import dữ liệu
            # đã kiểm tra") nên khi người dùng import THÊM tờ khai nhập khẩu rồi
            # xuất lại Excel (không re-import "dữ liệu đã kiểm tra"), [23]/[24]
            # tự cập nhật đúng (đọc file mới) nhưng [23a]/[24a] vẫn giữ số CŨ từ
            # cache — đã xác nhận đúng nguyên nhân qua dữ liệu thật (công ty
            # AFLEX MST 0316363200: xuất Excel xong, [23a]/[24a] vẫn không đổi).
            kh = str(row[1] or "").strip().upper() if len(row) > 1 else ""
            tt_row = str(row[11] or "").strip().lower() if len(row) > 11 else ""
            if kh == "TKNK" or "nhập khẩu" in tt_row or "nhap khau" in tt_row:
                ds_nk += ds_o; thue_nk += thue_o
        return {"ds": ds, "thue": thue, "ds_full": ds_full, "thue_full": thue_full,
                "ds_nk": ds_nk, "thue_nk": thue_nk, "_file": fpath}
    except Exception:
        return None
    finally:
        if wb is not None:
            try:
                wb.close()
            except Exception:
                pass


def _doc_nhom_ban_ra_tu_file_bang_ke(mst, save_dir, d_tu, d_den, export_dir=None):
    """Đọc nhóm BÁN RA theo thuế suất TRỰC TIẾP từ file Excel 'Bảng kê hóa
    đơn' (BangKe_HoaDon_{mst}...xlsx) ĐÃ XUẤT VÀ LƯU SẴN trên máy (sheet
    'BK Bán ra') — theo đúng yêu cầu: Kết xuất XML KHÔNG tự tra cứu/gọi mạng
    lại nữa, CHỈ dựa vào số liệu đã có sẵn trong file bảng kê đã lưu (số liệu
    người dùng đã xem/xác nhận đúng trong file đó). Đọc TỪNG DÒNG hóa đơn
    (không dùng dòng 'Tổng nhóm'/'TỔNG CỘNG' có sẵn — 2 dòng đó gộp CẢ LỊCH
    SỬ hóa đơn công ty, không lọc theo đúng kỳ khai), tự lọc lại theo đúng
    khoảng ngày (d_tu..d_den) của kỳ đang xuất XML.
    Trả về dict {'KCT'/'0'/'5'/'8'/'10'/'KHAC': {'ds','thue'}} — kể cả khi
    toàn bộ bằng 0 (công ty KHÔNG phát sinh bán ra kỳ này là chuyện bình
    thường, không phải lỗi). CHỈ trả None khi KHÔNG tìm/đọc được file hoặc
    sheet 'BK Bán ra' — tức thật sự chưa có dữ liệu để tin cậy."""
    fpath = _tim_file_bang_ke_moi_nhat(mst, save_dir, export_dir, d_tu, d_den)
    if not fpath:
        return None
    # Xem giải thích try/finally + wb.close() ở _doc_mua_vao_tu_file_bang_ke:
    # KHÔNG đóng workbook read_only sẽ giữ handle file mở, khiến người dùng
    # mở file này bằng Excel để sửa tay KHÔNG SAVE ĐƯỢC dù phần mềm chỉ đang
    # ĐỌC (đã xác nhận đúng nguyên nhân qua dữ liệu thật của người dùng).
    wb = None
    try:
        import openpyxl
        wb = openpyxl.load_workbook(fpath, data_only=True, read_only=True)
        if "BK Bán ra" not in wb.sheetnames:
            return None
        ws = wb["BK Bán ra"]

        nhan_to_key = {
            "1. Hàng hóa, dịch vụ không chịu thuế GTGT (KCT)": "KCT",
            "2. Hàng hóa, dịch vụ chịu thuế suất 0%": "0",
            "3. Hàng hóa, dịch vụ chịu thuế suất 5%": "5",
            "4. Hàng hóa, dịch vụ chịu thuế suất 8%": "8",
            "5. Hàng hóa, dịch vụ chịu thuế suất 10%": "10",
            "6. Khác / chưa lấy được file XML": "KHAC",
        }
        ket_qua = {"KCT": {"ds": 0, "thue": 0}, "0": {"ds": 0, "thue": 0},
                   "5": {"ds": 0, "thue": 0}, "8": {"ds": 0, "thue": 0},
                   "10": {"ds": 0, "thue": 0}, "KHAC": {"ds": 0, "thue": 0}}
        ds_full = thue_full = 0   # TỔNG CỘNG cả sheet (không lọc kỳ) — để đối chiếu [34]/[35]
        nhom_hien_tai = None
        for row in ws.iter_rows(min_row=2, values_only=True):
            col_a = row[0] if len(row) > 0 else None
            if isinstance(col_a, str) and col_a.strip() in nhan_to_key:
                nhom_hien_tai = nhan_to_key[col_a.strip()]
                continue
            if not isinstance(col_a, (int, float)) or nhom_hien_tai is None:
                continue
            ds_o = row[8] if len(row) > 8 else 0     # cột I: Doanh số bán chưa thuế
            thue_o = row[9] if len(row) > 9 else 0   # cột J: Thuế GTGT
            ds_o = ds_o if isinstance(ds_o, (int, float)) else 0
            thue_o = thue_o if isinstance(thue_o, (int, float)) else 0
            ds_full += ds_o; thue_full += thue_o
            ngay_raw = row[4] if len(row) > 4 else None   # cột E: Ngày lập
            d = None
            if isinstance(ngay_raw, (datetime.date, datetime.datetime)):
                d = ngay_raw.date() if isinstance(ngay_raw, datetime.datetime) else ngay_raw
            elif isinstance(ngay_raw, str) and "/" in ngay_raw:
                try:
                    d = datetime.datetime.strptime(ngay_raw.strip(), "%d/%m/%Y").date()
                except Exception:
                    d = None
            if not (d and d_tu <= d <= d_den):
                continue
            ket_qua[nhom_hien_tai]["ds"] += ds_o
            ket_qua[nhom_hien_tai]["thue"] += thue_o
        ket_qua["_full"] = {"ds": ds_full, "thue": thue_full}
        ket_qua["_file"] = fpath
        return ket_qua
    except Exception:
        return None
    finally:
        if wb is not None:
            try:
                wb.close()
            except Exception:
                pass


@app.get("/api/export-htkk/{cid}")
def export_htkk(cid: int, response: Response, ky: str = "", nguoi_ky: str = "", tu: str = "", den: str = "",
                luu_ket_xuat: int = 0, mo_file: int = 1):
    """Bọc lỗi để trả về CHI TIẾT lỗi thật thay vì lỗi 500 trống không rõ
    nguyên nhân (xem thêm giải thích ở export_htkk_tncn)."""
    # KHÔNG được để trình duyệt CACHE endpoint này (GET, cùng URL/tham số mỗi
    # lần bấm "Kết xuất XML") — đây là hành động GHI FILE MỚI mỗi lần gọi;
    # nếu trình duyệt tự phục vụ lại response CŨ từ cache thì server KHÔNG hề
    # chạy lại, file XML trên đĩa vẫn giữ nguyên nội dung CŨ dù dữ liệu công
    # ty (bảng kê/import) đã đổi — người dùng bấm xuất lại nhưng vẫn thấy y
    # hệt số liệu cũ, tưởng nhầm là code tính sai.
    response.headers["Cache-Control"] = "no-store"
    try:
        return _export_htkk_impl(cid, ky, nguoi_ky, tu, den, luu_ket_xuat, mo_file)
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(500, f"Lỗi kết xuất XML GTGT: {type(e).__name__}: {str(e)[:200]}")


def _export_htkk_impl(cid: int, ky: str = "", nguoi_ky: str = "", tu: str = "", den: str = "",
                luu_ket_xuat: int = 0, mo_file: int = 1):
    """
    Tạo file XML tờ khai 01/GTGT (TT80/2021) để nhập vào HTKK.
    Hàng bán ra 8% -> đưa vào nhóm 10% (ct32/ct33) + Phụ lục NQ142/2024.
    ky: 'MM/YYYY' (vd '05/2026'); nếu trống lấy từ hóa đơn.
    luu_ket_xuat=1: lưu thêm vào thư mục kết xuất của công ty theo Năm/Quý.
    mo_file=0: không tự mở file (dùng khi tự xuất sau tra cứu hàng loạt).
    """
    import html as _html
    conn = db()
    comp = conn.execute("SELECT * FROM companies WHERE id=?", (cid,)).fetchone()
    rows = _gop_hoa_don_trung_he_thong(
        conn.execute("SELECT * FROM invoices WHERE company_id=?", (cid,)).fetchall())
    if not comp:
        conn.close()
        raise HTTPException(404, "Không tìm thấy công ty")

    # Việc 1: lưu tên người ký vào công ty; nếu không truyền thì dùng cái đã lưu
    try:
        saved_nk = comp["nguoi_ky"] if "nguoi_ky" in comp.keys() else ""
    except Exception:
        saved_nk = ""
    if nguoi_ky:
        conn.execute("UPDATE companies SET nguoi_ky=? WHERE id=?", (nguoi_ky, cid))
        conn.commit()
    else:
        nguoi_ky = saved_nk or ""
    conn.close()

    def status_loai_bo(r):
        try:
            raw = json.loads(r["raw"]) if r["raw"] else {}
        except Exception:
            raw = {}
        tt = str(raw.get("tthai", r["tthai"]) or "").strip()
        if tt in ("4", "6"):  # đã bị thay thế / hủy
            return True
        kq = str(raw.get("ttxly", "") or "").strip().lower()
        kq_mota = _mo_ta_ket_qua(raw.get("ttxly", "")).lower()
        if kq == "4" or "không đủ điều kiện" in kq or "không đủ điều kiện" in kq_mota:
            return True
        return False

    mst_cty = str(comp["mst"] or "").strip()

    # ===== XÁC ĐỊNH KỲ KÊ KHAI + RANH GIỚI NGÀY *TRƯỚC* khi cộng dồn hóa đơn =====
    # QUAN TRỌNG: trước đây hàm này cộng dồn TẤT CẢ hóa đơn/tờ khai NK của công
    # ty (không lọc theo ngày) rồi mới xác định kỳ ở CUỐI hàm -> tờ khai kỳ nào
    # cũng vô tình cộng nhầm cả hóa đơn của kỳ khác (kể cả những năm trước) còn
    # lưu trong CSDL, khiến số liệu luôn SAI/CAO HƠN thực tế. Giờ xác định kỳ
    # (và khoảng ngày dd/mm/yyyy tương ứng) TRƯỚC, rồi chỉ cộng những hóa đơn có
    # ngày lập (tdlap) THỰC SỰ nằm trong đúng khoảng đó.
    import calendar

    def _ngay_hdon(tdlap):
        """'tdlap' dạng 'YYYY-MM-DD...' (hoặc có hậu tố giờ) -> date, None nếu hỏng."""
        s = str(tdlap or "").split("T")[0]
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date()
        except Exception:
            return None

    ky_auto = ""
    if not ky or "/" not in ky:
        for r in rows:
            if r["loai"] == "sold" and not status_loai_bo(r):
                d = _ngay_hdon(r["tdlap"])
                if d:
                    ky_auto = f"{d.month:02d}/{d.year}"
                    break
        ky = ky or ky_auto or "01/2026"

    # ky có thể là 'MM/YYYY' hoặc 'QX/YYYY' (kỳ quý) -> tách an toàn, không crash
    try:
        mm, yyyy = _ky_ve_thang(ky)
    except Exception:
        ky = ky_auto or "01/2026"
        mm, yyyy = _ky_ve_thang(ky)
    last_day = calendar.monthrange(int(yyyy), int(mm))[1]

    # ===== NHẬN BIẾT KỲ QUÝ: nếu khoảng ngày tra cứu (tu/den do FE gửi) trải
    # đúng 1 quý -> dùng ĐÚNG khoảng ngày đó làm ranh giới lọc (không chỉ để
    # LABEL); nếu FE không gửi tu/den thì mặc định lọc theo cả THÁNG của ky =====
    la_quy = False
    quy_so = 0
    tu_ngay_kkhai = f"01/{mm}/{yyyy}"
    den_ngay_kkhai = f"{last_day}/{mm}/{yyyy}"
    d_tu = datetime.date(int(yyyy), int(mm), 1)
    d_den = datetime.date(int(yyyy), int(mm), last_day)
    if tu and den:
        try:
            d1 = datetime.datetime.strptime(tu, "%d/%m/%Y").date()
            d2 = datetime.datetime.strptime(den, "%d/%m/%Y").date()
            songay = (d2 - d1).days
            # quý: bắt đầu tháng 1/4/7/10, kéo dài ~3 tháng
            if d1.month in (1, 4, 7, 10) and d1.day == 1 and 85 <= songay <= 95:
                la_quy = True
                quy_so = (d1.month - 1) // 3 + 1
                yyyy = str(d1.year)
            tu_ngay_kkhai = d1.strftime("%d/%m/%Y")
            den_ngay_kkhai = d2.strftime("%d/%m/%Y")
            d_tu, d_den = d1, d2
        except Exception:
            pass

    def trong_ky(tdlap):
        d = _ngay_hdon(tdlap)
        return bool(d and d_tu <= d <= d_den)

    # ----- Tổng MUA VÀO + BÁN RA: CHỈ đọc từ file Excel "Bảng kê hóa đơn" đã
    # xuất và lưu sẵn (sheet "BK Mua vào"/"BK Bán ra") — ĐÚNG YÊU CẦU: Kết
    # xuất XML KHÔNG BAO GIỜ tự tra cứu/gọi mạng lại/tính lại từ 'invoices'
    # nữa, kể cả khi không đọc được bảng kê — CHỈ dựa vào bảng kê đã lưu.
    # Trước đây khi không tìm/đọc được file bảng kê thì ÂM THẦM rơi xuống
    # tính lại theo cách cũ (từ 'invoices' trong DB + gọi mạng lấy chi tiết)
    # -> XML có thể ra số liệu KHÁC hẳn bảng kê mà không rõ vì sao (đã xác
    # nhận qua dữ liệu thật: dù đã sửa/xuất lại bảng kê đúng và khởi động lại
    # phần mềm, XML vẫn ra đúng số liệu CŨ — chứng tỏ vẫn rơi vào nhánh cũ).
    # Giờ nếu không đọc được bảng kê đúng kỳ thì BÁO LỖI RÕ ngay, không âm
    # thầm dùng nguồn số liệu khác.
    save_dir = (comp["save_dir"] or "").strip() if comp else ""
    export_dir_cty = (comp["export_dir"] if comp and "export_dir" in comp.keys() else "") or ""

    _tu_file_bk_mua = _doc_mua_vao_tu_file_bang_ke(mst_cty, save_dir, d_tu, d_den, export_dir_cty)
    if _tu_file_bk_mua is None:
        raise HTTPException(400,
            f"Không đọc được dữ liệu MUA VÀO đúng kỳ {ky} ({tu_ngay_kkhai} - "
            f"{den_ngay_kkhai}) từ file bảng kê đã xuất (sheet 'BK Mua vào', "
            f"file BangKe_HoaDon_{mst_cty}...xlsx trong thư mục tải về/thư mục "
            f"lưu của công ty). Hãy bấm 'Xuất Excel tổng hợp' cho ĐÚNG kỳ này "
            f"rồi mới bấm 'Kết xuất XML' — Kết xuất XML không tự tra cứu/tính "
            f"lại nữa, chỉ đọc đúng số liệu trong file bảng kê đã xuất.")
    mua_ds, mua_thue = _tu_file_bk_mua["ds"], _tu_file_bk_mua["thue"]
    mua_ds_full, mua_thue_full = _tu_file_bk_mua["ds_full"], _tu_file_bk_mua["thue_full"]
    file_bk_da_doc = _tu_file_bk_mua.get("_file") or ""

    # ----- BÁN RA: tách theo nhóm thuế suất — CŨNG CHỈ đọc từ bảng kê -----
    ban_theo_ts = {"0": {"ds": 0, "thue": 0}, "5": {"ds": 0, "thue": 0},
                   "8": {"ds": 0, "thue": 0}, "10": {"ds": 0, "thue": 0},
                   "KCT": {"ds": 0, "thue": 0}}
    _tu_file_bk = _doc_nhom_ban_ra_tu_file_bang_ke(mst_cty, save_dir, d_tu, d_den, export_dir_cty)
    if _tu_file_bk is None:
        raise HTTPException(400,
            f"Không đọc được dữ liệu BÁN RA đúng kỳ {ky} ({tu_ngay_kkhai} - "
            f"{den_ngay_kkhai}) từ file bảng kê đã xuất (sheet 'BK Bán ra', "
            f"file BangKe_HoaDon_{mst_cty}...xlsx trong thư mục tải về/thư mục "
            f"lưu của công ty). Hãy bấm 'Xuất Excel tổng hợp' cho ĐÚNG kỳ này "
            f"rồi mới bấm 'Kết xuất XML' — Kết xuất XML không tự tra cứu/tính "
            f"lại nữa, chỉ đọc đúng số liệu trong file bảng kê đã xuất.")
    full = _tu_file_bk.pop("_full", {"ds": 0, "thue": 0})
    _tu_file_bk.pop("_file", None)
    ban_ds_full, ban_thue_full = full["ds"], full["thue"]
    for k, v in _tu_file_bk.items():
        tgt = k if k in ban_theo_ts else "KCT"   # "KHAC" (Xuất Excel chưa lấy được file) gộp vào KCT
        ban_theo_ts[tgt]["ds"] += v["ds"]
        ban_theo_ts[tgt]["thue"] += v["thue"]

    # KHÔNG còn dùng dữ liệu ĐÃ IMPORT (bảng imported_data) để ghi đè mua_ds/
    # mua_thue/ban_theo_ts ở đây nữa — import Excel "dữ liệu đã kiểm tra" đã
    # GHI ĐÈ THẲNG vào bảng 'invoices' rồi (cả mua vào lẫn bán ra, xem
    # import_excel), nên 2 vòng lặp phía trên (mua_ds/mua_thue và
    # ban_theo_ts) ĐÃ tính đúng theo đúng dữ liệu import (nếu có) hệt như 2
    # sheet "BK Mua vào"/"BK Bán ra" của Xuất Excel tổng hợp. Trước đây còn
    # giữ 1 bảng cache riêng (imported_data) ưu tiên ghi đè NGOÀI 2 vòng lặp
    # trên — bảng cache này chỉ được tính đúng 1 LẦN lúc import, không tự
    # cập nhật khi có sửa lỗi phân loại nhóm thuế suất hay khi người dùng
    # tra cứu lại sau đó, nên ngày càng lệch khỏi dữ liệu THẬT trong
    # 'invoices'/hiện trên 2 sheet BK — đúng nguyên nhân người dùng báo
    # "tra cứu lại xong xuất XML vẫn sai" (XML âm thầm dùng số liệu import
    # CŨ, không phải dữ liệu mới).
    #
    # Phần hàng NHẬP KHẨU ([23a]/[24a]) TRƯỚC ĐÂY vẫn còn lấy riêng từ cache
    # imported_data.mua_ds_nk/mua_thue_nk (ghi 1 LẦN lúc "Import dữ liệu đã
    # kiểm tra", không tự cập nhật) — nên khi người dùng import THÊM tờ khai
    # nhập khẩu rồi chỉ "Xuất Excel tổng hợp" lại (không re-import "dữ liệu đã
    # kiểm tra"), [23]/[24] tự cập nhật đúng (đọc file mới) nhưng [23a]/[24a]
    # vẫn giữ nguyên số CŨ từ cache — đã xác nhận đúng nguyên nhân qua dữ liệu
    # thật (công ty AFLEX MST 0316363200: xuất Excel xong, [23a]/[24a] không
    # đổi, vẫn thiếu 2 trong 4 tờ khai nhập khẩu). Giờ tính TRỰC TIẾP từ CHÍNH
    # file bảng kê vừa đọc ở trên (dòng Ký hiệu 'TKNK') — cùng 1 nguồn dữ liệu
    # với [23]/[24], luôn đồng bộ, không còn phụ thuộc cache import riêng nữa.
    imp_nk_ds = _tu_file_bk_mua.get("ds_nk") or 0
    imp_nk_thue = _tu_file_bk_mua.get("thue_nk") or 0
    imp = _get_imported(cid, ky)

    # ===== SỐ DƯ ĐẦU KỲ [22]: lấy từ tạm tính VAT đã lưu (vat_balance) =====
    ct22_val = 0
    ky_tim = (f"Q{quy_so}/{yyyy}" if la_quy else ky)
    try:
        conn2 = db()
        vb = conn2.execute(
            "SELECT du_dau_ky FROM vat_balance WHERE company_id=? AND ky=?",
            (cid, ky_tim)).fetchone()
        if not vb:
            vb = conn2.execute(
                "SELECT du_dau_ky FROM vat_balance WHERE company_id=? AND ky=?",
                (cid, ky)).fetchone()
        conn2.close()
        if vb and vb["du_dau_ky"]:
            ct22_val = round(_to_num(vb["du_dau_ky"]) or 0)
    except Exception:
        pass

    # CHƯA có tạm tính VAT lưu sẵn cho kỳ này (vd công ty KHÔNG có mật khẩu
    # trang Thuế/không phát sinh hóa đơn nên chưa từng chạy "Tra cứu tờ khai
    # thuế hàng loạt" hay tự bấm "Tạm tính thuế VAT" — bước tự động lấy số dư
    # đầu kỳ trước đây CHỈ có ở 2 luồng đó, KHÔNG có khi bấm thẳng "Kết xuất
    # XML cho HTKK", nên số dư đầu kỳ [22] bị bỏ trống/0 dù kỳ trước ĐÃ CÓ tờ
    # khai với chỉ tiêu [41] > 0) -> TỰ ĐỘNG đọc chỉ tiêu [41] của tờ khai kỳ
    # liền trước (từ thư mục lưu file kết xuất riêng của công ty), giống hệt
    # "Tạm tính thuế VAT" đã làm, rồi LƯU LUÔN vào vat_balance để lần sau khỏi
    # phải dò lại file.
    if not ct22_val and comp:
        try:
            gia_tri_ct41, ky_truoc, _fp = _doc_ct41_ky_truoc(comp, ky_tim)
            if gia_tri_ct41:
                ct22_val = round(gia_tri_ct41)
                conn3 = db()
                conn3.execute("""
                    INSERT INTO vat_balance (company_id, ky, du_dau_ky, updated_at)
                    VALUES (?, ?, ?, ?)
                    ON CONFLICT(company_id, ky) DO UPDATE SET
                        du_dau_ky=excluded.du_dau_ky, updated_at=excluded.updated_at
                """, (cid, ky_tim, ct22_val, datetime.datetime.now().isoformat()))
                conn3.commit(); conn3.close()
        except Exception:
            pass

    # ----- Tính các chỉ tiêu tờ khai -----
    # ===== TỜ KHAI NHẬP KHẨU: tổng trị giá tính thuế GTGT + thuế GTGT hàng NK
    # CỦA ĐÚNG KỲ (theo ngày đăng ký tờ khai, ngay_dk) — trước đây cộng TẤT CẢ
    # tờ khai nhập khẩu từng nhập cho công ty, không lọc theo kỳ, nên tờ khai
    # GTGT kỳ nào cũng bị cộng nhầm cả tờ khai NK của kỳ/năm khác. =====
    tk_ds_nk = tk_thue_nk = 0
    tk_ds_nk_full = tk_thue_nk_full = 0   # KHÔNG lọc kỳ - dùng để đối chiếu BK Mua vào
    try:
        conn_tk = db()
        tk_rows = conn_tk.execute(
            "SELECT ngay_dk, items_json FROM tokhai_nhap WHERE company_id=?", (cid,)).fetchall()
        conn_tk.close()
        for tkr in tk_rows:
            try:
                its = json.loads(tkr["items_json"]) if tkr["items_json"] else []
            except Exception:
                its = []
            r_trong_ky_tk = trong_ky(tkr["ngay_dk"])
            for it in its:
                ds_it = round(it.get("tri_gia_gtgt", 0) or 0)
                thue_it = round(it.get("tien_thue_gtgt", 0) or 0)
                tk_ds_nk_full += ds_it; tk_thue_nk_full += thue_it
                if r_trong_ky_tk:
                    tk_ds_nk += ds_it
                    tk_thue_nk += thue_it
    except Exception:
        pass

    # Hàng 8% bản chất là 10% được giảm -> gộp vào nhóm 10% (ct32/ct33)
    ds_8 = ban_theo_ts["8"]["ds"]
    thue_8 = ban_theo_ts["8"]["thue"]
    # nhóm 10% trên tờ khai = hàng 10% thật + hàng 8% (tính theo thuế GỐC 10%)
    ds_10 = ban_theo_ts["10"]["ds"] + ds_8
    thue_10 = ban_theo_ts["10"]["thue"] + thue_8
    ds_5 = ban_theo_ts["5"]["ds"]; thue_5 = ban_theo_ts["5"]["thue"]
    ds_0 = ban_theo_ts["0"]["ds"]

    ct23 = round(mua_ds); ct24 = round(mua_thue); ct25 = ct24
    ct30 = round(ds_5); ct31 = round(thue_5)
    ct32 = round(ds_10); ct33 = round(thue_10)
    ct27 = ct30 + ct32; ct28 = ct31 + ct33
    ct29 = round(ds_0)
    ct34 = ct27 + ct29; ct35 = ct28
    # NQ142: thuế được giảm = doanh số 8% × 2%
    thue_duoc_giam = round(ds_8 * 0.02)

    # ===== DÙNG TEMPLATE XML THẬT, chỉ thay giá trị các thẻ (giữ nguyên cấu trúc) =====
    import re as _re
    tpl_path = os.path.join(BASE_DIR, "templates", "htkk_01gtgt_template.xml")
    with open(tpl_path, encoding="utf-8-sig") as f:
        xml = f.read()

    def set_tag(xml, tag, value):
        """Thay nội dung <tag>...</tag> bằng value (chỉ thẻ đầu tiên khớp)."""
        pat = _re.compile(r"(<" + tag + r">)(.*?)(</" + tag + r">)", _re.DOTALL)
        return pat.sub(lambda m: m.group(1) + str(value) + m.group(3), xml, count=1)

    def esc(s):
        return _html.escape(str(s or ""))

    # Thông tin chung - kỳ kê khai (quý hoặc tháng)
    if la_quy:
        xml = set_tag(xml, "kieuKy", "Q")   # Q = kê khai theo QUÝ -> HTKK tự hiển thị "Quý"
        xml = set_tag(xml, "kyKKhai", f"{quy_so}/{yyyy}")  # chỉ số quý, KHÔNG kèm 'Q' (tránh 'Quý Q2')
    else:
        xml = set_tag(xml, "kieuKy", "M")   # M = theo tháng
        xml = set_tag(xml, "kyKKhai", esc(ky))
    xml = set_tag(xml, "kyKKhaiTuNgay", tu_ngay_kkhai)
    xml = set_tag(xml, "kyKKhaiDenNgay", den_ngay_kkhai)
    xml = set_tag(xml, "ngayLapTKhai", datetime.date.today().isoformat())
    xml = set_tag(xml, "mst", esc(comp["mst"]))
    xml = set_tag(xml, "tenNNT", esc(comp["ten"]))
    # Địa chỉ + Cơ quan thuế nơi nộp: TRƯỚC ĐÂY luôn giữ nguyên giá trị của
    # công ty MẪU dùng để tạo file template (địa chỉ + mã/tên CQT của 1
    # công ty CỤ THỂ khác), khiến MỌI công ty xuất ra đều mang nhầm CQT/địa
    # chỉ của công ty đó — chính là nguyên nhân lỗi "Cơ quan thuế nơi nộp
    # không là Cơ quan thuế quản lý" khi nộp tờ khai của công ty KHÁC. Giờ
    # lấy đúng theo thông tin đã khai báo riêng cho TỪNG công ty (mục "Sửa
    # công ty"); công ty nào CHƯA khai báo thì báo cảnh báo rõ ràng thay vì
    # âm thầm gửi nhầm thông tin của công ty khác.
    dia_chi = (comp["dia_chi"] if "dia_chi" in comp.keys() else "") or ""
    ma_cqt = (comp["ma_cqt_noi_nop"] if "ma_cqt_noi_nop" in comp.keys() else "") or ""
    ten_cqt = (comp["ten_cqt_noi_nop"] if "ten_cqt_noi_nop" in comp.keys() else "") or ""
    canh_bao_cqt = []
    if dia_chi:
        xml = set_tag(xml, "dchiNNT", esc(dia_chi))
    else:
        canh_bao_cqt.append("địa chỉ trụ sở")
    if ma_cqt:
        xml = set_tag(xml, "maCQTNoiNop", esc(ma_cqt))
    else:
        canh_bao_cqt.append("mã CQT nơi nộp")
    if ten_cqt:
        xml = set_tag(xml, "tenCQTNoiNop", esc(ten_cqt))
    else:
        canh_bao_cqt.append("tên CQT nơi nộp")
    if nguoi_ky:
        xml = set_tag(xml, "nguoiKy", esc(nguoi_ky))
        xml = set_tag(xml, "ngayKy", datetime.date.today().isoformat())

    # Các chỉ tiêu (giữ nguyên những thẻ khác như ct22, ct36... = giá trị template
    # hoặc tính lại). Ở đây ta điền số liệu kỳ này:
    # ct23/24 = TỔNG mua vào (gồm cả hàng nhập khẩu); ct23a/24a = TRONG ĐÓ hàng nhập khẩu.
    # CHỈ dựa vào imp_nk_ds (tính TRỰC TIẾP từ CHÍNH file bảng kê đang đọc,
    # xem _doc_mua_vao_tu_file_bang_ke — ds/thue LUÔN CỘNG SẴN cả dòng TKNK)
    # — TRƯỚC ĐÂY còn kèm điều kiện "imp" (imported_data, 1 cache RIÊNG từ
    # luồng "Import dữ liệu đã kiểm tra" cũ, không liên quan gì tới việc
    # mua_ds đọc từ file bảng kê có sẵn NK hay chưa) khiến công ty KHÔNG
    # dùng luồng import Excel đó (đa số chỉ dùng "Xuất Excel tổng hợp" qua
    # tra cứu) luôn rơi vào nhánh else, CỘNG THÊM tk_ds_nk (bảng tokhai_nhap)
    # LẦN NỮA lên trên mua_ds vốn đã có sẵn NK -> [23]/[24] bị CỘNG TRÙNG
    # hàng nhập khẩu (đã xác nhận qua dữ liệu thật: công ty MST 0315364970,
    # [23]=941.743.359 trong khi mua_ds thật (đọc từ bảng kê, gồm cả NK) chỉ
    # 489.623.783 — chênh đúng bằng 452.119.576, chính là giá trị NK bị cộng
    # 2 lần).
    if imp_nk_ds:
        # sheet 'BK Mua vào' đã bao gồm SẴN các dòng tờ khai nhập khẩu (Ký
        # hiệu 'TKNK'/Trạng thái 'Tờ khai nhập khẩu') trong TỔNG mua vào ->
        # [23]/[24] giữ nguyên tổng, [23a]/[24a] chỉ TÁCH riêng phần nhập
        # khẩu ra để khai đúng chỉ tiêu, TUYỆT ĐỐI không cộng thêm lần nữa.
        ct23 = round(mua_ds)
        ct24 = round(mua_thue)
        ct23a = round(imp_nk_ds)      # giá trị HHDV nhập khẩu (chưa thuế GTGT)
        ct24a = round(imp_nk_thue)    # thuế GTGT hàng nhập khẩu
    else:
        # Tra cứu / file import không có dòng NK: tờ khai NK (nếu có) được nhập
        # RIÊNG (bảng tokhai_nhap) và CHƯA nằm trong mua_ds -> cộng thêm vào tổng.
        ct23a = tk_ds_nk
        ct24a = tk_thue_nk
        ct23 = round(mua_ds) + tk_ds_nk
        ct24 = round(mua_thue) + tk_thue_nk
    ct25 = ct24
    ct30 = round(ds_5); ct31 = round(thue_5)
    ds_10_tk = ban_theo_ts["10"]["ds"] + ds_8
    thue_10_tk = ban_theo_ts["10"]["thue"] + thue_8
    ct32 = round(ds_10_tk); ct33 = round(thue_10_tk)
    ct29 = round(ds_0)
    # [26] = doanh số bán ra KHÔNG CHỊU THUẾ GTGT (KCT) — TRƯỚC ĐÂY luôn ghi
    # cứng 0 (kể cả khi công ty có hóa đơn KCT thật), nên tờ khai xuất ra bị
    # THIẾU hẳn nhóm KCT, đồng thời [34] (tổng doanh thu) cũng sai theo do
    # không cộng phần này. Nay lấy đúng theo dữ liệu đã gộp (ban_theo_ts).
    ct26 = round(ban_theo_ts["KCT"]["ds"])
    # [27]/[28] = TỔNG doanh thu/thuế GTGT của HHDV bán ra CHỊU THUẾ GTGT —
    # gồm CẢ mức thuế suất 0% (ds_0/ct29). [29] CHỈ LÀ "trong đó: chịu thuế
    # suất 0%" — một PHẦN của [27], KHÔNG PHẢI khoản cộng thêm. Trước đây
    # code không cộng ds_0 vào ct27 (coi 0% như hàng KHÔNG chịu thuế), nên
    # công ty có doanh thu 0% (vd xuất khẩu) bị ghi ct27=0 sai hoàn toàn —
    # xác nhận qua file HTKK chuẩn thật (đã nộp được): ct27 = ct29 = ct34
    # khi TOÀN BỘ doanh thu là 0%, chứ không phải ct27=0.
    ct27 = ct29 + ct30 + ct32; ct28 = ct31 + ct33
    # [34] = [26]+[27] theo đúng mẫu 01/GTGT (tổng doanh thu bán ra gồm CẢ
    # không chịu thuế lẫn chịu thuế) — trước đây chỉ = [27], thiếu [26].
    ct34 = ct26 + ct27; ct35 = ct28

    # ===== ĐỐI CHIẾU với TỔNG CỘNG thật của sheet "BK Mua vào"/"BK Bán ra"
    # (Xuất Excel tổng hợp) — 2 sheet đó liệt kê MỌI hóa đơn hiện có, KHÔNG
    # lọc theo đúng kỳ khai như XML, nên khi có hóa đơn NGOÀI kỳ (vd hóa đơn
    # điều chỉnh ghi ngày lập ở kỳ trước) hoặc lỗi phân loại/nhập liệu, tổng
    # 2 sheet có thể LỆCH với [23]/[24]/[25]/[34]/[35] mà người dùng không hề
    # biết cho tới khi đối chiếu tay. Báo NGAY, LƯU LẠI (không mất khi toast
    # tự tắt) để không bỏ sót — theo đúng yêu cầu người dùng.
    mua_full_tk = 0 if imp_nk_ds else tk_ds_nk_full
    mua_thue_full_tk = 0 if imp_nk_ds else tk_thue_nk_full
    mua_ds_bk = round(mua_ds_full + mua_full_tk)
    mua_thue_bk = round(mua_thue_full + mua_thue_full_tk)
    ban_ds_bk = round(ban_ds_full)
    ban_thue_bk = round(ban_thue_full)
    NGUONG_LECH = 1000   # bỏ qua lệch làm tròn vặt vãnh dưới 1.000đ
    lech_mua_ds = mua_ds_bk - ct23
    lech_mua_thue = mua_thue_bk - ct25
    lech_ban_ds = ban_ds_bk - ct34
    lech_ban_thue = ban_thue_bk - ct35
    canh_bao_lech = []
    if abs(lech_mua_ds) >= NGUONG_LECH or abs(lech_mua_thue) >= NGUONG_LECH:
        canh_bao_lech.append(
            f"⚠ TỔNG CỘNG sheet 'BK Mua vào' (Doanh số {mua_ds_bk:,.0f}đ, Thuế GTGT "
            f"{mua_thue_bk:,.0f}đ) LỆCH với chỉ tiêu [23]/[24]/[25] trên XML (Doanh số "
            f"{ct23:,.0f}đ, Thuế {ct25:,.0f}đ) — chênh {lech_mua_ds:,.0f}đ doanh số, "
            f"{lech_mua_thue:,.0f}đ thuế. Thường do có hóa đơn NGOÀI kỳ đang khai (vd hóa "
            f"đơn điều chỉnh ghi ngày lập ở kỳ trước) — kiểm tra lại trước khi nộp.")
    if abs(lech_ban_ds) >= NGUONG_LECH or abs(lech_ban_thue) >= NGUONG_LECH:
        canh_bao_lech.append(
            f"⚠ TỔNG CỘNG sheet 'BK Bán ra' (Doanh số {ban_ds_bk:,.0f}đ, Thuế GTGT "
            f"{ban_thue_bk:,.0f}đ) LỆCH với chỉ tiêu [34]/[35] trên XML (Doanh số "
            f"{ct34:,.0f}đ, Thuế {ct35:,.0f}đ) — chênh {lech_ban_ds:,.0f}đ doanh số, "
            f"{lech_ban_thue:,.0f}đ thuế. Thường do có hóa đơn NGOÀI kỳ đang khai — kiểm "
            f"tra lại trước khi nộp.")
    if canh_bao_lech:
        _luu_loi_tra_cuu(cid, "\n\n".join(canh_bao_lech))

    ct36 = ct35 - ct25          # thuế GTGT phát sinh trong kỳ
    # ct22 = thuế còn được khấu trừ kỳ trước chuyển sang (số dư đầu kỳ)
    ct22 = ct22_val
    # Theo mẫu 01/GTGT (TT80):
    # [40a] = ([36]-[22]+[37]-[38]-[39a]) nếu ≥0 -> thuế phải nộp của hoạt động SXKD trong kỳ
    # [40]  = [40a] - [40b]  (ở đây 40b=0 -> [40]=[40a])
    # [41]  = phần âm (thuế chưa khấu trừ hết, chuyển kỳ sau) -> [43]=[41]-[42]
    ct37 = 0; ct38 = 0; ct39a = 0; ct40b = 0; ct42 = 0
    con_lai = ct36 - ct22 + ct37 - ct38 - ct39a
    ct40a = max(con_lai, 0)      # thuế phải nộp của SXKD trong kỳ
    ct40 = max(ct40a - ct40b, 0) # thuế còn phải nộp trong kỳ
    ct41 = max(-con_lai, 0)      # thuế chưa khấu trừ hết kỳ này
    ct43 = max(ct41 - ct42, 0)   # còn được khấu trừ chuyển kỳ sau

    # Thông báo (KHÔNG tự ẩn) số thuế GTGT PHẢI NỘP kỳ này — theo đúng chỉ
    # tiêu [40] vừa kết xuất, để người dùng biết ngay công ty nào phát sinh
    # phải nộp và nộp bao nhiêu mà không phải tự mở XML/HTKK ra xem. LUÔN
    # ghi (kể cả 0đ) để phân biệt "chưa kiểm tra" với "đã kiểm tra, không
    # phải nộp".
    ky_hien_thi_vat = f"Quý {quy_so}/{yyyy}" if la_quy else f"Tháng {mm}/{yyyy}"
    _luu_thue_vat_phai_nop(cid, ct40, ky_hien_thi_vat)

    for tag, val in [
        ("ct21", 0), ("ct22", ct22),
        ("ct23", ct23), ("ct24", ct24),
        ("ct23a", ct23a), ("ct24a", ct24a),
        ("ct25", ct25), ("ct26", ct26),
        ("ct27", ct27), ("ct28", ct28), ("ct29", ct29),
        ("ct30", ct30), ("ct31", ct31),
        ("ct32", ct32), ("ct33", ct33), ("ct32a", 0),
        ("ct34", ct34), ("ct35", ct35),
        ("ct36", ct36), ("ct37", ct37), ("ct38", ct38),
        ("ct39a", ct39a), ("ct40a", ct40a), ("ct40b", ct40b), ("ct40", ct40),
        ("ct41", ct41), ("ct42", ct42), ("ct43", ct43),
    ]:
        xml = set_tag(xml, tag, val)

    # Phụ lục NQ142/2024/QH15 (giảm 2% thuế GTGT hàng 8%): CHỈ khai khi kỳ
    # này THẬT SỰ có doanh thu bán ra thuế suất 8% (ds_8>0) — trước đây
    # phụ lục này LUÔN được đính kèm dù ds_8=0 (điền toàn số 0), khiến tờ
    # khai của những công ty KHÔNG có doanh thu 8% trong kỳ vẫn kèm 1 phụ
    # lục rỗng không cần thiết. Nếu không có 8% -> XÓA HẲN khối <PLuc>.
    if round(ds_8):
        xml = set_tag(xml, "giaTriHHDV", round(ds_8))
        xml = set_tag(xml, "thueGTGTDuocGiam", thue_duoc_giam)
        xml = set_tag(xml, "tongCongGiaTriHHDV", round(ds_8))
        xml = set_tag(xml, "tongCongThueGTGTDuocGiam", thue_duoc_giam)
        xml = set_tag(xml, "ct9", thue_duoc_giam)
        # tên hàng hóa bán ra trong phụ lục (thẻ tenHHDV - chỉ thẻ trong HH_DV_BanRaTrongKy)
        xml = _re.sub(r"(<tenHHDV>)(.*?)(</tenHHDV>)",
                      r"\g<1>Hàng hóa, dịch vụ thuế suất 8%\g<3>", xml, count=1)
    else:
        xml = _re.sub(r"\s*<PLuc>.*?</PLuc>\s*(?=</HSoKhaiThue>)", "\n", xml, count=1, flags=_re.DOTALL)

    # phần kỳ trong tên file: quý -> Q{n}{yyyy}, tháng -> M{mm}{yyyy}
    if la_quy:
        ky_fname = f"Q{quy_so}{yyyy}"
    else:
        ky_fname = f"M{mm}{yyyy}"
    # MST trong tên file HTKK dùng dạng 13 số (MST 10 số + '000' cho trụ sở chính)
    mst_file = str(comp["mst"] or "").strip()
    if len(mst_file) == 10:
        mst_file = mst_file + "000"
    fname = f"{mst_file}-01_GTGT_TT80-{ky_fname}-L00.xml"
    path = os.path.join(DOWNLOAD_DIR, fname)
    with open(path, "w", encoding="utf-8") as f:
        f.write("\ufeff" + xml)
    # Mặc định lưu ra DESKTOP cho dễ tìm; lưu thêm vào thư mục công ty (nếu có)
    open_path = path
    # ===== LƯU vào thư mục KẾT XUẤT theo Năm/Quý (nếu bật) — không rải Desktop =====
    da_luu_ket_xuat = False
    loi_luu_ket_xuat = ""
    if luu_ket_xuat:
        export_dir = (comp["export_dir"] if comp and "export_dir" in comp.keys() else "") or ""
        dich = _thu_muc_ket_xuat_ky(export_dir, tu_ngay_kkhai, den_ngay_kkhai)
        if dich:
            try:
                dest_kx = os.path.join(dich, fname)
                with open(dest_kx, "w", encoding="utf-8") as f:
                    f.write("\ufeff" + xml)
                open_path = dest_kx
                da_luu_ket_xuat = True
            except Exception as e:
                # KH\u00d4NG \u0111\u01b0\u1ee3c \u00e2m th\u1ea7m nu\u1ed1t l\u1ed7i r\u1ed3i l\u1eb7ng l\u1ebd r\u01a1i v\u1ec1 Desktop \u2014 ng\u01b0\u1eddi
                # d\u00f9ng \u0111\u00e3 c\u1ea5u h\u00ecnh \u0111\u00fang \u0111\u01b0\u1eddng d\u1eabn (th\u1ea5y r\u00f5 trong 'S\u1eeda c\u00f4ng ty')
                # nh\u01b0ng file v\u1eabn c\u1ee9 ra Desktop m\u00e0 KH\u00d4NG BI\u1ebeT V\u00cc SAO (vd \u0111\u01b0\u1eddng d\u1eabn
                # qu\u00e1 d\u00e0i >260 k\u00fd t\u1ef1 tr\u00ean Windows, \u1ed5 OneDrive \u0111ang kho\u00e1/\u0111\u1ed3ng b\u1ed9,
                # thi\u1ebfu quy\u1ec1n ghi...) \u2014 ph\u1ea3i b\u00e1o R\u00d5 nguy\u00ean nh\u00e2n th\u1eadt.
                loi_luu_ket_xuat = str(e)[:200]
        elif export_dir:
            loi_luu_ket_xuat = "kh\u00f4ng t\u1ea1o \u0111\u01b0\u1ee3c th\u01b0 m\u1ee5c \u0111\u00edch (ki\u1ec3m tra l\u1ea1i \u0111\u01b0\u1eddng d\u1eabn/quy\u1ec1n ghi)"
    if not da_luu_ket_xuat:
        desktop = _get_desktop_dir()
        if desktop and os.path.isdir(desktop):
            try:
                dest = os.path.join(desktop, fname)
                with open(dest, "w", encoding="utf-8") as f:
                    f.write("\ufeff" + xml)
                open_path = dest
            except Exception:
                pass
        save_dir2 = (comp["save_dir"] or "").strip() if comp else ""
        if save_dir2 and os.path.isdir(save_dir2):
            try:
                dest2 = os.path.join(save_dir2, fname)
                with open(dest2, "w", encoding="utf-8") as f:
                    f.write("\ufeff" + xml)
            except Exception:
                pass
    if mo_file:
        _open_file_local(open_path)
    canh_bao = ""
    if canh_bao_cqt:
        canh_bao = (f"⚠ Công ty CHƯA khai báo {', '.join(canh_bao_cqt)} — file XML đang dùng thông tin "
                    f"MẪU (có thể sai công ty), dễ bị Cơ quan Thuế báo lỗi. Vào 'Sửa công ty' để điền đủ "
                    f"trước khi nộp.")
    # [23a]/[24a] (hàng nhập khẩu) giờ tính TRỰC TIẾP từ CHÍNH file bảng kê
    # (dòng Ký hiệu 'TKNK') — CÙNG 1 nguồn dữ liệu và CÙNG lúc đọc với
    # [23]/[24] ở trên, không còn qua cache imported_data riêng (vốn chỉ ghi
    # 1 LẦN lúc "Import dữ liệu đã kiểm tra", dễ bị lạc hậu khi import thêm
    # tờ khai nhập khẩu rồi chỉ Xuất Excel lại mà không re-import).
    if imp_nk_ds:
        canh_bao = (canh_bao + "\n\n" if canh_bao else "") + (
            "ℹ️ Chỉ tiêu [23a]/[24a] (hàng nhập khẩu) lấy trực tiếp từ file bảng kê đã xuất cho kỳ này.")
        # Đối chiếu với số liệu tờ khai nhập khẩu (bảng tokhai_nhap) tính lại
        # TRỰC TIẾP cho đúng kỳ này (tk_ds_nk/tk_thue_nk) — nếu KHÁC với số vừa
        # đọc được từ file bảng kê (imp_nk_ds/imp_nk_thue), nghĩa là file bảng
        # kê trên đĩa CHƯA PHẢN ÁNH tờ khai nhập khẩu mới nhất (đã import thêm/
        # xoá SAU lần "Xuất Excel tổng hợp" gần nhất) — phải cảnh báo THẲNG,
        # không được âm thầm xuất ra số liệu chưa cập nhật đủ.
        if round(tk_thue_nk) != round(imp_nk_thue) or round(tk_ds_nk) != round(imp_nk_ds):
            canh_bao += (
                f"\n\n⚠ CẢNH BÁO CHÊNH LỆCH HÀNG NHẬP KHẨU: tờ khai nhập khẩu đã import (mục "
                f"'🛃 Import tờ khai nhập khẩu') hiện có tổng thuế GTGT hàng NK đúng kỳ này là "
                f"{round(tk_thue_nk):,} đ, nhưng file bảng kê đang dùng để xuất XML này (BangKe_HoaDon_"
                f"{mst_cty}...xlsx) chỉ có {round(imp_nk_thue):,} đ — CHÊNH LỆCH "
                f"{round(tk_thue_nk - imp_nk_thue):,} đ. File bảng kê trên đĩa có thể đã CŨ hơn tờ khai "
                f"nhập khẩu mới nhất. Hãy bấm '📊 Xuất Excel tổng hợp' LẠI cho đúng kỳ này rồi mới kết xuất "
                f"XML (nếu công ty có dùng 'Import dữ liệu đã kiểm tra', nhớ import lại file Excel vừa xuất "
                f"trước khi kết xuất XML).")
    if canh_bao_lech:
        canh_bao = (canh_bao + "\n\n" if canh_bao else "") + "\n\n".join(canh_bao_lech)
    if loi_luu_ket_xuat:
        canh_bao = (canh_bao + "\n\n" if canh_bao else "") + (
            f"⚠ KHÔNG lưu được vào 'Thư mục lưu file kết xuất' đã cấu hình ({loi_luu_ket_xuat}) "
            f"— đã lưu tạm ra Desktop thay thế. Hãy kiểm tra lại đường dẫn (đường dẫn quá dài, "
            f"ổ mạng/OneDrive đang khoá, hoặc thiếu quyền ghi đều có thể gây lỗi này).")
    # LUÔN hiển thị RÕ file bảng kê đã dùng để tính [23]-[35] (đường dẫn +
    # thời gian sửa đổi) — trước đây khi số liệu ra sai, không cách nào biết
    # NGAY server vừa đọc đúng file nào trên máy (có thể còn sót 1 bản khác
    # trùng tên ở thư mục khác mà người dùng không để ý), phải đoán mò/hỏi
    # qua lại nhiều lượt. Giờ báo thẳng để đối chiếu trực tiếp với file đang
    # xem trên máy.
    if file_bk_da_doc:
        try:
            _mtime_bk = datetime.datetime.fromtimestamp(
                os.path.getmtime(file_bk_da_doc)).strftime("%d/%m/%Y %H:%M:%S")
        except Exception:
            _mtime_bk = "?"
        canh_bao = (canh_bao + "\n\n" if canh_bao else "") + (
            f"ℹ️ Số liệu [23]-[35] lấy từ file bảng kê: {file_bk_da_doc} "
            f"(sửa đổi lúc {_mtime_bk}).")
    return {"ok": True, "fname": fname, "path": open_path, "canh_bao": canh_bao,
            "da_luu_ket_xuat": da_luu_ket_xuat, "dung_du_lieu_import": bool(imp_nk_ds),
            "lech_bk": bool(canh_bao_lech),
            "file_bang_ke": file_bk_da_doc,
            "thue_phai_nop": ct40, "thue_phai_nop_ky": ky_hien_thi_vat}


@app.get("/api/export-htkk-tncn/{cid}")
def export_htkk_tncn(cid: int, response: Response, ky: str = "", nguoi_ky: str = "", tu: str = "", den: str = "",
                     luu_ket_xuat: int = 0, mo_file: int = 1):
    """Bọc lỗi để trả về CHI TIẾT lỗi thật (thay vì lỗi 500 trống không rõ
    nguyên nhân — trước đây 1 lỗi bất ngờ nào đó (vd không ghi được file do
    thư mục kết xuất không hợp lệ) khiến người dùng chỉ thấy "Lỗi kết xuất
    (mã 500)" không biết vì sao, không tự khắc phục được."""
    # KHÔNG cache (xem giải thích ở export_htkk) — GET nhưng có tác dụng phụ
    # ghi file mới mỗi lần gọi.
    response.headers["Cache-Control"] = "no-store"
    try:
        return _export_htkk_tncn_impl(cid, ky, nguoi_ky, tu, den, luu_ket_xuat, mo_file)
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(500, f"Lỗi kết xuất XML TNCN: {type(e).__name__}: {str(e)[:200]}")


def _export_htkk_tncn_impl(cid: int, ky: str = "", nguoi_ky: str = "", tu: str = "", den: str = "",
                     luu_ket_xuat: int = 0, mo_file: int = 1):
    """
    Tạo file XML tờ khai 05/KK-TNCN (TT80/2021) để nhập vào HTKK.
    LƯU Ý: phần mềm hiện CHƯA có phân hệ tiền lương/thu nhập chịu thuế TNCN
    (không chấm công/tính lương) nên file luôn xuất ra ở dạng KHÔNG PHÁT SINH
    (mọi chỉ tiêu = 0) — đúng cho công ty/kỳ không phát sinh khấu trừ TNCN.
    Nếu kỳ này CÓ phát sinh, cần tự điền số liệu vào file (hoặc trên HTKK)
    trước khi nộp — phần mềm chỉ tự điền đúng công ty + kỳ báo cáo.
    ky: 'MM/YYYY' hoặc 'QX/YYYY'; nếu trống lấy tháng hiện tại.
    """
    import html as _html
    import re as _re
    import calendar
    conn = db()
    comp = conn.execute("SELECT * FROM companies WHERE id=?", (cid,)).fetchone()
    if not comp:
        conn.close()
        raise HTTPException(404, "Không tìm thấy công ty")
    try:
        saved_nk = comp["nguoi_ky"] if "nguoi_ky" in comp.keys() else ""
    except Exception:
        saved_nk = ""
    if nguoi_ky:
        conn.execute("UPDATE companies SET nguoi_ky=? WHERE id=?", (nguoi_ky, cid))
        conn.commit()
    else:
        nguoi_ky = saved_nk or ""
    conn.close()

    homnay = datetime.date.today()
    ky = ky or f"{homnay.month:02d}/{homnay.year}"
    try:
        mm, yyyy = _ky_ve_thang(ky)
    except Exception:
        ky = f"{homnay.month:02d}/{homnay.year}"
        mm, yyyy = _ky_ve_thang(ky)
    last_day = calendar.monthrange(int(yyyy), int(mm))[1]

    la_quy = False
    quy_so = 0
    tu_ngay_kkhai = f"01/{mm}/{yyyy}"
    den_ngay_kkhai = f"{last_day}/{mm}/{yyyy}"
    if tu and den:
        try:
            d1 = datetime.datetime.strptime(tu, "%d/%m/%Y").date()
            d2 = datetime.datetime.strptime(den, "%d/%m/%Y").date()
            songay = (d2 - d1).days
            if d1.month in (1, 4, 7, 10) and d1.day == 1 and 85 <= songay <= 95:
                la_quy = True
                quy_so = (d1.month - 1) // 3 + 1
                yyyy = str(d1.year)
            tu_ngay_kkhai = d1.strftime("%d/%m/%Y")
            den_ngay_kkhai = d2.strftime("%d/%m/%Y")
        except Exception:
            pass
    else:
        # 05/KK-TNCN thường kê khai theo QUÝ; nếu ky truyền vào dạng 'QX/YYYY'
        # thì tách trực tiếp, không bắt buộc phải có tu/den.
        kyu = (ky or "").strip().upper()
        if kyu.startswith("Q") and "/" in kyu:
            try:
                q_str, y_str = kyu[1:].split("/", 1)
                quy_so = max(1, min(4, int(q_str)))
                yyyy = y_str.strip()
                la_quy = True
                mm1 = (quy_so - 1) * 3 + 1
                mm2 = mm1 + 2
                tu_ngay_kkhai = f"01/{mm1:02d}/{yyyy}"
                den_ngay_kkhai = f"{calendar.monthrange(int(yyyy), mm2)[1]}/{mm2:02d}/{yyyy}"
            except Exception:
                pass

    tpl_path = os.path.join(BASE_DIR, "templates", "htkk_05tncn_template.xml")
    with open(tpl_path, encoding="utf-8-sig") as f:
        xml = f.read()

    def set_tag(xml, tag, value):
        pat = _re.compile(r"(<" + tag + r">)(.*?)(</" + tag + r">)", _re.DOTALL)
        return pat.sub(lambda m: m.group(1) + str(value) + m.group(3), xml, count=1)

    def esc(s):
        return _html.escape(str(s or ""))

    if la_quy:
        xml = set_tag(xml, "kieuKy", "Q")
        xml = set_tag(xml, "kyKKhai", f"{quy_so}/{yyyy}")
    else:
        xml = set_tag(xml, "kieuKy", "M")
        xml = set_tag(xml, "kyKKhai", esc(ky))
    xml = set_tag(xml, "kyKKhaiTuNgay", tu_ngay_kkhai)
    xml = set_tag(xml, "kyKKhaiDenNgay", den_ngay_kkhai)
    xml = set_tag(xml, "ngayLapTKhai", homnay.isoformat())
    xml = set_tag(xml, "mst", esc(comp["mst"]))
    xml = set_tag(xml, "mst_cu", esc(comp["mst"]))
    xml = set_tag(xml, "tenNNT", esc(comp["ten"]))

    # Địa chỉ + CQT nơi nộp: lấy đúng theo thông tin đã khai báo riêng cho
    # TỪNG công ty (mục "Sửa công ty") — cùng cơ chế/cảnh báo như 01/GTGT,
    # để tránh lặp lại lỗi "Cơ quan thuế nơi nộp không là Cơ quan thuế quản lý".
    dia_chi = (comp["dia_chi"] if "dia_chi" in comp.keys() else "") or ""
    ma_cqt = (comp["ma_cqt_noi_nop"] if "ma_cqt_noi_nop" in comp.keys() else "") or ""
    ten_cqt = (comp["ten_cqt_noi_nop"] if "ten_cqt_noi_nop" in comp.keys() else "") or ""
    canh_bao_cqt = []
    if dia_chi:
        xml = set_tag(xml, "dchiNNT", esc(dia_chi))
    else:
        canh_bao_cqt.append("địa chỉ trụ sở")
    if ma_cqt:
        xml = set_tag(xml, "maCQTNoiNop", esc(ma_cqt))
    else:
        canh_bao_cqt.append("mã CQT nơi nộp")
    if ten_cqt:
        xml = set_tag(xml, "tenCQTNoiNop", esc(ten_cqt))
    else:
        canh_bao_cqt.append("tên CQT nơi nộp")
    # maXaNNT/tenXaNNT (phường/xã trụ sở): template mẫu có sẵn giá trị CỨNG
    # (copy từ 1 công ty mẫu khi tạo template) — theo yêu cầu, KHÔNG tạo
    # thêm trường khai báo riêng cho phường/xã, mà dùng LUÔN mã/tên CQT nơi
    # nộp đã khai báo sẵn (cùng 1 nơi với maCQTNoiNop/tenCQTNoiNop ở trên)
    # để tránh còn sót giá trị mẫu sai của công ty khác.
    if ma_cqt:
        xml = set_tag(xml, "maXaNNT", esc(ma_cqt))
    if ten_cqt:
        xml = set_tag(xml, "tenXaNNT", esc(ten_cqt))
    if nguoi_ky:
        xml = set_tag(xml, "nguoiKy", esc(nguoi_ky))
        xml = set_tag(xml, "ngayKy", homnay.isoformat())

    # Chưa có nguồn dữ liệu tiền lương/thu nhập chịu thuế TNCN -> luôn xuất
    # tờ khai "không phát sinh" (mọi chỉ tiêu = 0), khớp file mẫu chuẩn.
    for tag in ("ct15", "ct16", "ct17", "ct18", "ct19", "ct20", "ct21", "ct22",
                "ct23", "ct24", "ct25", "ct25_1", "ct26", "ct27", "ct28",
                "ct29", "ct30", "ct31", "ct32"):
        xml = set_tag(xml, tag, 0)

    if la_quy:
        ky_fname = f"Q{quy_so}{yyyy}"
    else:
        ky_fname = f"M{mm}{yyyy}"
    mst_file = str(comp["mst"] or "").strip()
    if len(mst_file) == 10:
        mst_file = mst_file + "000"
    fname = f"{mst_file}-05_KK_TNCN_TT80-{ky_fname}-L00.xml"
    path = os.path.join(DOWNLOAD_DIR, fname)
    with open(path, "w", encoding="utf-8") as f:
        f.write("﻿" + xml)
    open_path = path
    # ===== LƯU vào thư mục KẾT XUẤT theo Năm/Quý (nếu bật) — không rải Desktop =====
    da_luu_ket_xuat = False
    loi_luu_ket_xuat = ""
    if luu_ket_xuat:
        export_dir = (comp["export_dir"] if comp and "export_dir" in comp.keys() else "") or ""
        dich = _thu_muc_ket_xuat_ky(export_dir, tu_ngay_kkhai, den_ngay_kkhai)
        if dich:
            try:
                dest_kx = os.path.join(dich, fname)
                with open(dest_kx, "w", encoding="utf-8") as f:
                    f.write("﻿" + xml)
                open_path = dest_kx
                da_luu_ket_xuat = True
            except Exception as e:
                # KHÔNG được âm thầm nuốt lỗi rồi lặng lẽ rơi về Desktop — người
                # dùng đã cấu hình đúng đường dẫn (thấy rõ trong 'Sửa công ty')
                # nhưng file vẫn cứ ra Desktop mà KHÔNG BIẾT VÌ SAO (vd đường dẫn
                # quá dài >260 ký tự trên Windows, ổ OneDrive đang khoá/đồng bộ,
                # thiếu quyền ghi...) — phải báo RÕ nguyên nhân thật.
                loi_luu_ket_xuat = str(e)[:200]
        elif export_dir:
            loi_luu_ket_xuat = "không tạo được thư mục đích (kiểm tra lại đường dẫn/quyền ghi)"
    if not da_luu_ket_xuat:
        desktop = _get_desktop_dir()
        if desktop and os.path.isdir(desktop):
            try:
                dest = os.path.join(desktop, fname)
                with open(dest, "w", encoding="utf-8") as f:
                    f.write("﻿" + xml)
                open_path = dest
            except Exception:
                pass
        save_dir2 = (comp["save_dir"] or "").strip() if comp else ""
        if save_dir2 and os.path.isdir(save_dir2):
            try:
                dest2 = os.path.join(save_dir2, fname)
                with open(dest2, "w", encoding="utf-8") as f:
                    f.write("﻿" + xml)
            except Exception:
                pass
    if mo_file:
        _open_file_local(open_path)
    canh_bao_parts = []
    if canh_bao_cqt:
        canh_bao_parts.append(
            f"⚠ Công ty CHƯA khai báo {', '.join(canh_bao_cqt)} — file XML đang dùng thông tin "
            f"MẪU (có thể sai công ty). Vào 'Sửa công ty' để điền đủ trước khi nộp.")
    canh_bao_parts.append(
        "ℹ Phần mềm chưa có phân hệ tiền lương/TNCN nên file này luôn là tờ khai KHÔNG PHÁT "
        "SINH (mọi chỉ tiêu = 0). Nếu kỳ này công ty CÓ phát sinh khấu trừ TNCN, hãy tự điền số "
        "liệu vào file (hoặc trực tiếp trên HTKK) trước khi nộp.")
    if loi_luu_ket_xuat:
        canh_bao_parts.append(
            f"⚠ KHÔNG lưu được vào 'Thư mục lưu file kết xuất' đã cấu hình ({loi_luu_ket_xuat}) "
            f"— đã lưu tạm ra Desktop thay thế. Hãy kiểm tra lại đường dẫn (đường dẫn quá dài, "
            f"ổ mạng/OneDrive đang khoá, hoặc thiếu quyền ghi đều có thể gây lỗi này).")
    canh_bao = " ".join(canh_bao_parts)
    return {"ok": True, "fname": fname, "path": open_path, "canh_bao": canh_bao,
            "da_luu_ket_xuat": da_luu_ket_xuat}


def _ky_ve_thang(ky):
    """Tách kỳ 'MM/YYYY' hoặc 'QX/YYYY' -> (mm:str 2 số, yyyy:str).
    Với kỳ quý, lấy THÁNG ĐẦU của quý làm mm (chỉ dùng để tính ngày mặc định
    của tờ khai; KHÔNG dùng để tra cứu/so khớp dữ liệu đã lưu theo kỳ)."""
    a, b = ky.split("/", 1)
    a = a.strip().upper()
    yyyy = int(b.strip())
    if a.startswith("Q") and a[1:].isdigit():
        q = max(1, min(4, int(a[1:])))
        mm = (q - 1) * 3 + 1
    else:
        mm = int(a)
    return f"{mm:02d}", str(yyyy)


def _ky_lien_truoc(ky):
    """Trả về CHUỖI kỳ liền trước 'ky', GIỮ NGUYÊN kiểu kỳ (tháng hay quý):
    'MM/YYYY' -> tháng trước; 'QX/YYYY' -> quý trước. '' nếu không hợp lệ."""
    ky = (ky or "").strip()
    if not ky or "/" not in ky:
        return ""
    a, b = ky.split("/", 1)
    a = a.strip().upper()
    try:
        y = int(b.strip())
    except Exception:
        return ""
    if a.startswith("Q") and a[1:].isdigit():
        q = int(a[1:])
        pq = 4 if q <= 1 else q - 1
        py = y - 1 if q <= 1 else y
        return f"Q{pq}/{py}"
    try:
        m = int(a)
    except Exception:
        return ""
    pm = 12 if m <= 1 else m - 1
    py = y - 1 if m <= 1 else y
    return f"{pm:02d}/{py}"


def _ky_tu_khoang_ngay(tu, den):
    """Suy ra kỳ kê khai 'QX/YYYY' (nếu khoảng ngày đúng 1 quý) hoặc
    'MM/YYYY' từ khoảng ngày tra cứu (dd/mm/yyyy) — bản Python của hàm
    kyKeKhaiTu() bên frontend, dùng để TỰ ĐỘNG xác định kỳ khi không có ô
    nhập kỳ riêng (vd sau khi tra cứu hóa đơn hàng loạt xong)."""
    if not tu:
        return ""
    try:
        d1, m1s, y1 = tu.split("/")
        m1 = int(m1s)
    except Exception:
        return ""
    if den:
        try:
            d2, m2s, y2 = den.split("/")
            m2 = int(m2s)
        except Exception:
            d2 = y2 = None
        else:
            if d1 == "01" and m1 in (1, 4, 7, 10) and y1 == y2 and m2 - m1 == 2:
                return f"Q{(m1 - 1) // 3 + 1}/{y1}"
    return f"{m1:02d}/{y1}"


def _parse_thue_suat(ts_raw):
    """Trả về tỷ lệ thuế (0.08 cho 8%) từ chuỗi thuế suất.
    Hỗ trợ: '8%', '8', 'KHAC:5.26%', 'KHAC:5.26', '5.26%'.
    Trả None nếu không xác định được (KCT, KHÔNG, rỗng, hoặc không có số)."""
    s = str(ts_raw or "").strip().upper()
    if not s or s in ("KCT", "KHÔNG", "KO", "0%", "0"):
        return 0.0 if s in ("0%", "0") else None
    # lấy phần sau dấu ':' nếu có (KHAC:5.26%)
    if ":" in s:
        s = s.split(":", 1)[1]
    s = s.replace("%", "").replace(",", ".").strip()
    try:
        v = float(s)
        return v / 100
    except Exception:
        return None


def _thue_theo_cong_thue(it, items, r):
    """Khi không parse được thuế suất của 1 dòng hàng, lấy tiền thuế theo số
    tổng của cổng thuế (tgtthue) chia theo tỷ lệ thành tiền của dòng đó."""
    tong_thue_hd = _to_num(r["tgtthue"]) or 0
    if not tong_thue_hd:
        return 0
    tong_tt = sum((_to_num(x.get("thtien")) or 0) for x in items) or 1
    ds = _to_num(it.get("thtien")) or 0
    return round(tong_thue_hd * (ds / tong_tt))


@app.get("/api/export-excel/{cid}")
def export_excel(cid: int, luu_ket_xuat: int = 0, tu_ngay: str = "",
                 den_ngay: str = "", mo_file: int = 1):
    """Xuất Excel bảng kê hóa đơn.
    luu_ket_xuat=1: NGOÀI Desktop, còn LƯU thêm vào thư mục kết xuất của công
      ty theo cấu trúc Năm/Quý (dựa vào tu_ngay/den_ngay). Nếu công ty chưa
      đặt 'Thư mục lưu file kết xuất' thì bỏ qua (vẫn lưu Desktop như thường).
    mo_file: MẶC ĐỊNH = 1 (tự mở file Excel ngay sau khi xuất, cho tiện xem
      luôn). Có ĐÁNH ĐỔI đã biết: file "Bảng kê hóa đơn" này là NGUỒN DỮ
      LIỆU chính mà "Kết xuất XML" đọc vào và bị GHI ĐÈ LẠI mỗi khi Import
      "dữ liệu đã kiểm tra" (xem import_excel) hoặc bấm "Xuất Excel tổng
      hợp" lần nữa — nếu Excel CÒN ĐANG MỞ sẵn file này (do lần xuất TRƯỚC
      tự mở, chưa đóng), Windows/OneDrive có thể KHOÁ file, khiến lần ghi
      đè SAU đó báo lỗi "File In Use"/"Document not saved". Từng đổi mặc
      định về 0 (không tự mở) để né hẳn lỗi này, nhưng người dùng thấy bất
      tiện hơn nhiều so với việc thỉnh thoảng phải đóng Excel trước khi
      Import/Xuất lại — nên bật lại tự mở theo yêu cầu. Nếu gặp lại "File In
      Use": đóng file Excel đang mở rồi thử lại, hoặc gọi endpoint này với
      mo_file=0 để tắt tự mở.
    Response trả về là FileResponse (qua _resp_xuat) — header 'Cache-Control:
    no-store' được gắn ở đó (không cache endpoint này, vì file "Bảng kê hóa
    đơn" ghi ra ở đây là NGUỒN DUY NHẤT mà "Kết xuất XML" đọc vào từ bản .18
    trở đi — nếu trình duyệt lặng lẽ phục vụ lại response CŨ, file trên đĩa
    không được cập nhật dù dữ liệu công ty đã đổi)."""
    import time as _tx
    _t0 = _tx.time()
    def _tlog(m):
        try: print(f"[xuat-excel +{_tx.time()-_t0:.1f}s] {m}", flush=True)
        except Exception: pass
    import openpyxl
    from openpyxl.styles import Font, PatternFill, Alignment
    from openpyxl.utils import get_column_letter

    conn = db()
    comp = conn.execute("SELECT * FROM companies WHERE id=?", (cid,)).fetchone()
    rows = _gop_hoa_don_trung_he_thong(conn.execute(
        "SELECT * FROM invoices WHERE company_id=? ORDER BY loai, tdlap DESC",
        (cid,)).fetchall())

    # CHỈ XỬ LÝ ĐÚNG KỲ ĐANG XUẤT khi có truyền tu_ngay/den_ngay — theo yêu
    # cầu: trước đây bước "nạp trước chi tiết" bên dưới LUÔN xử lý TOÀN BỘ
    # lịch sử hóa đơn công ty (mọi kỳ cộng dồn từ trước tới giờ), dù người
    # dùng chỉ đang xuất 1 kỳ cụ thể — khiến phải chờ tải bù hàng trăm hóa
    # đơn của CÁC KỲ KHÁC không liên quan mỗi lần xuất. Nếu KHÔNG truyền
    # tu_ngay/den_ngay (rỗng) thì vẫn giữ hành vi CŨ — xử lý toàn bộ lịch sử
    # (dùng cho các luồng cố ý muốn đầy đủ mọi kỳ trong 1 file).
    def _ngay_hoa_don(tdlap):
        s = str(tdlap or "").split("T")[0].strip()
        for fmt in ("%Y-%m-%d", "%d/%m/%Y"):
            try:
                return datetime.datetime.strptime(s, fmt).date()
            except Exception:
                pass
        return None

    _tu_loc = _den_loc = None
    if (tu_ngay or "").strip() and (den_ngay or "").strip():
        try:
            _tu_loc = datetime.datetime.strptime(tu_ngay.strip(), "%d/%m/%Y").date()
            _den_loc = datetime.datetime.strptime(den_ngay.strip(), "%d/%m/%Y").date()
        except Exception:
            _tu_loc = _den_loc = None
    if _tu_loc and _den_loc:
        _truoc_loc = len(rows)
        rows = [r for r in rows
               if (d := _ngay_hoa_don(r["tdlap"])) and _tu_loc <= d <= _den_loc]
        _tlog(f"lọc đúng kỳ {tu_ngay} - {den_ngay}: {len(rows)}/{_truoc_loc} hóa đơn")

    # ===== NẠP TRƯỚC CHI TIẾT SONG SONG (tăng tốc xuất Excel) =====
    # Chỉ nạp hóa đơn CHƯA có detail_json VÀ chưa có file đã tải (ƯU TIÊN TUYỆT ĐỐI
    # file XML/ZIP đã tải sẵn trên máy — KHÔNG gọi mạng lại cho hóa đơn đã có file).
    import concurrent.futures as _cf
    client0 = CLIENTS.get(cid)
    # CHƯA đăng nhập (hoặc phiên đã hết) mà công ty có lưu mật khẩu -> TỰ ĐĂNG
    # NHẬP trước khi xuất, thay vì bỏ cuộc và hiện placeholder "chưa có file
    # XML đã tải — đăng nhập rồi xuất lại" bắt người dùng phải tự làm lại thao
    # tác thủ công (đăng nhập ở màn hình khác rồi quay lại bấm xuất lần nữa).
    if comp and (not client0 or not client0.token or client0._token_dead) and comp["password"]:
        _tlog("chưa đăng nhập — tự động đăng nhập trước khi xuất...")
        # Dùng trình duyệt ẩn để vẽ captcha CHÍNH XÁC (như tra cứu hàng loạt/
        # /api/auto-login) thay vì để rớt về svglib (kém chính xác hơn hẳn) —
        # trước đây bước tự đăng nhập lúc xuất Excel KHÔNG mở trình duyệt ẩn,
        # nên tỉ lệ giải captcha thấp hơn hẳn, hay thất bại sau đủ 8 lần thử
        # dù có mật khẩu đúng, khiến các hóa đơn chưa có file/detail bị bỏ lỡ.
        drv_dn = _mo_trinh_duyet_captcha()
        try:
            ok_dn, msg_dn, _, _ = _tu_dong_dang_nhap(cid, so_lan=8, drv=drv_dn)
        except Exception as e:
            ok_dn, msg_dn = False, str(e)
        finally:
            _dong_trinh_duyet_captcha(drv_dn)
        _tlog(f"tự đăng nhập {'thành công' if ok_dn else 'thất bại'}: {msg_dn}")
        client0 = CLIENTS.get(cid)
    save_dir0 = (comp["save_dir"] or "").strip() if comp else ""

    # XÂY INDEX FILE 1 LẦN — dùng chung cho cả bước kiểm tra "đã có file" lẫn
    # lúc dựng sheet sau này (trước đây quét thư mục 2 LẦN riêng biệt).
    # Khoá theo (ký hiệu, số hoá đơn, MST người bán) — KHÔNG được bỏ MST khỏi
    # khoá: nhiều người bán khác nhau có thể trùng ký hiệu + số hoá đơn (vd cả
    # 2 đều "C26MTT" số "246"), nếu chỉ khoá theo (ký hiệu, số) sẽ ĐỌC NHẦM chi
    # tiết (mặt hàng, tiền...) của hóa đơn công ty khác cho hóa đơn đang xét.
    _file_index = {}
    _file_index_2 = {}   # dự phòng cho file cũ không có MST trong tên
    if save_dir0 and os.path.isdir(save_dir0):
        for rootdir, _d, files in os.walk(save_dir0):
            for fn in files:
                low = fn.lower()
                if not (low.endswith(".zip") or low.endswith(".xml")):
                    continue
                name = fn.rsplit(".", 1)[0]
                parts = name.split("_")
                if len(parts) < 2:
                    continue
                f_khh, f_sho = parts[0], parts[1].lstrip("0") or "0"
                path = os.path.join(rootdir, fn)

                def _uu_tien_xml(prev, low=low):
                    return prev is None or (prev.lower().endswith(".zip") and low.endswith(".xml"))
                if len(parts) >= 3:
                    # Chuẩn hóa MST trong khoá (bỏ dấu gạch/khoảng trắng) —
                    # MST cùng 1 người bán đôi khi trang Thuế trả về LỆCH ĐỊNH
                    # DẠNG giữa các lần tra cứu (có/không hậu tố chi nhánh),
                    # so khớp CHUỖI Y HỆT sẽ không nhận ra file ĐÃ CÓ SẴN trên
                    # máy — khiến kết xuất tưởng "thiếu file" rồi tự đi tải lại
                    # qua mạng dù file đã tải từ trước, dù người dùng xác nhận
                    # file vẫn còn nguyên trên máy.
                    key = (f_khh, f_sho, _chuan_mst(parts[2])[:10])
                    if _uu_tien_xml(_file_index.get(key)):
                        _file_index[key] = path
                else:
                    key2 = (f_khh, f_sho)
                    if _uu_tien_xml(_file_index_2.get(key2)):
                        _file_index_2[key2] = path
    have_file = set(_file_index.keys()) | set(_file_index_2.keys())
    _tlog(f"tim thay {len(have_file)} file hoa don da tai tren may (thu muc: {save_dir0 or '(chưa đặt)'})")

    def find_invoice_file(r):
        khh = str(r["khhdon"] or "").strip()
        sho = str(r["shdon"] or "").strip().lstrip("0") or "0"
        mst = _chuan_mst(r["nbmst"])[:10]
        return _file_index.get((khh, sho, mst)) or _file_index_2.get((khh, sho))

    def _doc_file_hoadon(fpath):
        """Đọc + parse 1 file XML/ZIP hóa đơn đã tải. Trả về (items, summary)."""
        try:
            with open(fpath, "rb") as f:
                data = f.read()
            if fpath.lower().endswith(".zip"):
                import zipfile as _zf, io as _io2
                try:
                    z = _zf.ZipFile(_io2.BytesIO(data))
                    xn = next((n for n in z.namelist()
                               if n.lower().endswith(".xml")), None)
                    if xn:
                        data = z.read(xn)
                except Exception:
                    pass
            return _parse_xml_invoice(data), _parse_invoice_summary(data)
        except Exception:
            return [], None

    can_nap = []
    da_co_file_rows = []
    # Hóa đơn "KHÔNG MÃ" (ttxly=6): đã KIỂM CHỨNG THỰC TẾ (response API thật)
    # rằng endpoint get_detail() (/invoices/detail — cùng API dùng cho nút
    # "Xem hóa đơn" trên trang Thuế) VẪN gọi được và trả về dòng hàng với
    # ĐÚNG số tiền/thuế suất — CHỈ RIÊNG trường "tên hàng hóa" bị trang Thuế
    # để trống (không phải lỗi phần mềm, không phải không gọi được mạng).
    # Vẫn cho gọi mạng bình thường ở lượt nhanh đầu (để lấy đúng breakdown
    # theo từng dòng/thuế suất — chính xác hơn cách gộp theo tổng hóa đơn),
    # nhưng KHÔNG đưa vào vòng CHỜ 429 kiên nhẫn ở "LƯỢT CUỐI" phía dưới (nếu
    # lượt nhanh đã không lấy được do giới hạn tốc độ, có sẵn phương án dự
    # phòng dùng tổng tiền theo bảng kê — không cần chờ thêm tốn thời gian).
    id_khong_ma = set()
    can_lam_moi_khong_file = []   # có detail_json nhưng KHÔNG có file -> làm mới NGÀY LẬP qua mạng (xem dưới)
    for r in rows:
        khh = str(r["khhdon"] or ""); sho = str(r["shdon"] or "").lstrip("0") or "0"
        mst = _chuan_mst(r["nbmst"])[:10]
        co_file = (khh, sho, mst) in _file_index or (khh, sho) in _file_index_2
        if r["detail_json"]:
            # Vẫn tranh thủ đối chiếu/tự sửa NGÀY LẬP nếu có file trên máy, dù
            # detail_json đã có sẵn từ TRƯỚC — TRƯỚC ĐÂY bỏ qua HẲN các dòng
            # đã có detail_json (continue ngay ở đây, không xét file), nên hóa
            # đơn nào bị sai ngày ngay từ LẦN ĐẦU (trước khi có cơ chế đối
            # chiếu này, hoặc trước khi cổng Thuế tự sửa lại phía họ) sẽ bị
            # "khoá cứng" ngày SAI MÃI MÃI — không bao giờ được đối chiếu lại
            # nữa dù Xuất Excel bao nhiêu lần, vì detail_json không đổi. Đã
            # xác nhận qua dữ liệu thật: hóa đơn K25TCN/239341 (CÔNG TY XĂNG
            # DẦU TIỀN GIANG) luôn hiện "Ngày lập" 30/06/2025 trên bảng kê dù
            # file XML/trang xem hóa đơn thật ghi đúng 01/07/2025 — khiến hóa
            # đơn bị tính nhầm sang kỳ TRƯỚC (Quý 2) khi thực ra thuộc Quý 3,
            # "biến mất" khỏi tờ khai HTKK của đúng kỳ.
            if co_file:
                fpath = _file_index.get((khh, sho, mst)) or _file_index_2.get((khh, sho))
                if fpath:
                    items, _s = _doc_file_hoadon(fpath)
                    if items:
                        try:
                            _sua_tdlap_theo_id(r["id"], items[0].get("ngay"), r["tdlap"])
                        except Exception:
                            pass
            else:
                # Hóa đơn "KHÔNG MÃ" (Tổng cục Thuế KHÔNG cấp file XML/ZIP cho
                # loại này) KHÔNG CÓ FILE để đối chiếu như nhánh trên — cùng 1
                # lỗi "khoá cứng ngày sai" nhưng không có cách nào tự sửa nếu
                # không hỏi lại chính trang Thuế. Đã xác nhận qua dữ liệu thật:
                # hóa đơn K25TCN/360602 (không mã — trang xem hóa đơn ghi đúng
                # 01/10/2025) luôn hiện "Ngày lập" 30/09/2025 trên bảng kê dù
                # Xuất Excel lại nhiều lần, vì detail_json (cache 1 lần từ lần
                # tra cứu ĐẦU) không bao giờ được hỏi lại. Gom lại, làm mới
                # SONG SONG ở bước riêng bên dưới (không hỏi mạng ngay trong
                # vòng lặp tuần tự này — chậm nếu có nhiều hóa đơn không mã).
                can_lam_moi_khong_file.append(r)
            continue
        if co_file:
            da_co_file_rows.append(r)
            continue   # đã có file trên máy -> get_invoice_items sẽ đọc file, KHÔNG cần mạng
        try:
            if str((json.loads(r["raw"]) if r["raw"] else {}).get("ttxly", "") or "").strip() == "6":
                id_khong_ma.add(r["id"])
        except Exception:
            pass
        can_nap.append(dict(r))
    _tlog(f"{len(da_co_file_rows)} hóa đơn dùng được file đã tải, {len(can_nap)} hóa đơn thiếu cả detail lẫn file"
          + (f" (trong đó {len(id_khong_ma)} hóa đơn KHÔNG MÃ — vẫn gọi mạng lấy chi tiết bình "
             f"thường như hóa đơn khác, không loại trừ)" if id_khong_ma else ""))

    # ===== Làm mới Ngày lập cho hóa đơn ĐÃ CÓ detail_json nhưng KHÔNG CÓ file
    # (chủ yếu hóa đơn KHÔNG MÃ) — xem giải thích ở nhánh "else" phía trên.
    # Chạy SONG SONG (không tuần tự từng cái) để không làm chậm Xuất Excel khi
    # công ty có nhiều hóa đơn không mã. Chỉ CẦN gọi lại ĐÚNG hệ thống/khmshdon
    # đã lưu trước đó (đã từng lấy được chi tiết thành công với tổ hợp này) —
    # không cần thử lại mọi biến thể như lúc lấy chi tiết LẦN ĐẦU.
    if can_lam_moi_khong_file and client0 and client0.token and not client0._token_dead:
        _tlog(f"đối chiếu lại Ngày lập cho {len(can_lam_moi_khong_file)} hóa đơn không có file (không mã)...")

        def _lam_moi_ngay(r):
            try:
                ht0 = r["he_thong"] or "query"
                d_fresh = client0.get_detail(r["nbmst"], r["khhdon"], r["khmshdon"],
                                              r["shdon"], ht0, max_retry=1,
                                              cho_khi_429=False, loai=r["loai"])
                if not (d_fresh and (d_fresh.get("hdhhdvu") or d_fresh.get("nbmst"))):
                    return None
                return r["id"], d_fresh
            except Exception:
                return None

        so_da_sua = 0
        _by_id_khong_file = {r["id"]: r for r in can_lam_moi_khong_file}
        workers_lm = {"fast": 4, "balanced": 3, "safe": 2}.get(CURRENT_SPEED, 3)
        with _cf.ThreadPoolExecutor(max_workers=workers_lm) as ex:
            for ket in ex.map(_lam_moi_ngay, can_lam_moi_khong_file):
                if not ket:
                    continue
                inv_id, d_fresh = ket
                r0 = _by_id_khong_file.get(inv_id)
                ngay_cu_d = str(r0["tdlap"] or "").split("T")[0] if r0 else ""
                ngay_fresh = str(d_fresh.get("tdlap") or "").strip()
                if ngay_fresh and ngay_cu_d and ngay_fresh.split("T")[0] != ngay_cu_d:
                    cn = db()
                    cn.execute("UPDATE invoices SET tdlap=?, detail_json=? WHERE id=?",
                               (ngay_fresh, json.dumps(d_fresh, ensure_ascii=False), inv_id))
                    cn.commit(); cn.close()
                    so_da_sua += 1
        if so_da_sua:
            _tlog(f"✓ đã tự sửa lại Ngày lập cho {so_da_sua}/{len(can_lam_moi_khong_file)} hóa đơn không mã "
                 f"(khác với ngày đã lưu trước đó)")
    # Ghi rõ TỪNG hóa đơn thiếu cả file lẫn detail (ký hiệu/số/MST/trạng thái)
    # — trước đây CHỈ có con số tổng, không biết CHÍNH XÁC hóa đơn nào để tự
    # kiểm tra lại trên máy (vd người dùng chắc chắn đã tick "Tải file XML"
    # lúc tra cứu nhưng vẫn thiếu — cần biết đúng hóa đơn nào mới dò được vì
    # sao: file bị xoá sau đó, tên file lệch định dạng không khớp được, hay
    # thật sự chưa từng tải được lúc tra cứu).
    if can_nap:
        for r in can_nap[:30]:
            try:
                raw_cn = json.loads(r["raw"]) if r["raw"] else {}
            except Exception:
                raw_cn = {}
            _tlog(f"  · thiếu: {r['loai']} {r['khhdon']} số {r['shdon']} — MST bán {r['nbmst']} — "
                 f"tthai={r['tthai']} ttxly={raw_cn.get('ttxly', '')} — id={r['id']}")
        if len(can_nap) > 30:
            _tlog(f"  · ... còn {len(can_nap) - 30} hóa đơn thiếu khác (không liệt kê hết)")

    def _tai_1(rr, cho_khi_429=False, max_retry=1):
        if client0._token_dead:
            return rr["id"], None   # phiên đã hết -> khỏi thử, trả nhanh
        ht0 = rr["he_thong"] or "query"
        for ht in [ht0, ("sco-query" if ht0 == "query" else "query")]:
            for km in _bien_the_khmshdon(rr["khmshdon"]):
                try:
                    d = client0.get_detail(rr["nbmst"], rr["khhdon"],
                                           km, rr["shdon"], ht,
                                           max_retry=max_retry, cho_khi_429=cho_khi_429,
                                           loai=rr["loai"])
                    if d and (d.get("hdhhdvu") or d.get("nbmst")):
                        return rr["id"], json.dumps(d, ensure_ascii=False)
                except Exception:
                    pass
        return rr["id"], None

    def _nap_song_song(ds_rows, nhan, cho_khi_429=False, workers=None):
        """Nạp chi tiết qua mạng SONG SONG cho 1 danh sách hóa đơn, lưu DB
        1 lần. Trả về số hóa đơn lấy được.
        cho_khi_429=True -> CHỜ theo Retry-After khi bị giới hạn tốc độ thay
        vì bỏ ngay (dùng cho lượt cuối, đảm bảo KHÔNG bỏ sót hóa đơn nào)."""
        if not (ds_rows and client0 and client0.token and not client0._token_dead):
            return 0
        results_map = {}
        _tlog(f"{nhan} {len(ds_rows)} hóa đơn qua mạng (song song)...")
        if workers is None:
            # SỐ LUỒNG THẤP + CÓ NGHỈ giữa các lần xem — mô phỏng người thật
            # bấm "Xem hóa đơn" lần lượt. Trước đây tới 20 luồng bắn liên tục
            # không nghỉ khiến tường lửa trang Thuế coi là tấn công và CHẶN CẢ
            # IP ở tầng kết nối (trình duyệt cũng không vào được) — người dùng
            # xác nhận cứ xuất Excel số lượng lớn là bị chặn.
            workers = {"fast": 4, "balanced": 3, "safe": 2}.get(CURRENT_SPEED, 3)
        max_retry = 2 if cho_khi_429 else 1

        def _goi(rr):
            kq = _tai_1(rr, cho_khi_429=cho_khi_429, max_retry=max_retry)
            time.sleep(SP()["file"])   # nghỉ giữa các lần xem (như người thật)
            return kq

        with _cf.ThreadPoolExecutor(max_workers=workers) as ex:
            for inv_id, dj in ex.map(_goi, ds_rows):
                if dj:
                    results_map[inv_id] = dj
        cn = db()
        for inv_id, dj in results_map.items():
            cn.execute("UPDATE invoices SET detail_json=? WHERE id=?", (dj, inv_id))
        cn.commit(); cn.close()
        return len(results_map)

    if can_nap:
        if client0 and client0.token and not client0._token_dead:
            so_lay_duoc = _nap_song_song(can_nap, "thử nạp nhanh (không chờ khi bị giới hạn tốc độ)")
            con_thieu = len(can_nap) - so_lay_duoc
            if client0._token_dead:
                _tlog(f"phiên đăng nhập đã hết hạn giữa chừng — dừng nạp qua mạng, còn {con_thieu} hóa đơn chưa có chi tiết")
            elif con_thieu:
                _tlog(f"lấy được {so_lay_duoc}/{len(can_nap)}; còn {con_thieu} hóa đơn bị giới hạn tốc độ — "
                     f"chạy lại 'Kết xuất Excel' sau ít phút để lấy nốt (đã lưu tiến độ)")
        else:
            why = ("chưa đăng nhập/phiên đã hết" if not (client0 and client0.token) else "phiên đã hết hạn")
            _tlog(f"bỏ qua nạp mạng cho {len(can_nap)} hóa đơn ({why}) — sẽ hiện placeholder, "
                 f"đăng nhập lại rồi xuất lại để lấy nốt")

    # ===== KIỂM TRA NHANH file "đã có" có THỰC SỰ ĐỌC ĐƯỢC không (offline,
    # không cần mạng) — hóa đơn nào file lỗi/rỗng (hỏng, sai định dạng...)
    # thì gộp NẠP LẠI QUA MẠNG SONG SONG luôn ở đây. TRƯỚC ĐÂY việc này để
    # tới lúc dựng sheet mới phát hiện rồi gọi mạng TUẦN TỰ TỪNG CÁI 1 — với
    # hàng trăm hóa đơn, đây chính là nguyên nhân "đã nạp xong chi tiết" mà
    # vẫn treo rất lâu ở bước dựng sheet.
    _items_cache = {}
    can_nap2 = []
    if da_co_file_rows:
        for r in da_co_file_rows:
            fpath = find_invoice_file(r)
            items, summary = (_doc_file_hoadon(fpath) if fpath else ([], None))
            if items:
                key = (r["khhdon"], r["shdon"], r["nbmst"], r["loai"])
                _items_cache[key] = (items, summary)
                # Tranh thủ đối chiếu/tự sửa NGÀY LẬP theo đúng file XML gốc —
                # đã gặp trường hợp API tra cứu danh sách và file XML thật
                # của CHÍNH Tổng cục Thuế lệch ngày nhau (vd hóa đơn VETC).
                try:
                    _sua_tdlap_theo_id(r["id"], items[0].get("ngay"), r["tdlap"])
                except Exception:
                    pass
            else:
                can_nap2.append(dict(r))
        if can_nap2:
            so_lay_duoc2 = _nap_song_song(can_nap2, "file đã tải nhưng đọc lỗi/rỗng — nạp lại")
            if so_lay_duoc2 < len(can_nap2):
                _tlog(f"⚠ {len(can_nap2) - so_lay_duoc2}/{len(can_nap2)} hóa đơn có file trên máy "
                     f"nhưng ĐỌC LỖI và nạp lại qua mạng cũng không được")

    # ===== LƯỢT CUỐI: PHẢI LẤY ĐỦ mới xong, không để hóa đơn nào hiện
    # placeholder "chưa lấy được chi tiết" chỉ vì bị giới hạn tốc độ (429) —
    # theo đúng yêu cầu "phải tải đầy đủ mới xong quá trình". 2 lượt phía
    # trên bỏ ngay khi gặp 429 (để không làm chậm cả quá trình) — số hóa đơn
    # CÒN THIẾU lúc này thường đã nhỏ, nên lượt cuối này LẶP NHIỀU VÒNG, mỗi
    # vòng CHỜ đúng theo Retry-After của trang Thuế (chấp nhận chậm hơn) với
    # ít luồng song song hơn, CHỈ DỪNG khi lấy đủ hết — trước đây chỉ thử 1
    # vòng rồi bỏ cuộc dù vẫn còn thiếu nhiều (vd 7/11 hóa đơn vẫn thiếu sau
    # 1 vòng ~9 phút), khiến file Excel xuất ra còn dòng "chưa lấy được chi
    # tiết" dù trang Thuế thực ra vẫn trả lời được nếu kiên nhẫn thử tiếp.
    # LƯU Ý: hóa đơn KHÔNG MÃ (ttxly=6) VẪN được xử lý bình thường ở đây —
    # đã kiểm chứng bằng dữ liệu thật là API get_detail() VẪN trả về đúng
    # chi tiết dòng hàng (kể cả tên hàng hóa) cho loại này khi request thành
    # công, KHÔNG hề "chắc chắn không có" như suy đoán ban đầu. Vấn đề thực
    # sự chỉ là bị giới hạn tốc độ khi gọi hàng loạt — giống hệt hóa đơn
    # thường — nên cần được thử lại kiên nhẫn giống nhau, không loại riêng.
    ds_can_kiem_tra = can_nap + can_nap2
    # LƯU Ý: KHÔNG loại trừ trường hợp client0._token_dead ở đây — vòng lặp
    # bên dưới đã TỰ ĐỘNG đăng nhập lại khi phát hiện phiên hết hạn giữa
    # chừng (xem nhánh "if client0._token_dead" trong vòng while), nên vẫn
    # phải VÀO vòng lặp ngay cả khi phiên vừa chết ở bước "thử nạp nhanh"
    # phía trên — nếu chặn ở đây thì không bao giờ có cơ hội đăng nhập lại.
    if ds_can_kiem_tra and client0 and client0.token:
        ids_can_kiem_tra = [r["id"] for r in ds_can_kiem_tra]
        ph = ",".join("?" * len(ids_can_kiem_tra))
        # An toàn: nếu NHIỀU VÒNG LIÊN TỤC không lấy thêm được hóa đơn nào
        # (có thể lỗi khác hẳn 429 tạm thời, vd phiên hết hạn/lỗi hẳn phía
        # Thuế cho đúng hóa đơn đó) thì mới dừng lại — tránh lặp vô tận vô
        # ích khi vấn đề không phải do giới hạn tốc độ.
        SO_VONG_KHONG_TIEN_TOI_DA = 5
        so_vong_khong_tien = 0
        vong = 0
        while True:
            con_thieu_rows = conn.execute(
                f"SELECT * FROM invoices WHERE id IN ({ph}) AND (detail_json IS NULL OR detail_json='')",
                ids_can_kiem_tra).fetchall()
            if not con_thieu_rows:
                if vong:
                    _tlog("✓ đã lấy đủ chi tiết cho toàn bộ hóa đơn còn thiếu (không còn hóa đơn nào "
                         "phải hiện placeholder 'chưa lấy được chi tiết')")
                break
            if client0._token_dead:
                # Phiên hết hạn GIỮA CHỪNG -> TỰ ĐĂNG NHẬP LẠI (trình duyệt ẩn
                # vẽ captcha chính xác) rồi TIẾP TỤC lấy nốt thay vì bỏ cuộc —
                # đúng yêu cầu "tra cứu/xuất phải tải hết, lỗi thì quay lại
                # tải cho đủ", không để hiện placeholder "chưa lấy được".
                if not (comp and comp["password"]):
                    _tlog(f"⚠ phiên đăng nhập hết hạn giữa chừng — còn {len(con_thieu_rows)} hóa đơn CHƯA "
                         f"lấy được chi tiết, đăng nhập lại rồi xuất lại để lấy nốt")
                    break
                _tlog(f"⚠ phiên đăng nhập hết hạn giữa chừng — đang tự động đăng nhập lại để lấy nốt "
                     f"{len(con_thieu_rows)} hóa đơn còn thiếu chi tiết...")
                drv_relog2 = _mo_trinh_duyet_captcha()
                try:
                    ok_relog2, tb_relog2, _, _ = _tu_dong_dang_nhap(cid, so_lan=8, drv=drv_relog2)
                finally:
                    _dong_trinh_duyet_captcha(drv_relog2)
                if not ok_relog2:
                    _tlog(f"⚠ tự đăng nhập lại thất bại ({tb_relog2}) — còn {len(con_thieu_rows)} hóa đơn "
                         f"CHƯA lấy được chi tiết, đăng nhập lại rồi xuất lại để lấy nốt")
                    break
                _tlog("✓ đã tự đăng nhập lại thành công, tiếp tục lấy nốt chi tiết...")
                client0 = CLIENTS.get(cid)
                continue
            vong += 1
            _tlog(f"còn {len(con_thieu_rows)} hóa đơn chưa lấy được — thử lại vòng {vong} (chờ đúng "
                 f"thời gian giới hạn tốc độ của trang Thuế, KHÔNG bỏ cuộc cho tới khi lấy đủ)...")
            so_lay_duoc3 = _nap_song_song(con_thieu_rows, f"thử lại vòng {vong} (chờ khi bị giới hạn tốc độ)",
                                          cho_khi_429=True, workers=2)
            if so_lay_duoc3 == 0:
                so_vong_khong_tien += 1
                if so_vong_khong_tien >= SO_VONG_KHONG_TIEN_TOI_DA:
                    # Liệt kê CHÍNH XÁC hóa đơn còn thiếu — đã thử cả biến thể
                    # khmshdon lẫn cả 2 hệ thống mà vẫn thất bại NHIỀU vòng
                    # liên tiếp thường là API thật sự KHÔNG CÓ dữ liệu cho
                    # đúng tổ hợp tham số đang lưu (khác lỗi giới hạn tốc độ
                    # tạm thời) — cần biết đúng hóa đơn nào để dò tiếp.
                    ds_mota2 = "; ".join(
                        f"{r['khhdon']} số {r['shdon']} (MST {r['nbmst']}, id={r['id']})"
                        for r in con_thieu_rows[:10])
                    _tlog(f"⚠ đã thử {so_vong_khong_tien} vòng liên tiếp KHÔNG lấy thêm được hóa đơn nào "
                         f"(có thể lỗi khác ngoài giới hạn tốc độ) — dừng lại, còn {len(con_thieu_rows)} "
                         f"hóa đơn CHƯA lấy được chi tiết: {ds_mota2}"
                         f"{' ...' if len(con_thieu_rows) > 10 else ''}. Xuất lại 'Kết xuất Excel' sau ít "
                         f"phút để thử tiếp.")
                    break
            else:
                so_vong_khong_tien = 0

    # đọc lại rows để có detail_json mới nhất (từ các lượt nạp mạng ở trên) —
    # PHẢI lọc lại ĐÚNG KỲ lần nữa ở đây (giống bộ lọc đầu hàm): câu SELECT
